window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ECC"]={"book":"ECC","editions":{"hbo-source":[[1,1,"דִּבְרֵי֙ קֹהֶ֣לֶת בֶּן־דָּוִ֔ד מֶ֖לֶךְ בִּ⁠ירוּשָׁלִָֽם׃","di̇bĕréy֙ qòhe֣leţ bėn-dá̇wi֔d me֖lekĕ bi̇⁠yrẇşá̌liáֽm׃"],[1,2,"הֲבֵ֤ל הֲבָלִים֙ אָמַ֣ר קֹהֶ֔לֶת הֲבֵ֥ל הֲבָלִ֖ים הַ⁠כֹּ֥ל הָֽבֶל׃","hàbé֤l hàbáliym֙ ʼáma֣r qòhe֔leţ hàbé֥l hàbáli֖ym ha⁠kò֥̇l háֽbel׃"],[1,3,"מַה־יִּתְר֖וֹן לָֽ⁠אָדָ֑ם בְּ⁠כָל־עֲמָל֔⁠וֹ שֶֽׁ⁠יַּעֲמֹ֖ל תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","mah-yi̇ţĕr֖wòn láֽ⁠ʼádá֑m bĕ̇⁠kál-ʻàmál֔⁠wò şěֽ⁠yȧʻàmò֖l ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[1,4,"דּ֤וֹר הֹלֵךְ֙ וְ⁠ד֣וֹר בָּ֔א וְ⁠הָ⁠אָ֖רֶץ לְ⁠עוֹלָ֥ם עֹמָֽדֶת׃","ḋ֤wòr hòlékĕ֙ wĕ⁠d֣wòr bá̇֔ʼ wĕ⁠há⁠ʼá֖reẕ lĕ⁠ʻwòlá֥m ʻòmáֽdeţ׃"],[1,5,"וְ⁠זָרַ֥ח הַ⁠שֶּׁ֖מֶשׁ וּ⁠בָ֣א הַ⁠שָּׁ֑מֶשׁ וְ⁠אֶ֨ל־מְקוֹמ֔⁠וֹ שׁוֹאֵ֛ף זוֹרֵ֥חַֽ ה֖וּא שָֽׁם׃","wĕ⁠zára֥ẖ ha⁠şė֖̌meş̌ ẇ⁠bá֣ʼ ha⁠şá֑̇̌meş̌ wĕ⁠ʼe֨l-mĕqwòm֔⁠wò ş̌wòʼé֛p zwòré֥ẖaֽ h֖ẇʼ şáֽ̌m׃"],[1,6,"הוֹלֵךְ֙ אֶל־דָּר֔וֹם וְ⁠סוֹבֵ֖ב אֶל־צָפ֑וֹן סוֹבֵ֤ב ׀ סֹבֵב֙ הוֹלֵ֣ךְ הָ⁠ר֔וּחַ וְ⁠עַל־סְבִיבֹתָ֖י⁠ו שָׁ֥ב הָ⁠רֽוּחַ׃","hwòlékĕ֙ ʼel-dá̇r֔wòm wĕ⁠swòbé֖b ʼel-ẕáp֑wòn swòbé֤b ׀ sòbéb֙ hwòlé֣kĕ há⁠r֔ẇẖa wĕ⁠ʻal-sĕbiybòţá֖y⁠w şá֥̌b há⁠rֽẇẖa׃"],[1,7,"כָּל־הַ⁠נְּחָלִים֙ הֹלְכִ֣ים אֶל־הַ⁠יָּ֔ם וְ⁠הַ⁠יָּ֖ם אֵינֶ֣⁠נּוּ מָלֵ֑א אֶל־מְק֗וֹם שֶׁ֤⁠הַ⁠נְּחָלִים֙ הֹֽלְכִ֔ים שָׁ֛ם הֵ֥ם שָׁבִ֖ים לָ⁠לָֽכֶת׃","ká̇l-ha⁠nĕ̇ẖáliym֙ hòlĕki֣ym ʼel-ha⁠yá̇֔m wĕ⁠ha⁠yá֖̇m ʼéyne֣⁠ṅẇ málé֑ʼ ʼel-mĕq֗wòm şě֤⁠ha⁠nĕ̇ẖáliym֙ hòֽlĕki֔ym şá֛̌m hé֥m şá̌bi֖ym lá⁠láֽkeţ׃"],[1,8,"כָּל־הַ⁠דְּבָרִ֣ים יְגֵעִ֔ים לֹא־יוּכַ֥ל אִ֖ישׁ לְ⁠דַבֵּ֑ר לֹא־תִשְׂבַּ֥ע עַ֨יִן֙ לִ⁠רְא֔וֹת וְ⁠לֹא־תִמָּלֵ֥א אֹ֖זֶן מִ⁠שְּׁמֹֽעַ׃","ká̇l-ha⁠dĕ̇bári֣ym yĕgéʻi֔ym lòʼ-yẇka֥l ʼi֖yş̌ lĕ⁠dabé֑̇r lòʼ-ţişĕ̂bȧ֥ʻ ʻa֨yin֙ li⁠rĕʼ֔wòţ wĕ⁠lòʼ-ţimá̇lé֥ʼ ʼò֖zen mi⁠şĕ̇̌mòֽʻa׃"],[1,9,"מַה־שֶּֽׁ⁠הָיָה֙ ה֣וּא שֶׁ⁠יִּהְיֶ֔ה וּ⁠מַה־שֶׁ⁠נַּֽעֲשָׂ֔ה ה֖וּא שֶׁ⁠יֵּעָשֶׂ֑ה וְ⁠אֵ֥ין כָּל־חָדָ֖שׁ תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","mah-şėֽ̌⁠háyáh֙ h֣ẇʼ şě⁠yi̇hĕye֔h ẇ⁠mah-şě⁠nȧֽʻàşá̂֔h h֖ẇʼ şě⁠yé̇ʻáşê֑h wĕ⁠ʼé֥yn ká̇l-ẖádá֖ş̌ ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[1,10,"יֵ֥שׁ דָּבָ֛ר שֶׁ⁠יֹּאמַ֥ר רְאֵה־זֶ֖ה חָדָ֣שׁ ה֑וּא כְּבָר֙ הָיָ֣ה לְ⁠עֹֽלָמִ֔ים אֲשֶׁ֥ר הָיָ֖ה מִ⁠לְּ⁠פָנֵֽ⁠נוּ׃","yé֥ş̌ dá̇bá֛r şě⁠yò̇ʼma֥r rĕʼéh-ze֖h ẖádá֣ş̌ h֑ẇʼ kĕ̇bár֙ háyá֣h lĕ⁠ʻòֽlámi֔ym ʼàşě֥r háyá֖h mi⁠lĕ̇⁠pánéֽ⁠nẇ׃"],[1,11,"אֵ֥ין זִכְר֖וֹן לָ⁠רִאשֹׁנִ֑ים וְ⁠גַ֨ם לָ⁠אַחֲרֹנִ֜ים שֶׁ⁠יִּהְי֗וּ לֹֽא־יִהְיֶ֤ה לָ⁠הֶם֙ זִכָּר֔וֹן עִ֥ם שֶׁ⁠יִּהְי֖וּ לָ⁠אַחֲרֹנָֽה׃פ","ʼé֥yn zikĕr֖wòn lá⁠riʼşò̌ni֑ym wĕ⁠ga֨m lá⁠ʼaẖàròni֜ym şě⁠yi̇hĕy֗ẇ lòֽʼ-yihĕye֤h lá⁠hem֙ ziká̇r֔wòn ʻi֥m şě⁠yi̇hĕy֖ẇ lá⁠ʼaẖàrònáֽh׃p"],[1,12,"אֲנִ֣י קֹהֶ֗לֶת הָיִ֥יתִי מֶ֛לֶךְ עַל־יִשְׂרָאֵ֖ל בִּ⁠ירוּשָׁלִָֽם׃","ʼàni֣y qòhe֗leţ háyi֥yţiy me֛lekĕ ʻal-yişĕ̂ráʼé֖l bi̇⁠yrẇşá̌liáֽm׃"],[1,13,"וְ⁠נָתַ֣תִּי אֶת־לִבִּ֗⁠י לִ⁠דְר֤וֹשׁ וְ⁠לָ⁠תוּר֙ בַּֽ⁠חָכְמָ֔ה עַ֛ל כָּל־אֲשֶׁ֥ר נַעֲשָׂ֖ה תַּ֣חַת הַ⁠שָּׁמָ֑יִם ה֣וּא ׀ עִנְיַ֣ן רָ֗ע נָתַ֧ן אֱלֹהִ֛ים לִ⁠בְנֵ֥י הָ⁠אָדָ֖ם לַ⁠עֲנ֥וֹת בּֽ⁠וֹ׃","wĕ⁠náţa֣ţi̇y ʼeţ-libi̇֗⁠y li⁠dĕr֤wòş̌ wĕ⁠lá⁠ţẇr֙ bȧֽ⁠ẖákĕmá֔h ʻa֛l ká̇l-ʼàşě֥r naʻàşá֖̂h ţȧ֣ẖaţ ha⁠şá̇̌má֑yim h֣ẇʼ ׀ ʻinĕya֣n rá֗ʻ náţa֧n ʼèlòhi֛ym li⁠bĕné֥y há⁠ʼádá֖m la⁠ʻàn֥wòţ ḃֽ⁠wò׃"],[1,14,"רָאִ֨יתִי֙ אֶת־כָּל־הַֽ⁠מַּעֲשִׂ֔ים שֶֽׁ⁠נַּעֲשׂ֖וּ תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ וְ⁠הִנֵּ֥ה הַ⁠כֹּ֛ל הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","ráʼi֨yţiy֙ ʼeţ-ká̇l-haֽ⁠mȧʻàşî֔ym şěֽ⁠nȧʻàş֖̂ẇ ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ wĕ⁠hiné֥̇h ha⁠kò֛̇l he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[1,15,"מְעֻוָּ֖ת לֹא־יוּכַ֣ל לִ⁠תְקֹ֑ן וְ⁠חֶסְר֖וֹן לֹא־יוּכַ֥ל לְ⁠הִמָּנֽוֹת׃","mĕʻuwá֖̇ţ lòʼ-yẇka֣l li⁠ţĕqò֑n wĕ⁠ẖesĕr֖wòn lòʼ-yẇka֥l lĕ⁠himá̇nֽwòţ׃"],[1,16,"דִּבַּ֨רְתִּי אֲנִ֤י עִם־לִבִּ⁠י֙ לֵ⁠אמֹ֔ר אֲנִ֗י הִנֵּ֨ה הִגְדַּ֤לְתִּי וְ⁠הוֹסַ֨פְתִּי֙ חָכְמָ֔ה עַ֛ל כָּל־אֲשֶׁר־הָיָ֥ה לְ⁠פָנַ֖⁠י עַל־יְרוּשָׁלִָ֑ם וְ⁠לִבִּ֛⁠י רָאָ֥ה הַרְבֵּ֖ה חָכְמָ֥ה וָ⁠דָֽעַת׃","di̇bȧ֨rĕţi̇y ʼàni֤y ʻim-libi̇⁠y֙ lé⁠ʼmò֔r ʼàni֗y hiné̇֨h higĕdȧ֤lĕţi̇y wĕ⁠hwòsa֨pĕţi̇y֙ ẖákĕmá֔h ʻa֛l ká̇l-ʼàşěr-háyá֥h lĕ⁠pána֖⁠y ʻal-yĕrẇşá̌liá֑m wĕ⁠libi֛̇⁠y ráʼá֥h harĕbé֖̇h ẖákĕmá֥h wá⁠dáֽʻaţ׃"],[1,17,"וָ⁠אֶתְּנָ֤⁠ה לִבִּ⁠י֙ לָ⁠דַ֣עַת חָכְמָ֔ה וְ⁠דַ֥עַת הוֹלֵל֖וֹת וְ⁠שִׂכְל֑וּת יָדַ֕עְתִּי שֶׁ⁠גַּם־זֶ֥ה ה֖וּא רַעְי֥וֹן רֽוּחַ׃","wá⁠ʼeţĕ̇ná֤⁠h libi̇⁠y֙ lá⁠da֣ʻaţ ẖákĕmá֔h wĕ⁠da֥ʻaţ hwòlél֖wòţ wĕ⁠şîkĕl֑ẇţ yáda֕ʻĕţi̇y şě⁠gȧm-ze֥h h֖ẇʼ raʻĕy֥wòn rֽẇẖa׃"],[1,18,"כִּ֛י בְּ⁠רֹ֥ב חָכְמָ֖ה רָב־כָּ֑עַס וְ⁠יוֹסִ֥יף דַּ֖עַת יוֹסִ֥יף מַכְאֽוֹב׃","ki֛̇y bĕ̇⁠rò֥b ẖákĕmá֖h ráb-ká֑̇ʻas wĕ⁠ywòsi֥yp dȧ֖ʻaţ ywòsi֥yp makĕʼֽwòb׃"],[2,1,"אָמַ֤רְתִּֽי אֲנִי֙ בְּ⁠לִבִּ֔⁠י לְכָ⁠ה־נָּ֛א אֲנַסְּ⁠כָ֛ה בְ⁠שִׂמְחָ֖ה וּ⁠רְאֵ֣ה בְ⁠ט֑וֹב וְ⁠הִנֵּ֥ה גַם־ה֖וּא הָֽבֶל׃","ʼáma֤rĕţiֽ̇y ʼàniy֙ bĕ̇⁠libi̇֔⁠y lĕká⁠h-ná֛̇ʼ ʼànasĕ̇⁠ká֛h bĕ⁠şîmĕẖá֖h ẇ⁠rĕʼé֣h bĕ⁠t֑wòb wĕ⁠hiné֥̇h gam-h֖ẇʼ háֽbel׃"],[2,2,"לִ⁠שְׂח֖וֹק אָמַ֣רְתִּי מְהוֹלָ֑ל וּ⁠לְ⁠שִׂמְחָ֖ה מַה־זֹּ֥ה עֹשָֽׂה׃","li⁠şĕ̂ẖ֖wòq ʼáma֣rĕţi̇y mĕhwòlá֑l ẇ⁠lĕ⁠şîmĕẖá֖h mah-zò֥̇h ʻòşáֽ̂h׃"],[2,3,"תַּ֣רְתִּי בְ⁠לִבִּ֔⁠י לִ⁠מְשׁ֥וֹךְ בַּ⁠יַּ֖יִן אֶת־בְּשָׂרִ֑⁠י וְ⁠לִבִּ֞⁠י נֹהֵ֤ג בַּֽ⁠חָכְמָה֙ וְ⁠לֶ⁠אֱחֹ֣ז בְּ⁠סִכְל֔וּת עַ֣ד אֲשֶׁר־אֶרְאֶ֗ה אֵי־זֶ֨ה ט֜וֹב לִ⁠בְנֵ֤י הָ⁠אָדָם֙ אֲשֶׁ֤ר יַעֲשׂוּ֙ תַּ֣חַת הַ⁠שָּׁמַ֔יִם מִסְפַּ֖ר יְמֵ֥י חַיֵּי⁠הֶֽם׃","ţȧ֣rĕţi̇y bĕ⁠libi̇֔⁠y li⁠mĕş֥̌wòkĕ bȧ⁠yȧ֖yin ʼeţ-bĕ̇şá̂ri֑⁠y wĕ⁠libi̇֞⁠y nòhé֤g bȧֽ⁠ẖákĕmáh֙ wĕ⁠le⁠ʼèẖò֣z bĕ̇⁠sikĕl֔ẇţ ʻa֣d ʼàşěr-ʼerĕʼe֗h ʼéy-ze֨h t֜wòb li⁠bĕné֤y há⁠ʼádám֙ ʼàşě֤r yaʻàş̂ẇ֙ ţȧ֣ẖaţ ha⁠şá̇̌ma֔yim misĕpȧ֖r yĕmé֥y ẖayé̇y⁠heֽm׃"],[2,4,"הִגְדַּ֖לְתִּי מַעֲשָׂ֑⁠י בָּנִ֤יתִי לִ⁠י֙ בָּתִּ֔ים נָטַ֥עְתִּי לִ֖⁠י כְּרָמִֽים׃","higĕdȧ֖lĕţi̇y maʻàşá֑̂⁠y bá̇ni֤yţiy li⁠y֙ bá̇ţi̇֔ym náta֥ʻĕţi̇y li֖⁠y kĕ̇rámiֽym׃"],[2,5,"עָשִׂ֣יתִי לִ֔⁠י גַּנּ֖וֹת וּ⁠פַרְדֵּסִ֑ים וְ⁠נָטַ֥עְתִּי בָ⁠הֶ֖ם עֵ֥ץ כָּל־פֶּֽרִי׃","ʻáşî֣yţiy li֔⁠y gȧṅ֖wòţ ẇ⁠parĕdé̇si֑ym wĕ⁠náta֥ʻĕţi̇y bá⁠he֖m ʻé֥ẕ ká̇l-pėֽriy׃"],[2,6,"עָשִׂ֥יתִי לִ֖⁠י בְּרֵכ֣וֹת מָ֑יִם לְ⁠הַשְׁק֣וֹת מֵ⁠הֶ֔ם יַ֖עַר צוֹמֵ֥חַ עֵצִֽים׃","ʻáşî֥yţiy li֖⁠y bĕ̇rék֣wòţ má֑yim lĕ⁠haşĕ̌q֣wòţ mé⁠he֔m ya֖ʻar ẕwòmé֥ẖa ʻéẕiֽym׃"],[2,7,"קָנִ֨יתִי֙ עֲבָדִ֣ים וּ⁠שְׁפָח֔וֹת וּ⁠בְנֵי־בַ֖יִת הָ֣יָה לִ֑⁠י גַּ֣ם מִקְנֶה֩ בָקָ֨ר וָ⁠צֹ֤אן הַרְבֵּה֙ הָ֣יָה לִ֔⁠י מִ⁠כֹּ֛ל שֶֽׁ⁠הָי֥וּ לְ⁠פָנַ֖⁠י בִּ⁠ירוּשָׁלִָֽם׃","qáni֨yţiy֙ ʻàbádi֣ym ẇ⁠şĕ̌páẖ֔wòţ ẇ⁠bĕnéy-ba֖yiţ há֣yáh li֑⁠y gȧ֣m miqĕneh֩ báqá֨r wá⁠ẕò֤ʼn harĕbé̇h֙ há֣yáh li֔⁠y mi⁠kò֛̇l şěֽ⁠háy֥ẇ lĕ⁠pána֖⁠y bi̇⁠yrẇşá̌liáֽm׃"],[2,8,"כָּנַ֤סְתִּי לִ⁠י֙ גַּם־כֶּ֣סֶף וְ⁠זָהָ֔ב וּ⁠סְגֻלַּ֥ת מְלָכִ֖ים וְ⁠הַ⁠מְּדִינ֑וֹת עָשִׂ֨יתִי לִ֜⁠י שָׁרִ֣ים וְ⁠שָׁר֗וֹת וְ⁠תַעֲנוּגֹ֛ת בְּנֵ֥י הָ⁠אָדָ֖ם שִׁדָּ֥ה וְ⁠שִׁדּֽוֹת׃","ká̇na֤sĕţi̇y li⁠y֙ gȧm-kė֣sep wĕ⁠záhá֔b ẇ⁠sĕgulȧ֥ţ mĕláki֖ym wĕ⁠ha⁠mĕ̇diyn֑wòţ ʻáşî֨yţiy li֜⁠y şá̌ri֣ym wĕ⁠şá̌r֗wòţ wĕ⁠ţaʻànẇgò֛ţ bĕ̇né֥y há⁠ʼádá֖m şǐdá֥̇h wĕ⁠şǐḋֽwòţ׃"],[2,9,"וְ⁠גָדַ֣לְתִּי וְ⁠הוֹסַ֔פְתִּי מִ⁠כֹּ֛ל שֶׁ⁠הָיָ֥ה לְ⁠פָנַ֖⁠י בִּ⁠ירוּשָׁלִָ֑ם אַ֥ף חָכְמָתִ֖⁠י עָ֥מְדָה לִּֽ⁠י׃","wĕ⁠gáda֣lĕţi̇y wĕ⁠hwòsa֔pĕţi̇y mi⁠kò֛̇l şě⁠háyá֥h lĕ⁠pána֖⁠y bi̇⁠yrẇşá̌liá֑m ʼa֥p ẖákĕmáţi֖⁠y ʻá֥mĕdáh liֽ̇⁠y׃"],[2,10,"וְ⁠כֹל֙ אֲשֶׁ֣ר שָֽׁאֲל֣וּ עֵינַ֔⁠י לֹ֥א אָצַ֖לְתִּי מֵ⁠הֶ֑ם לֹֽא־מָנַ֨עְתִּי אֶת־לִבִּ֜⁠י מִ⁠כָּל־שִׂמְחָ֗ה כִּֽי־לִבִּ֤⁠י שָׂמֵ֨חַ֙ מִ⁠כָּל־עֲמָלִ֔⁠י וְ⁠זֶֽה־הָיָ֥ה חֶלְקִ֖⁠י מִ⁠כָּל־עֲמָלִֽ⁠י׃","wĕ⁠kòl֙ ʼàşě֣r şáֽ̌ʼàl֣ẇ ʻéyna֔⁠y lò֥ʼ ʼáẕa֖lĕţi̇y mé⁠he֑m lòֽʼ-mána֨ʻĕţi̇y ʼeţ-libi̇֜⁠y mi⁠ká̇l-şîmĕẖá֗h kiֽ̇y-libi֤̇⁠y şá̂mé֨ẖa֙ mi⁠ká̇l-ʻàmáli֔⁠y wĕ⁠zeֽh-háyá֥h ẖelĕqi֖⁠y mi⁠ká̇l-ʻàmáliֽ⁠y׃"],[2,11,"וּ⁠פָנִ֣יתִֽי אֲנִ֗י בְּ⁠כָל־מַעֲשַׂ⁠י֙ שֶֽׁ⁠עָשׂ֣וּ יָדַ֔⁠י וּ⁠בֶֽ⁠עָמָ֖ל שֶׁ⁠עָמַ֣לְתִּי לַ⁠עֲשׂ֑וֹת וְ⁠הִנֵּ֨ה הַ⁠כֹּ֥ל הֶ֨בֶל֙ וּ⁠רְע֣וּת ר֔וּחַ וְ⁠אֵ֥ין יִתְר֖וֹן תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","ẇ⁠páni֣yţiֽy ʼàni֗y bĕ̇⁠kál-maʻàşâ⁠y֙ şěֽ⁠ʻáş֣̂ẇ yáda֔⁠y ẇ⁠beֽ⁠ʻámá֖l şě⁠ʻáma֣lĕţi̇y la⁠ʻàş֑̂wòţ wĕ⁠hiné̇֨h ha⁠kò֥̇l he֨bel֙ ẇ⁠rĕʻ֣ẇţ r֔ẇẖa wĕ⁠ʼé֥yn yiţĕr֖wòn ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[2,12,"וּ⁠פָנִ֤יתִֽי אֲנִי֙ לִ⁠רְא֣וֹת חָכְמָ֔ה וְ⁠הוֹלֵל֖וֹת וְ⁠סִכְל֑וּת כִּ֣י ׀ מֶ֣ה הָ⁠אָדָ֗ם שֶׁ⁠יָּבוֹא֙ אַחֲרֵ֣י הַ⁠מֶּ֔לֶךְ אֵ֥ת אֲשֶׁר־כְּבָ֖ר עָשֽׂוּ⁠הוּ׃","ẇ⁠páni֤yţiֽy ʼàniy֙ li⁠rĕʼ֣wòţ ẖákĕmá֔h wĕ⁠hwòlél֖wòţ wĕ⁠sikĕl֑ẇţ ki֣̇y ׀ me֣h há⁠ʼádá֗m şě⁠yá̇bwòʼ֙ ʼaẖàré֣y ha⁠mė֔lekĕ ʼé֥ţ ʼàşěr-kĕ̇bá֖r ʻáşֽ̂ẇ⁠hẇ׃"],[2,13,"וְ⁠רָאִ֣יתִי אָ֔נִי שֶׁ⁠יֵּ֥שׁ יִתְר֛וֹן לַֽ⁠חָכְמָ֖ה מִן־הַ⁠סִּכְל֑וּת כִּֽ⁠יתְר֥וֹן הָ⁠א֖וֹר מִן־הַ⁠חֹֽשֶׁךְ׃","wĕ⁠ráʼi֣yţiy ʼá֔niy şě⁠yé֥̇ş̌ yiţĕr֛wòn laֽ⁠ẖákĕmá֖h min-ha⁠si̇kĕl֑ẇţ kiֽ̇⁠yţĕr֥wòn há⁠ʼ֖wòr min-ha⁠ẖòֽşěkĕ׃"],[2,14,"הֶֽ⁠חָכָם֙ עֵינָ֣י⁠ו בְּ⁠רֹאשׁ֔⁠וֹ וְ⁠הַ⁠כְּסִ֖יל בַּ⁠חֹ֣שֶׁךְ הוֹלֵ֑ךְ וְ⁠יָדַ֣עְתִּי גַם־אָ֔נִי שֶׁ⁠מִּקְרֶ֥ה אֶחָ֖ד יִקְרֶ֥ה אֶת־כֻּלָּֽ⁠ם׃","heֽ⁠ẖákám֙ ʻéyná֣y⁠w bĕ̇⁠ròʼş̌֔⁠wò wĕ⁠ha⁠kĕ̇si֖yl bȧ⁠ẖò֣şěkĕ hwòlé֑kĕ wĕ⁠yáda֣ʻĕţi̇y gam-ʼá֔niy şě⁠mi̇qĕre֥h ʼeẖá֖d yiqĕre֥h ʼeţ-ku̇láֽ̇⁠m׃"],[2,15,"וְ⁠אָמַ֨רְתִּֽי אֲנִ֜י בְּ⁠לִבִּ֗⁠י כְּ⁠מִקְרֵ֤ה הַ⁠כְּסִיל֙ גַּם־אֲנִ֣י יִקְרֵ֔⁠נִי וְ⁠לָ֧⁠מָּה חָכַ֛מְתִּי אֲנִ֖י אָ֣ז יוֹתֵ֑ר וְ⁠דִבַּ֣רְתִּי בְ⁠לִבִּ֔⁠י שֶׁ⁠גַּם־זֶ֖ה הָֽבֶל׃","wĕ⁠ʼáma֨rĕţiֽ̇y ʼàni֜y bĕ̇⁠libi̇֗⁠y kĕ̇⁠miqĕré֤h ha⁠kĕ̇siyl֙ gȧm-ʼàni֣y yiqĕré֔⁠niy wĕ⁠lá֧⁠má̇h ẖáka֛mĕţi̇y ʼàni֖y ʼá֣z ywòţé֑r wĕ⁠dibȧ֣rĕţi̇y bĕ⁠libi̇֔⁠y şě⁠gȧm-ze֖h háֽbel׃"],[2,16,"כִּי֩ אֵ֨ין זִכְר֧וֹן לֶ⁠חָכָ֛ם עִֽם־הַ⁠כְּסִ֖יל לְ⁠עוֹלָ֑ם בְּ⁠שֶׁ⁠כְּבָ֞ר הַ⁠יָּמִ֤ים הַ⁠בָּאִים֙ הַ⁠כֹּ֣ל נִשְׁכָּ֔ח וְ⁠אֵ֛יךְ יָמ֥וּת הֶ⁠חָכָ֖ם עִֽם־הַ⁠כְּסִֽיל׃","ki̇y֩ ʼé֨yn zikĕr֧wòn le⁠ẖáká֛m ʻiֽm-ha⁠kĕ̇si֖yl lĕ⁠ʻwòlá֑m bĕ̇⁠şě⁠kĕ̇bá֞r ha⁠yá̇mi֤ym ha⁠bá̇ʼiym֙ ha⁠kò֣̇l nişĕ̌ká̇֔ẖ wĕ⁠ʼé֛ykĕ yám֥ẇţ he⁠ẖáká֖m ʻiֽm-ha⁠kĕ̇siֽyl׃"],[2,17,"וְ⁠שָׂנֵ֨אתִי֙ אֶת־הַ֣⁠חַיִּ֔ים כִּ֣י רַ֤ע עָלַ⁠י֙ הַֽ⁠מַּעֲשֶׂ֔ה שֶׁ⁠נַּעֲשָׂ֖ה תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ כִּֽי־הַ⁠כֹּ֥ל הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","wĕ⁠şá̂né֨ʼţiy֙ ʼeţ-ha֣⁠ẖayi̇֔ym ki֣̇y ra֤ʻ ʻála⁠y֙ haֽ⁠mȧʻàşê֔h şě⁠nȧʻàşá֖̂h ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ kiֽ̇y-ha⁠kò֥̇l he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[2,18,"וְ⁠שָׂנֵ֤אתִֽי אֲנִי֙ אֶת־כָּל־עֲמָלִ֔⁠י שֶׁ⁠אֲנִ֥י עָמֵ֖ל תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ שֶׁ֣⁠אַנִּיחֶ֔⁠נּוּ לָ⁠אָדָ֖ם שֶׁ⁠יִּהְיֶ֥ה אַחֲרָֽ⁠י׃","wĕ⁠şá̂né֤ʼţiֽy ʼàniy֙ ʼeţ-ká̇l-ʻàmáli֔⁠y şě⁠ʼàni֥y ʻámé֖l ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ şě֣⁠ʼani̇yẖe֔⁠ṅẇ lá⁠ʼádá֖m şě⁠yi̇hĕye֥h ʼaẖàráֽ⁠y׃"],[2,19,"וּ⁠מִ֣י יוֹדֵ֗עַ הֶֽ⁠חָכָ֤ם יִהְיֶה֙ א֣וֹ סָכָ֔ל וְ⁠יִשְׁלַט֙ בְּ⁠כָל־עֲמָלִ֔⁠י שֶֽׁ⁠עָמַ֥לְתִּי וְ⁠שֶׁ⁠חָכַ֖מְתִּי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ גַּם־זֶ֖ה הָֽבֶל׃","ẇ⁠mi֣y ywòdé֗ʻa heֽ⁠ẖáká֤m yihĕyeh֙ ʼ֣wò sáká֔l wĕ⁠yişĕ̌lat֙ bĕ̇⁠kál-ʻàmáli֔⁠y şěֽ⁠ʻáma֥lĕţi̇y wĕ⁠şě⁠ẖáka֖mĕţi̇y ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ gȧm-ze֖h háֽbel׃"],[2,20,"וְ⁠סַבּ֥וֹתִֽי אֲנִ֖י לְ⁠יַאֵ֣שׁ אֶת־לִבִּ֑⁠י עַ֚ל כָּל־הֶ֣⁠עָמָ֔ל שֶׁ⁠עָמַ֖לְתִּי תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","wĕ⁠saḃ֥wòţiֽy ʼàni֖y lĕ⁠yaʼé֣ş̌ ʼeţ-libi֑̇⁠y ʻa֚l ká̇l-he֣⁠ʻámá֔l şě⁠ʻáma֖lĕţi̇y ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[2,21,"כִּי־יֵ֣שׁ אָדָ֗ם שֶׁ⁠עֲמָל֛⁠וֹ בְּ⁠חָכְמָ֥ה וּ⁠בְ⁠דַ֖עַת וּ⁠בְ⁠כִשְׁר֑וֹן וּ⁠לְ⁠אָדָ֞ם שֶׁ⁠לֹּ֤א עָֽמַל־בּ⁠וֹ֙ יִתְּנֶ֣⁠נּוּ חֶלְק֔⁠וֹ גַּם־זֶ֥ה הֶ֖בֶל וְ⁠רָעָ֥ה רַבָּֽה׃","ki̇y-yé֣ş̌ ʼádá֗m şě⁠ʻàmál֛⁠wò bĕ̇⁠ẖákĕmá֥h ẇ⁠bĕ⁠da֖ʻaţ ẇ⁠bĕ⁠kişĕ̌r֑wòn ẇ⁠lĕ⁠ʼádá֞m şě⁠lò֤̇ʼ ʻáֽmal-ḃ⁠wò֙ yiţĕ̇ne֣⁠ṅẇ ẖelĕq֔⁠wò gȧm-ze֥h he֖bel wĕ⁠ráʻá֥h rabáֽ̇h׃"],[2,22,"כִּ֠י מֶֽה־הֹוֶ֤ה לָֽ⁠אָדָם֙ בְּ⁠כָל־עֲמָל֔⁠וֹ וּ⁠בְ⁠רַעְי֖וֹן לִבּ֑⁠ו שֶׁ⁠ה֥וּא עָמֵ֖ל תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","ki̇֠y meֽh-hòwe֤h láֽ⁠ʼádám֙ bĕ̇⁠kál-ʻàmál֔⁠wò ẇ⁠bĕ⁠raʻĕy֖wòn liḃ֑⁠w şě⁠h֥ẇʼ ʻámé֖l ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[2,23,"כִּ֧י כָל־יָמָ֣י⁠ו מַכְאֹבִ֗ים וָ⁠כַ֨עַס֙ עִנְיָנ֔⁠וֹ גַּם־בַּ⁠לַּ֖יְלָה לֹא־שָׁכַ֣ב לִבּ֑⁠וֹ גַּם־זֶ֖ה הֶ֥בֶל הֽוּא׃","ki֧̇y kál-yámá֣y⁠w makĕʼòbi֗ym wá⁠ka֨ʻas֙ ʻinĕyán֔⁠wò gȧm-bȧ⁠lȧ֖yĕláh lòʼ-şá̌ka֣b liḃ֑⁠wò gȧm-ze֖h he֥bel hֽẇʼ׃"],[2,24,"אֵֽין־ט֤וֹב בָּ⁠אָדָם֙ שֶׁ⁠יֹּאכַ֣ל וְ⁠שָׁתָ֔ה וְ⁠הֶרְאָ֧ה אֶת־נַפְשׁ֛⁠וֹ ט֖וֹב בַּ⁠עֲמָל֑⁠וֹ גַּם־זֹה֙ רָאִ֣יתִי אָ֔נִי כִּ֛י מִ⁠יַּ֥ד הָ⁠אֱלֹהִ֖ים הִֽיא׃","ʼéֽyn-t֤wòb bá̇⁠ʼádám֙ şě⁠yò̇ʼka֣l wĕ⁠şá̌ţá֔h wĕ⁠herĕʼá֧h ʼeţ-napĕş֛̌⁠wò t֖wòb bȧ⁠ʻàmál֑⁠wò gȧm-zòh֙ ráʼi֣yţiy ʼá֔niy ki֛̇y mi⁠yȧ֥d há⁠ʼèlòhi֖ym hiֽyʼ׃"],[2,25,"כִּ֣י מִ֥י יֹאכַ֛ל וּ⁠מִ֥י יָח֖וּשׁ ח֥וּץ מִמֶּֽ⁠נִּי׃","ki֣̇y mi֥y yòʼka֛l ẇ⁠mi֥y yáẖ֖ẇş̌ ẖ֥ẇẕ mimėֽ⁠ni̇y׃"],[2,26,"כִּ֤י לְ⁠אָדָם֙ שֶׁ⁠טּ֣וֹב לְ⁠פָנָ֔י⁠ו נָתַ֛ן חָכְמָ֥ה וְ⁠דַ֖עַת וְ⁠שִׂמְחָ֑ה וְ⁠לַ⁠חוֹטֶא֩ נָתַ֨ן עִנְיָ֜ן לֶ⁠אֱס֣וֹף וְ⁠לִ⁠כְנ֗וֹס לָ⁠תֵת֙ לְ⁠טוֹב֙ לִ⁠פְנֵ֣י הָֽ⁠אֱלֹהִ֔ים גַּם־זֶ֥ה הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","ki֤̇y lĕ⁠ʼádám֙ şě⁠ṫ֣wòb lĕ⁠páná֔y⁠w náţa֛n ẖákĕmá֥h wĕ⁠da֖ʻaţ wĕ⁠şîmĕẖá֑h wĕ⁠la⁠ẖwòteʼ֩ náţa֨n ʻinĕyá֜n le⁠ʼès֣wòp wĕ⁠li⁠kĕn֗wòs lá⁠ţéţ֙ lĕ⁠twòb֙ li⁠pĕné֣y háֽ⁠ʼèlòhi֔ym gȧm-ze֥h he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[3,1,"לַ⁠כֹּ֖ל זְמָ֑ן וְ⁠עֵ֥ת לְ⁠כָל־חֵ֖פֶץ תַּ֥חַת הַ⁠שָּׁמָֽיִם׃ס","la⁠kò֖̇l zĕmá֑n wĕ⁠ʻé֥ţ lĕ⁠kál-ẖé֖peẕ ţȧ֥ẖaţ ha⁠şá̇̌máֽyim׃s"],[3,2,"עֵ֥ת לָ⁠לֶ֖דֶת וְ⁠עֵ֣ת לָ⁠מ֑וּת עֵ֣ת לָ⁠טַ֔עַת וְ⁠עֵ֖ת לַ⁠עֲק֥וֹר נָטֽוּעַ׃","ʻé֥ţ lá⁠le֖deţ wĕ⁠ʻé֣ţ lá⁠m֑ẇţ ʻé֣ţ lá⁠ta֔ʻaţ wĕ⁠ʻé֖ţ la⁠ʻàq֥wòr nátֽẇʻa׃"],[3,3,"עֵ֤ת לַ⁠הֲרוֹג֙ וְ⁠עֵ֣ת לִ⁠רְפּ֔וֹא עֵ֥ת לִ⁠פְר֖וֹץ וְ⁠עֵ֥ת לִ⁠בְנֽוֹת׃","ʻé֤ţ la⁠hàrwòg֙ wĕ⁠ʻé֣ţ li⁠rĕṗ֔wòʼ ʻé֥ţ li⁠pĕr֖wòẕ wĕ⁠ʻé֥ţ li⁠bĕnֽwòţ׃"],[3,4,"עֵ֤ת לִ⁠בְכּוֹת֙ וְ⁠עֵ֣ת לִ⁠שְׂח֔וֹק עֵ֥ת סְפ֖וֹד וְ⁠עֵ֥ת רְקֽוֹד׃","ʻé֤ţ li⁠bĕk̇wòţ֙ wĕ⁠ʻé֣ţ li⁠şĕ̂ẖ֔wòq ʻé֥ţ sĕp֖wòd wĕ⁠ʻé֥ţ rĕqֽwòd׃"],[3,5,"עֵ֚ת לְ⁠הַשְׁלִ֣יךְ אֲבָנִ֔ים וְ⁠עֵ֖ת כְּנ֣וֹס אֲבָנִ֑ים עֵ֣ת לַ⁠חֲב֔וֹק וְ⁠עֵ֖ת לִ⁠רְחֹ֥ק מֵ⁠חַבֵּֽק׃","ʻé֚ţ lĕ⁠haşĕ̌li֣ykĕ ʼàbáni֔ym wĕ⁠ʻé֖ţ kĕ̇n֣wòs ʼàbáni֑ym ʻé֣ţ la⁠ẖàb֔wòq wĕ⁠ʻé֖ţ li⁠rĕẖò֥q mé⁠ẖabéֽ̇q׃"],[3,6,"עֵ֤ת לְ⁠בַקֵּשׁ֙ וְ⁠עֵ֣ת לְ⁠אַבֵּ֔ד עֵ֥ת לִ⁠שְׁמ֖וֹר וְ⁠עֵ֥ת לְ⁠הַשְׁלִֽיךְ׃","ʻé֤ţ lĕ⁠baqé̇ş̌֙ wĕ⁠ʻé֣ţ lĕ⁠ʼabé̇֔d ʻé֥ţ li⁠şĕ̌m֖wòr wĕ⁠ʻé֥ţ lĕ⁠haşĕ̌liֽykĕ׃"],[3,7,"עֵ֤ת לִ⁠קְר֨וֹעַ֙ וְ⁠עֵ֣ת לִ⁠תְפּ֔וֹר עֵ֥ת לַ⁠חֲשׁ֖וֹת וְ⁠עֵ֥ת לְ⁠דַבֵּֽר׃","ʻé֤ţ li⁠qĕr֨wòʻa֙ wĕ⁠ʻé֣ţ li⁠ţĕṗ֔wòr ʻé֥ţ la⁠ẖàş֖̌wòţ wĕ⁠ʻé֥ţ lĕ⁠dabéֽ̇r׃"],[3,8,"עֵ֤ת לֶֽ⁠אֱהֹב֙ וְ⁠עֵ֣ת לִ⁠שְׂנֹ֔א עֵ֥ת מִלְחָמָ֖ה וְ⁠עֵ֥ת שָׁלֽוֹם׃ס","ʻé֤ţ leֽ⁠ʼèhòb֙ wĕ⁠ʻé֣ţ li⁠şĕ̂nò֔ʼ ʻé֥ţ milĕẖámá֖h wĕ⁠ʻé֥ţ şá̌lֽwòm׃s"],[3,9,"מַה־יִּתְרוֹן֙ הָֽ⁠עוֹשֶׂ֔ה בַּ⁠אֲשֶׁ֖ר ה֥וּא עָמֵֽל׃","mah-yi̇ţĕrwòn֙ háֽ⁠ʻwòşê֔h bȧ⁠ʼàşě֖r h֥ẇʼ ʻáméֽl׃"],[3,10,"רָאִ֣יתִי אֶת־הָֽ⁠עִנְיָ֗ן אֲשֶׁ֨ר נָתַ֧ן אֱלֹהִ֛ים לִ⁠בְנֵ֥י הָ⁠אָדָ֖ם לַ⁠עֲנ֥וֹת בּֽ⁠וֹ׃","ráʼi֣yţiy ʼeţ-háֽ⁠ʻinĕyá֗n ʼàşě֨r náţa֧n ʼèlòhi֛ym li⁠bĕné֥y há⁠ʼádá֖m la⁠ʻàn֥wòţ ḃֽ⁠wò׃"],[3,11,"אֶת־הַ⁠כֹּ֥ל עָשָׂ֖ה יָפֶ֣ה בְ⁠עִתּ֑⁠וֹ גַּ֤ם אֶת־הָ⁠עֹלָם֙ נָתַ֣ן בְּ⁠לִבָּ֔⁠ם מִ⁠בְּלִ֞י אֲשֶׁ֧ר לֹא־יִמְצָ֣א הָ⁠אָדָ֗ם אֶת־הַֽ⁠מַּעֲשֶׂ֛ה אֲשֶׁר־עָשָׂ֥ה הָ⁠אֱלֹהִ֖ים מֵ⁠רֹ֥אשׁ וְ⁠עַד־סֽוֹף׃","ʼeţ-ha⁠kò֥̇l ʻáşá֖̂h yápe֣h bĕ⁠ʻiţ֑̇⁠wò gȧ֤m ʼeţ-há⁠ʻòlám֙ náţa֣n bĕ̇⁠libá̇֔⁠m mi⁠bĕ̇li֞y ʼàşě֧r lòʼ-yimĕẕá֣ʼ há⁠ʼádá֗m ʼeţ-haֽ⁠mȧʻàşê֛h ʼàşěr-ʻáşá֥̂h há⁠ʼèlòhi֖ym mé⁠rò֥ʼş̌ wĕ⁠ʻad-sֽwòp׃"],[3,12,"יָדַ֕עְתִּי כִּ֛י אֵ֥ין ט֖וֹב בָּ֑⁠ם כִּ֣י אִם־לִ⁠שְׂמ֔וֹחַ וְ⁠לַ⁠עֲשׂ֥וֹת ט֖וֹב בְּ⁠חַיָּֽי⁠ו׃","yáda֕ʻĕţi̇y ki֛̇y ʼé֥yn t֖wòb bá֑̇⁠m ki֣̇y ʼim-li⁠şĕ̂m֔wòẖa wĕ⁠la⁠ʻàş֥̂wòţ t֖wòb bĕ̇⁠ẖayáֽ̇y⁠w׃"],[3,13,"וְ⁠גַ֤ם כָּל־הָ⁠אָדָם֙ שֶׁ⁠יֹּאכַ֣ל וְ⁠שָׁתָ֔ה וְ⁠רָאָ֥ה ט֖וֹב בְּ⁠כָל־עֲמָל֑⁠וֹ מַתַּ֥ת אֱלֹהִ֖ים הִֽיא׃","wĕ⁠ga֤m ká̇l-há⁠ʼádám֙ şě⁠yò̇ʼka֣l wĕ⁠şá̌ţá֔h wĕ⁠ráʼá֥h t֖wòb bĕ̇⁠kál-ʻàmál֑⁠wò maţȧ֥ţ ʼèlòhi֖ym hiֽyʼ׃"],[3,14,"יָדַ֗עְתִּי כִּ֠י כָּל־אֲשֶׁ֨ר יַעֲשֶׂ֤ה הָ⁠אֱלֹהִים֙ ה֚וּא יִהְיֶ֣ה לְ⁠עוֹלָ֔ם עָלָי⁠ו֙ אֵ֣ין לְ⁠הוֹסִ֔יף וּ⁠מִמֶּ֖⁠נּוּ אֵ֣ין לִ⁠גְרֹ֑עַ וְ⁠הָ⁠אֱלֹהִ֣ים עָשָׂ֔ה שֶׁ⁠יִּֽרְא֖וּ מִ⁠לְּ⁠פָנָֽי⁠ו׃","yáda֗ʻĕţi̇y ki̇֠y ká̇l-ʼàşě֨r yaʻàşê֤h há⁠ʼèlòhiym֙ h֚ẇʼ yihĕye֣h lĕ⁠ʻwòlá֔m ʻáláy⁠w֙ ʼé֣yn lĕ⁠hwòsi֔yp ẇ⁠mimė֖⁠ṅẇ ʼé֣yn li⁠gĕrò֑ʻa wĕ⁠há⁠ʼèlòhi֣ym ʻáşá̂֔h şě⁠yiֽ̇rĕʼ֖ẇ mi⁠lĕ̇⁠pánáֽy⁠w׃"],[3,15,"מַה־שֶּֽׁ⁠הָיָה֙ כְּבָ֣ר ה֔וּא וַ⁠אֲשֶׁ֥ר לִ⁠הְי֖וֹת כְּבָ֣ר הָיָ֑ה וְ⁠הָ⁠אֱלֹהִ֖ים יְבַקֵּ֥שׁ אֶת־נִרְדָּֽף׃","mah-şėֽ̌⁠háyáh֙ kĕ̇bá֣r h֔ẇʼ wa⁠ʼàşě֥r li⁠hĕy֖wòţ kĕ̇bá֣r háyá֑h wĕ⁠há⁠ʼèlòhi֖ym yĕbaqé֥̇ş̌ ʼeţ-nirĕdáֽ̇p׃"],[3,16,"וְ⁠ע֥וֹד רָאִ֖יתִי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ מְק֤וֹם הַ⁠מִּשְׁפָּט֙ שָׁ֣מָּ⁠ה הָ⁠רֶ֔שַׁע וּ⁠מְק֥וֹם הַ⁠צֶּ֖דֶק שָׁ֥מָּ⁠ה הָ⁠רָֽשַׁע׃","wĕ⁠ʻ֥wòd ráʼi֖yţiy ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ mĕq֤wòm ha⁠mi̇şĕ̌pá̇t֙ şá֣̌má̇⁠h há⁠re֔şǎʻ ẇ⁠mĕq֥wòm ha⁠ẕė֖deq şá֥̌má̇⁠h há⁠ráֽşǎʻ׃"],[3,17,"אָמַ֤רְתִּֽי אֲנִי֙ בְּ⁠לִבִּ֔⁠י אֶת־הַ⁠צַּדִּיק֙ וְ⁠אֶת־הָ֣⁠רָשָׁ֔ע יִשְׁפֹּ֖ט הָ⁠אֱלֹהִ֑ים כִּי־עֵ֣ת לְ⁠כָל־חֵ֔פֶץ וְ⁠עַ֥ל כָּל־הַֽ⁠מַּעֲשֶׂ֖ה שָֽׁם׃","ʼáma֤rĕţiֽ̇y ʼàniy֙ bĕ̇⁠libi̇֔⁠y ʼeţ-ha⁠ẕȧdi̇yq֙ wĕ⁠ʼeţ-há֣⁠ráşá̌֔ʻ yişĕ̌pò֖̇t há⁠ʼèlòhi֑ym ki̇y-ʻé֣ţ lĕ⁠kál-ẖé֔peẕ wĕ⁠ʻa֥l ká̇l-haֽ⁠mȧʻàşê֖h şáֽ̌m׃"],[3,18,"אָמַ֤רְתִּֽי אֲנִי֙ בְּ⁠לִבִּ֔⁠י עַל־דִּבְרַת֙ בְּנֵ֣י הָ⁠אָדָ֔ם לְ⁠בָרָ֖⁠ם הָ⁠אֱלֹהִ֑ים וְ⁠לִ⁠רְא֕וֹת שְׁ⁠הֶם־בְּהֵמָ֥ה הֵ֖מָּה לָ⁠הֶֽם׃","ʼáma֤rĕţiֽ̇y ʼàniy֙ bĕ̇⁠libi̇֔⁠y ʻal-di̇bĕraţ֙ bĕ̇né֣y há⁠ʼádá֔m lĕ⁠bárá֖⁠m há⁠ʼèlòhi֑ym wĕ⁠li⁠rĕʼ֕wòţ şĕ̌⁠hem-bĕ̇hémá֥h hé֖má̇h lá⁠heֽm׃"],[3,19,"כִּי֩ מִקְרֶ֨ה בְֽנֵי־הָ⁠אָדָ֜ם וּ⁠מִקְרֶ֣ה הַ⁠בְּהֵמָ֗ה וּ⁠מִקְרֶ֤ה אֶחָד֙ לָ⁠הֶ֔ם כְּ⁠מ֥וֹת זֶה֙ כֵּ֣ן מ֣וֹת זֶ֔ה וְ⁠ר֥וּחַ אֶחָ֖ד לַ⁠כֹּ֑ל וּ⁠מוֹתַ֨ר הָ⁠אָדָ֤ם מִן־הַ⁠בְּהֵמָה֙ אָ֔יִן כִּ֥י הַ⁠כֹּ֖ל הָֽבֶל׃","ki̇y֩ miqĕre֨h bĕֽnéy-há⁠ʼádá֜m ẇ⁠miqĕre֣h ha⁠bĕ̇hémá֗h ẇ⁠miqĕre֤h ʼeẖád֙ lá⁠he֔m kĕ̇⁠m֥wòţ zeh֙ ké֣̇n m֣wòţ ze֔h wĕ⁠r֥ẇẖa ʼeẖá֖d la⁠kò֑̇l ẇ⁠mwòţa֨r há⁠ʼádá֤m min-ha⁠bĕ̇hémáh֙ ʼá֔yin ki֥̇y ha⁠kò֖̇l háֽbel׃"],[3,20,"הַ⁠כֹּ֥ל הוֹלֵ֖ךְ אֶל־מָק֣וֹם אֶחָ֑ד הַ⁠כֹּל֙ הָיָ֣ה מִן־הֶֽ⁠עָפָ֔ר וְ⁠הַ⁠כֹּ֖ל שָׁ֥ב אֶל־הֶ⁠עָפָֽר׃","ha⁠kò֥̇l hwòlé֖kĕ ʼel-máq֣wòm ʼeẖá֑d ha⁠kò̇l֙ háyá֣h min-heֽ⁠ʻápá֔r wĕ⁠ha⁠kò֖̇l şá֥̌b ʼel-he⁠ʻápáֽr׃"],[3,21,"מִ֣י יוֹדֵ֗עַ ר֚וּחַ בְּנֵ֣י הָ⁠אָדָ֔ם הָ⁠עֹלָ֥ה הִ֖יא לְ⁠מָ֑עְלָ⁠ה וְ⁠ר֨וּחַ֙ הַ⁠בְּהֵמָ֔ה הַ⁠יֹּרֶ֥דֶת הִ֖יא לְ⁠מַ֥טָּה לָ⁠אָֽרֶץ׃","mi֣y ywòdé֗ʻa r֚ẇẖa bĕ̇né֣y há⁠ʼádá֔m há⁠ʻòlá֥h hi֖yʼ lĕ⁠má֑ʻĕlá⁠h wĕ⁠r֨ẇẖa֙ ha⁠bĕ̇hémá֔h ha⁠yò̇re֥deţ hi֖yʼ lĕ⁠ma֥tá̇h lá⁠ʼáֽreẕ׃"],[3,22,"וְ⁠רָאִ֗יתִי כִּ֣י אֵ֥ין טוֹב֙ מֵ⁠אֲשֶׁ֨ר יִשְׂמַ֤ח הָ⁠אָדָם֙ בְּֽ⁠מַעֲשָׂ֔י⁠ו כִּי־ה֖וּא חֶלְק֑⁠וֹ כִּ֣י מִ֤י יְבִיאֶ֨⁠נּוּ֙ לִ⁠רְא֔וֹת בְּ⁠מֶ֖ה שֶׁ⁠יִּהְיֶ֥ה אַחֲרָֽי⁠ו׃","wĕ⁠ráʼi֗yţiy ki֣̇y ʼé֥yn twòb֙ mé⁠ʼàşě֨r yişĕ̂ma֤ẖ há⁠ʼádám֙ bĕֽ̇⁠maʻàşá̂֔y⁠w ki̇y-h֖ẇʼ ẖelĕq֑⁠wò ki֣̇y mi֤y yĕbiyʼe֨⁠ṅẇ֙ li⁠rĕʼ֔wòţ bĕ̇⁠me֖h şě⁠yi̇hĕye֥h ʼaẖàráֽy⁠w׃"],[4,1,"וְ⁠שַׁ֣בְתִּֽי אֲנִ֗י וָ⁠אֶרְאֶה֙ אֶת־כָּל־הָ֣⁠עֲשֻׁקִ֔ים אֲשֶׁ֥ר נַעֲשִׂ֖ים תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ וְ⁠הִנֵּ֣ה ׀ דִּמְעַ֣ת הָ⁠עֲשֻׁקִ֗ים וְ⁠אֵ֤ין לָ⁠הֶם֙ מְנַחֵ֔ם וּ⁠מִ⁠יַּ֤ד עֹֽשְׁקֵי⁠הֶם֙ כֹּ֔חַ וְ⁠אֵ֥ין לָ⁠הֶ֖ם מְנַחֵֽם׃","wĕ⁠şǎ֣bĕţiֽ̇y ʼàni֗y wá⁠ʼerĕʼeh֙ ʼeţ-ká̇l-há֣⁠ʻàşǔqi֔ym ʼàşě֥r naʻàşî֖ym ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ wĕ⁠hiné֣̇h ׀ di̇mĕʻa֣ţ há⁠ʻàşǔqi֗ym wĕ⁠ʼé֤yn lá⁠hem֙ mĕnaẖé֔m ẇ⁠mi⁠yȧ֤d ʻòֽşĕ̌qéy⁠hem֙ kò̇֔ẖa wĕ⁠ʼé֥yn lá⁠he֖m mĕnaẖéֽm׃"],[4,2,"וְ⁠שַׁבֵּ֧חַ אֲנִ֛י אֶת־הַ⁠מֵּתִ֖ים שֶׁ⁠כְּבָ֣ר מֵ֑תוּ מִן־הַ֣⁠חַיִּ֔ים אֲשֶׁ֛ר הֵ֥מָּה חַיִּ֖ים עֲדֶֽנָ⁠ה׃","wĕ⁠şǎbé֧̇ẖa ʼàni֛y ʼeţ-ha⁠mé̇ţi֖ym şě⁠kĕ̇bá֣r mé֑ţẇ min-ha֣⁠ẖayi̇֔ym ʼàşě֛r hé֥má̇h ẖayi֖̇ym ʻàdeֽná⁠h׃"],[4,3,"וְ⁠טוֹב֙ מִ⁠שְּׁנֵי⁠הֶ֔ם אֵ֥ת אֲשֶׁר־עֲדֶ֖ן לֹ֣א הָיָ֑ה אֲשֶׁ֤ר לֹֽא־רָאָה֙ אֶת־הַ⁠מַּעֲשֶׂ֣ה הָ⁠רָ֔ע אֲשֶׁ֥ר נַעֲשָׂ֖ה תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","wĕ⁠twòb֙ mi⁠şĕ̇̌néy⁠he֔m ʼé֥ţ ʼàşěr-ʻàde֖n lò֣ʼ háyá֑h ʼàşě֤r lòֽʼ-ráʼáh֙ ʼeţ-ha⁠mȧʻàşê֣h há⁠rá֔ʻ ʼàşě֥r naʻàşá֖̂h ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[4,4,"וְ⁠רָאִ֨יתִֽי אֲנִ֜י אֶת־כָּל־עָמָ֗ל וְ⁠אֵת֙ כָּל־כִּשְׁר֣וֹן הַֽ⁠מַּעֲשֶׂ֔ה כִּ֛י הִ֥יא קִנְאַת־אִ֖ישׁ מֵ⁠רֵעֵ֑⁠הוּ גַּם־זֶ֥ה הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","wĕ⁠ráʼi֨yţiֽy ʼàni֜y ʼeţ-ká̇l-ʻámá֗l wĕ⁠ʼéţ֙ ká̇l-ki̇şĕ̌r֣wòn haֽ⁠mȧʻàşê֔h ki֛̇y hi֥yʼ qinĕʼaţ-ʼi֖yş̌ mé⁠réʻé֑⁠hẇ gȧm-ze֥h he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[4,5,"הַ⁠כְּסִיל֙ חֹבֵ֣ק אֶת־יָדָ֔י⁠ו וְ⁠אֹכֵ֖ל אֶת־בְּשָׂרֽ⁠וֹ׃","ha⁠kĕ̇siyl֙ ẖòbé֣q ʼeţ-yádá֔y⁠w wĕ⁠ʼòké֖l ʼeţ-bĕ̇şá̂rֽ⁠wò׃"],[4,6,"ט֕וֹב מְלֹ֥א כַ֖ף נָ֑חַת מִ⁠מְּלֹ֥א חָפְנַ֛יִם עָמָ֖ל וּ⁠רְע֥וּת רֽוּחַ׃","t֕wòb mĕlò֥ʼ ka֖p ná֑ẖaţ mi⁠mĕ̇lò֥ʼ ẖápĕna֛yim ʻámá֖l ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[4,7,"וְ⁠שַׁ֧בְתִּי אֲנִ֛י וָ⁠אֶרְאֶ֥ה הֶ֖בֶל תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","wĕ⁠şǎ֧bĕţi̇y ʼàni֛y wá⁠ʼerĕʼe֥h he֖bel ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[4,8,"יֵ֣שׁ אֶחָד֩ וְ⁠אֵ֨ין שֵׁנִ֜י גַּ֣ם בֵּ֧ן וָ⁠אָ֣ח אֵֽין־ל֗⁠וֹ וְ⁠אֵ֥ין קֵץ֙ לְ⁠כָל־עֲמָל֔⁠וֹ גַּם־עיני⁠ו לֹא־תִשְׂבַּ֣ע עֹ֑שֶׁר וּ⁠לְ⁠מִ֣י ׀ אֲנִ֣י עָמֵ֗ל וּ⁠מְחַסֵּ֤ר אֶת־נַפְשִׁ⁠י֙ מִ⁠טּוֹבָ֔ה גַּם־זֶ֥ה הֶ֛בֶל וְ⁠עִנְיַ֥ן רָ֖ע הֽוּא׃","yé֣ş̌ ʼeẖád֩ wĕ⁠ʼé֨yn şé̌ni֜y gȧ֣m bé֧̇n wá⁠ʼá֣ẖ ʼéֽyn-l֗⁠wò wĕ⁠ʼé֥yn qéẕ֙ lĕ⁠kál-ʻàmál֔⁠wò gȧm-ʻyny⁠w lòʼ-ţişĕ̂bȧ֣ʻ ʻò֑şěr ẇ⁠lĕ⁠mi֣y ׀ ʼàni֣y ʻámé֗l ẇ⁠mĕẖasé֤̇r ʼeţ-napĕşǐ⁠y֙ mi⁠ṫwòbá֔h gȧm-ze֥h he֛bel wĕ⁠ʻinĕya֥n rá֖ʻ hֽẇʼ׃"],[4,9,"טוֹבִ֥ים הַ⁠שְּׁנַ֖יִם מִן־הָ⁠אֶחָ֑ד אֲשֶׁ֧ר יֵשׁ־לָ⁠הֶ֛ם שָׂכָ֥ר ט֖וֹב בַּ⁠עֲמָלָֽ⁠ם׃","twòbi֥ym ha⁠şĕ̇̌na֖yim min-há⁠ʼeẖá֑d ʼàşě֧r yéş̌-lá⁠he֛m şá̂ká֥r t֖wòb bȧ⁠ʻàmáláֽ⁠m׃"],[4,10,"כִּ֣י אִם־יִפֹּ֔לוּ הָ⁠אֶחָ֖ד יָקִ֣ים אֶת־חֲבֵר֑⁠וֹ וְ⁠אִ֣י⁠ל֗⁠וֹ הָֽ⁠אֶחָד֙ שֶׁ⁠יִּפּ֔וֹל וְ⁠אֵ֥ין שֵׁנִ֖י לַ⁠הֲקִימֽ⁠וֹ׃","ki֣̇y ʼim-yipò̇֔lẇ há⁠ʼeẖá֖d yáqi֣ym ʼeţ-ẖàbér֑⁠wò wĕ⁠ʼi֣y⁠l֗⁠wò háֽ⁠ʼeẖád֙ şě⁠yi̇ṗ֔wòl wĕ⁠ʼé֥yn şé̌ni֖y la⁠hàqiymֽ⁠wò׃"],[4,11,"גַּ֛ם אִם־יִשְׁכְּב֥וּ שְׁנַ֖יִם וְ⁠חַ֣ם לָ⁠הֶ֑ם וּ⁠לְ⁠אֶחָ֖ד אֵ֥יךְ יֵחָֽם׃","gȧ֛m ʼim-yişĕ̌kĕ̇b֥ẇ şĕ̌na֖yim wĕ⁠ẖa֣m lá⁠he֑m ẇ⁠lĕ⁠ʼeẖá֖d ʼé֥ykĕ yéẖáֽm׃"],[4,12,"וְ⁠אִֽם־יִתְקְפ⁠וֹ֙ הָ⁠אֶחָ֔ד הַ⁠שְּׁנַ֖יִם יַעַמְד֣וּ נֶגְדּ֑⁠וֹ וְ⁠הַ⁠חוּט֙ הַֽ⁠מְשֻׁלָּ֔שׁ לֹ֥א בִ⁠מְהֵרָ֖ה יִנָּתֵֽק׃","wĕ⁠ʼiֽm-yiţĕqĕp⁠wò֙ há⁠ʼeẖá֔d ha⁠şĕ̇̌na֖yim yaʻamĕd֣ẇ negĕḋ֑⁠wò wĕ⁠ha⁠ẖẇt֙ haֽ⁠mĕşǔlá̇֔ş̌ lò֥ʼ bi⁠mĕhérá֖h yiná̇ţéֽq׃"],[4,13,"ט֛וֹב יֶ֥לֶד מִסְכֵּ֖ן וְ⁠חָכָ֑ם מִ⁠מֶּ֤לֶךְ זָקֵן֙ וּ⁠כְסִ֔יל אֲשֶׁ֛ר לֹא־יָדַ֥ע לְ⁠הִזָּהֵ֖ר עֽוֹד׃","t֛wòb ye֥led misĕké֖̇n wĕ⁠ẖáká֑m mi⁠mė֤lekĕ záqén֙ ẇ⁠kĕsi֔yl ʼàşě֛r lòʼ-yáda֥ʻ lĕ⁠hizá̇hé֖r ʻֽwòd׃"],[4,14,"כִּֽי־מִ⁠בֵּ֥ית הָ⁠סוּרִ֖ים יָצָ֣א לִ⁠מְלֹ֑ךְ כִּ֛י גַּ֥ם בְּ⁠מַלְכוּת֖⁠וֹ נוֹלַ֥ד רָֽשׁ׃","kiֽ̇y-mi⁠bé֥̇yţ há⁠sẇri֖ym yáẕá֣ʼ li⁠mĕlò֑kĕ ki֛̇y gȧ֥m bĕ̇⁠malĕkẇţ֖⁠wò nwòla֥d ráֽş̌׃"],[4,15,"רָאִ֨יתִי֙ אֶת־כָּל־הַ֣⁠חַיִּ֔ים הַֽ⁠מְהַלְּכִ֖ים תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ עִ֚ם הַ⁠יֶּ֣לֶד הַ⁠שֵּׁנִ֔י אֲשֶׁ֥ר יַעֲמֹ֖ד תַּחְתָּֽי⁠ו׃","ráʼi֨yţiy֙ ʼeţ-ká̇l-ha֣⁠ẖayi̇֔ym haֽ⁠mĕhalĕ̇ki֖ym ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ʻi֚m ha⁠yė֣led ha⁠şé̇̌ni֔y ʼàşě֥r yaʻàmò֖d ţȧẖĕţáֽ̇y⁠w׃"],[4,16,"אֵֽין־קֵ֣ץ לְ⁠כָל־הָ⁠עָ֗ם לְ⁠כֹ֤ל אֲשֶׁר־הָיָה֙ לִ⁠פְנֵי⁠הֶ֔ם גַּ֥ם הָ⁠אַחֲרוֹנִ֖ים לֹ֣א יִשְׂמְחוּ־ב֑⁠וֹ כִּֽי־גַם־זֶ֥ה הֶ֖בֶל וְ⁠רַעְי֥וֹן רֽוּחַ׃","ʼéֽyn-qé֣ẕ lĕ⁠kál-há⁠ʻá֗m lĕ⁠kò֤l ʼàşěr-háyáh֙ li⁠pĕnéy⁠he֔m gȧ֥m há⁠ʼaẖàrwòni֖ym lò֣ʼ yişĕ̂mĕẖẇ-b֑⁠wò kiֽ̇y-gam-ze֥h he֖bel wĕ⁠raʻĕy֥wòn rֽẇẖa׃"],[5,1,"שְׁמֹ֣ר רגלי⁠ך כַּ⁠אֲשֶׁ֤ר תֵּלֵךְ֙ אֶל־בֵּ֣ית הָ⁠אֱלֹהִ֔ים וְ⁠קָר֣וֹב לִ⁠שְׁמֹ֔עַ מִ⁠תֵּ֥ת הַ⁠כְּסִילִ֖ים זָ֑בַח כִּֽי־אֵינָ֥⁠ם יוֹדְעִ֖ים לַ⁠עֲשׂ֥וֹת רָֽע׃","şĕ̌mò֣r rgly⁠k kȧ⁠ʼàşě֤r ţé̇lékĕ֙ ʼel-bé֣̇yţ há⁠ʼèlòhi֔ym wĕ⁠qár֣wòb li⁠şĕ̌mò֔ʻa mi⁠ţé֥̇ţ ha⁠kĕ̇siyli֖ym zá֑baẖ kiֽ̇y-ʼéyná֥⁠m ywòdĕʻi֖ym la⁠ʻàş֥̂wòţ ráֽʻ׃"],[5,2,"אַל־תְּבַהֵ֨ל עַל־פִּ֜י⁠ךָ וְ⁠לִבְּ⁠ךָ֧ אַל־יְמַהֵ֛ר לְ⁠הוֹצִ֥יא דָבָ֖ר לִ⁠פְנֵ֣י הָ⁠אֱלֹהִ֑ים כִּ֣י הָ⁠אֱלֹהִ֤ים בַּ⁠שָּׁמַ֨יִם֙ וְ⁠אַתָּ֣ה עַל־הָ⁠אָ֔רֶץ עַֽל־כֵּ֛ן יִהְי֥וּ דְבָרֶ֖י⁠ךָ מְעַטִּֽים׃","ʼal-ţĕ̇bahé֨l ʻal-pi̇֜y⁠ká wĕ⁠libĕ̇⁠ká֧ ʼal-yĕmahé֛r lĕ⁠hwòẕi֥yʼ dábá֖r li⁠pĕné֣y há⁠ʼèlòhi֑ym ki֣̇y há⁠ʼèlòhi֤ym bȧ⁠şá̇̌ma֨yim֙ wĕ⁠ʼaţá֣̇h ʻal-há⁠ʼá֔reẕ ʻaֽl-ké֛̇n yihĕy֥ẇ dĕbáre֖y⁠ká mĕʻatiֽ̇ym׃"],[5,3,"כִּ֛י בָּ֥א הַ⁠חֲל֖וֹם בְּ⁠רֹ֣ב עִנְיָ֑ן וְ⁠ק֥וֹל כְּסִ֖יל בְּ⁠רֹ֥ב דְּבָרִֽים׃","ki֛̇y bá֥̇ʼ ha⁠ẖàl֖wòm bĕ̇⁠rò֣b ʻinĕyá֑n wĕ⁠q֥wòl kĕ̇si֖yl bĕ̇⁠rò֥b dĕ̇báriֽym׃"],[5,4,"כַּ⁠אֲשֶׁר֩ תִּדֹּ֨ר נֶ֜דֶר לֵֽ⁠אלֹהִ֗ים אַל־תְּאַחֵר֙ לְ⁠שַׁלְּמ֔⁠וֹ כִּ֛י אֵ֥ין חֵ֖פֶץ בַּ⁠כְּסִילִ֑ים אֵ֥ת אֲשֶׁר־תִּדֹּ֖ר שַׁלֵּֽם׃","kȧ⁠ʼàşěr֩ ţi̇dò̇֨r ne֜der lֽé⁠ʼlòhi֗ym ʼal-ţĕ̇ʼaẖér֙ lĕ⁠şǎlĕ̇m֔⁠wò ki֛̇y ʼé֥yn ẖé֖peẕ bȧ⁠kĕ̇siyli֑ym ʼé֥ţ ʼàşěr-ţi̇dò֖̇r şǎléֽ̇m׃"],[5,5,"ט֖וֹב אֲשֶׁ֣ר לֹֽא־תִדֹּ֑ר מִ⁠שֶׁ⁠תִּדּ֖וֹר וְ⁠לֹ֥א תְשַׁלֵּֽם׃","t֖wòb ʼàşě֣r lòֽʼ-ţidò֑̇r mi⁠şě⁠ţi̇ḋ֖wòr wĕ⁠lò֥ʼ ţĕşǎléֽ̇m׃"],[5,6,"אַל־תִּתֵּ֤ן אֶת־פִּ֨י⁠ךָ֙ לַ⁠חֲטִ֣יא אֶת־בְּשָׂרֶ֔⁠ךָ וְ⁠אַל־תֹּאמַר֙ לִ⁠פְנֵ֣י הַ⁠מַּלְאָ֔ךְ כִּ֥י שְׁגָגָ֖ה הִ֑יא לָ֣⁠מָּה יִקְצֹ֤ף הָֽ⁠אֱלֹהִים֙ עַל־קוֹלֶ֔⁠ךָ וְ⁠חִבֵּ֖ל אֶת־מַעֲשֵׂ֥ה יָדֶֽי⁠ךָ׃","ʼal-ţi̇ţé֤̇n ʼeţ-pi̇֨y⁠ká֙ la⁠ẖàti֣yʼ ʼeţ-bĕ̇şá̂re֔⁠ká wĕ⁠ʼal-ţò̇ʼmar֙ li⁠pĕné֣y ha⁠mȧlĕʼá֔kĕ ki֥̇y şĕ̌gágá֖h hi֑yʼ lá֣⁠má̇h yiqĕẕò֤p háֽ⁠ʼèlòhiym֙ ʻal-qwòle֔⁠ká wĕ⁠ẖibé֖̇l ʼeţ-maʻàşé֥̂h yádeֽy⁠ká׃"],[5,7,"כִּ֣י בְ⁠רֹ֤ב חֲלֹמוֹת֙ וַ⁠הֲבָלִ֔ים וּ⁠דְבָרִ֖ים הַרְבֵּ֑ה כִּ֥י אֶת־הָ⁠אֱלֹהִ֖ים יְרָֽא׃","ki֣̇y bĕ⁠rò֤b ẖàlòmwòţ֙ wa⁠hàbáli֔ym ẇ⁠dĕbári֖ym harĕbé֑̇h ki֥̇y ʼeţ-há⁠ʼèlòhi֖ym yĕráֽʼ׃"],[5,8,"אִם־עֹ֣שֶׁק רָ֠שׁ וְ⁠גֵ֨זֶל מִשְׁפָּ֤ט וָ⁠צֶ֨דֶק֙ תִּרְאֶ֣ה בַ⁠מְּדִינָ֔ה אַל־תִּתְמַ֖הּ עַל־הַ⁠חֵ֑פֶץ כִּ֣י גָבֹ֜הַּ מֵ⁠עַ֤ל גָּבֹ֨הַ֙ שֹׁמֵ֔ר וּ⁠גְבֹהִ֖ים עֲלֵי⁠הֶֽם׃","ʼim-ʻò֣şěq rá֠ş̌ wĕ⁠gé֨zel mişĕ̌pá֤̇t wá⁠ẕe֨deq֙ ţi̇rĕʼe֣h ba⁠mĕ̇diyná֔h ʼal-ţi̇ţĕma֖ḣ ʻal-ha⁠ẖé֑peẕ ki֣̇y gábò֜hȧ mé⁠ʻa֤l gá̇bò֨ha֙ şò̌mé֔r ẇ⁠gĕbòhi֖ym ʻàléy⁠heֽm׃"],[5,9,"וְ⁠יִתְר֥וֹן אֶ֖רֶץ בַּ⁠כֹּ֣ל היא מֶ֥לֶךְ לְ⁠שָׂדֶ֖ה נֶעֱבָֽד׃","wĕ⁠yiţĕr֥wòn ʼe֖reẕ bȧ⁠kò֣̇l hyʼ me֥lekĕ lĕ⁠şá̂de֖h neʻèbáֽd׃"],[5,10,"אֹהֵ֥ב כֶּ֨סֶף֙ לֹא־יִשְׂבַּ֣ע כֶּ֔סֶף וּ⁠מִֽי־אֹהֵ֥ב בֶּ⁠הָמ֖וֹן לֹ֣א תְבוּאָ֑ה גַּם־זֶ֖ה הָֽבֶל׃","ʼòhé֥b kė֨sep֙ lòʼ-yişĕ̂bȧ֣ʻ kė֔sep ẇ⁠miֽy-ʼòhé֥b bė⁠hám֖wòn lò֣ʼ ţĕbẇʼá֑h gȧm-ze֖h háֽbel׃"],[5,11,"בִּ⁠רְבוֹת֙ הַ⁠טּוֹבָ֔ה רַבּ֖וּ אוֹכְלֶ֑י⁠הָ וּ⁠מַה־כִּשְׁרוֹן֙ לִ⁠בְעָלֶ֔י⁠הָ כִּ֖י אִם־ראית עֵינָֽי⁠ו׃","bi̇⁠rĕbwòţ֙ ha⁠ṫwòbá֔h raḃ֖ẇ ʼwòkĕle֑y⁠há ẇ⁠mah-ki̇şĕ̌rwòn֙ li⁠bĕʻále֔y⁠há ki֖̇y ʼim-rʼyţ ʻéynáֽy⁠w׃"],[5,12,"מְתוּקָה֙ שְׁנַ֣ת הָ⁠עֹבֵ֔ד אִם־מְעַ֥ט וְ⁠אִם־הַרְבֵּ֖ה יֹאכֵ֑ל וְ⁠הַ⁠שָּׂבָע֙ לֶֽ⁠עָשִׁ֔יר אֵינֶ֛⁠נּוּ מַנִּ֥יחַֽ ל֖⁠וֹ לִ⁠ישֽׁוֹן׃","mĕţẇqáh֙ şĕ̌na֣ţ há⁠ʻòbé֔d ʼim-mĕʻa֥t wĕ⁠ʼim-harĕbé֖̇h yòʼké֑l wĕ⁠ha⁠şá̇̂báʻ֙ leֽ⁠ʻáşǐ֔yr ʼéyne֛⁠ṅẇ mani֥̇yẖaֽ l֖⁠wò li⁠yşֽ̌wòn׃"],[5,13,"יֵ֚שׁ רָעָ֣ה חוֹלָ֔ה רָאִ֖יתִי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ עֹ֛שֶׁר שָׁמ֥וּר לִ⁠בְעָלָ֖י⁠ו לְ⁠רָעָתֽ⁠וֹ׃","yé֚ş̌ ráʻá֣h ẖwòlá֔h ráʼi֖yţiy ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ʻò֛şěr şá̌m֥ẇr li⁠bĕʻálá֖y⁠w lĕ⁠ráʻáţֽ⁠wò׃"],[5,14,"וְ⁠אָבַ֛ד הָ⁠עֹ֥שֶׁר הַ⁠ה֖וּא בְּ⁠עִנְיַ֣ן רָ֑ע וְ⁠הוֹלִ֣יד בֵּ֔ן וְ⁠אֵ֥ין בְּ⁠יָד֖⁠וֹ מְאֽוּמָה׃","wĕ⁠ʼába֛d há⁠ʻò֥şěr ha⁠h֖ẇʼ bĕ̇⁠ʻinĕya֣n rá֑ʻ wĕ⁠hwòli֣yd bé̇֔n wĕ⁠ʼé֥yn bĕ̇⁠yád֖⁠wò mĕʼֽẇmáh׃"],[5,15,"כַּ⁠אֲשֶׁ֤ר יָצָא֙ מִ⁠בֶּ֣טֶן אִמּ֔⁠וֹ עָר֛וֹם יָשׁ֥וּב לָ⁠לֶ֖כֶת כְּ⁠שֶׁ⁠בָּ֑א וּ⁠מְא֨וּמָה֙ לֹא־יִשָּׂ֣א בַ⁠עֲמָל֔⁠וֹ שֶׁ⁠יֹּלֵ֖ךְ בְּ⁠יָדֽ⁠וֹ׃","kȧ⁠ʼàşě֤r yáẕáʼ֙ mi⁠bė֣ten ʼiṁ֔⁠wò ʻár֛wòm yáş֥̌ẇb lá⁠le֖keţ kĕ̇⁠şě⁠bá֑̇ʼ ẇ⁠mĕʼ֨ẇmáh֙ lòʼ-yişá֣̇̂ʼ ba⁠ʻàmál֔⁠wò şě⁠yò̇lé֖kĕ bĕ̇⁠yádֽ⁠wò׃"],[5,16,"וְ⁠גַם־זֹה֙ רָעָ֣ה חוֹלָ֔ה כָּ⁠ל־עֻמַּ֥ת שֶׁ⁠בָּ֖א כֵּ֣ן יֵלֵ֑ךְ וּ⁠מַה־יִּתְר֣וֹן ל֔⁠וֹ שֶֽׁ⁠יַּעֲמֹ֖ל לָ⁠רֽוּחַ׃","wĕ⁠gam-zòh֙ ráʻá֣h ẖwòlá֔h ká̇⁠l-ʻumȧ֥ţ şě⁠bá֖̇ʼ ké֣̇n yélé֑kĕ ẇ⁠mah-yi̇ţĕr֣wòn l֔⁠wò şěֽ⁠yȧʻàmò֖l lá⁠rֽẇẖa׃"],[5,17,"גַּ֥ם כָּל־יָמָ֖י⁠ו בַּ⁠חֹ֣שֶׁךְ יֹאכֵ֑ל וְ⁠כָעַ֥ס הַרְבֵּ֖ה וְ⁠חָלְי֥⁠וֹ וָ⁠קָֽצֶף׃","gȧ֥m ká̇l-yámá֖y⁠w bȧ⁠ẖò֣şěkĕ yòʼké֑l wĕ⁠káʻa֥s harĕbé֖̇h wĕ⁠ẖálĕy֥⁠wò wá⁠qáֽẕep׃"],[5,18,"הִנֵּ֞ה אֲשֶׁר־רָאִ֣יתִי אָ֗נִי ט֣וֹב אֲשֶׁר־יָפֶ֣ה לֶֽ⁠אֶכוֹל־וְ֠⁠לִ⁠שְׁתּוֹת וְ⁠לִ⁠רְא֨וֹת טוֹבָ֜ה בְּ⁠כָל־עֲמָל֣⁠וֹ ׀ שֶׁ⁠יַּעֲמֹ֣ל תַּֽחַת־הַ⁠שֶּׁ֗מֶשׁ מִסְפַּ֧ר יְמֵי־חי⁠ו אֲשֶׁר־נָֽתַן־ל֥⁠וֹ הָ⁠אֱלֹהִ֖ים כִּי־ה֥וּא חֶלְקֽ⁠וֹ׃","hiné̇֞h ʼàşěr-ráʼi֣yţiy ʼá֗niy t֣wòb ʼàşěr-yápe֣h leֽ⁠ʼekwòl-wĕ֠⁠li⁠şĕ̌ţ̇wòţ wĕ⁠li⁠rĕʼ֨wòţ twòbá֜h bĕ̇⁠kál-ʻàmál֣⁠wò ׀ şě⁠yȧʻàmò֣l ţȧֽẖaţ-ha⁠şė̌֗meş̌ misĕpȧ֧r yĕméy-ẖy⁠w ʼàşěr-náֽţan-l֥⁠wò há⁠ʼèlòhi֖ym ki̇y-h֥ẇʼ ẖelĕqֽ⁠wò׃"],[5,19,"גַּ֣ם כָּֽל־הָ⁠אָדָ֡ם אֲשֶׁ֣ר נָֽתַן־ל֣⁠וֹ הָ⁠אֱלֹהִים֩ עֹ֨שֶׁר וּ⁠נְכָסִ֜ים וְ⁠הִשְׁלִיט֨⁠וֹ לֶ⁠אֱכֹ֤ל מִמֶּ֨⁠נּוּ֙ וְ⁠לָ⁠שֵׂ֣את אֶת־חֶלְק֔⁠וֹ וְ⁠לִ⁠שְׂמֹ֖חַ בַּ⁠עֲמָל֑⁠וֹ זֹ֕ה מַתַּ֥ת אֱלֹהִ֖ים הִֽיא׃","gȧ֣m káֽ̇l-há⁠ʼádá֡m ʼàşě֣r náֽţan-l֣⁠wò há⁠ʼèlòhiym֩ ʻò֨şěr ẇ⁠nĕkási֜ym wĕ⁠hişĕ̌liyt֨⁠wò le⁠ʼèkò֤l mimė֨⁠ṅẇ֙ wĕ⁠lá⁠şé֣̂ʼţ ʼeţ-ẖelĕq֔⁠wò wĕ⁠li⁠şĕ̂mò֖ẖa bȧ⁠ʻàmál֑⁠wò zò֕h maţȧ֥ţ ʼèlòhi֖ym hiֽyʼ׃"],[5,20,"כִּ֚י לֹ֣א הַרְבֵּ֔ה יִזְכֹּ֖ר אֶת־יְמֵ֣י חַיָּ֑י⁠ו כִּ֧י הָ⁠אֱלֹהִ֛ים מַעֲנֶ֖ה בְּ⁠שִׂמְחַ֥ת לִבּֽ⁠וֹ׃","ki֚̇y lò֣ʼ harĕbé̇֔h yizĕkò֖̇r ʼeţ-yĕmé֣y ẖayá֑̇y⁠w ki֧̇y há⁠ʼèlòhi֛ym maʻàne֖h bĕ̇⁠şîmĕẖa֥ţ liḃֽ⁠wò׃"],[6,1,"יֵ֣שׁ רָעָ֔ה אֲשֶׁ֥ר רָאִ֖יתִי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ וְ⁠רַבָּ֥ה הִ֖יא עַל־הָ⁠אָדָֽם׃","yé֣ş̌ ráʻá֔h ʼàşě֥r ráʼi֖yţiy ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ wĕ⁠rabá֥̇h hi֖yʼ ʻal-há⁠ʼádáֽm׃"],[6,2,"אִ֣ישׁ אֲשֶׁ֣ר יִתֶּן־ל֣⁠וֹ הָ⁠אֱלֹהִ֡ים עֹשֶׁר֩ וּ⁠נְכָסִ֨ים וְ⁠כָב֜וֹד וְֽ⁠אֵינֶ֨⁠נּוּ חָסֵ֥ר לְ⁠נַפְשׁ֣⁠וֹ ׀ מִ⁠כֹּ֣ל אֲשֶׁר־יִתְאַוֶּ֗ה וְ⁠לֹֽא־יַשְׁלִיטֶ֤⁠נּוּ הָֽ⁠אֱלֹהִים֙ לֶ⁠אֱכֹ֣ל מִמֶּ֔⁠נּוּ כִּ֛י אִ֥ישׁ נָכְרִ֖י יֹֽאכֲלֶ֑⁠נּוּ זֶ֥ה הֶ֛בֶל וָ⁠חֳלִ֥י רָ֖ע הֽוּא׃","ʼi֣yş̌ ʼàşě֣r yiţėn-l֣⁠wò há⁠ʼèlòhi֡ym ʻòşěr֩ ẇ⁠nĕkási֨ym wĕ⁠káb֜wòd wĕֽ⁠ʼéyne֨⁠ṅẇ ẖásé֥r lĕ⁠napĕş֣̌⁠wò ׀ mi⁠kò֣̇l ʼàşěr-yiţĕʼawė֗h wĕ⁠lòֽʼ-yaşĕ̌liyte֤⁠ṅẇ háֽ⁠ʼèlòhiym֙ le⁠ʼèkò֣l mimė֔⁠ṅẇ ki֛̇y ʼi֥yş̌ nákĕri֖y yòֽʼkàle֑⁠ṅẇ ze֥h he֛bel wá⁠ẖoli֥y rá֖ʻ hֽẇʼ׃"],[6,3,"אִם־יוֹלִ֣יד אִ֣ישׁ מֵאָ֡ה וְ⁠שָׁנִים֩ רַבּ֨וֹת יִֽחְיֶ֜ה וְ⁠רַ֣ב ׀ שֶׁ⁠יִּהְי֣וּ יְמֵֽי־שָׁנָ֗י⁠ו וְ⁠נַפְשׁ⁠וֹ֙ לֹא־תִשְׂבַּ֣ע מִן־הַ⁠טּוֹבָ֔ה וְ⁠גַם־קְבוּרָ֖ה לֹא־הָ֣יְתָה לּ֑⁠וֹ אָמַ֕רְתִּי ט֥וֹב מִמֶּ֖⁠נּוּ הַ⁠נָּֽפֶל׃","ʼim-ywòli֣yd ʼi֣yş̌ méʼá֡h wĕ⁠şá̌niym֩ raḃ֨wòţ yiֽẖĕye֜h wĕ⁠ra֣b ׀ şě⁠yi̇hĕy֣ẇ yĕméֽy-şá̌ná֗y⁠w wĕ⁠napĕş̌⁠wò֙ lòʼ-ţişĕ̂bȧ֣ʻ min-ha⁠ṫwòbá֔h wĕ⁠gam-qĕbẇrá֖h lòʼ-há֣yĕţáh l֑̇⁠wò ʼáma֕rĕţi̇y t֥wòb mimė֖⁠ṅẇ ha⁠náֽ̇pel׃"],[6,4,"כִּֽי־בַ⁠הֶ֥בֶל בָּ֖א וּ⁠בַ⁠חֹ֣שֶׁךְ יֵלֵ֑ךְ וּ⁠בַ⁠חֹ֖שֶׁךְ שְׁמ֥⁠וֹ יְכֻסֶּֽה׃","kiֽ̇y-ba⁠he֥bel bá֖̇ʼ ẇ⁠ba⁠ẖò֣şěkĕ yélé֑kĕ ẇ⁠ba⁠ẖò֖şěkĕ şĕ̌m֥⁠wò yĕkusėֽh׃"],[6,5,"גַּם־שֶׁ֥מֶשׁ לֹא־רָאָ֖ה וְ⁠לֹ֣א יָדָ֑ע נַ֥חַת לָ⁠זֶ֖ה מִ⁠זֶּֽה׃","gȧm-şě֥meş̌ lòʼ-ráʼá֖h wĕ⁠lò֣ʼ yádá֑ʻ na֥ẖaţ lá⁠ze֖h mi⁠zėֽh׃"],[6,6,"וְ⁠אִלּ֣וּ חָיָ֗ה אֶ֤לֶף שָׁנִים֙ פַּעֲמַ֔יִם וְ⁠טוֹבָ֖ה לֹ֣א רָאָ֑ה הֲ⁠לֹ֛א אֶל־מָק֥וֹם אֶחָ֖ד הַ⁠כֹּ֥ל הוֹלֵֽךְ׃","wĕ⁠ʼil֣̇ẇ ẖáyá֗h ʼe֤lep şá̌niym֙ pȧʻàma֔yim wĕ⁠twòbá֖h lò֣ʼ ráʼá֑h hà⁠lò֛ʼ ʼel-máq֥wòm ʼeẖá֖d ha⁠kò֥̇l hwòléֽkĕ׃"],[6,7,"כָּל־עֲמַ֥ל הָ⁠אָדָ֖ם לְ⁠פִ֑י⁠הוּ וְ⁠גַם־הַ⁠נֶּ֖פֶשׁ לֹ֥א תִמָּלֵֽא׃","ká̇l-ʻàma֥l há⁠ʼádá֖m lĕ⁠pi֑y⁠hẇ wĕ⁠gam-ha⁠nė֖peş̌ lò֥ʼ ţimá̇léֽʼ׃"],[6,8,"כִּ֛י מַה־יּוֹתֵ֥ר לֶ⁠חָכָ֖ם מִֽן־הַ⁠כְּסִ֑יל מַה־לֶּ⁠עָנִ֣י יוֹדֵ֔עַ לַ⁠הֲלֹ֖ךְ נֶ֥גֶד הַ⁠חַיִּֽים׃","ki֛̇y mah-ẏwòţé֥r le⁠ẖáká֖m miֽn-ha⁠kĕ̇si֑yl mah-lė⁠ʻáni֣y ywòdé֔ʻa la⁠hàlò֖kĕ ne֥ged ha⁠ẖayiֽ̇ym׃"],[6,9,"ט֛וֹב מַרְאֵ֥ה עֵינַ֖יִם מֵֽ⁠הֲלָךְ־נָ֑פֶשׁ גַּם־זֶ֥ה הֶ֖בֶל וּ⁠רְע֥וּת רֽוּחַ׃","t֛wòb marĕʼé֥h ʻéyna֖yim méֽ⁠hàlákĕ-ná֑peş̌ gȧm-ze֥h he֖bel ẇ⁠rĕʻ֥ẇţ rֽẇẖa׃"],[6,10,"מַה־שֶּֽׁ⁠הָיָ֗ה כְּבָר֙ נִקְרָ֣א שְׁמ֔⁠וֹ וְ⁠נוֹדָ֖ע אֲשֶׁר־ה֣וּא אָדָ֑ם וְ⁠לֹא־יוּכַ֣ל לָ⁠דִ֔ין עִ֥ם ש⁠התקיף מִמֶּֽ⁠נּוּ׃","mah-şėֽ̌⁠háyá֗h kĕ̇bár֙ niqĕrá֣ʼ şĕ̌m֔⁠wò wĕ⁠nwòdá֖ʻ ʼàşěr-h֣ẇʼ ʼádá֑m wĕ⁠lòʼ-yẇka֣l lá⁠di֔yn ʻi֥m ş⁠hţqyp mimėֽ⁠ṅẇ׃"],[6,11,"כִּ֛י יֵשׁ־דְּבָרִ֥ים הַרְבֵּ֖ה מַרְבִּ֣ים הָ֑בֶל מַה־יֹּתֵ֖ר לָ⁠אָדָֽם׃","ki֛̇y yéş̌-dĕ̇bári֥ym harĕbé֖̇h marĕbi֣̇ym há֑bel mah-yò̇ţé֖r lá⁠ʼádáֽm׃"],[6,12,"כִּ֣י מִֽי־יוֹדֵעַ֩ מַה־טּ֨וֹב לָֽ⁠אָדָ֜ם בַּֽ⁠חַיִּ֗ים מִסְפַּ֛ר יְמֵי־חַיֵּ֥י הֶבְל֖⁠וֹ וְ⁠יַעֲשֵׂ֣⁠ם כַּ⁠צֵּ֑ל אֲשֶׁר֙ מִֽי־יַגִּ֣יד לָֽ⁠אָדָ֔ם מַה־יִּהְיֶ֥ה אַחֲרָ֖י⁠ו תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","ki֣̇y miֽy-ywòdéʻa֩ mah-ṫ֨wòb láֽ⁠ʼádá֜m bȧֽ⁠ẖayi̇֗ym misĕpȧ֛r yĕméy-ẖayé֥̇y hebĕl֖⁠wò wĕ⁠yaʻàşé֣̂⁠m kȧ⁠ẕé֑̇l ʼàşěr֙ miֽy-yagi֣̇yd láֽ⁠ʼádá֔m mah-yi̇hĕye֥h ʼaẖàrá֖y⁠w ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[7,1,"ט֥וֹב שֵׁ֖ם מִ⁠שֶּׁ֣מֶן ט֑וֹב וְ⁠י֣וֹם הַ⁠מָּ֔וֶת מִ⁠יּ֖וֹם הִוָּלְדֽ⁠וֹ׃","t֥wòb şé֖̌m mi⁠şė֣̌men t֑wòb wĕ⁠y֣wòm ha⁠má̇֔weţ mi⁠ẏ֖wòm hiwá̇lĕdֽ⁠wò׃"],[7,2,"ט֞וֹב לָ⁠לֶ֣כֶת אֶל־בֵּֽית־אֵ֗בֶל מִ⁠לֶּ֨כֶת֙ אֶל־בֵּ֣ית מִשְׁתֶּ֔ה בַּ⁠אֲשֶׁ֕ר ה֖וּא ס֣וֹף כָּל־הָ⁠אָדָ֑ם וְ⁠הַ⁠חַ֖י יִתֵּ֥ן אֶל־לִבּֽ⁠וֹ׃","t֞wòb lá⁠le֣keţ ʼel-béֽ̇yţ-ʼé֗bel mi⁠lė֨keţ֙ ʼel-bé֣̇yţ mişĕ̌ţė֔h bȧ⁠ʼàşě֕r h֖ẇʼ s֣wòp ká̇l-há⁠ʼádá֑m wĕ⁠ha⁠ẖa֖y yiţé֥̇n ʼel-liḃֽ⁠wò׃"],[7,3,"ט֥וֹב כַּ֖עַס מִ⁠שְּׂחֹ֑ק כִּֽי־בְ⁠רֹ֥עַ פָּנִ֖ים יִ֥יטַב לֵֽב׃","t֥wòb kȧ֖ʻas mi⁠şĕ̇̂ẖò֑q kiֽ̇y-bĕ⁠rò֥ʻa pá̇ni֖ym yi֥ytab léֽb׃"],[7,4,"לֵ֤ב חֲכָמִים֙ בְּ⁠בֵ֣ית אֵ֔בֶל וְ⁠לֵ֥ב כְּסִילִ֖ים בְּ⁠בֵ֥ית שִׂמְחָֽה׃","lé֤b ẖàkámiym֙ bĕ̇⁠bé֣yţ ʼé֔bel wĕ⁠lé֥b kĕ̇siyli֖ym bĕ̇⁠bé֥yţ şîmĕẖáֽh׃"],[7,5,"ט֕וֹב לִ⁠שְׁמֹ֖עַ גַּעֲרַ֣ת חָכָ֑ם מֵ⁠אִ֕ישׁ שֹׁמֵ֖עַ שִׁ֥יר כְּסִילִֽים׃","t֕wòb li⁠şĕ̌mò֖ʻa gȧʻàra֣ţ ẖáká֑m mé⁠ʼi֕yş̌ şò̌mé֖ʻa şǐ֥yr kĕ̇siyliֽym׃"],[7,6,"כִּ֣י כְ⁠ק֤וֹל הַ⁠סִּירִים֙ תַּ֣חַת הַ⁠סִּ֔יר כֵּ֖ן שְׂחֹ֣ק הַ⁠כְּסִ֑יל וְ⁠גַם־זֶ֖ה הָֽבֶל׃","ki֣̇y kĕ⁠q֤wòl ha⁠si̇yriym֙ ţȧ֣ẖaţ ha⁠si̇֔yr ké֖̇n şĕ̂ẖò֣q ha⁠kĕ̇si֑yl wĕ⁠gam-ze֖h háֽbel׃"],[7,7,"כִּ֥י הָ⁠עֹ֖שֶׁק יְהוֹלֵ֣ל חָכָ֑ם וִֽ⁠יאַבֵּ֥ד אֶת־לֵ֖ב מַתָּנָֽה׃","ki֥̇y há⁠ʻò֖şěq yĕhwòlé֣l ẖáká֑m wiֽ⁠yʼabé֥̇d ʼeţ-lé֖b maţá̇náֽh׃"],[7,8,"ט֛וֹב אַחֲרִ֥ית דָּבָ֖ר מֵֽ⁠רֵאשִׁית֑⁠וֹ ט֥וֹב אֶֽרֶךְ־ר֖וּחַ מִ⁠גְּבַהּ־רֽוּחַ׃","t֛wòb ʼaẖàri֥yţ dá̇bá֖r mֽé⁠réʼşǐyţ֑⁠wò t֥wòb ʼeֽrekĕ-r֖ẇẖa mi⁠gĕ̇baḣ-rֽẇẖa׃"],[7,9,"אַל־תְּבַהֵ֥ל בְּ⁠רֽוּחֲ⁠ךָ֖ לִ⁠כְע֑וֹס כִּ֣י כַ֔עַס בְּ⁠חֵ֥יק כְּסִילִ֖ים יָנֽוּחַ׃","ʼal-ţĕ̇bahé֥l bĕ̇⁠rֽẇẖà⁠ká֖ li⁠kĕʻ֑wòs ki֣̇y ka֔ʻas bĕ̇⁠ẖé֥yq kĕ̇siyli֖ym yánֽẇẖa׃"],[7,10,"אַל־תֹּאמַר֙ מֶ֣ה הָיָ֔ה שֶׁ֤⁠הַ⁠יָּמִים֙ הָ⁠רִ֣אשֹׁנִ֔ים הָי֥וּ טוֹבִ֖ים מֵ⁠אֵ֑לֶּה כִּ֛י לֹ֥א מֵ⁠חָכְמָ֖ה שָׁאַ֥לְתָּ עַל־זֶֽה׃","ʼal-ţò̇ʼmar֙ me֣h háyá֔h şě֤⁠ha⁠yá̇miym֙ há⁠ri֣ʼşò̌ni֔ym háy֥ẇ twòbi֖ym mé⁠ʼé֑lėh ki֛̇y lò֥ʼ mé⁠ẖákĕmá֖h şá̌ʼa֥lĕţá̇ ʻal-zeֽh׃"],[7,11,"טוֹבָ֥ה חָכְמָ֖ה עִֽם־נַחֲלָ֑ה וְ⁠יֹתֵ֖ר לְ⁠רֹאֵ֥י הַ⁠שָּֽׁמֶשׁ׃","twòbá֥h ẖákĕmá֖h ʻiֽm-naẖàlá֑h wĕ⁠yòţé֖r lĕ⁠ròʼé֥y ha⁠şáֽ̇̌meş̌׃"],[7,12,"כִּ֛י בְּ⁠צֵ֥ל הַֽ⁠חָכְמָ֖ה בְּ⁠צֵ֣ל הַ⁠כָּ֑סֶף וְ⁠יִתְר֣וֹן דַּ֔עַת הַֽ⁠חָכְמָ֖ה תְּחַיֶּ֥ה בְעָלֶֽי⁠הָ׃","ki֛̇y bĕ̇⁠ẕé֥l haֽ⁠ẖákĕmá֖h bĕ̇⁠ẕé֣l ha⁠ká֑̇sep wĕ⁠yiţĕr֣wòn dȧ֔ʻaţ haֽ⁠ẖákĕmá֖h ţĕ̇ẖayė֥h bĕʻáleֽy⁠há׃"],[7,13,"רְאֵ֖ה אֶת־מַעֲשֵׂ֣ה הָ⁠אֱלֹהִ֑ים כִּ֣י מִ֤י יוּכַל֙ לְ⁠תַקֵּ֔ן אֵ֖ת אֲשֶׁ֥ר עִוְּתֽ⁠וֹ׃","rĕʼé֖h ʼeţ-maʻàşé֣̂h há⁠ʼèlòhi֑ym ki֣̇y mi֤y yẇkal֙ lĕ⁠ţaqé̇֔n ʼé֖ţ ʼàşě֥r ʻiwĕ̇ţֽ⁠wò׃"],[7,14,"בְּ⁠י֤וֹם טוֹבָה֙ הֱיֵ֣ה בְ⁠ט֔וֹב וּ⁠בְ⁠י֥וֹם רָעָ֖ה רְאֵ֑ה גַּ֣ם אֶת־זֶ֤ה לְ⁠עֻמַּת־זֶה֙ עָשָׂ֣ה הָֽ⁠אֱלֹהִ֔ים עַל־דִּבְרַ֗ת שֶׁ⁠לֹּ֨א יִמְצָ֧א הָֽ⁠אָדָ֛ם אַחֲרָ֖י⁠ו מְאֽוּמָה׃","bĕ̇⁠y֤wòm twòbáh֙ hèyé֣h bĕ⁠t֔wòb ẇ⁠bĕ⁠y֥wòm ráʻá֖h rĕʼé֑h gȧ֣m ʼeţ-ze֤h lĕ⁠ʻumȧţ-zeh֙ ʻáşá֣̂h háֽ⁠ʼèlòhi֔ym ʻal-di̇bĕra֗ţ şě⁠lò̇֨ʼ yimĕẕá֧ʼ háֽ⁠ʼádá֛m ʼaẖàrá֖y⁠w mĕʼֽẇmáh׃"],[7,15,"אֶת־הַ⁠כֹּ֥ל רָאִ֖יתִי בִּ⁠ימֵ֣י הֶבְלִ֑⁠י יֵ֤שׁ צַדִּיק֙ אֹבֵ֣ד בְּ⁠צִדְק֔⁠וֹ וְ⁠יֵ֣שׁ רָשָׁ֔ע מַאֲרִ֖יךְ בְּ⁠רָעָתֽ⁠וֹ׃","ʼeţ-ha⁠kò֥̇l ráʼi֖yţiy bi̇⁠ymé֣y hebĕli֑⁠y yé֤ş̌ ẕadi̇yq֙ ʼòbé֣d bĕ̇⁠ẕidĕq֔⁠wò wĕ⁠yé֣ş̌ ráşá̌֔ʻ maʼàri֖ykĕ bĕ̇⁠ráʻáţֽ⁠wò׃"],[7,16,"אַל־תְּהִ֤י צַדִּיק֙ הַרְבֵּ֔ה וְ⁠אַל־תִּתְחַכַּ֖ם יוֹתֵ֑ר לָ֖⁠מָּה תִּשּׁוֹמֵֽם׃","ʼal-ţĕ̇hi֤y ẕadi̇yq֙ harĕbé̇֔h wĕ⁠ʼal-ţi̇ţĕẖakȧ֖m ywòţé֑r lá֖⁠má̇h ţi̇ş̇̌wòméֽm׃"],[7,17,"אַל־תִּרְשַׁ֥ע הַרְבֵּ֖ה וְ⁠אַל־תְּהִ֣י סָכָ֑ל לָ֥⁠מָּה תָמ֖וּת בְּ⁠לֹ֥א עִתֶּֽ⁠ךָ׃","ʼal-ţi̇rĕşǎ֥ʻ harĕbé֖̇h wĕ⁠ʼal-ţĕ̇hi֣y sáká֑l lá֥⁠má̇h ţám֖ẇţ bĕ̇⁠lò֥ʼ ʻiţėֽ⁠ká׃"],[7,18,"ט֚וֹב אֲשֶׁ֣ר תֶּאֱחֹ֣ז בָּ⁠זֶ֔ה וְ⁠גַם־מִ⁠זֶּ֖ה אַל־תַּנַּ֣ח אֶת־יָדֶ֑⁠ךָ כִּֽי־יְרֵ֥א אֱלֹהִ֖ים יֵצֵ֥א אֶת־כֻּלָּֽ⁠ם׃","t֚wòb ʼàşě֣r ţėʼèẖò֣z bá̇⁠ze֔h wĕ⁠gam-mi⁠zė֖h ʼal-ţȧnȧ֣ẖ ʼeţ-yáde֑⁠ká kiֽ̇y-yĕré֥ʼ ʼèlòhi֖ym yéẕé֥ʼ ʼeţ-ku̇láֽ̇⁠m׃"],[7,19,"הַֽ⁠חָכְמָ֖ה תָּעֹ֣ז לֶ⁠חָכָ֑ם מֵֽ⁠עֲשָׂרָה֙ שַׁלִּיטִ֔ים אֲשֶׁ֥ר הָי֖וּ בָּ⁠עִֽיר׃","haֽ⁠ẖákĕmá֖h ţá̇ʻò֣z le⁠ẖáká֑m méֽ⁠ʻàşá̂ráh֙ şǎli̇yti֔ym ʼàşě֥r háy֖ẇ bá̇⁠ʻiֽyr׃"],[7,20,"כִּ֣י אָדָ֔ם אֵ֥ין צַדִּ֖יק בָּ⁠אָ֑רֶץ אֲשֶׁ֥ר יַעֲשֶׂה־טּ֖וֹב וְ⁠לֹ֥א יֶחֱטָֽא׃","ki֣̇y ʼádá֔m ʼé֥yn ẕadi֖̇yq bá̇⁠ʼá֑reẕ ʼàşě֥r yaʻàşêh-ṫ֖wòb wĕ⁠lò֥ʼ yeẖètáֽʼ׃"],[7,21,"גַּ֤ם לְ⁠כָל־הַ⁠דְּבָרִים֙ אֲשֶׁ֣ר יְדַבֵּ֔רוּ אַל־תִּתֵּ֖ן לִבֶּ֑⁠ךָ אֲשֶׁ֥ר לֹֽא־תִשְׁמַ֥ע אֶֽת־עַבְדְּ⁠ךָ֖ מְקַלְלֶֽ⁠ךָ׃","gȧ֤m lĕ⁠kál-ha⁠dĕ̇báriym֙ ʼàşě֣r yĕdabé̇֔rẇ ʼal-ţi̇ţé֖̇n libė֑⁠ká ʼàşě֥r lòֽʼ-ţişĕ̌ma֥ʻ ʼeֽţ-ʻabĕdĕ̇⁠ká֖ mĕqalĕleֽ⁠ká׃"],[7,22,"כִּ֛י גַּם־פְּעָמִ֥ים רַבּ֖וֹת יָדַ֣ע לִבֶּ֑⁠ךָ אֲשֶׁ֥ר גַּם־את קִלַּ֥לְתָּ אֲחֵרִֽים׃","ki֛̇y gȧm-pĕ̇ʻámi֥ym raḃ֖wòţ yáda֣ʻ libė֑⁠ká ʼàşě֥r gȧm-ʼţ qilȧ֥lĕţá̇ ʼàẖériֽym׃"],[7,23,"כָּל־זֹ֖ה נִסִּ֣יתִי בַֽ⁠חָכְמָ֑ה אָמַ֣רְתִּי אֶחְכָּ֔מָה וְ⁠הִ֖יא רְחוֹקָ֥ה מִמֶּֽ⁠נִּי׃","ká̇l-zò֖h nisi֣̇yţiy baֽ⁠ẖákĕmá֑h ʼáma֣rĕţi̇y ʼeẖĕká̇֔máh wĕ⁠hi֖yʼ rĕẖwòqá֥h mimėֽ⁠ni̇y׃"],[7,24,"רָח֖וֹק מַה־שֶּׁ⁠הָיָ֑ה וְ⁠עָמֹ֥ק ׀ עָמֹ֖ק מִ֥י יִמְצָאֶֽ⁠נּוּ׃","ráẖ֖wòq mah-şė̌⁠háyá֑h wĕ⁠ʻámò֥q ׀ ʻámò֖q mi֥y yimĕẕáʼeֽ⁠ṅẇ׃"],[7,25,"סַבּ֨וֹתִֽי אֲנִ֤י וְ⁠לִבִּ⁠י֙ לָ⁠דַ֣עַת וְ⁠לָ⁠ת֔וּר וּ⁠בַקֵּ֥שׁ חָכְמָ֖ה וְ⁠חֶשְׁבּ֑וֹן וְ⁠לָ⁠דַ֨עַת֙ רֶ֣שַׁע כֶּ֔סֶל וְ⁠הַ⁠סִּכְל֖וּת הוֹלֵלֽוֹת׃","saḃ֨wòţiֽy ʼàni֤y wĕ⁠libi̇⁠y֙ lá⁠da֣ʻaţ wĕ⁠lá⁠ţ֔ẇr ẇ⁠baqé֥̇ş̌ ẖákĕmá֖h wĕ⁠ẖeşĕ̌ḃ֑wòn wĕ⁠lá⁠da֨ʻaţ֙ re֣şǎʻ kė֔sel wĕ⁠ha⁠si̇kĕl֖ẇţ hwòlélֽwòţ׃"],[7,26,"וּ⁠מוֹצֶ֨א אֲנִ֜י מַ֣ר מִ⁠מָּ֗וֶת אֶת־הָֽ⁠אִשָּׁה֙ אֲשֶׁר־הִ֨יא מְצוֹדִ֧ים וַ⁠חֲרָמִ֛ים לִבָּ֖⁠הּ אֲסוּרִ֣ים יָדֶ֑י⁠הָ ט֞וֹב לִ⁠פְנֵ֤י הָ⁠אֱלֹהִים֙ יִמָּלֵ֣ט מִמֶּ֔⁠נָּה וְ⁠חוֹטֵ֖א יִלָּ֥כֶד בָּֽ⁠הּ׃","ẇ⁠mwòẕe֨ʼ ʼàni֜y ma֣r mi⁠má̇֗weţ ʼeţ-háֽ⁠ʼişá̇̌h֙ ʼàşěr-hi֨yʼ mĕẕwòdi֧ym wa⁠ẖàrámi֛ym libá֖̇⁠ḣ ʼàsẇri֣ym yáde֑y⁠há t֞wòb li⁠pĕné֤y há⁠ʼèlòhiym֙ yimá̇lé֣t mimė֔⁠ná̇h wĕ⁠ẖwòté֖ʼ yilá֥̇ked báֽ̇⁠ḣ׃"],[7,27,"רְאֵה֙ זֶ֣ה מָצָ֔אתִי אָמְרָ֖ה קֹהֶ֑לֶת אַחַ֥ת לְ⁠אַחַ֖ת לִ⁠מְצֹ֥א חֶשְׁבּֽוֹן׃","rĕʼéh֙ ze֣h máẕá֔ʼţiy ʼámĕrá֖h qòhe֑leţ ʼaẖa֥ţ lĕ⁠ʼaẖa֖ţ li⁠mĕẕò֥ʼ ẖeşĕ̌ḃֽwòn׃"],[7,28,"אֲשֶׁ֛ר עוֹד־בִּקְשָׁ֥ה נַפְשִׁ֖⁠י וְ⁠לֹ֣א מָצָ֑אתִי אָדָ֞ם אֶחָ֤ד מֵ⁠אֶ֨לֶף֙ מָצָ֔אתִי וְ⁠אִשָּׁ֥ה בְ⁠כָל־אֵ֖לֶּה לֹ֥א מָצָֽאתִי׃","ʼàşě֛r ʻwòd-bi̇qĕşá֥̌h napĕşǐ֖⁠y wĕ⁠lò֣ʼ máẕá֑ʼţiy ʼádá֞m ʼeẖá֤d mé⁠ʼe֨lep֙ máẕá֔ʼţiy wĕ⁠ʼişá֥̇̌h bĕ⁠kál-ʼé֖lėh lò֥ʼ máẕáֽʼţiy׃"],[7,29,"לְ⁠בַד֙ רְאֵה־זֶ֣ה מָצָ֔אתִי אֲשֶׁ֨ר עָשָׂ֧ה הָ⁠אֱלֹהִ֛ים אֶת־הָ⁠אָדָ֖ם יָשָׁ֑ר וְ⁠הֵ֥מָּה בִקְשׁ֖וּ חִשְּׁבֹנ֥וֹת רַבִּֽים׃","lĕ⁠bad֙ rĕʼéh-ze֣h máẕá֔ʼţiy ʼàşě֨r ʻáşá֧̂h há⁠ʼèlòhi֛ym ʼeţ-há⁠ʼádá֖m yáşá֑̌r wĕ⁠hé֥má̇h biqĕş֖̌ẇ ẖişĕ̇̌bòn֥wòţ rabiֽ̇ym׃"],[8,1,"מִ֚י כְּ⁠הֶ֣⁠חָכָ֔ם וּ⁠מִ֥י יוֹדֵ֖עַ פֵּ֣שֶׁר דָּבָ֑ר חָכְמַ֤ת אָדָם֙ תָּאִ֣יר פָּנָ֔י⁠ו וְ⁠עֹ֥ז פָּנָ֖י⁠ו יְשֻׁנֶּֽא׃","mi֚y kĕ̇⁠he֣⁠ẖáká֔m ẇ⁠mi֥y ywòdé֖ʻa pé֣̇şěr dá̇bá֑r ẖákĕma֤ţ ʼádám֙ ţá̇ʼi֣yr pá̇ná֔y⁠w wĕ⁠ʻò֥z pá̇ná֖y⁠w yĕşǔnėֽʼ׃"],[8,2,"אֲנִי֙ פִּי־מֶ֣לֶךְ שְׁמ֔וֹר וְ⁠עַ֕ל דִּבְרַ֖ת שְׁבוּעַ֥ת אֱלֹהִֽים׃","ʼàniy֙ pi̇y-me֣lekĕ şĕ̌m֔wòr wĕ⁠ʻa֕l di̇bĕra֖ţ şĕ̌bẇʻa֥ţ ʼèlòhiֽym׃"],[8,3,"אַל־תִּבָּהֵ֤ל מִ⁠פָּנָי⁠ו֙ תֵּלֵ֔ךְ אַֽל־תַּעֲמֹ֖ד בְּ⁠דָבָ֣ר רָ֑ע כִּ֛י כָּל־אֲשֶׁ֥ר יַחְפֹּ֖ץ יַעֲשֶֽׂה׃","ʼal-ţi̇bá̇hé֤l mi⁠pá̇náy⁠w֙ ţé̇lé֔kĕ ʼaֽl-ţȧʻàmò֖d bĕ̇⁠dábá֣r rá֑ʻ ki֛̇y ká̇l-ʼàşě֥r yaẖĕpò֖̇ẕ yaʻàşêֽh׃"],[8,4,"בַּ⁠אֲשֶׁ֥ר דְּבַר־מֶ֖לֶךְ שִׁלְט֑וֹן וּ⁠מִ֥י יֹֽאמַר־ל֖⁠וֹ מַֽה־תַּעֲשֶֽׂה׃","bȧ⁠ʼàşě֥r dĕ̇bar-me֖lekĕ şǐlĕt֑wòn ẇ⁠mi֥y yòֽʼmar-l֖⁠wò maֽh-ţȧʻàşêֽh׃"],[8,5,"שׁוֹמֵ֣ר מִצְוָ֔ה לֹ֥א יֵדַ֖ע דָּבָ֣ר רָ֑ע וְ⁠עֵ֣ת וּ⁠מִשְׁפָּ֔ט יֵדַ֖ע לֵ֥ב חָכָֽם׃","ş̌wòmé֣r miẕĕwá֔h lò֥ʼ yéda֖ʻ dá̇bá֣r rá֑ʻ wĕ⁠ʻé֣ţ ẇ⁠mişĕ̌pá̇֔t yéda֖ʻ lé֥b ẖákáֽm׃"],[8,6,"כִּ֣י לְ⁠כָל־חֵ֔פֶץ יֵ֖שׁ עֵ֣ת וּ⁠מִשְׁפָּ֑ט כִּֽי־רָעַ֥ת הָ⁠אָדָ֖ם רַבָּ֥ה עָלָֽי⁠ו׃","ki֣̇y lĕ⁠kál-ẖé֔peẕ yé֖ş̌ ʻé֣ţ ẇ⁠mişĕ̌pá֑̇t kiֽ̇y-ráʻa֥ţ há⁠ʼádá֖m rabá֥̇h ʻáláֽy⁠w׃"],[8,7,"כִּֽי־אֵינֶ֥⁠נּוּ יֹדֵ֖עַ מַה־שֶּׁ⁠יִּֽהְיֶ֑ה כִּ֚י כַּ⁠אֲשֶׁ֣ר יִֽהְיֶ֔ה מִ֖י יַגִּ֥יד לֽ⁠וֹ׃","kiֽ̇y-ʼéyne֥⁠ṅẇ yòdé֖ʻa mah-şė̌⁠yiֽ̇hĕye֑h ki֚̇y kȧ⁠ʼàşě֣r yiֽhĕye֔h mi֖y yagi֥̇yd lֽ⁠wò׃"],[8,8,"אֵ֣ין אָדָ֞ם שַׁלִּ֤יט בָּ⁠ר֨וּחַ֙ לִ⁠כְל֣וֹא אֶת־הָ⁠ר֔וּחַ וְ⁠אֵ֤ין שִׁלְטוֹן֙ בְּ⁠י֣וֹם הַ⁠מָּ֔וֶת וְ⁠אֵ֥ין מִשְׁלַ֖חַת בַּ⁠מִּלְחָמָ֑ה וְ⁠לֹֽא־יְמַלֵּ֥ט רֶ֖שַׁע אֶת־בְּעָלָֽי⁠ו׃","ʼé֣yn ʼádá֞m şǎli֤̇yt bá̇⁠r֨ẇẖa֙ li⁠kĕl֣wòʼ ʼeţ-há⁠r֔ẇẖa wĕ⁠ʼé֤yn şǐlĕtwòn֙ bĕ̇⁠y֣wòm ha⁠má̇֔weţ wĕ⁠ʼé֥yn mişĕ̌la֖ẖaţ bȧ⁠mi̇lĕẖámá֑h wĕ⁠lòֽʼ-yĕmalé֥̇t re֖şǎʻ ʼeţ-bĕ̇ʻáláֽy⁠w׃"],[8,9,"אֶת־כָּל־זֶ֤ה רָאִ֨יתִי֙ וְ⁠נָת֣וֹן אֶת־לִבִּ֔⁠י לְ⁠כָֽל־מַעֲשֶׂ֔ה אֲשֶׁ֥ר נַעֲשָׂ֖ה תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ עֵ֗ת אֲשֶׁ֨ר שָׁלַ֧ט הָ⁠אָדָ֛ם בְּ⁠אָדָ֖ם לְ⁠רַ֥ע לֽ⁠וֹ׃","ʼeţ-ká̇l-ze֤h ráʼi֨yţiy֙ wĕ⁠náţ֣wòn ʼeţ-libi̇֔⁠y lĕ⁠káֽl-maʻàşê֔h ʼàşě֥r naʻàşá֖̂h ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ʻé֗ţ ʼàşě֨r şá̌la֧t há⁠ʼádá֛m bĕ̇⁠ʼádá֖m lĕ⁠ra֥ʻ lֽ⁠wò׃"],[8,10,"וּ⁠בְ⁠כֵ֡ן רָאִיתִי֩ רְשָׁעִ֨ים קְבֻרִ֜ים וָ⁠בָ֗אוּ וּ⁠מִ⁠מְּק֤וֹם קָדוֹשׁ֙ יְהַלֵּ֔כוּ וְ⁠יִֽשְׁתַּכְּח֥וּ בָ⁠עִ֖יר אֲשֶׁ֣ר כֵּן־עָשׂ֑וּ גַּם־זֶ֖ה הָֽבֶל׃","ẇ⁠bĕ⁠ké֡n ráʼiyţiy֩ rĕşá̌ʻi֨ym qĕburi֜ym wá⁠bá֗ʼẇ ẇ⁠mi⁠mĕ̇q֤wòm qádwòş̌֙ yĕhalé̇֔kẇ wĕ⁠yiֽşĕ̌ţȧkĕ̇ẖ֥ẇ bá⁠ʻi֖yr ʼàşě֣r ké̇n-ʻáş֑̂ẇ gȧm-ze֖h háֽbel׃"],[8,11,"אֲשֶׁר֙ אֵין־נַעֲשָׂ֣ה פִתְגָ֔ם מַעֲשֵׂ֥ה הָ⁠רָעָ֖ה מְהֵרָ֑ה עַל־כֵּ֡ן מָלֵ֞א לֵ֧ב בְּֽנֵי־הָ⁠אָדָ֛ם בָּ⁠הֶ֖ם לַ⁠עֲשׂ֥וֹת רָֽע׃","ʼàşěr֙ ʼéyn-naʻàşá֣̂h piţĕgá֔m maʻàşé֥̂h há⁠ráʻá֖h mĕhérá֑h ʻal-ké̇֡n málé֞ʼ lé֧b bĕֽ̇néy-há⁠ʼádá֛m bá̇⁠he֖m la⁠ʻàş֥̂wòţ ráֽʻ׃"],[8,12,"אֲשֶׁ֣ר חֹטֶ֗א עֹשֶׂ֥ה רָ֛ע מְאַ֖ת וּ⁠מַאֲרִ֣יךְ ל֑⁠וֹ כִּ֚י גַּם־יוֹדֵ֣עַ אָ֔נִי אֲשֶׁ֤ר יִהְיֶה־טּוֹב֙ לְ⁠יִרְאֵ֣י הָ⁠אֱלֹהִ֔ים אֲשֶׁ֥ר יִֽירְא֖וּ מִ⁠לְּ⁠פָנָֽי⁠ו׃","ʼàşě֣r ẖòte֗ʼ ʻòşê֥h rá֛ʻ mĕʼa֖ţ ẇ⁠maʼàri֣ykĕ l֑⁠wò ki֚̇y gȧm-ywòdé֣ʻa ʼá֔niy ʼàşě֤r yihĕyeh-ṫwòb֙ lĕ⁠yirĕʼé֣y há⁠ʼèlòhi֔ym ʼàşě֥r yiֽyrĕʼ֖ẇ mi⁠lĕ̇⁠pánáֽy⁠w׃"],[8,13,"וְ⁠טוֹב֙ לֹֽא־יִהְיֶ֣ה לָֽ⁠רָשָׁ֔ע וְ⁠לֹֽא־יַאֲרִ֥יךְ יָמִ֖ים כַּ⁠צֵּ֑ל אֲשֶׁ֛ר אֵינֶ֥⁠נּוּ יָרֵ֖א מִ⁠לִּ⁠פְנֵ֥י אֱלֹהִֽים׃","wĕ⁠twòb֙ lòֽʼ-yihĕye֣h láֽ⁠ráşá̌֔ʻ wĕ⁠lòֽʼ-yaʼàri֥ykĕ yámi֖ym kȧ⁠ẕé֑̇l ʼàşě֛r ʼéyne֥⁠ṅẇ yáré֖ʼ mi⁠li̇⁠pĕné֥y ʼèlòhiֽym׃"],[8,14,"יֶשׁ־הֶבֶל֮ אֲשֶׁ֣ר נַעֲשָׂ֣ה עַל־הָ⁠אָרֶץ֒ אֲשֶׁ֣ר ׀ יֵ֣שׁ צַדִּיקִ֗ים אֲשֶׁ֨ר מַגִּ֤יעַ אֲלֵ⁠הֶם֙ כְּ⁠מַעֲשֵׂ֣ה הָ⁠רְשָׁעִ֔ים וְ⁠יֵ֣שׁ רְשָׁעִ֔ים שֶׁ⁠מַּגִּ֥יעַ אֲלֵ⁠הֶ֖ם כְּ⁠מַעֲשֵׂ֣ה הַ⁠צַּדִּיקִ֑ים אָמַ֕רְתִּי שֶׁ⁠גַּם־זֶ֖ה הָֽבֶל׃","yeş̌-hebel֮ ʼàşě֣r naʻàşá֣̂h ʻal-há⁠ʼáreẕ֒ ʼàşě֣r ׀ yé֣ş̌ ẕadi̇yqi֗ym ʼàşě֨r magi֤̇yʻa ʼàlé⁠hem֙ kĕ̇⁠maʻàşé֣̂h há⁠rĕşá̌ʻi֔ym wĕ⁠yé֣ş̌ rĕşá̌ʻi֔ym şě⁠mȧgi֥̇yʻa ʼàlé⁠he֖m kĕ̇⁠maʻàşé֣̂h ha⁠ẕȧdi̇yqi֑ym ʼáma֕rĕţi̇y şě⁠gȧm-ze֖h háֽbel׃"],[8,15,"וְ⁠שִׁבַּ֤חְתִּֽי אֲנִי֙ אֶת־הַ⁠שִּׂמְחָ֔ה אֲשֶׁ֨ר אֵֽין־ט֤וֹב לָֽ⁠אָדָם֙ תַּ֣חַת הַ⁠שֶּׁ֔מֶשׁ כִּ֛י אִם־לֶ⁠אֱכ֥וֹל וְ⁠לִ⁠שְׁתּ֖וֹת וְ⁠לִ⁠שְׂמ֑וֹחַ וְ⁠ה֞וּא יִלְוֶ֣⁠נּוּ בַ⁠עֲמָל֗⁠וֹ יְמֵ֥י חַיָּ֛י⁠ו אֲשֶׁר־נָֽתַן־ל֥⁠וֹ הָ⁠אֱלֹהִ֖ים תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","wĕ⁠şǐbȧ֤ẖĕţiֽ̇y ʼàniy֙ ʼeţ-ha⁠şi̇̂mĕẖá֔h ʼàşě֨r ʼéֽyn-t֤wòb láֽ⁠ʼádám֙ ţȧ֣ẖaţ ha⁠şė̌֔meş̌ ki֛̇y ʼim-le⁠ʼèk֥wòl wĕ⁠li⁠şĕ̌ţ֖̇wòţ wĕ⁠li⁠şĕ̂m֑wòẖa wĕ⁠h֞ẇʼ yilĕwe֣⁠ṅẇ ba⁠ʻàmál֗⁠wò yĕmé֥y ẖayá֛̇y⁠w ʼàşěr-náֽţan-l֥⁠wò há⁠ʼèlòhi֖ym ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[8,16,"כַּ⁠אֲשֶׁ֨ר נָתַ֤תִּי אֶת־לִבִּ⁠י֙ לָ⁠דַ֣עַת חָכְמָ֔ה וְ⁠לִ⁠רְאוֹת֙ אֶת־הָ֣⁠עִנְיָ֔ן אֲשֶׁ֥ר נַעֲשָׂ֖ה עַל־הָ⁠אָ֑רֶץ כִּ֣י גַ֤ם בַּ⁠יּוֹם֙ וּ⁠בַ⁠לַּ֔יְלָה שֵׁנָ֕ה בְּ⁠עֵינָ֖י⁠ו אֵינֶ֥⁠נּוּ רֹאֶֽה׃","kȧ⁠ʼàşě֨r náţa֤ţi̇y ʼeţ-libi̇⁠y֙ lá⁠da֣ʻaţ ẖákĕmá֔h wĕ⁠li⁠rĕʼwòţ֙ ʼeţ-há֣⁠ʻinĕyá֔n ʼàşě֥r naʻàşá֖̂h ʻal-há⁠ʼá֑reẕ ki֣̇y ga֤m bȧ⁠ẏwòm֙ ẇ⁠ba⁠lȧ֔yĕláh şé̌ná֕h bĕ̇⁠ʻéyná֖y⁠w ʼéyne֥⁠ṅẇ ròʼeֽh׃"],[8,17,"וְ⁠רָאִיתִי֮ אֶת־כָּל־מַעֲשֵׂ֣ה הָ⁠אֱלֹהִים֒ כִּי֩ לֹ֨א יוּכַ֜ל הָ⁠אָדָ֗ם לִ⁠מְצוֹא֙ אֶת־הַֽ⁠מַּעֲשֶׂה֙ אֲשֶׁ֣ר נַעֲשָׂ֣ה תַֽחַת־הַ⁠שֶּׁ֔מֶשׁ בְּ֠⁠שֶׁ⁠ל אֲשֶׁ֨ר יַעֲמֹ֧ל הָ⁠אָדָ֛ם לְ⁠בַקֵּ֖שׁ וְ⁠לֹ֣א יִמְצָ֑א וְ⁠גַ֨ם אִם־יֹאמַ֤ר הֶֽ⁠חָכָם֙ לָ⁠דַ֔עַת לֹ֥א יוּכַ֖ל לִ⁠מְצֹֽא׃","wĕ⁠ráʼiyţiy֮ ʼeţ-ká̇l-maʻàşé֣̂h há⁠ʼèlòhiym֒ ki̇y֩ lò֨ʼ yẇka֜l há⁠ʼádá֗m li⁠mĕẕwòʼ֙ ʼeţ-haֽ⁠mȧʻàşêh֙ ʼàşě֣r naʻàşá֣̂h ţaֽẖaţ-ha⁠şė̌֔meş̌ bĕ̇֠⁠şě⁠l ʼàşě֨r yaʻàmò֧l há⁠ʼádá֛m lĕ⁠baqé֖̇ş̌ wĕ⁠lò֣ʼ yimĕẕá֑ʼ wĕ⁠ga֨m ʼim-yòʼma֤r heֽ⁠ẖákám֙ lá⁠da֔ʻaţ lò֥ʼ yẇka֖l li⁠mĕẕòֽʼ׃"],[9,1,"כִּ֣י אֶת־כָּל־זֶ֞ה נָתַ֤תִּי אֶל־לִבִּ⁠י֙ וְ⁠לָ⁠ב֣וּר אֶת־כָּל־זֶ֔ה אֲשֶׁ֨ר הַ⁠צַּדִּיקִ֧ים וְ⁠הַ⁠חֲכָמִ֛ים וַ⁠עֲבָדֵי⁠הֶ֖ם בְּ⁠יַ֣ד הָ⁠אֱלֹהִ֑ים גַּֽם־אַהֲבָ֣ה גַם־שִׂנְאָ֗ה אֵ֤ין יוֹדֵ֨עַ֙ הָֽ⁠אָדָ֔ם הַ⁠כֹּ֖ל לִ⁠פְנֵי⁠הֶֽם׃","ki֣̇y ʼeţ-ká̇l-ze֞h náţa֤ţi̇y ʼel-libi̇⁠y֙ wĕ⁠lá⁠b֣ẇr ʼeţ-ká̇l-ze֔h ʼàşě֨r ha⁠ẕȧdi̇yqi֧ym wĕ⁠ha⁠ẖàkámi֛ym wa⁠ʻàbádéy⁠he֖m bĕ̇⁠ya֣d há⁠ʼèlòhi֑ym gȧֽm-ʼahàbá֣h gam-şînĕʼá֗h ʼé֤yn ywòdé֨ʻa֙ háֽ⁠ʼádá֔m ha⁠kò֖̇l li⁠pĕnéy⁠heֽm׃"],[9,2,"הַ⁠כֹּ֞ל כַּ⁠אֲשֶׁ֣ר לַ⁠כֹּ֗ל מִקְרֶ֨ה אֶחָ֜ד לַ⁠צַּדִּ֤יק וְ⁠לָ⁠רָשָׁע֙ לַ⁠טּוֹב֙ וְ⁠לַ⁠טָּה֣וֹר וְ⁠לַ⁠טָּמֵ֔א וְ⁠לַ⁠זֹּבֵ֔חַ וְ⁠לַ⁠אֲשֶׁ֖ר אֵינֶ֣⁠נּוּ זֹבֵ֑חַ כַּ⁠טּוֹב֙ כַּֽ⁠חֹטֶ֔א הַ⁠נִּשְׁבָּ֕ע כַּ⁠אֲשֶׁ֖ר שְׁבוּעָ֥ה יָרֵֽא׃","ha⁠kò̇֞l kȧ⁠ʼàşě֣r la⁠kò̇֗l miqĕre֨h ʼeẖá֜d la⁠ẕȧdi֤̇yq wĕ⁠lá⁠ráşá̌ʻ֙ la⁠ṫwòb֙ wĕ⁠la⁠tá̇h֣wòr wĕ⁠la⁠tá̇mé֔ʼ wĕ⁠la⁠zò̇bé֔ẖa wĕ⁠la⁠ʼàşě֖r ʼéyne֣⁠ṅẇ zòbé֑ẖa kȧ⁠ṫwòb֙ kȧֽ⁠ẖòte֔ʼ ha⁠ni̇şĕ̌bá̇֕ʻ kȧ⁠ʼàşě֖r şĕ̌bẇʻá֥h yáréֽʼ׃"],[9,3,"זֶ֣ה ׀ רָ֗ע בְּ⁠כֹ֤ל אֲשֶֽׁר־נַעֲשָׂה֙ תַּ֣חַת הַ⁠שֶּׁ֔מֶשׁ כִּֽי־מִקְרֶ֥ה אֶחָ֖ד לַ⁠כֹּ֑ל וְ⁠גַ֣ם לֵ֣ב בְּֽנֵי־הָ֠⁠אָדָם מָלֵא־רָ֨ע וְ⁠הוֹלֵל֤וֹת בִּ⁠לְבָבָ⁠ם֙ בְּ⁠חַיֵּי⁠הֶ֔ם וְ⁠אַחֲרָ֖י⁠ו אֶל־הַ⁠מֵּתִֽים׃","ze֣h ׀ rá֗ʻ bĕ̇⁠kò֤l ʼàşěֽr-naʻàşá̂h֙ ţȧ֣ẖaţ ha⁠şė̌֔meş̌ kiֽ̇y-miqĕre֥h ʼeẖá֖d la⁠kò֑̇l wĕ⁠ga֣m lé֣b bĕֽ̇néy-há֠⁠ʼádám máléʼ-rá֨ʻ wĕ⁠hwòlél֤wòţ bi̇⁠lĕbábá⁠m֙ bĕ̇⁠ẖayé̇y⁠he֔m wĕ⁠ʼaẖàrá֖y⁠w ʼel-ha⁠mé̇ţiֽym׃"],[9,4,"כִּי־מִי֙ אֲשֶׁ֣ר יבחר אֶ֥ל כָּל־הַ⁠חַיִּ֖ים יֵ֣שׁ בִּטָּח֑וֹן כִּֽי־לְ⁠כֶ֤לֶב חַי֙ ה֣וּא ט֔וֹב מִן־הָ⁠אַרְיֵ֖ה הַ⁠מֵּֽת׃","ki̇y-miy֙ ʼàşě֣r ybẖr ʼe֥l ká̇l-ha⁠ẖayi֖̇ym yé֣ş̌ bi̇tá̇ẖ֑wòn kiֽ̇y-lĕ⁠ke֤leb ẖay֙ h֣ẇʼ t֔wòb min-há⁠ʼarĕyé֖h ha⁠méֽ̇ţ׃"],[9,5,"כִּ֧י הַֽ⁠חַיִּ֛ים יוֹדְעִ֖ים שֶׁ⁠יָּמֻ֑תוּ וְ⁠הַ⁠מֵּתִ֞ים אֵינָ֧⁠ם יוֹדְעִ֣ים מְא֗וּמָה וְ⁠אֵֽין־ע֤וֹד לָ⁠הֶם֙ שָׂכָ֔ר כִּ֥י נִשְׁכַּ֖ח זִכְרָֽ⁠ם׃","ki֧̇y haֽ⁠ẖayi֛̇ym ywòdĕʻi֖ym şě⁠yá̇mu֑ţẇ wĕ⁠ha⁠mé̇ţi֞ym ʼéyná֧⁠m ywòdĕʻi֣ym mĕʼ֗ẇmáh wĕ⁠ʼéֽyn-ʻ֤wòd lá⁠hem֙ şá̂ká֔r ki֥̇y nişĕ̌kȧ֖ẖ zikĕráֽ⁠m׃"],[9,6,"גַּ֣ם אַהֲבָתָ֧⁠ם גַּם־שִׂנְאָתָ֛⁠ם גַּם־קִנְאָתָ֖⁠ם כְּבָ֣ר אָבָ֑דָה וְ⁠חֵ֨לֶק אֵין־לָ⁠הֶ֥ם עוֹד֙ לְ⁠עוֹלָ֔ם בְּ⁠כֹ֥ל אֲשֶֽׁר־נַעֲשָׂ֖ה תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","gȧ֣m ʼahàbáţá֧⁠m gȧm-şînĕʼáţá֛⁠m gȧm-qinĕʼáţá֖⁠m kĕ̇bá֣r ʼábá֑dáh wĕ⁠ẖé֨leq ʼéyn-lá⁠he֥m ʻwòd֙ lĕ⁠ʻwòlá֔m bĕ̇⁠kò֥l ʼàşěֽr-naʻàşá֖̂h ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[9,7,"לֵ֣ךְ אֱכֹ֤ל בְּ⁠שִׂמְחָה֙ לַחְמֶ֔⁠ךָ וּֽ⁠שֲׁתֵ֥ה בְ⁠לֶב־ט֖וֹב יֵינֶ֑⁠ךָ כִּ֣י כְבָ֔ר רָצָ֥ה הָ⁠אֱלֹהִ֖ים אֶֽת־מַעֲשֶֽׂי⁠ךָ׃","lé֣kĕ ʼèkò֤l bĕ̇⁠şîmĕẖáh֙ laẖĕme֔⁠ká ẇֽ⁠şà̌ţé֥h bĕ⁠leb-t֖wòb yéyne֑⁠ká ki֣̇y kĕbá֔r ráẕá֥h há⁠ʼèlòhi֖ym ʼeֽţ-maʻàşêֽy⁠ká׃"],[9,8,"בְּ⁠כָל־עֵ֕ת יִהְי֥וּ בְגָדֶ֖י⁠ךָ לְבָנִ֑ים וְ⁠שֶׁ֖מֶן עַל־רֹאשְׁ⁠ךָ֥ אַל־יֶחְסָֽר׃","bĕ̇⁠kál-ʻé֕ţ yihĕy֥ẇ bĕgáde֖y⁠ká lĕbáni֑ym wĕ⁠şě֖men ʻal-ròʼşĕ̌⁠ká֥ ʼal-yeẖĕsáֽr׃"],[9,9,"רְאֵ֨ה חַיִּ֜ים עִם־אִשָּׁ֣ה אֲשֶׁר־אָהַ֗בְתָּ כָּל־יְמֵי֙ חַיֵּ֣י הֶבְלֶ֔⁠ךָ אֲשֶׁ֤ר נָֽתַן־לְ⁠ךָ֙ תַּ֣חַת הַ⁠שֶּׁ֔מֶשׁ כֹּ֖ל יְמֵ֣י הֶבְלֶ֑⁠ךָ כִּ֣י ה֤וּא חֶלְקְ⁠ךָ֙ בַּֽ⁠חַיִּ֔ים וּ⁠בַ⁠עֲמָ֣לְ⁠ךָ֔ אֲשֶׁר־אַתָּ֥ה עָמֵ֖ל תַּ֥חַת הַ⁠שָּֽׁמֶשׁ׃","rĕʼé֨h ẖayi̇֜ym ʻim-ʼişá֣̇̌h ʼàşěr-ʼáha֗bĕţá̇ ká̇l-yĕméy֙ ẖayé֣̇y hebĕle֔⁠ká ʼàşě֤r náֽţan-lĕ⁠ká֙ ţȧ֣ẖaţ ha⁠şė̌֔meş̌ kò֖̇l yĕmé֣y hebĕle֑⁠ká ki֣̇y h֤ẇʼ ẖelĕqĕ⁠ká֙ bȧֽ⁠ẖayi̇֔ym ẇ⁠ba⁠ʻàmá֣lĕ⁠ká֔ ʼàşěr-ʼaţá֥̇h ʻámé֖l ţȧ֥ẖaţ ha⁠şáֽ̇̌meş̌׃"],[9,10,"כֹּ֠ל אֲשֶׁ֨ר תִּמְצָ֧א יָֽדְ⁠ךָ֛ לַ⁠עֲשׂ֥וֹת בְּ⁠כֹחֲ⁠ךָ֖ עֲשֵׂ֑ה כִּי֩ אֵ֨ין מַעֲשֶׂ֤ה וְ⁠חֶשְׁבּוֹן֙ וְ⁠דַ֣עַת וְ⁠חָכְמָ֔ה בִּ⁠שְׁא֕וֹל אֲשֶׁ֥ר אַתָּ֖ה הֹלֵ֥ךְ שָֽׁמָּ⁠ה׃ס","kò̇֠l ʼàşě֨r ţi̇mĕẕá֧ʼ yáֽdĕ⁠ká֛ la⁠ʻàş֥̂wòţ bĕ̇⁠kòẖà⁠ká֖ ʻàşé֑̂h ki̇y֩ ʼé֨yn maʻàşê֤h wĕ⁠ẖeşĕ̌ḃwòn֙ wĕ⁠da֣ʻaţ wĕ⁠ẖákĕmá֔h bi̇⁠şĕ̌ʼ֕wòl ʼàşě֥r ʼaţá֖̇h hòlé֥kĕ şáֽ̌má̇⁠h׃s"],[9,11,"שַׁ֜בְתִּי וְ⁠רָאֹ֣ה תַֽחַת־הַ⁠שֶּׁ֗מֶשׁ כִּ֣י לֹא֩ לַ⁠קַּלִּ֨ים הַ⁠מֵּר֜וֹץ וְ⁠לֹ֧א לַ⁠גִּבּוֹרִ֣ים הַ⁠מִּלְחָמָ֗ה וְ֠⁠גַם לֹ֣א לַ⁠חֲכָמִ֥ים לֶ֨חֶם֙ וְ⁠גַ֨ם לֹ֤א לַ⁠נְּבֹנִים֙ עֹ֔שֶׁר וְ⁠גַ֛ם לֹ֥א לַ⁠יֹּדְעִ֖ים חֵ֑ן כִּי־עֵ֥ת וָ⁠פֶ֖גַע יִקְרֶ֥ה אֶת־כֻּלָּֽ⁠ם׃","şǎ֜bĕţi̇y wĕ⁠ráʼò֣h ţaֽẖaţ-ha⁠şė̌֗meş̌ ki֣̇y lòʼ֩ la⁠qȧli̇֨ym ha⁠mé̇r֜wòẕ wĕ⁠lò֧ʼ la⁠gi̇ḃwòri֣ym ha⁠mi̇lĕẖámá֗h wĕ֠⁠gam lò֣ʼ la⁠ẖàkámi֥ym le֨ẖem֙ wĕ⁠ga֨m lò֤ʼ la⁠nĕ̇bòniym֙ ʻò֔şěr wĕ⁠ga֛m lò֥ʼ la⁠yò̇dĕʻi֖ym ẖé֑n ki̇y-ʻé֥ţ wá⁠pe֖gaʻ yiqĕre֥h ʼeţ-ku̇láֽ̇⁠m׃"],[9,12,"כִּ֡י גַּם֩ לֹֽא־יֵדַ֨ע הָ⁠אָדָ֜ם אֶת־עִתּ֗⁠וֹ כַּ⁠דָּגִים֙ שֶׁ⁠נֶּֽאֱחָזִים֙ בִּ⁠מְצוֹדָ֣ה רָעָ֔ה וְ⁠כַ֨⁠צִּפֳּרִ֔ים הָ⁠אֲחֻז֖וֹת בַּ⁠פָּ֑ח כָּ⁠הֵ֗ם יֽוּקָשִׁים֙ בְּנֵ֣י הָֽ⁠אָדָ֔ם לְ⁠עֵ֣ת רָעָ֔ה כְּ⁠שֶׁ⁠תִּפּ֥וֹל עֲלֵי⁠הֶ֖ם פִּתְאֹֽם׃","ki̇֡y gȧm֩ lòֽʼ-yéda֨ʻ há⁠ʼádá֜m ʼeţ-ʻiţ̇֗⁠wò kȧ⁠dá̇giym֙ şě⁠nėֽʼèẖáziym֙ bi̇⁠mĕẕwòdá֣h ráʻá֔h wĕ⁠ka֨⁠ẕi̇pȯri֔ym há⁠ʼàẖuz֖wòţ bȧ⁠pá֑̇ẖ ká̇⁠hé֗m yֽẇqáşǐym֙ bĕ̇né֣y háֽ⁠ʼádá֔m lĕ⁠ʻé֣ţ ráʻá֔h kĕ̇⁠şě⁠ţi̇ṗ֥wòl ʻàléy⁠he֖m pi̇ţĕʼòֽm׃"],[9,13,"גַּם־זֹ֛ה רָאִ֥יתִי חָכְמָ֖ה תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ וּ⁠גְדוֹלָ֥ה הִ֖יא אֵלָֽ⁠י׃","gȧm-zò֛h ráʼi֥yţiy ẖákĕmá֖h ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ẇ⁠gĕdwòlá֥h hi֖yʼ ʼéláֽ⁠y׃"],[9,14,"עִ֣יר קְטַנָּ֔ה וַ⁠אֲנָשִׁ֥ים בָּ֖⁠הּ מְעָ֑ט וּ⁠בָֽא־אֵלֶ֜י⁠הָ מֶ֤לֶךְ גָּדוֹל֙ וְ⁠סָבַ֣ב אֹתָ֔⁠הּ וּ⁠בָנָ֥ה עָלֶ֖י⁠הָ מְצוֹדִ֥ים גְּדֹלִֽים׃","ʻi֣yr qĕtaná̇֔h wa⁠ʼànáşǐ֥ym bá֖̇⁠ḣ mĕʻá֑t ẇ⁠báֽʼ-ʼéle֜y⁠há me֤lekĕ gá̇dwòl֙ wĕ⁠sába֣b ʼòţá֔⁠ḣ ẇ⁠báná֥h ʻále֖y⁠há mĕẕwòdi֥ym gĕ̇dòliֽym׃"],[9,15,"וּ⁠מָ֣צָא בָ֗⁠הּ אִ֤ישׁ מִסְכֵּן֙ חָכָ֔ם וּ⁠מִלַּט־ה֥וּא אֶת־הָ⁠עִ֖יר בְּ⁠חָכְמָת֑⁠וֹ וְ⁠אָדָם֙ לֹ֣א זָכַ֔ר אֶת־הָ⁠אִ֥ישׁ הַ⁠מִּסְכֵּ֖ן הַ⁠הּֽוּא׃","ẇ⁠má֣ẕáʼ bá֗⁠ḣ ʼi֤yş̌ misĕké̇n֙ ẖáká֔m ẇ⁠milȧt-h֥ẇʼ ʼeţ-há⁠ʻi֖yr bĕ̇⁠ẖákĕmáţ֑⁠wò wĕ⁠ʼádám֙ lò֣ʼ záka֔r ʼeţ-há⁠ʼi֥yş̌ ha⁠mi̇sĕké֖̇n ha⁠ḣֽẇʼ׃"],[9,16,"וְ⁠אָמַ֣רְתִּי אָ֔נִי טוֹבָ֥ה חָכְמָ֖ה מִ⁠גְּבוּרָ֑ה וְ⁠חָכְמַ֤ת הַ⁠מִּסְכֵּן֙ בְּזוּיָ֔ה וּ⁠דְבָרָ֖י⁠ו אֵינָ֥⁠ם נִשְׁמָעִֽים׃","wĕ⁠ʼáma֣rĕţi̇y ʼá֔niy twòbá֥h ẖákĕmá֖h mi⁠gĕ̇bẇrá֑h wĕ⁠ẖákĕma֤ţ ha⁠mi̇sĕké̇n֙ bĕ̇zẇyá֔h ẇ⁠dĕbárá֖y⁠w ʼéyná֥⁠m nişĕ̌máʻiֽym׃"],[9,17,"דִּבְרֵ֣י חֲכָמִ֔ים בְּ⁠נַ֖חַת נִשְׁמָעִ֑ים מִ⁠זַּעֲקַ֥ת מוֹשֵׁ֖ל בַּ⁠כְּסִילִֽים׃","di̇bĕré֣y ẖàkámi֔ym bĕ̇⁠na֖ẖaţ nişĕ̌máʻi֑ym mi⁠zȧʻàqa֥ţ mwòşé֖̌l bȧ⁠kĕ̇siyliֽym׃"],[9,18,"טוֹבָ֥ה חָכְמָ֖ה מִ⁠כְּלֵ֣י קְרָ֑ב וְ⁠חוֹטֶ֣א אֶחָ֔ד יְאַבֵּ֥ד טוֹבָ֥ה הַרְבֵּֽה׃","twòbá֥h ẖákĕmá֖h mi⁠kĕ̇lé֣y qĕrá֑b wĕ⁠ẖwòte֣ʼ ʼeẖá֔d yĕʼabé֥̇d twòbá֥h harĕbéֽ̇h׃"],[10,1,"זְב֣וּבֵי מָ֔וֶת יַבְאִ֥ישׁ יַבִּ֖יעַ שֶׁ֣מֶן רוֹקֵ֑חַ יָקָ֛ר מֵ⁠חָכְמָ֥ה מִ⁠כָּב֖וֹד סִכְל֥וּת מְעָֽט׃","zĕb֣ẇbéy má֔weţ yabĕʼi֥yş̌ yabi֖̇yʻa şě֣men rwòqé֑ẖa yáqá֛r mé⁠ẖákĕmá֥h mi⁠ká̇b֖wòd sikĕl֥ẇţ mĕʻáֽt׃"],[10,2,"לֵ֤ב חָכָם֙ לִֽ⁠ימִינ֔⁠וֹ וְ⁠לֵ֥ב כְּסִ֖יל לִ⁠שְׂמֹאלֽ⁠וֹ׃","lé֤b ẖákám֙ liֽ⁠ymiyn֔⁠wò wĕ⁠lé֥b kĕ̇si֖yl li⁠şĕ̂mòʼlֽ⁠wò׃"],[10,3,"וְ⁠גַם־בַּ⁠דֶּ֛רֶךְ כ⁠ש⁠ה⁠סכל הֹלֵ֖ךְ לִבּ֣⁠וֹ חָסֵ֑ר וְ⁠אָמַ֥ר לַ⁠כֹּ֖ל סָכָ֥ל הֽוּא׃","wĕ⁠gam-bȧ⁠dė֛rekĕ k⁠ş⁠h⁠skl hòlé֖kĕ liḃ֣⁠wò ẖásé֑r wĕ⁠ʼáma֥r la⁠kò֖̇l sáká֥l hֽẇʼ׃"],[10,4,"אִם־ר֤וּחַ הַ⁠מּוֹשֵׁל֙ תַּעֲלֶ֣ה עָלֶ֔י⁠ךָ מְקוֹמְ⁠ךָ֖ אַל־תַּנַּ֑ח כִּ֣י מַרְפֵּ֔א יַנִּ֖יחַ חֲטָאִ֥ים גְּדוֹלִֽים׃","ʼim-r֤ẇẖa ha⁠ṁwòşé̌l֙ ţȧʻàle֣h ʻále֔y⁠ká mĕqwòmĕ⁠ká֖ ʼal-ţȧnȧ֑ẖ ki֣̇y marĕpé̇֔ʼ yani֖̇yẖa ẖàtáʼi֥ym gĕ̇dwòliֽym׃"],[10,5,"יֵ֣שׁ רָעָ֔ה רָאִ֖יתִי תַּ֣חַת הַ⁠שָּׁ֑מֶשׁ כִּ⁠שְׁגָגָ֕ה שֶׁ⁠יֹּצָ֖א מִ⁠לִּ⁠פְנֵ֥י הַ⁠שַּׁלִּֽיט׃","yé֣ş̌ ráʻá֔h ráʼi֖yţiy ţȧ֣ẖaţ ha⁠şá֑̇̌meş̌ ki̇⁠şĕ̌gágá֕h şě⁠yò̇ẕá֖ʼ mi⁠li̇⁠pĕné֥y ha⁠şȧ̌liֽ̇yt׃"],[10,6,"נִתַּ֣ן הַ⁠סֶּ֔כֶל בַּ⁠מְּרוֹמִ֖ים רַבִּ֑ים וַ⁠עֲשִׁירִ֖ים בַּ⁠שֵּׁ֥פֶל יֵשֵֽׁבוּ׃","niţȧ֣n ha⁠sė֔kel bȧ⁠mĕ̇rwòmi֖ym rabi֑̇ym wa⁠ʻàşǐyri֖ym bȧ⁠şé֥̇̌pel yéşéֽ̌bẇ׃"],[10,7,"רָאִ֥יתִי עֲבָדִ֖ים עַל־סוּסִ֑ים וְ⁠שָׂרִ֛ים הֹלְכִ֥ים כַּ⁠עֲבָדִ֖ים עַל־הָ⁠אָֽרֶץ׃","ráʼi֥yţiy ʻàbádi֖ym ʻal-sẇsi֑ym wĕ⁠şá̂ri֛ym hòlĕki֥ym kȧ⁠ʻàbádi֖ym ʻal-há⁠ʼáֽreẕ׃"],[10,8,"חֹפֵ֥ר גּוּמָּ֖ץ בּ֣⁠וֹ יִפּ֑וֹל וּ⁠פֹרֵ֥ץ גָּדֵ֖ר יִשְּׁכֶ֥⁠נּוּ נָחָֽשׁ׃","ẖòpé֥r ġẇmá֖̇ẕ ḃ֣⁠wò yiṗ֑wòl ẇ⁠pòré֥ẕ gá̇dé֖r yişĕ̇̌ke֥⁠ṅẇ náẖáֽş̌׃"],[10,9,"מַסִּ֣יעַ אֲבָנִ֔ים יֵעָצֵ֖ב בָּ⁠הֶ֑ם בּוֹקֵ֥עַ עֵצִ֖ים יִסָּ֥כֶן בָּֽ⁠ם׃","masi֣̇yʻa ʼàbáni֔ym yéʻáẕé֖b bá̇⁠he֑m ḃwòqé֥ʻa ʻéẕi֖ym yisá֥̇ken báֽ̇⁠m׃"],[10,10,"אִם־קֵהָ֣ה הַ⁠בַּרְזֶ֗ל וְ⁠הוּא֙ לֹא־פָנִ֣ים קִלְקַ֔ל וַ⁠חֲיָלִ֖ים יְגַבֵּ֑ר וְ⁠יִתְר֥וֹן הכשיר חָכְמָֽה׃","ʼim-qéhá֣h ha⁠bȧrĕze֗l wĕ⁠hẇʼ֙ lòʼ-páni֣ym qilĕqa֔l wa⁠ẖàyáli֖ym yĕgabé֑̇r wĕ⁠yiţĕr֥wòn hkşyr ẖákĕmáֽh׃"],[10,11,"אִם־יִשֹּׁ֥ךְ הַ⁠נָּחָ֖שׁ בְּ⁠לוֹא־לָ֑חַשׁ וְ⁠אֵ֣ין יִתְר֔וֹן לְ⁠בַ֖עַל הַ⁠לָּשֽׁוֹן׃","ʼim-yişò֥̇̌kĕ ha⁠ná̇ẖá֖ş̌ bĕ̇⁠lwòʼ-lá֑ẖaş̌ wĕ⁠ʼé֣yn yiţĕr֔wòn lĕ⁠ba֖ʻal ha⁠lá̇şֽ̌wòn׃"],[10,12,"דִּבְרֵ֥י פִי־חָכָ֖ם חֵ֑ן וְ⁠שִׂפְת֥וֹת כְּסִ֖יל תְּבַלְּעֶֽ⁠נּוּ׃","di̇bĕré֥y piy-ẖáká֖m ẖé֑n wĕ⁠şîpĕţ֥wòţ kĕ̇si֖yl ţĕ̇balĕ̇ʻeֽ⁠ṅẇ׃"],[10,13,"תְּחִלַּ֥ת דִּבְרֵי־פִ֖י⁠הוּ סִכְל֑וּת וְ⁠אַחֲרִ֣ית פִּ֔י⁠הוּ הוֹלֵל֖וּת רָעָֽה׃","ţĕ̇ẖilȧ֥ţ di̇bĕréy-pi֖y⁠hẇ sikĕl֑ẇţ wĕ⁠ʼaẖàri֣yţ pi̇֔y⁠hẇ hwòlél֖ẇţ ráʻáֽh׃"],[10,14,"וְ⁠הַ⁠סָּכָ֖ל יַרְבֶּ֣ה דְבָרִ֑ים לֹא־יֵדַ֤ע הָ⁠אָדָם֙ מַה־שֶׁ⁠יִּֽהְיֶ֔ה וַ⁠אֲשֶׁ֤ר יִֽהְיֶה֙ מֵֽ⁠אַחֲרָ֔י⁠ו מִ֖י יַגִּ֥יד לֽ⁠וֹ׃","wĕ⁠ha⁠sá̇ká֖l yarĕbė֣h dĕbári֑ym lòʼ-yéda֤ʻ há⁠ʼádám֙ mah-şě⁠yiֽ̇hĕye֔h wa⁠ʼàşě֤r yiֽhĕyeh֙ méֽ⁠ʼaẖàrá֔y⁠w mi֖y yagi֥̇yd lֽ⁠wò׃"],[10,15,"עֲמַ֥ל הַ⁠כְּסִילִ֖ים תְּיַגְּעֶ֑⁠נּוּ אֲשֶׁ֥ר לֹֽא־יָדַ֖ע לָ⁠לֶ֥כֶת אֶל־עִֽיר׃","ʻàma֥l ha⁠kĕ̇siyli֖ym ţĕ̇yagĕ̇ʻe֑⁠ṅẇ ʼàşě֥r lòֽʼ-yáda֖ʻ lá⁠le֥keţ ʼel-ʻiֽyr׃"],[10,16,"אִֽי־לָ֣⁠ךְ אֶ֔רֶץ שֶׁ⁠מַּלְכֵּ֖⁠ךְ נָ֑עַר וְ⁠שָׂרַ֖יִ⁠ךְ בַּ⁠בֹּ֥קֶר יֹאכֵֽלוּ׃","ʼiֽy-lá֣⁠kĕ ʼe֔reẕ şě⁠mȧlĕké֖̇⁠kĕ ná֑ʻar wĕ⁠şá̂ra֖yi⁠kĕ bȧ⁠bò֥̇qer yòʼkéֽlẇ׃"],[10,17,"אַשְׁרֵ֣י⁠ךְ אֶ֔רֶץ שֶׁ⁠מַּלְכֵּ֖⁠ךְ בֶּן־חוֹרִ֑ים וְ⁠שָׂרַ֨יִ⁠ךְ֙ בָּ⁠עֵ֣ת יֹאכֵ֔לוּ בִּ⁠גְבוּרָ֖ה וְ⁠לֹ֥א בַ⁠שְּׁתִֽי׃","ʼaşĕ̌ré֣y⁠kĕ ʼe֔reẕ şě⁠mȧlĕké֖̇⁠kĕ bėn-ẖwòri֑ym wĕ⁠şá̂ra֨yi⁠kĕ֙ bá̇⁠ʻé֣ţ yòʼké֔lẇ bi̇⁠gĕbẇrá֖h wĕ⁠lò֥ʼ ba⁠şĕ̇̌ţiֽy׃"],[10,18,"בַּ⁠עֲצַלְתַּ֖יִם יִמַּ֣ךְ הַ⁠מְּקָרֶ֑ה וּ⁠בְ⁠שִׁפְל֥וּת יָדַ֖יִם יִדְלֹ֥ף הַ⁠בָּֽיִת׃","bȧ⁠ʻàẕalĕţȧ֖yim yimȧ֣kĕ ha⁠mĕ̇qáre֑h ẇ⁠bĕ⁠şǐpĕl֥ẇţ yáda֖yim yidĕlò֥p ha⁠báֽ̇yiţ׃"],[10,19,"לִ⁠שְׂחוֹק֙ עֹשִׂ֣ים לֶ֔חֶם וְ⁠יַ֖יִן יְשַׂמַּ֣ח חַיִּ֑ים וְ⁠הַ⁠כֶּ֖סֶף יַעֲנֶ֥ה אֶת־הַ⁠כֹּֽל׃","li⁠şĕ̂ẖwòq֙ ʻòşî֣ym le֔ẖem wĕ⁠ya֖yin yĕşâmȧ֣ẖ ẖayi֑̇ym wĕ⁠ha⁠kė֖sep yaʻàne֥h ʼeţ-ha⁠kòֽ̇l׃"],[10,20,"גַּ֣ם בְּ⁠מַדָּֽעֲ⁠ךָ֗ מֶ֚לֶךְ אַל־תְּקַלֵּ֔ל וּ⁠בְ⁠חַדְרֵי֙ מִשְׁכָּ֣בְ⁠ךָ֔ אַל־תְּקַלֵּ֖ל עָשִׁ֑יר כִּ֣י ע֤וֹף הַ⁠שָּׁמַ֨יִם֙ יוֹלִ֣יךְ אֶת־הַ⁠קּ֔וֹל וּ⁠בַ֥עַל ה⁠כנפים יַגֵּ֥יד דָּבָֽר׃","gȧ֣m bĕ̇⁠madáֽ̇ʻà⁠ká֗ me֚lekĕ ʼal-ţĕ̇qalé̇֔l ẇ⁠bĕ⁠ẖadĕréy֙ mişĕ̌ká֣̇bĕ⁠ká֔ ʼal-ţĕ̇qalé֖̇l ʻáşǐ֑yr ki֣̇y ʻ֤wòp ha⁠şá̇̌ma֨yim֙ ywòli֣ykĕ ʼeţ-ha⁠q̇֔wòl ẇ⁠ba֥ʻal h⁠knpym yagé֥̇yd dá̇báֽr׃"],[11,1,"שַׁלַּ֥ח לַחְמְ⁠ךָ֖ עַל־פְּנֵ֣י הַ⁠מָּ֑יִם כִּֽי־בְ⁠רֹ֥ב הַ⁠יָּמִ֖ים תִּמְצָאֶֽ⁠נּוּ׃","şǎlȧ֥ẖ laẖĕmĕ⁠ká֖ ʻal-pĕ̇né֣y ha⁠má֑̇yim kiֽ̇y-bĕ⁠rò֥b ha⁠yá̇mi֖ym ţi̇mĕẕáʼeֽ⁠ṅẇ׃"],[11,2,"תֶּן־חֵ֥לֶק לְ⁠שִׁבְעָ֖ה וְ⁠גַ֣ם לִ⁠שְׁמוֹנָ֑ה כִּ֚י לֹ֣א תֵדַ֔ע מַה־יִּהְיֶ֥ה רָעָ֖ה עַל־הָ⁠אָֽרֶץ׃","ţėn-ẖé֥leq lĕ⁠şǐbĕʻá֖h wĕ⁠ga֣m li⁠şĕ̌mwòná֑h ki֚̇y lò֣ʼ ţéda֔ʻ mah-yi̇hĕye֥h ráʻá֖h ʻal-há⁠ʼáֽreẕ׃"],[11,3,"אִם־יִמָּלְא֨וּ הֶ⁠עָבִ֥ים גֶּ֨שֶׁם֙ עַל־הָ⁠אָ֣רֶץ יָרִ֔יקוּ וְ⁠אִם־יִפּ֥וֹל עֵ֛ץ בַּ⁠דָּר֖וֹם וְ⁠אִ֣ם בַּ⁠צָּפ֑וֹן מְק֛וֹם שֶׁ⁠יִּפּ֥וֹל הָ⁠עֵ֖ץ שָׁ֥ם יְהֽוּא׃","ʼim-yimá̇lĕʼ֨ẇ he⁠ʻábi֥ym gė֨şěm֙ ʻal-há⁠ʼá֣reẕ yári֔yqẇ wĕ⁠ʼim-yiṗ֥wòl ʻé֛ẕ bȧ⁠dá̇r֖wòm wĕ⁠ʼi֣m bȧ⁠ẕá̇p֑wòn mĕq֛wòm şě⁠yi̇ṗ֥wòl há⁠ʻé֖ẕ şá֥̌m yĕhֽẇʼ׃"],[11,4,"שֹׁמֵ֥ר ר֖וּחַ לֹ֣א יִזְרָ֑ע וְ⁠רֹאֶ֥ה בֶ⁠עָבִ֖ים לֹ֥א יִקְצֽוֹר׃","şò̌mé֥r r֖ẇẖa lò֣ʼ yizĕrá֑ʻ wĕ⁠ròʼe֥h be⁠ʻábi֖ym lò֥ʼ yiqĕẕֽwòr׃"],[11,5,"כַּ⁠אֲשֶׁ֨ר אֵֽינְ⁠ךָ֤ יוֹדֵ֨עַ֙ מַה־דֶּ֣רֶךְ הָ⁠ר֔וּחַ כַּ⁠עֲצָמִ֖ים בְּ⁠בֶ֣טֶן הַ⁠מְּלֵאָ֑ה כָּ֗כָה לֹ֤א תֵדַע֙ אֶת־מַעֲשֵׂ֣ה הָֽ⁠אֱלֹהִ֔ים אֲשֶׁ֥ר יַעֲשֶׂ֖ה אֶת־הַ⁠כֹּֽל׃","kȧ⁠ʼàşě֨r ʼéֽynĕ⁠ká֤ ywòdé֨ʻa֙ mah-dė֣rekĕ há⁠r֔ẇẖa kȧ⁠ʻàẕámi֖ym bĕ̇⁠be֣ten ha⁠mĕ̇léʼá֑h ká̇֗káh lò֤ʼ ţédaʻ֙ ʼeţ-maʻàşé֣̂h háֽ⁠ʼèlòhi֔ym ʼàşě֥r yaʻàşê֖h ʼeţ-ha⁠kòֽ̇l׃"],[11,6,"בַּ⁠בֹּ֨קֶר֙ זְרַ֣ע אֶת־זַרְעֶ֔⁠ךָ וְ⁠לָ⁠עֶ֖רֶב אַל־תַּנַּ֣ח יָדֶ֑⁠ךָ כִּי֩ אֵֽינְ⁠ךָ֨ יוֹדֵ֜ע אֵ֣י זֶ֤ה יִכְשָׁר֙ הֲ⁠זֶ֣ה אוֹ־זֶ֔ה וְ⁠אִם־שְׁנֵי⁠הֶ֥ם כְּ⁠אֶחָ֖ד טוֹבִֽים׃","bȧ⁠bò̇֨qer֙ zĕra֣ʻ ʼeţ-zarĕʻe֔⁠ká wĕ⁠lá⁠ʻe֖reb ʼal-ţȧnȧ֣ẖ yáde֑⁠ká ki̇y֩ ʼéֽynĕ⁠ká֨ ywòdé֜ʻ ʼé֣y ze֤h yikĕşá̌r֙ hà⁠ze֣h ʼwò-ze֔h wĕ⁠ʼim-şĕ̌néy⁠he֥m kĕ̇⁠ʼeẖá֖d twòbiֽym׃"],[11,7,"וּ⁠מָת֖וֹק הָ⁠א֑וֹר וְ⁠ט֥וֹב לַֽ⁠עֵינַ֖יִם לִ⁠רְא֥וֹת אֶת־הַ⁠שָּֽׁמֶשׁ׃","ẇ⁠máţ֖wòq há⁠ʼ֑wòr wĕ⁠t֥wòb laֽ⁠ʻéyna֖yim li⁠rĕʼ֥wòţ ʼeţ-ha⁠şáֽ̇̌meş̌׃"],[11,8,"כִּ֣י אִם־שָׁנִ֥ים הַרְבֵּ֛ה יִחְיֶ֥ה הָ⁠אָדָ֖ם בְּ⁠כֻלָּ֣⁠ם יִשְׂמָ֑ח וְ⁠יִזְכֹּר֙ אֶת־יְמֵ֣י הַ⁠חֹ֔שֶׁךְ כִּֽי־הַרְבֵּ֥ה יִהְי֖וּ כָּל־שֶׁ⁠בָּ֥א הָֽבֶל׃","ki֣̇y ʼim-şá̌ni֥ym harĕbé֛̇h yiẖĕye֥h há⁠ʼádá֖m bĕ̇⁠kulá֣̇⁠m yişĕ̂má֑ẖ wĕ⁠yizĕkò̇r֙ ʼeţ-yĕmé֣y ha⁠ẖò֔şěkĕ kiֽ̇y-harĕbé֥̇h yihĕy֖ẇ ká̇l-şě⁠bá֥̇ʼ háֽbel׃"],[11,9,"שְׂמַ֧ח בָּח֣וּר בְּ⁠יַלְדוּתֶ֗י⁠ךָ וִֽ⁠יטִֽיבְ⁠ךָ֤ לִבְּ⁠ךָ֙ בִּ⁠ימֵ֣י בְחוּרוֹתֶ֔⁠ךָ וְ⁠הַלֵּךְ֙ בְּ⁠דַרְכֵ֣י לִבְּ⁠ךָ֔ וּ⁠בְ⁠מַרְאֵ֖י עֵינֶ֑י⁠ךָ וְ⁠דָ֕ע כִּ֧י עַל־כָּל־אֵ֛לֶּה יְבִֽיאֲ⁠ךָ֥ הָ⁠אֱלֹהִ֖ים בַּ⁠מִּשְׁפָּֽט׃","şĕ̂ma֧ẖ bá̇ẖ֣ẇr bĕ̇⁠yalĕdẇţe֗y⁠ká wiֽ⁠ytiֽybĕ⁠ká֤ libĕ̇⁠ká֙ bi̇⁠ymé֣y bĕẖẇrwòţe֔⁠ká wĕ⁠halé̇kĕ֙ bĕ̇⁠darĕké֣y libĕ̇⁠ká֔ ẇ⁠bĕ⁠marĕʼé֖y ʻéyne֑y⁠ká wĕ⁠dá֕ʻ ki֧̇y ʻal-ká̇l-ʼé֛lėh yĕbiֽyʼà⁠ká֥ há⁠ʼèlòhi֖ym bȧ⁠mi̇şĕ̌páֽ̇t׃"],[11,10,"וְ⁠הָסֵ֥ר כַּ֨עַס֙ מִ⁠לִּבֶּ֔⁠ךָ וְ⁠הַעֲבֵ֥ר רָעָ֖ה מִ⁠בְּשָׂרֶ֑⁠ךָ כִּֽי־הַ⁠יַּלְד֥וּת וְ⁠הַֽ⁠שַּׁחֲר֖וּת הָֽבֶל׃","wĕ⁠hásé֥r kȧ֨ʻas֙ mi⁠li̇bė֔⁠ká wĕ⁠haʻàbé֥r ráʻá֖h mi⁠bĕ̇şá̂re֑⁠ká kiֽ̇y-ha⁠yȧlĕd֥ẇţ wĕ⁠haֽ⁠şȧ̌ẖàr֖ẇţ háֽbel׃"],[12,1,"וּ⁠זְכֹר֙ אֶת־בּ֣וֹרְאֶ֔י⁠ךָ בִּ⁠ימֵ֖י בְּחוּרֹתֶ֑י⁠ךָ עַ֣ד אֲשֶׁ֤ר לֹא־יָבֹ֨אוּ֙ יְמֵ֣י הָֽ⁠רָעָ֔ה וְ⁠הִגִּ֣יעוּ שָׁנִ֔ים אֲשֶׁ֣ר תֹּאמַ֔ר אֵֽין־לִ֥⁠י בָ⁠הֶ֖ם חֵֽפֶץ׃","ẇ⁠zĕkòr֙ ʼeţ-ḃ֣wòrĕʼe֔y⁠ká bi̇⁠ymé֖y bĕ̇ẖẇròţe֑y⁠ká ʻa֣d ʼàşě֤r lòʼ-yábò֨ʼẇ֙ yĕmé֣y háֽ⁠ráʻá֔h wĕ⁠higi֣̇yʻẇ şá̌ni֔ym ʼàşě֣r ţò̇ʼma֔r ʼéֽyn-li֥⁠y bá⁠he֖m ẖéֽpeẕ׃"],[12,2,"עַ֠ד אֲשֶׁ֨ר לֹֽא־תֶחְשַׁ֤ךְ הַ⁠שֶּׁ֨מֶשׁ֙ וְ⁠הָ⁠א֔וֹר וְ⁠הַ⁠יָּרֵ֖חַ וְ⁠הַ⁠כּוֹכָבִ֑ים וְ⁠שָׁ֥בוּ הֶ⁠עָבִ֖ים אַחַ֥ר הַ⁠גָּֽשֶׁם׃","ʻa֠d ʼàşě֨r lòֽʼ-ţeẖĕşǎ֤kĕ ha⁠şė̌֨meş̌֙ wĕ⁠há⁠ʼ֔wòr wĕ⁠ha⁠yá̇ré֖ẖa wĕ⁠ha⁠k̇wòkábi֑ym wĕ⁠şá֥̌bẇ he⁠ʻábi֖ym ʼaẖa֥r ha⁠gáֽ̇şěm׃"],[12,3,"בַּ⁠יּ֗וֹם שֶׁ⁠יָּזֻ֨עוּ֙ שֹׁמְרֵ֣י הַ⁠בַּ֔יִת וְ⁠הִֽתְעַוְּת֖וּ אַנְשֵׁ֣י הֶ⁠חָ֑יִל וּ⁠בָטְל֤וּ הַ⁠טֹּֽחֲנוֹת֙ כִּ֣י מִעֵ֔טוּ וְ⁠חָשְׁכ֥וּ הָ⁠רֹא֖וֹת בָּ⁠אֲרֻבּֽוֹת׃","bȧ⁠ẏ֗wòm şě⁠yá̇zu֨ʻẇ֙ şò̌mĕré֣y ha⁠bȧ֔yiţ wĕ⁠hiֽţĕʻawĕ̇ţ֖ẇ ʼanĕşé֣̌y he⁠ẖá֑yil ẇ⁠bátĕl֤ẇ ha⁠tòֽ̇ẖànwòţ֙ ki֣̇y miʻé֔tẇ wĕ⁠ẖáşĕ̌k֥ẇ há⁠ròʼ֖wòţ bá̇⁠ʼàruḃֽwòţ׃"],[12,4,"וְ⁠סֻגְּר֤וּ דְלָתַ֨יִם֙ בַּ⁠שּׁ֔וּק בִּ⁠שְׁפַ֖ל ק֣וֹל הַֽ⁠טַּחֲנָ֑ה וְ⁠יָקוּם֙ לְ⁠ק֣וֹל הַ⁠צִּפּ֔וֹר וְ⁠יִשַּׁ֖חוּ כָּל־בְּנ֥וֹת הַ⁠שִּֽׁיר׃","wĕ⁠sugĕ̇r֤ẇ dĕláţa֨yim֙ bȧ⁠ş̇̌֔ẇq bi̇⁠şĕ̌pa֖l q֣wòl haֽ⁠tȧẖàná֑h wĕ⁠yáqẇm֙ lĕ⁠q֣wòl ha⁠ẕi̇ṗ֔wòr wĕ⁠yişȧ֖̌ẖẇ ká̇l-bĕ̇n֥wòţ ha⁠şiֽ̇̌yr׃"],[12,5,"גַּ֣ם מִ⁠גָּבֹ֤הַּ יִרָ֨אוּ֙ וְ⁠חַתְחַתִּ֣ים בַּ⁠דֶּ֔רֶךְ וְ⁠יָנֵ֤אץ הַ⁠שָּׁקֵד֙ וְ⁠יִסְתַּבֵּ֣ל הֶֽ⁠חָגָ֔ב וְ⁠תָפֵ֖ר הָֽ⁠אֲבִיּוֹנָ֑ה כִּֽי־הֹלֵ֤ךְ הָ⁠אָדָם֙ אֶל־בֵּ֣ית עוֹלָמ֔⁠וֹ וְ⁠סָבְב֥וּ בָ⁠שּׁ֖וּק הַ⁠סֹּפְדִֽים׃","gȧ֣m mi⁠gá̇bò֤hȧ yirá֨ʼẇ֙ wĕ⁠ẖaţĕẖaţi֣̇ym bȧ⁠dė֔rekĕ wĕ⁠yáné֤ʼẕ ha⁠şá̇̌qéd֙ wĕ⁠yisĕţȧbé֣̇l heֽ⁠ẖágá֔b wĕ⁠ţápé֖r háֽ⁠ʼàbiẏwòná֑h kiֽ̇y-hòlé֤kĕ há⁠ʼádám֙ ʼel-bé֣̇yţ ʻwòlám֔⁠wò wĕ⁠sábĕb֥ẇ bá⁠ş֖̇̌ẇq ha⁠sò̇pĕdiֽym׃"],[12,6,"עַ֣ד אֲשֶׁ֤ר לֹֽא־ירחק חֶ֣בֶל הַ⁠כֶּ֔סֶף וְ⁠תָרֻ֖ץ גֻּלַּ֣ת הַ⁠זָּהָ֑ב וְ⁠תִשָּׁ֤בֶר כַּד֙ עַל־הַ⁠מַּבּ֔וּעַ וְ⁠נָרֹ֥ץ הַ⁠גַּלְגַּ֖ל אֶל־הַ⁠בּֽוֹר׃","ʻa֣d ʼàşě֤r lòֽʼ-yrẖq ẖe֣bel ha⁠kė֔sep wĕ⁠ţáru֖ẕ gu̇lȧ֣ţ ha⁠zá̇há֑b wĕ⁠ţişá֤̇̌ber kȧd֙ ʻal-ha⁠mȧḃ֔ẇʻa wĕ⁠nárò֥ẕ ha⁠gȧlĕgȧ֖l ʼel-ha⁠ḃֽwòr׃"],[12,7,"וְ⁠יָשֹׁ֧ב הֶ⁠עָפָ֛ר עַל־הָ⁠אָ֖רֶץ כְּ⁠שֶׁ⁠הָיָ֑ה וְ⁠הָ⁠ר֣וּחַ תָּשׁ֔וּב אֶל־הָ⁠אֱלֹהִ֖ים אֲשֶׁ֥ר נְתָנָֽ⁠הּ׃","wĕ⁠yáşò֧̌b he⁠ʻápá֛r ʻal-há⁠ʼá֖reẕ kĕ̇⁠şě⁠háyá֑h wĕ⁠há⁠r֣ẇẖa ţá̇ş̌֔ẇb ʼel-há⁠ʼèlòhi֖ym ʼàşě֥r nĕţánáֽ⁠ḣ׃"],[12,8,"הֲבֵ֧ל הֲבָלִ֛ים אָמַ֥ר הַ⁠קּוֹהֶ֖לֶת הַ⁠כֹּ֥ל הָֽבֶל׃","hàbé֧l hàbáli֛ym ʼáma֥r ha⁠q̇wòhe֖leţ ha⁠kò֥̇l háֽbel׃"],[12,9,"וְ⁠יֹתֵ֕ר שֶׁ⁠הָיָ֥ה קֹהֶ֖לֶת חָכָ֑ם ע֗וֹד לִמַּד־דַּ֨עַת֙ אֶת־הָ⁠עָ֔ם וְ⁠אִזֵּ֣ן וְ⁠חִקֵּ֔ר תִּקֵּ֖ן מְשָׁלִ֥ים הַרְבֵּֽה׃","wĕ⁠yòţé֕r şě⁠háyá֥h qòhe֖leţ ẖáká֑m ʻ֗wòd limȧd-dȧ֨ʻaţ֙ ʼeţ-há⁠ʻá֔m wĕ⁠ʼizé֣̇n wĕ⁠ẖiqé̇֔r ţi̇qé֖̇n mĕşá̌li֥ym harĕbéֽ̇h׃"],[12,10,"בִּקֵּ֣שׁ קֹהֶ֔לֶת לִ⁠מְצֹ֖א דִּבְרֵי־חֵ֑פֶץ וְ⁠כָת֥וּב יֹ֖שֶׁר דִּבְרֵ֥י אֱמֶֽת׃","bi̇qé֣̇ş̌ qòhe֔leţ li⁠mĕẕò֖ʼ di̇bĕréy-ẖé֑peẕ wĕ⁠káţ֥ẇb yò֖şěr di̇bĕré֥y ʼèmeֽţ׃"],[12,11,"דִּבְרֵ֤י חֲכָמִים֙ כַּ⁠דָּ֣רְבֹנ֔וֹת וּֽ⁠כְ⁠מַשְׂמְר֥וֹת נְטוּעִ֖ים בַּעֲלֵ֣י אֲסֻפּ֑וֹת נִתְּנ֖וּ מֵ⁠רֹעֶ֥ה אֶחָֽד׃","di̇bĕré֤y ẖàkámiym֙ kȧ⁠dá֣̇rĕbòn֔wòţ ẇֽ⁠kĕ⁠maşĕ̂mĕr֥wòţ nĕtẇʻi֖ym bȧʻàlé֣y ʼàsuṗ֑wòţ niţĕ̇n֖ẇ mé⁠ròʻe֥h ʼeẖáֽd׃"],[12,12,"וְ⁠יֹתֵ֥ר מֵ⁠הֵ֖מָּה בְּנִ֣⁠י הִזָּהֵ֑ר עֲשׂ֨וֹת סְפָרִ֤ים הַרְבֵּה֙ אֵ֣ין קֵ֔ץ וְ⁠לַ֥הַג הַרְבֵּ֖ה יְגִעַ֥ת בָּשָֽׂר׃","wĕ⁠yòţé֥r mé⁠hé֖má̇h bĕ̇ni֣⁠y hizá̇hé֑r ʻàş̂֨wòţ sĕpári֤ym harĕbé̇h֙ ʼé֣yn qé֔ẕ wĕ⁠la֥hag harĕbé֖̇h yĕgiʻa֥ţ bá̇şáֽ̂r׃"],[12,13,"ס֥וֹף דָּבָ֖ר הַ⁠כֹּ֣ל נִשְׁמָ֑ע אֶת־הָ⁠אֱלֹהִ֤ים יְרָא֙ וְ⁠אֶת־מִצְוֺתָ֣י⁠ו שְׁמ֔וֹר כִּי־זֶ֖ה כָּל־הָ⁠אָדָֽם׃","s֥wòp dá̇bá֖r ha⁠kò֣̇l nişĕ̌má֑ʻ ʼeţ-há⁠ʼèlòhi֤ym yĕráʼ֙ wĕ⁠ʼeţ-miẕĕwֺţá֣y⁠w şĕ̌m֔wòr ki̇y-ze֖h ká̇l-há⁠ʼádáֽm׃"],[12,14,"כִּ֤י אֶת־כָּל־מַֽעֲשֶׂ֔ה הָ⁠אֱלֹהִ֛ים יָבִ֥א בְ⁠מִשְׁפָּ֖ט עַ֣ל כָּל־נֶעְלָ֑ם אִם־ט֖וֹב וְ⁠אִם־רָֽע׃","ki֤̇y ʼeţ-ká̇l-maֽʻàşê֔h há⁠ʼèlòhi֛ym yábi֥ʼ bĕ⁠mişĕ̌pá֖̇t ʻa֣l ká̇l-neʻĕlá֑m ʼim-t֖wòb wĕ⁠ʼim-ráֽʻ׃"]],"fra-lsg1910":[[1,1,"Paroles de l'Ecclésiaste, fils de David, roi de Jérusalem.","Paroles de l'Ecclésiaste, fils de David, roi de Jérusalem."],[1,2,"Vanité des vanités, dit l'Ecclésiaste, vanité des vanités, tout est vanité.","Vanité des vanités, dit l'Ecclésiaste, vanité des vanités, tout est vanité."],[1,3,"Quel avantage revient-il à l'homme de toute la peine qu'il se donne sous le soleil?","Quel avantage revient-il à l'homme de toute la peine qu'il se donne sous le soleil?"],[1,4,"Une génération s'en va, une autre vient, et la terre subsiste toujours.","Une génération s'en va, une autre vient, et la terre subsiste toujours."],[1,5,"Le soleil se lève, le soleil se couche; il soupire après le lieu d'où il se lève de nouveau.","Le soleil se lève, le soleil se couche; il soupire après le lieu d'où il se lève de nouveau."],[1,6,"Le vent se dirige vers le midi, tourne vers le nord; puis il tourne encore, et reprend les mêmes circuits.","Le vent se dirige vers le midi, tourne vers le nord; puis il tourne encore, et reprend les mêmes circuits."],[1,7,"Tous les fleuves vont à la mer, et la mer n'est point remplie; ils continuent à aller vers le lieu où ils se dirigent.","Tous les fleuves vont à la mer, et la mer n'est point remplie; ils continuent à aller vers le lieu où ils se dirigent."],[1,8,"Toutes choses sont en travail au delà de ce qu'on peut dire; l'oeil ne se rassasie pas de voir, et l'oreille ne se lasse pas d'entendre.","Toutes choses sont en travail au delà de ce qu'on peut dire; l'oeil ne se rassasie pas de voir, et l'oreille ne se lasse pas d'entendre."],[1,9,"Ce qui a été, c'est ce qui sera, et ce qui s'est fait, c'est ce qui se fera, il n'y a rien de nouveau sous le soleil.","Ce qui a été, c'est ce qui sera, et ce qui s'est fait, c'est ce qui se fera, il n'y a rien de nouveau sous le soleil."],[1,10,"S'il est une chose dont on dise: Vois ceci, c'est nouveau! cette chose existait déjà dans les siècles qui nous ont précédés.","S'il est une chose dont on dise: Vois ceci, c'est nouveau! cette chose existait déjà dans les siècles qui nous ont précédés."],[1,11,"On ne se souvient pas de ce qui est ancien; et ce qui arrivera dans la suite ne laissera pas de souvenir chez ceux qui vivront plus tard.","On ne se souvient pas de ce qui est ancien; et ce qui arrivera dans la suite ne laissera pas de souvenir chez ceux qui vivront plus tard."],[1,12,"Moi, l'Ecclésiaste, j'ai été roi d'Israël à Jérusalem.","Moi, l'Ecclésiaste, j'ai été roi d'Israël à Jérusalem."],[1,13,"J'ai appliqué mon coeur à rechercher et à sonder par la sagesse tout ce qui se fait sous les cieux: c'est là une occupation pénible, à laquelle Dieu soumet les fils de l'homme.","J'ai appliqué mon coeur à rechercher et à sonder par la sagesse tout ce qui se fait sous les cieux: c'est là une occupation pénible, à laquelle Dieu soumet les fils de l'homme."],[1,14,"J'ai vu tout ce qui se fait sous le soleil; et voici, tout est vanité et poursuite du vent.","J'ai vu tout ce qui se fait sous le soleil; et voici, tout est vanité et poursuite du vent."],[1,15,"Ce qui est courbé ne peut se redresser, et ce qui manque ne peut être compté.","Ce qui est courbé ne peut se redresser, et ce qui manque ne peut être compté."],[1,16,"J'ai dit en mon coeur: Voici, j'ai grandi et surpassé en sagesse tous ceux qui ont dominé avant moi sur Jérusalem, et mon coeur a vu beaucoup de sagesse et de science.","J'ai dit en mon coeur: Voici, j'ai grandi et surpassé en sagesse tous ceux qui ont dominé avant moi sur Jérusalem, et mon coeur a vu beaucoup de sagesse et de science."],[1,17,"J'ai appliqué mon coeur à connaître la sagesse, et à connaître la sottise et la folie; j'ai compris que cela aussi c'est la poursuite du vent.","J'ai appliqué mon coeur à connaître la sagesse, et à connaître la sottise et la folie; j'ai compris que cela aussi c'est la poursuite du vent."],[1,18,"Car avec beaucoup de sagesse on a beaucoup de chagrin, et celui qui augmente sa science augmente sa douleur.","Car avec beaucoup de sagesse on a beaucoup de chagrin, et celui qui augmente sa science augmente sa douleur."],[2,1,"J'ai dit en mon coeur: Allons! je t'éprouverai par la joie, et tu goûteras le bonheur. Et voici, c'est encore là une vanité.","J'ai dit en mon coeur: Allons! je t'éprouverai par la joie, et tu goûteras le bonheur. Et voici, c'est encore là une vanité."],[2,2,"J'ai dit du rire: Insensé! et de la joie: À quoi sert-elle?","J'ai dit du rire: Insensé! et de la joie: À quoi sert-elle?"],[2,3,"Je résolus en mon coeur de livrer ma chair au vin, tandis que mon coeur me conduirait avec sagesse, et de m'attacher à la folie jusqu'à ce que je visse ce qu'il est bon pour les fils de l'homme de faire sous les cieux pendant le nombre des jours de leur vie.","Je résolus en mon coeur de livrer ma chair au vin, tandis que mon coeur me conduirait avec sagesse, et de m'attacher à la folie jusqu'à ce que je visse ce qu'il est bon pour les fils de l'homme de faire sous les cieux pendant le nombre des jours de leur vie."],[2,4,"J'exécutai de grands ouvrages: je me bâtis des maisons; je me plantai des vignes;","J'exécutai de grands ouvrages: je me bâtis des maisons; je me plantai des vignes;"],[2,5,"je me fis des jardins et des vergers, et j'y plantai des arbres à fruit de toute espèce;","je me fis des jardins et des vergers, et j'y plantai des arbres à fruit de toute espèce;"],[2,6,"je me créai des étangs, pour arroser la forêt où croissaient les arbres.","je me créai des étangs, pour arroser la forêt où croissaient les arbres."],[2,7,"J'achetai des serviteurs et des servantes, et j'eus leurs enfants nés dans la maison; je possédai des troupeaux de boeufs et de brebis, plus que tous ceux qui étaient avant moi dans Jérusalem.","J'achetai des serviteurs et des servantes, et j'eus leurs enfants nés dans la maison; je possédai des troupeaux de boeufs et de brebis, plus que tous ceux qui étaient avant moi dans Jérusalem."],[2,8,"Je m'amassai de l'argent et de l'or, et les richesses des rois et des provinces. Je me procurai des chanteurs et des chanteuses, et les délices des fils de l'homme, des femmes en grand nombre.","Je m'amassai de l'argent et de l'or, et les richesses des rois et des provinces. Je me procurai des chanteurs et des chanteuses, et les délices des fils de l'homme, des femmes en grand nombre."],[2,9,"Je devins grand, plus grand que tous ceux qui étaient avant moi dans Jérusalem. Et même ma sagesse demeura avec moi.","Je devins grand, plus grand que tous ceux qui étaient avant moi dans Jérusalem. Et même ma sagesse demeura avec moi."],[2,10,"Tout ce que mes yeux avaient désiré, je ne les en ai point privés; je n'ai refusé à mon coeur aucune joie; car mon coeur prenait plaisir à tout mon travail, et c'est la part qui m'en est revenue.","Tout ce que mes yeux avaient désiré, je ne les en ai point privés; je n'ai refusé à mon coeur aucune joie; car mon coeur prenait plaisir à tout mon travail, et c'est la part qui m'en est revenue."],[2,11,"Puis, j'ai considéré tous les ouvrages que mes mains avaient faits, et la peine que j'avais prise à les exécuter; et voici, tout est vanité et poursuite du vent, et il n'y a aucun avantage à tirer de ce qu'on fait sous le soleil.","Puis, j'ai considéré tous les ouvrages que mes mains avaient faits, et la peine que j'avais prise à les exécuter; et voici, tout est vanité et poursuite du vent, et il n'y a aucun avantage à tirer de ce qu'on fait sous le soleil."],[2,12,"Alors j'ai tourné mes regards vers la sagesse, et vers la sottise et la folie. -Car que fera l'homme qui succédera au roi? Ce qu'on a déjà fait.","Alors j'ai tourné mes regards vers la sagesse, et vers la sottise et la folie. -Car que fera l'homme qui succédera au roi? Ce qu'on a déjà fait."],[2,13,"Et j'ai vu que la sagesse a de l'avantage sur la folie, comme la lumière a de l'avantage sur les ténèbres;","Et j'ai vu que la sagesse a de l'avantage sur la folie, comme la lumière a de l'avantage sur les ténèbres;"],[2,14,"le sage a ses yeux à la tête, et l'insensé marche dans les ténèbres. Mais j'ai reconnu aussi qu'ils ont l'un et l'autre un même sort.","le sage a ses yeux à la tête, et l'insensé marche dans les ténèbres. Mais j'ai reconnu aussi qu'ils ont l'un et l'autre un même sort."],[2,15,"Et j'ai dit en mon coeur: J'aurai le même sort que l'insensé; pourquoi donc ai-je été plus sage? Et j'ai dit en mon coeur que c'est encore là une vanité.","Et j'ai dit en mon coeur: J'aurai le même sort que l'insensé; pourquoi donc ai-je été plus sage? Et j'ai dit en mon coeur que c'est encore là une vanité."],[2,16,"Car la mémoire du sage n'est pas plus éternelle que celle de l'insensé, puisque déjà les jours qui suivent, tout est oublié. Eh quoi! le sage meurt aussi bien que l'insensé!","Car la mémoire du sage n'est pas plus éternelle que celle de l'insensé, puisque déjà les jours qui suivent, tout est oublié. Eh quoi! le sage meurt aussi bien que l'insensé!"],[2,17,"Et j'ai haï la vie, car ce qui se fait sous le soleil m'a déplu, car tout est vanité et poursuite du vent.","Et j'ai haï la vie, car ce qui se fait sous le soleil m'a déplu, car tout est vanité et poursuite du vent."],[2,18,"J'ai haï tout le travail que j'ai fait sous le soleil, et dont je dois laisser la jouissance à l'homme qui me succédera.","J'ai haï tout le travail que j'ai fait sous le soleil, et dont je dois laisser la jouissance à l'homme qui me succédera."],[2,19,"Et qui sait s'il sera sage ou insensé? Cependant il sera maître de tout mon travail, de tout le fruit de ma sagesse sous le soleil. C'est encore là une vanité.","Et qui sait s'il sera sage ou insensé? Cependant il sera maître de tout mon travail, de tout le fruit de ma sagesse sous le soleil. C'est encore là une vanité."],[2,20,"Et j'en suis venu à livrer mon coeur au désespoir, à cause de tout le travail que j'ai fait sous le soleil.","Et j'en suis venu à livrer mon coeur au désespoir, à cause de tout le travail que j'ai fait sous le soleil."],[2,21,"Car tel homme a travaillé avec sagesse et science et avec succès, et il laisse le produit de son travail à un homme qui ne s'en est point occupé. C'est encore là une vanité et un grand mal.","Car tel homme a travaillé avec sagesse et science et avec succès, et il laisse le produit de son travail à un homme qui ne s'en est point occupé. C'est encore là une vanité et un grand mal."],[2,22,"Que revient-il, en effet, à l'homme de tout son travail et de la préoccupation de son coeur, objet de ses fatigues sous le soleil?","Que revient-il, en effet, à l'homme de tout son travail et de la préoccupation de son coeur, objet de ses fatigues sous le soleil?"],[2,23,"Tous ses jours ne sont que douleur, et son partage n'est que chagrin; même la nuit son coeur ne repose pas. C'est encore là une vanité.","Tous ses jours ne sont que douleur, et son partage n'est que chagrin; même la nuit son coeur ne repose pas. C'est encore là une vanité."],[2,24,"Il n'y a de bonheur pour l'homme qu'à manger et à boire, et à faire jouir son âme du bien-être, au milieu de son travail; mais j'ai vu que cela aussi vient de la main de Dieu.","Il n'y a de bonheur pour l'homme qu'à manger et à boire, et à faire jouir son âme du bien-être, au milieu de son travail; mais j'ai vu que cela aussi vient de la main de Dieu."],[2,25,"Qui, en effet, peut manger et jouir, si ce n'est moi?","Qui, en effet, peut manger et jouir, si ce n'est moi?"],[2,26,"Car il donne à l'homme qui lui est agréable la sagesse, la science et la joie; mais il donne au pécheur le soin de recueillir et d'amasser, afin de donner à celui qui est agréable à Dieu. C'est encore là une vanité et la poursuite du vent.","Car il donne à l'homme qui lui est agréable la sagesse, la science et la joie; mais il donne au pécheur le soin de recueillir et d'amasser, afin de donner à celui qui est agréable à Dieu. C'est encore là une vanité et la poursuite du vent."],[3,1,"Il y a un temps pour tout, un temps pour toute chose sous les cieux:","Il y a un temps pour tout, un temps pour toute chose sous les cieux:"],[3,2,"un temps pour naître, et un temps pour mourir; un temps pour planter, et un temps pour arracher ce qui a été planté;","un temps pour naître, et un temps pour mourir; un temps pour planter, et un temps pour arracher ce qui a été planté;"],[3,3,"un temps pour tuer, et un temps pour guérir; un temps pour abattre, et un temps pour bâtir;","un temps pour tuer, et un temps pour guérir; un temps pour abattre, et un temps pour bâtir;"],[3,4,"un temps pour pleurer, et un temps pour rire; un temps pour se lamenter, et un temps pour danser;","un temps pour pleurer, et un temps pour rire; un temps pour se lamenter, et un temps pour danser;"],[3,5,"un temps pour lancer des pierres, et un temps pour ramasser des pierres; un temps pour embrasser, et un temps pour s'éloigner des embrassements;","un temps pour lancer des pierres, et un temps pour ramasser des pierres; un temps pour embrasser, et un temps pour s'éloigner des embrassements;"],[3,6,"un temps pour chercher, et un temps pour perdre; un temps pour garder, et un temps pour jeter;","un temps pour chercher, et un temps pour perdre; un temps pour garder, et un temps pour jeter;"],[3,7,"un temps pour déchirer, et un temps pour coudre; un temps pour se taire, et un temps pour parler;","un temps pour déchirer, et un temps pour coudre; un temps pour se taire, et un temps pour parler;"],[3,8,"un temps pour aimer, et un temps pour haïr; un temps pour la guerre, et un temps pour la paix.","un temps pour aimer, et un temps pour haïr; un temps pour la guerre, et un temps pour la paix."],[3,9,"Quel avantage celui qui travaille retire-t-il de sa peine?","Quel avantage celui qui travaille retire-t-il de sa peine?"],[3,10,"J'ai vu à quelle occupation Dieu soumet les fils de l'homme.","J'ai vu à quelle occupation Dieu soumet les fils de l'homme."],[3,11,"Il fait toute chose bonne en son temps; même il a mis dans leur coeur la pensée de l'éternité, bien que l'homme ne puisse pas saisir l'oeuvre que Dieu fait, du commencement jusqu'à la fin.","Il fait toute chose bonne en son temps; même il a mis dans leur coeur la pensée de l'éternité, bien que l'homme ne puisse pas saisir l'oeuvre que Dieu fait, du commencement jusqu'à la fin."],[3,12,"J'ai reconnu qu'il n'y a de bonheur pour eux qu'à se réjouir et à se donner du bien-être pendant leur vie;","J'ai reconnu qu'il n'y a de bonheur pour eux qu'à se réjouir et à se donner du bien-être pendant leur vie;"],[3,13,"mais que, si un homme mange et boit et jouit du bien-être au milieu de tout son travail, c'est là un don de Dieu.","mais que, si un homme mange et boit et jouit du bien-être au milieu de tout son travail, c'est là un don de Dieu."],[3,14,"J'ai reconnu que tout ce que Dieu fait durera toujours, qu'il n'y a rien à y ajouter et rien à en retrancher, et que Dieu agit ainsi afin qu'on le craigne.","J'ai reconnu que tout ce que Dieu fait durera toujours, qu'il n'y a rien à y ajouter et rien à en retrancher, et que Dieu agit ainsi afin qu'on le craigne."],[3,15,"Ce qui est a déjà été, et ce qui sera a déjà été, et Dieu ramène ce qui est passé.","Ce qui est a déjà été, et ce qui sera a déjà été, et Dieu ramène ce qui est passé."],[3,16,"J'ai encore vu sous le soleil qu'au lieu établi pour juger il y a de la méchanceté, et qu'au lieu établi pour la justice il y a de la méchanceté.","J'ai encore vu sous le soleil qu'au lieu établi pour juger il y a de la méchanceté, et qu'au lieu établi pour la justice il y a de la méchanceté."],[3,17,"J'ai dit en mon coeur: Dieu jugera le juste et le méchant; car il y a là un temps pour toute chose et pour toute oeuvre.","J'ai dit en mon coeur: Dieu jugera le juste et le méchant; car il y a là un temps pour toute chose et pour toute oeuvre."],[3,18,"J'ai dit en mon coeur, au sujet des fils de l'homme, que Dieu les éprouverait, et qu'eux-mêmes verraient qu'ils ne sont que des bêtes.","J'ai dit en mon coeur, au sujet des fils de l'homme, que Dieu les éprouverait, et qu'eux-mêmes verraient qu'ils ne sont que des bêtes."],[3,19,"Car le sort des fils de l'homme et celui de la bête sont pour eux un même sort; comme meurt l'un, ainsi meurt l'autre, ils ont tous un même souffle, et la supériorité de l'homme sur la bête est nulle; car tout est vanité.","Car le sort des fils de l'homme et celui de la bête sont pour eux un même sort; comme meurt l'un, ainsi meurt l'autre, ils ont tous un même souffle, et la supériorité de l'homme sur la bête est nulle; car tout est vanité."],[3,20,"Tout va dans un même lieu; tout a été fait de la poussière, et tout retourne à la poussière.","Tout va dans un même lieu; tout a été fait de la poussière, et tout retourne à la poussière."],[3,21,"Qui sait si le souffle des fils de l'homme monte en haut, et si le souffle de la bête descend en bas dans la terre?","Qui sait si le souffle des fils de l'homme monte en haut, et si le souffle de la bête descend en bas dans la terre?"],[3,22,"Et j'ai vu qu'il n'y a rien de mieux pour l'homme que de se réjouir de ses oeuvres: c'est là sa part. Car qui le fera jouir de ce qui sera après lui?","Et j'ai vu qu'il n'y a rien de mieux pour l'homme que de se réjouir de ses oeuvres: c'est là sa part. Car qui le fera jouir de ce qui sera après lui?"],[4,1,"J'ai considéré ensuite toutes les oppressions qui se commettent sous le soleil; et voici, les opprimés sont dans les larmes, et personne qui les console! ils sont en butte à la violence de leurs oppresseurs, et personne qui les console!","J'ai considéré ensuite toutes les oppressions qui se commettent sous le soleil; et voici, les opprimés sont dans les larmes, et personne qui les console! ils sont en butte à la violence de leurs oppresseurs, et personne qui les console!"],[4,2,"Et j'ai trouvé les morts qui sont déjà morts plus heureux que les vivants qui sont encore vivants,","Et j'ai trouvé les morts qui sont déjà morts plus heureux que les vivants qui sont encore vivants,"],[4,3,"et plus heureux que les uns et les autres celui qui n'a point encore existé et qui n'a pas vu les mauvaises actions qui se commettent sous le soleil.","et plus heureux que les uns et les autres celui qui n'a point encore existé et qui n'a pas vu les mauvaises actions qui se commettent sous le soleil."],[4,4,"J'ai vu que tout travail et toute habileté dans le travail n'est que jalousie de l'homme à l'égard de son prochain. C'est encore là une vanité et la poursuite du vent.","J'ai vu que tout travail et toute habileté dans le travail n'est que jalousie de l'homme à l'égard de son prochain. C'est encore là une vanité et la poursuite du vent."],[4,5,"L'insensé se croise les mains, et mange sa propre chair.","L'insensé se croise les mains, et mange sa propre chair."],[4,6,"Mieux vaut une main pleine avec repos, que les deux mains pleines avec travail et poursuite du vent.","Mieux vaut une main pleine avec repos, que les deux mains pleines avec travail et poursuite du vent."],[4,7,"J'ai considéré une autre vanité sous le soleil.","J'ai considéré une autre vanité sous le soleil."],[4,8,"Tel homme est seul et sans personne qui lui tienne de près, il n'a ni fils ni frère, et pourtant son travail n'a point de fin et ses yeux ne sont jamais rassasiés de richesses. Pour qui donc est-ce que je travaille, et que je prive mon âme de jouissances? C'est encore là une vanité et une chose mauvaise.","Tel homme est seul et sans personne qui lui tienne de près, il n'a ni fils ni frère, et pourtant son travail n'a point de fin et ses yeux ne sont jamais rassasiés de richesses. Pour qui donc est-ce que je travaille, et que je prive mon âme de jouissances? C'est encore là une vanité et une chose mauvaise."],[4,9,"Deux valent mieux qu'un, parce qu'ils retirent un bon salaire de leur travail.","Deux valent mieux qu'un, parce qu'ils retirent un bon salaire de leur travail."],[4,10,"Car, s'ils tombent, l'un relève son compagnon; mais malheur à celui qui est seul et qui tombe, sans avoir un second pour le relever!","Car, s'ils tombent, l'un relève son compagnon; mais malheur à celui qui est seul et qui tombe, sans avoir un second pour le relever!"],[4,11,"De même, si deux couchent ensemble, ils auront chaud; mais celui qui est seul, comment aura-t-il chaud?","De même, si deux couchent ensemble, ils auront chaud; mais celui qui est seul, comment aura-t-il chaud?"],[4,12,"Et si quelqu'un est plus fort qu'un seul, les deux peuvent lui résister; et la corde à trois fils ne se rompt pas facilement.","Et si quelqu'un est plus fort qu'un seul, les deux peuvent lui résister; et la corde à trois fils ne se rompt pas facilement."],[4,13,"Mieux vaut un enfant pauvre et sage qu'un roi vieux et insensé qui ne sait plus écouter les avis;","Mieux vaut un enfant pauvre et sage qu'un roi vieux et insensé qui ne sait plus écouter les avis;"],[4,14,"car il peut sortir de prison pour régner, et même être né pauvre dans son royaume.","car il peut sortir de prison pour régner, et même être né pauvre dans son royaume."],[4,15,"J'ai vu tous les vivants qui marchent sous le soleil entourer l'enfant qui devait succéder au roi et régner à sa place.","J'ai vu tous les vivants qui marchent sous le soleil entourer l'enfant qui devait succéder au roi et régner à sa place."],[4,16,"Il n'y avait point de fin à tout ce peuple, à tous ceux à la tête desquels il était. Et toutefois, ceux qui viendront après ne se réjouiront pas à son sujet. Car c'est encore là une vanité et la poursuite du vent.","Il n'y avait point de fin à tout ce peuple, à tous ceux à la tête desquels il était. Et toutefois, ceux qui viendront après ne se réjouiront pas à son sujet. Car c'est encore là une vanité et la poursuite du vent."],[5,1,"Prends garde à ton pied, lorsque tu entres dans la maison de Dieu; approche-toi pour écouter, plutôt que pour offrir le sacrifice des insensés, car ils ne savent pas qu'ils font mal.","Prends garde à ton pied, lorsque tu entres dans la maison de Dieu; approche-toi pour écouter, plutôt que pour offrir le sacrifice des insensés, car ils ne savent pas qu'ils font mal."],[5,2,"Ne te presse pas d'ouvrir la bouche, et que ton coeur ne se hâte pas d'exprimer une parole devant Dieu; car Dieu est au ciel, et toi sur la terre: que tes paroles soient donc peu nombreuses.","Ne te presse pas d'ouvrir la bouche, et que ton coeur ne se hâte pas d'exprimer une parole devant Dieu; car Dieu est au ciel, et toi sur la terre: que tes paroles soient donc peu nombreuses."],[5,3,"Car, si les songes naissent de la multitude des occupations, la voix de l'insensé se fait entendre dans la multitude des paroles.","Car, si les songes naissent de la multitude des occupations, la voix de l'insensé se fait entendre dans la multitude des paroles."],[5,4,"Lorsque tu as fait un voeu à Dieu, ne tarde pas à l'accomplir, car il n'aime pas les insensés: accomplis le voeu que tu as fait.","Lorsque tu as fait un voeu à Dieu, ne tarde pas à l'accomplir, car il n'aime pas les insensés: accomplis le voeu que tu as fait."],[5,5,"Mieux vaut pour toi ne point faire de voeu, que d'en faire un et de ne pas l'accomplir.","Mieux vaut pour toi ne point faire de voeu, que d'en faire un et de ne pas l'accomplir."],[5,6,"Ne permets pas à ta bouche de faire pécher ta chair, et ne dis pas en présence de l'envoyé que c'est une inadvertance. Pourquoi Dieu s'irriterait-il de tes paroles, et détruirait-il l'ouvrage de tes mains?","Ne permets pas à ta bouche de faire pécher ta chair, et ne dis pas en présence de l'envoyé que c'est une inadvertance. Pourquoi Dieu s'irriterait-il de tes paroles, et détruirait-il l'ouvrage de tes mains?"],[5,7,"Car, s'il y a des vanités dans la multitude des songes, il y en a aussi dans beaucoup de paroles; c'est pourquoi, crains Dieu.","Car, s'il y a des vanités dans la multitude des songes, il y en a aussi dans beaucoup de paroles; c'est pourquoi, crains Dieu."],[5,8,"Si tu vois dans une province le pauvre opprimé et la violation du droit et de la justice, ne t'en étonne point; car un homme élevé est placé sous la surveillance d'un autre plus élevé, et au-dessus d'eux il en est de plus élevés encore.","Si tu vois dans une province le pauvre opprimé et la violation du droit et de la justice, ne t'en étonne point; car un homme élevé est placé sous la surveillance d'un autre plus élevé, et au-dessus d'eux il en est de plus élevés encore."],[5,9,"Un avantage pour le pays à tous égards, c'est un roi honoré du pays.","Un avantage pour le pays à tous égards, c'est un roi honoré du pays."],[5,10,"Celui qui aime l'argent n'est pas rassasié par l'argent, et celui qui aime les richesses n'en profite pas. C'est encore là une vanité.","Celui qui aime l'argent n'est pas rassasié par l'argent, et celui qui aime les richesses n'en profite pas. C'est encore là une vanité."],[5,11,"Quand le bien abonde, ceux qui le mangent abondent; et quel avantage en revient-il à son possesseur, sinon qu'il le voit de ses yeux?","Quand le bien abonde, ceux qui le mangent abondent; et quel avantage en revient-il à son possesseur, sinon qu'il le voit de ses yeux?"],[5,12,"Le sommeil du travailleur est doux, qu'il ait peu ou beaucoup à manger; mais le rassasiement du riche ne le laisse pas dormir.","Le sommeil du travailleur est doux, qu'il ait peu ou beaucoup à manger; mais le rassasiement du riche ne le laisse pas dormir."],[5,13,"Il est un mal grave que j'ai vu sous le soleil: des richesses conservées, pour son malheur, par celui qui les possède.","Il est un mal grave que j'ai vu sous le soleil: des richesses conservées, pour son malheur, par celui qui les possède."],[5,14,"Ces richesses se perdent par quelque événement fâcheux; il a engendré un fils, et il ne reste rien entre ses mains.","Ces richesses se perdent par quelque événement fâcheux; il a engendré un fils, et il ne reste rien entre ses mains."],[5,15,"Comme il est sorti du ventre de sa mère, il s'en retourne nu ainsi qu'il était venu, et pour son travail n'emporte rien qu'il puisse prendre dans sa main.","Comme il est sorti du ventre de sa mère, il s'en retourne nu ainsi qu'il était venu, et pour son travail n'emporte rien qu'il puisse prendre dans sa main."],[5,16,"C'est encore là un mal grave. Il s'en va comme il était venu; et quel avantage lui revient-il d'avoir travaillé pour du vent?","C'est encore là un mal grave. Il s'en va comme il était venu; et quel avantage lui revient-il d'avoir travaillé pour du vent?"],[5,17,"De plus, toute sa vie il mange dans les ténèbres, et il a beaucoup de chagrin, de maux et d'irritation.","De plus, toute sa vie il mange dans les ténèbres, et il a beaucoup de chagrin, de maux et d'irritation."],[5,18,"Voici ce que j'ai vu: c'est pour l'homme une chose bonne et belle de manger et de boire, et de jouir du bien-être au milieu de tout le travail qu'il fait sous le soleil, pendant le nombre des jours de vie que Dieu lui a donnés; car c'est là sa part.","Voici ce que j'ai vu: c'est pour l'homme une chose bonne et belle de manger et de boire, et de jouir du bien-être au milieu de tout le travail qu'il fait sous le soleil, pendant le nombre des jours de vie que Dieu lui a donnés; car c'est là sa part."],[5,19,"Mais, si Dieu a donné à un homme des richesses et des biens, s'il l'a rendu maître d'en manger, d'en prendre sa part, et de se réjouir au milieu de son travail, c'est là un don de Dieu.","Mais, si Dieu a donné à un homme des richesses et des biens, s'il l'a rendu maître d'en manger, d'en prendre sa part, et de se réjouir au milieu de son travail, c'est là un don de Dieu."],[5,20,"Car il ne se souviendra pas beaucoup des jours de sa vie, parce que Dieu répand la joie dans son coeur.","Car il ne se souviendra pas beaucoup des jours de sa vie, parce que Dieu répand la joie dans son coeur."],[6,1,"Il est un mal que j'ai vu sous le soleil, et qui est fréquent parmi les hommes.","Il est un mal que j'ai vu sous le soleil, et qui est fréquent parmi les hommes."],[6,2,"Il y a tel homme à qui Dieu a donné des richesses, des biens, et de la gloire, et qui ne manque pour son âme de rien de ce qu'il désire, mais que Dieu ne laisse pas maître d'en jouir, car c'est un étranger qui en jouira. C'est là une vanité et un mal grave.","Il y a tel homme à qui Dieu a donné des richesses, des biens, et de la gloire, et qui ne manque pour son âme de rien de ce qu'il désire, mais que Dieu ne laisse pas maître d'en jouir, car c'est un étranger qui en jouira. C'est là une vanité et un mal grave."],[6,3,"Quand un homme aurait cent fils, vivrait un grand nombre d'années, et que les jours de ses années se multiplieraient, si son âme ne s'est point rassasiée de bonheur, et si de plus il n'a point de sépulture, je dis qu'un avorton est plus heureux que lui.","Quand un homme aurait cent fils, vivrait un grand nombre d'années, et que les jours de ses années se multiplieraient, si son âme ne s'est point rassasiée de bonheur, et si de plus il n'a point de sépulture, je dis qu'un avorton est plus heureux que lui."],[6,4,"Car il est venu en vain, il s'en va dans les ténèbres, et son nom reste couvert de ténèbres;","Car il est venu en vain, il s'en va dans les ténèbres, et son nom reste couvert de ténèbres;"],[6,5,"il n'a point vu, il n'a point connu le soleil; il a plus de repos que cet homme.","il n'a point vu, il n'a point connu le soleil; il a plus de repos que cet homme."],[6,6,"Et quand celui-ci vivrait deux fois mille ans, sans jouir du bonheur, tout ne va-t-il pas dans un même lieu?","Et quand celui-ci vivrait deux fois mille ans, sans jouir du bonheur, tout ne va-t-il pas dans un même lieu?"],[6,7,"Tout le travail de l'homme est pour sa bouche, et cependant ses désirs ne sont jamais satisfaits.","Tout le travail de l'homme est pour sa bouche, et cependant ses désirs ne sont jamais satisfaits."],[6,8,"Car quel avantage le sage a-t-il sur l'insensé? quel avantage a le malheureux qui sait se conduire en présence des vivants?","Car quel avantage le sage a-t-il sur l'insensé? quel avantage a le malheureux qui sait se conduire en présence des vivants?"],[6,9,"Ce que les yeux voient est préférable à l'agitation des désirs: c'est encore là une vanité et la poursuite du vent.","Ce que les yeux voient est préférable à l'agitation des désirs: c'est encore là une vanité et la poursuite du vent."],[6,10,"Ce qui existe a déjà été appelé par son nom; et l'on sait que celui qui est homme ne peut contester avec un plus fort que lui.","Ce qui existe a déjà été appelé par son nom; et l'on sait que celui qui est homme ne peut contester avec un plus fort que lui."],[6,11,"S'il y a beaucoup de choses, il y a beaucoup de vanités: quel avantage en revient-il à l'homme?","S'il y a beaucoup de choses, il y a beaucoup de vanités: quel avantage en revient-il à l'homme?"],[6,12,"Car qui sait ce qui est bon pour l'homme dans la vie, pendant le nombre des jours de sa vie de vanité, qu'il passe comme une ombre? Et qui peut dire à l'homme ce qui sera après lui sous le soleil?","Car qui sait ce qui est bon pour l'homme dans la vie, pendant le nombre des jours de sa vie de vanité, qu'il passe comme une ombre? Et qui peut dire à l'homme ce qui sera après lui sous le soleil?"],[7,1,"Une bonne réputation vaut mieux que le bon parfum, et le jour de la mort que le jour de la naissance.","Une bonne réputation vaut mieux que le bon parfum, et le jour de la mort que le jour de la naissance."],[7,2,"Mieux vaut aller dans une maison de deuil que d'aller dans une maison de festin; car c'est là la fin de tout homme, et celui qui vit prend la chose à coeur.","Mieux vaut aller dans une maison de deuil que d'aller dans une maison de festin; car c'est là la fin de tout homme, et celui qui vit prend la chose à coeur."],[7,3,"Mieux vaut le chagrin que le rire; car avec un visage triste le coeur peut être content.","Mieux vaut le chagrin que le rire; car avec un visage triste le coeur peut être content."],[7,4,"Le coeur des sages est dans la maison de deuil, et le coeur des insensés dans la maison de joie.","Le coeur des sages est dans la maison de deuil, et le coeur des insensés dans la maison de joie."],[7,5,"Mieux vaut entendre la réprimande du sage que d'entendre le chant des insensés.","Mieux vaut entendre la réprimande du sage que d'entendre le chant des insensés."],[7,6,"Car comme le bruit des épines sous la chaudière, ainsi est le rire des insensés. C'est encore là une vanité.","Car comme le bruit des épines sous la chaudière, ainsi est le rire des insensés. C'est encore là une vanité."],[7,7,"L'oppression rend insensé le sage, et les présents corrompent le coeur.","L'oppression rend insensé le sage, et les présents corrompent le coeur."],[7,8,"Mieux vaut la fin d'une chose que son commencement; mieux vaut un esprit patient qu'un esprit hautain.","Mieux vaut la fin d'une chose que son commencement; mieux vaut un esprit patient qu'un esprit hautain."],[7,9,"Ne te hâte pas en ton esprit de t'irriter, car l'irritation repose dans le sein des insensés.","Ne te hâte pas en ton esprit de t'irriter, car l'irritation repose dans le sein des insensés."],[7,10,"Ne dis pas: D'où vient que les jours passés étaient meilleurs que ceux ci? Car ce n'est point par sagesse que tu demandes cela.","Ne dis pas: D'où vient que les jours passés étaient meilleurs que ceux ci? Car ce n'est point par sagesse que tu demandes cela."],[7,11,"La sagesse vaut autant qu'un héritage, et même plus pour ceux qui voient le soleil.","La sagesse vaut autant qu'un héritage, et même plus pour ceux qui voient le soleil."],[7,12,"Car à l'ombre de la sagesse on est abrité comme à l'ombre de l'argent; mais un avantage de la science, c'est que la sagesse fait vivre ceux qui la possèdent.","Car à l'ombre de la sagesse on est abrité comme à l'ombre de l'argent; mais un avantage de la science, c'est que la sagesse fait vivre ceux qui la possèdent."],[7,13,"Regarde l'oeuvre de Dieu: qui pourra redresser ce qu'il a courbé?","Regarde l'oeuvre de Dieu: qui pourra redresser ce qu'il a courbé?"],[7,14,"Au jour du bonheur, sois heureux, et au jour du malheur, réfléchis: Dieu a fait l'un comme l'autre, afin que l'homme ne découvre en rien ce qui sera après lui.","Au jour du bonheur, sois heureux, et au jour du malheur, réfléchis: Dieu a fait l'un comme l'autre, afin que l'homme ne découvre en rien ce qui sera après lui."],[7,15,"J'ai vu tout cela pendant les jours de ma vanité. Il y a tel juste qui périt dans sa justice, et il y a tel méchant qui prolonge son existence dans sa méchanceté.","J'ai vu tout cela pendant les jours de ma vanité. Il y a tel juste qui périt dans sa justice, et il y a tel méchant qui prolonge son existence dans sa méchanceté."],[7,16,"Ne sois pas juste à l'excès, et ne te montre pas trop sage: pourquoi te détruirais-tu?","Ne sois pas juste à l'excès, et ne te montre pas trop sage: pourquoi te détruirais-tu?"],[7,17,"Ne sois pas méchant à l'excès, et ne sois pas insensé: pourquoi mourrais-tu avant ton temps?","Ne sois pas méchant à l'excès, et ne sois pas insensé: pourquoi mourrais-tu avant ton temps?"],[7,18,"Il est bon que tu retiennes ceci, et que tu ne négliges point cela; car celui qui craint Dieu échappe à toutes ces choses.","Il est bon que tu retiennes ceci, et que tu ne négliges point cela; car celui qui craint Dieu échappe à toutes ces choses."],[7,19,"La sagesse rend le sage plus fort que dix chefs qui sont dans une ville.","La sagesse rend le sage plus fort que dix chefs qui sont dans une ville."],[7,20,"Non, il n'y a sur la terre point d'homme juste qui fasse le bien et qui ne pèche jamais.","Non, il n'y a sur la terre point d'homme juste qui fasse le bien et qui ne pèche jamais."],[7,21,"Ne fais donc pas attention à toutes les paroles qu'on dit, de peur que tu n'entendes ton serviteur te maudire;","Ne fais donc pas attention à toutes les paroles qu'on dit, de peur que tu n'entendes ton serviteur te maudire;"],[7,22,"car ton coeur a senti bien des fois que tu as toi-même maudit les autres.","car ton coeur a senti bien des fois que tu as toi-même maudit les autres."],[7,23,"J'ai éprouvé tout cela par la sagesse. J'ai dit: Je serai sage. Et la sagesse est restée loin de moi.","J'ai éprouvé tout cela par la sagesse. J'ai dit: Je serai sage. Et la sagesse est restée loin de moi."],[7,24,"Ce qui est loin, ce qui est profond, profond, qui peut l'atteindre?","Ce qui est loin, ce qui est profond, profond, qui peut l'atteindre?"],[7,25,"Je me suis appliqué dans mon coeur à connaître, à sonder, et à chercher la sagesse et la raison des choses, et à connaître la folie de la méchanceté et la stupidité de la sottise.","Je me suis appliqué dans mon coeur à connaître, à sonder, et à chercher la sagesse et la raison des choses, et à connaître la folie de la méchanceté et la stupidité de la sottise."],[7,26,"Et j'ai trouvé plus amère que la mort la femme dont le coeur est un piège et un filet, et dont les mains sont des liens; celui qui est agréable à Dieu lui échappe, mais le pécheur est pris par elle.","Et j'ai trouvé plus amère que la mort la femme dont le coeur est un piège et un filet, et dont les mains sont des liens; celui qui est agréable à Dieu lui échappe, mais le pécheur est pris par elle."],[7,27,"Voici ce que j'ai trouvé, dit l'Ecclésiaste, en examinant les choses une à une pour en saisir la raison;","Voici ce que j'ai trouvé, dit l'Ecclésiaste, en examinant les choses une à une pour en saisir la raison;"],[7,28,"voici ce que mon âme cherche encore, et que je n'ai point trouvé. J'ai trouvé un homme entre mille; mais je n'ai pas trouvé une femme entre elles toutes.","voici ce que mon âme cherche encore, et que je n'ai point trouvé. J'ai trouvé un homme entre mille; mais je n'ai pas trouvé une femme entre elles toutes."],[7,29,"Seulement, voici ce que j'ai trouvé, c'est que Dieu a fait les hommes droits; mais ils ont cherché beaucoup de détours.","Seulement, voici ce que j'ai trouvé, c'est que Dieu a fait les hommes droits; mais ils ont cherché beaucoup de détours."],[8,1,"Qui est comme le sage, et qui connaît l'explication des choses? La sagesse d'un homme fait briller son visage, et la sévérité de sa face est changée.","Qui est comme le sage, et qui connaît l'explication des choses? La sagesse d'un homme fait briller son visage, et la sévérité de sa face est changée."],[8,2,"Je te dis: Observe les ordres du roi, et cela à cause du serment fait à Dieu.","Je te dis: Observe les ordres du roi, et cela à cause du serment fait à Dieu."],[8,3,"Ne te hâte pas de t'éloigner de lui, et ne persiste pas dans une chose mauvaise: car il peut faire tout ce qui lui plaît,","Ne te hâte pas de t'éloigner de lui, et ne persiste pas dans une chose mauvaise: car il peut faire tout ce qui lui plaît,"],[8,4,"parce que la parole du roi est puissante; et qui lui dira: Que fais-tu?","parce que la parole du roi est puissante; et qui lui dira: Que fais-tu?"],[8,5,"Celui qui observe le commandement ne connaît point de chose mauvaise, et le coeur du sage connaît le temps et le jugement.","Celui qui observe le commandement ne connaît point de chose mauvaise, et le coeur du sage connaît le temps et le jugement."],[8,6,"Car il y a pour toute chose un temps et un jugement, quand le malheur accable l'homme.","Car il y a pour toute chose un temps et un jugement, quand le malheur accable l'homme."],[8,7,"Mais il ne sait point ce qui arrivera, et qui lui dira comment cela arrivera?","Mais il ne sait point ce qui arrivera, et qui lui dira comment cela arrivera?"],[8,8,"L'homme n'est pas maître de son souffle pour pouvoir le retenir, et il n'a aucune puissance sur le jour de la mort; il n'y a point de délivrance dans ce combat, et la méchanceté ne saurait sauver les méchants.","L'homme n'est pas maître de son souffle pour pouvoir le retenir, et il n'a aucune puissance sur le jour de la mort; il n'y a point de délivrance dans ce combat, et la méchanceté ne saurait sauver les méchants."],[8,9,"J'ai vu tout cela, et j'ai appliqué mon coeur à tout ce qui se fait sous le soleil. Il y a un temps où l'homme domine sur l'homme pour le rendre malheureux.","J'ai vu tout cela, et j'ai appliqué mon coeur à tout ce qui se fait sous le soleil. Il y a un temps où l'homme domine sur l'homme pour le rendre malheureux."],[8,10,"Alors j'ai vu des méchants recevoir la sépulture et entrer dans leur repos, et ceux qui avaient agi avec droiture s'en aller loin du lieu saint et être oubliés dans la ville. C'est encore là une vanité.","Alors j'ai vu des méchants recevoir la sépulture et entrer dans leur repos, et ceux qui avaient agi avec droiture s'en aller loin du lieu saint et être oubliés dans la ville. C'est encore là une vanité."],[8,11,"Parce qu'une sentence contre les mauvaises actions ne s'exécute pas promptement, le coeur des fils de l'homme se remplit en eux du désir de faire le mal.","Parce qu'une sentence contre les mauvaises actions ne s'exécute pas promptement, le coeur des fils de l'homme se remplit en eux du désir de faire le mal."],[8,12,"Cependant, quoique le pécheur fasse cent fois le mal et qu'il y persévère longtemps, je sais aussi que le bonheur est pour ceux qui craignent Dieu, parce qu'ils ont de la crainte devant lui.","Cependant, quoique le pécheur fasse cent fois le mal et qu'il y persévère longtemps, je sais aussi que le bonheur est pour ceux qui craignent Dieu, parce qu'ils ont de la crainte devant lui."],[8,13,"Mais le bonheur n'est pas pour le méchant, et il ne prolongera point ses jours, pas plus que l'ombre, parce qu'il n'a pas de la crainte devant Dieu.","Mais le bonheur n'est pas pour le méchant, et il ne prolongera point ses jours, pas plus que l'ombre, parce qu'il n'a pas de la crainte devant Dieu."],[8,14,"Il est une vanité qui a lieu sur la terre: c'est qu'il y a des justes auxquels il arrive selon l'oeuvre des méchants, et des méchants auxquels il arrive selon l'oeuvre des justes. Je dis que c'est encore là une vanité.","Il est une vanité qui a lieu sur la terre: c'est qu'il y a des justes auxquels il arrive selon l'oeuvre des méchants, et des méchants auxquels il arrive selon l'oeuvre des justes. Je dis que c'est encore là une vanité."],[8,15,"J'ai donc loué la joie, parce qu'il n'y a de bonheur pour l'homme sous le soleil qu'à manger et à boire et à se réjouir; c'est là ce qui doit l'accompagner au milieu de son travail, pendant les jours de vie que Dieu lui donne sous le soleil.","J'ai donc loué la joie, parce qu'il n'y a de bonheur pour l'homme sous le soleil qu'à manger et à boire et à se réjouir; c'est là ce qui doit l'accompagner au milieu de son travail, pendant les jours de vie que Dieu lui donne sous le soleil."],[8,16,"Lorsque j'ai appliqué mon coeur à connaître la sagesse et à considérer les choses qui se passent sur la terre, -car les yeux de l'homme ne goûtent le sommeil ni jour ni nuit,","Lorsque j'ai appliqué mon coeur à connaître la sagesse et à considérer les choses qui se passent sur la terre, -car les yeux de l'homme ne goûtent le sommeil ni jour ni nuit,"],[8,17,"j'ai vu toute l'oeuvre de Dieu, j'ai vu que l'homme ne peut pas trouver ce qui se fait sous le soleil; il a beau se fatiguer à chercher, il ne trouve pas; et même si le sage veut connaître, il ne peut pas trouver.","j'ai vu toute l'oeuvre de Dieu, j'ai vu que l'homme ne peut pas trouver ce qui se fait sous le soleil; il a beau se fatiguer à chercher, il ne trouve pas; et même si le sage veut connaître, il ne peut pas trouver."],[9,1,"Oui, j'ai appliqué mon coeur à tout cela, j'ai fait de tout cela l'objet de mon examen, et j'ai vu que les justes et les sages, et leurs travaux, sont dans la main de Dieu, et l'amour aussi bien que la haine; les hommes ne savent rien: tout est devant eux.","Oui, j'ai appliqué mon coeur à tout cela, j'ai fait de tout cela l'objet de mon examen, et j'ai vu que les justes et les sages, et leurs travaux, sont dans la main de Dieu, et l'amour aussi bien que la haine; les hommes ne savent rien: tout est devant eux."],[9,2,"Tout arrive également à tous; même sort pour le juste et pour le méchant, pour celui qui est bon et pur et pour celui qui est impur, pour celui qui sacrifie et pour celui qui ne sacrifie pas; il en est du bon comme du pécheur, de celui qui jure comme de celui qui craint de jurer.","Tout arrive également à tous; même sort pour le juste et pour le méchant, pour celui qui est bon et pur et pour celui qui est impur, pour celui qui sacrifie et pour celui qui ne sacrifie pas; il en est du bon comme du pécheur, de celui qui jure comme de celui qui craint de jurer."],[9,3,"Ceci est un mal parmi tout ce qui se fait sous le soleil, c'est qu'il y a pour tous un même sort; aussi le coeur des fils de l'homme est-il plein de méchanceté, et la folie est dans leur coeur pendant leur vie; après quoi, ils vont chez les morts. Car, qui est excepté?","Ceci est un mal parmi tout ce qui se fait sous le soleil, c'est qu'il y a pour tous un même sort; aussi le coeur des fils de l'homme est-il plein de méchanceté, et la folie est dans leur coeur pendant leur vie; après quoi, ils vont chez les morts. Car, qui est excepté?"],[9,4,"Pour tous ceux qui vivent il y a de l'espérance; et même un chien vivant vaut mieux qu'un lion mort.","Pour tous ceux qui vivent il y a de l'espérance; et même un chien vivant vaut mieux qu'un lion mort."],[9,5,"Les vivants, en effet, savent qu'ils mourront; mais les morts ne savent rien, et il n'y a pour eux plus de salaire, puisque leur mémoire est oubliée.","Les vivants, en effet, savent qu'ils mourront; mais les morts ne savent rien, et il n'y a pour eux plus de salaire, puisque leur mémoire est oubliée."],[9,6,"Et leur amour, et leur haine, et leur envie, ont déjà péri; et ils n'auront plus jamais aucune part à tout ce qui se fait sous le soleil.","Et leur amour, et leur haine, et leur envie, ont déjà péri; et ils n'auront plus jamais aucune part à tout ce qui se fait sous le soleil."],[9,7,"Va, mange avec joie ton pain, et bois gaiement ton vin; car dès longtemps Dieu prend plaisir à ce que tu fais.","Va, mange avec joie ton pain, et bois gaiement ton vin; car dès longtemps Dieu prend plaisir à ce que tu fais."],[9,8,"Qu'en tout temps tes vêtements soient blancs, et que l'huile ne manque point sur ta tête.","Qu'en tout temps tes vêtements soient blancs, et que l'huile ne manque point sur ta tête."],[9,9,"Jouis de la vie avec la femme que tu aimes, pendant tous les jours de ta vie de vanité, que Dieu t'a donnés sous le soleil, pendant tous les jours de ta vanité; car c'est ta part dans la vie, au milieu de ton travail que tu fais sous le soleil.","Jouis de la vie avec la femme que tu aimes, pendant tous les jours de ta vie de vanité, que Dieu t'a donnés sous le soleil, pendant tous les jours de ta vanité; car c'est ta part dans la vie, au milieu de ton travail que tu fais sous le soleil."],[9,10,"Tout ce que ta main trouve à faire avec ta force, fais-le; car il n'y a ni oeuvre, ni pensée, ni science, ni sagesse, dans le séjour des morts, où tu vas.","Tout ce que ta main trouve à faire avec ta force, fais-le; car il n'y a ni oeuvre, ni pensée, ni science, ni sagesse, dans le séjour des morts, où tu vas."],[9,11,"J'ai encore vu sous le soleil que la course n'est point aux agiles ni la guerre aux vaillants, ni le pain aux sages, ni la richesse aux intelligents, ni la faveur aux savants; car tout dépend pour eux du temps et des circonstances.","J'ai encore vu sous le soleil que la course n'est point aux agiles ni la guerre aux vaillants, ni le pain aux sages, ni la richesse aux intelligents, ni la faveur aux savants; car tout dépend pour eux du temps et des circonstances."],[9,12,"L'homme ne connaît pas non plus son heure, pareil aux poissons qui sont pris au filet fatal, et aux oiseaux qui sont pris au piège; comme eux, les fils de l'homme sont enlacés au temps du malheur, lorsqu'il tombe sur eux tout à coup.","L'homme ne connaît pas non plus son heure, pareil aux poissons qui sont pris au filet fatal, et aux oiseaux qui sont pris au piège; comme eux, les fils de l'homme sont enlacés au temps du malheur, lorsqu'il tombe sur eux tout à coup."],[9,13,"J'ai aussi vu sous le soleil ce trait d'une sagesse qui m'a paru grande.","J'ai aussi vu sous le soleil ce trait d'une sagesse qui m'a paru grande."],[9,14,"Il y avait une petite ville, avec peu d'hommes dans son sein; un roi puissant marcha sur elle, l'investit, et éleva contre elle de grands forts.","Il y avait une petite ville, avec peu d'hommes dans son sein; un roi puissant marcha sur elle, l'investit, et éleva contre elle de grands forts."],[9,15,"Il s'y trouvait un homme pauvre et sage, qui sauva la ville par sa sagesse. Et personne ne s'est souvenu de cet homme pauvre.","Il s'y trouvait un homme pauvre et sage, qui sauva la ville par sa sagesse. Et personne ne s'est souvenu de cet homme pauvre."],[9,16,"Et j'ai dit: La sagesse vaut mieux que la force. Cependant la sagesse du pauvre est méprisée, et ses paroles ne sont pas écoutées.","Et j'ai dit: La sagesse vaut mieux que la force. Cependant la sagesse du pauvre est méprisée, et ses paroles ne sont pas écoutées."],[9,17,"Les paroles des sages tranquillement écoutées valent mieux que les cris de celui qui domine parmi les insensés.","Les paroles des sages tranquillement écoutées valent mieux que les cris de celui qui domine parmi les insensés."],[9,18,"La sagesse vaut mieux que les instruments de guerre; mais un seul pécheur détruit beaucoup de bien.","La sagesse vaut mieux que les instruments de guerre; mais un seul pécheur détruit beaucoup de bien."],[10,1,"Les mouches mortes infectent et font fermenter l'huile du parfumeur; un peu de folie l'emporte sur la sagesse et sur la gloire.","Les mouches mortes infectent et font fermenter l'huile du parfumeur; un peu de folie l'emporte sur la sagesse et sur la gloire."],[10,2,"Le coeur du sage est à sa droite, et le coeur de l'insensé à sa gauche.","Le coeur du sage est à sa droite, et le coeur de l'insensé à sa gauche."],[10,3,"Quand l'insensé marche dans un chemin, le sens lui manque, et il dit de chacun: Voilà un fou!","Quand l'insensé marche dans un chemin, le sens lui manque, et il dit de chacun: Voilà un fou!"],[10,4,"Si l'esprit de celui qui domine s'élève contre toi, ne quitte point ta place; car le calme prévient de grands péchés.","Si l'esprit de celui qui domine s'élève contre toi, ne quitte point ta place; car le calme prévient de grands péchés."],[10,5,"Il est un mal que j'ai vu sous le soleil, comme une erreur provenant de celui qui gouverne:","Il est un mal que j'ai vu sous le soleil, comme une erreur provenant de celui qui gouverne:"],[10,6,"la folie occupe des postes très élevés, et des riches sont assis dans l'abaissement.","la folie occupe des postes très élevés, et des riches sont assis dans l'abaissement."],[10,7,"J'ai vu des esclaves sur des chevaux, et des princes marchant sur terre comme des esclaves.","J'ai vu des esclaves sur des chevaux, et des princes marchant sur terre comme des esclaves."],[10,8,"Celui qui creuse une fosse y tombera, et celui qui renverse une muraille sera mordu par un serpent.","Celui qui creuse une fosse y tombera, et celui qui renverse une muraille sera mordu par un serpent."],[10,9,"Celui qui remue des pierres en sera blessé, et celui qui fend du bois en éprouvera du danger.","Celui qui remue des pierres en sera blessé, et celui qui fend du bois en éprouvera du danger."],[10,10,"S'il a émoussé le fer, et s'il n'en a pas aiguisé le tranchant, il devra redoubler de force; mais la sagesse a l'avantage du succès.","S'il a émoussé le fer, et s'il n'en a pas aiguisé le tranchant, il devra redoubler de force; mais la sagesse a l'avantage du succès."],[10,11,"Si le serpent mord faute d'enchantement, il n'y a point d'avantage pour l'enchanteur.","Si le serpent mord faute d'enchantement, il n'y a point d'avantage pour l'enchanteur."],[10,12,"Les paroles de la bouche du sage sont pleines de grâce; mais les lèvres de l'insensé causent sa perte.","Les paroles de la bouche du sage sont pleines de grâce; mais les lèvres de l'insensé causent sa perte."],[10,13,"Le commencement des paroles de sa bouche est folie, et la fin de son discours est une méchante folie.","Le commencement des paroles de sa bouche est folie, et la fin de son discours est une méchante folie."],[10,14,"L'insensé multiplie les paroles. L'homme ne sait point ce qui arrivera, et qui lui dira ce qui sera après lui?","L'insensé multiplie les paroles. L'homme ne sait point ce qui arrivera, et qui lui dira ce qui sera après lui?"],[10,15,"Le travail de l'insensé le fatigue, parce qu'il ne sait pas aller à la ville.","Le travail de l'insensé le fatigue, parce qu'il ne sait pas aller à la ville."],[10,16,"Malheur à toi, pays dont le roi est un enfant, et dont les princes mangent dès le matin!","Malheur à toi, pays dont le roi est un enfant, et dont les princes mangent dès le matin!"],[10,17,"Heureux toi, pays dont le roi est de race illustre, et dont les princes mangent au temps convenable, pour soutenir leurs forces, et non pour se livrer à la boisson!","Heureux toi, pays dont le roi est de race illustre, et dont les princes mangent au temps convenable, pour soutenir leurs forces, et non pour se livrer à la boisson!"],[10,18,"Quand les mains sont paresseuses, la charpente s'affaisse; et quand les mains sont lâches, la maison a des gouttières.","Quand les mains sont paresseuses, la charpente s'affaisse; et quand les mains sont lâches, la maison a des gouttières."],[10,19,"On fait des repas pour se divertir, le vin rend la vie joyeuse, et l'argent répond à tout.","On fait des repas pour se divertir, le vin rend la vie joyeuse, et l'argent répond à tout."],[10,20,"Ne maudis pas le roi, même dans ta pensée, et ne maudis pas le riche dans la chambre où tu couches; car l'oiseau du ciel emporterait ta voix, l'animal ailé publierait tes paroles.","Ne maudis pas le roi, même dans ta pensée, et ne maudis pas le riche dans la chambre où tu couches; car l'oiseau du ciel emporterait ta voix, l'animal ailé publierait tes paroles."],[11,1,"Jette ton pain sur la face des eaux, car avec le temps tu le retrouveras;","Jette ton pain sur la face des eaux, car avec le temps tu le retrouveras;"],[11,2,"donnes-en une part à sept et même à huit, car tu ne sais pas quel malheur peut arriver sur la terre.","donnes-en une part à sept et même à huit, car tu ne sais pas quel malheur peut arriver sur la terre."],[11,3,"Quand les nuages sont pleins de pluie, ils la répandent sur la terre; et si un arbre tombe, au midi ou au nord, il reste à la place où il est tombé.","Quand les nuages sont pleins de pluie, ils la répandent sur la terre; et si un arbre tombe, au midi ou au nord, il reste à la place où il est tombé."],[11,4,"Celui qui observe le vent ne sèmera point, et celui qui regarde les nuages ne moissonnera point.","Celui qui observe le vent ne sèmera point, et celui qui regarde les nuages ne moissonnera point."],[11,5,"Comme tu ne sais pas quel est le chemin du vent, ni comment se forment les os dans le ventre de la femme enceinte, tu ne connais pas non plus l'oeuvre de Dieu qui fait tout.","Comme tu ne sais pas quel est le chemin du vent, ni comment se forment les os dans le ventre de la femme enceinte, tu ne connais pas non plus l'oeuvre de Dieu qui fait tout."],[11,6,"Dès le matin sème ta semence, et le soir ne laisse pas reposer ta main; car tu ne sais point ce qui réussira, ceci ou cela, ou si l'un et l'autre sont également bons.","Dès le matin sème ta semence, et le soir ne laisse pas reposer ta main; car tu ne sais point ce qui réussira, ceci ou cela, ou si l'un et l'autre sont également bons."],[11,7,"La lumière est douce, et il est agréable aux yeux de voir le soleil.","La lumière est douce, et il est agréable aux yeux de voir le soleil."],[11,8,"Si donc un homme vit beaucoup d'années, qu'il se réjouisse pendant toutes ces années, et qu'il pense aux jours de ténèbres qui seront nombreux; tout ce qui arrivera est vanité.","Si donc un homme vit beaucoup d'années, qu'il se réjouisse pendant toutes ces années, et qu'il pense aux jours de ténèbres qui seront nombreux; tout ce qui arrivera est vanité."],[11,9,"Jeune homme, réjouis-toi dans ta jeunesse, livre ton coeur à la joie pendant les jours de ta jeunesse, marche dans les voies de ton coeur et selon les regards de tes yeux; mais sache que pour tout cela Dieu t'appellera en jugement.","Jeune homme, réjouis-toi dans ta jeunesse, livre ton coeur à la joie pendant les jours de ta jeunesse, marche dans les voies de ton coeur et selon les regards de tes yeux; mais sache que pour tout cela Dieu t'appellera en jugement."],[11,10,"Bannis de ton coeur le chagrin, et éloigne le mal de ton corps; car la jeunesse et l'aurore sont vanité.","Bannis de ton coeur le chagrin, et éloigne le mal de ton corps; car la jeunesse et l'aurore sont vanité."],[12,1,"Mais souviens-toi de ton créateur pendant les jours de ta jeunesse, avant que les jours mauvais arrivent et que les années s'approchent où tu diras: Je n'y prends point de plaisir;","Mais souviens-toi de ton créateur pendant les jours de ta jeunesse, avant que les jours mauvais arrivent et que les années s'approchent où tu diras: Je n'y prends point de plaisir;"],[12,2,"avant que s'obscurcissent le soleil et la lumière, la lune et les étoiles, et que les nuages reviennent après la pluie,","avant que s'obscurcissent le soleil et la lumière, la lune et les étoiles, et que les nuages reviennent après la pluie,"],[12,3,"temps où les gardiens de la maison tremblent, où les hommes forts se courbent, où celles qui moulent s'arrêtent parce qu'elles sont diminuées, où ceux qui regardent par les fenêtres sont obscurcis,","temps où les gardiens de la maison tremblent, où les hommes forts se courbent, où celles qui moulent s'arrêtent parce qu'elles sont diminuées, où ceux qui regardent par les fenêtres sont obscurcis,"],[12,4,"où les deux battants de la porte se ferment sur la rue quand s'abaisse le bruit de la meule, où l'on se lève au chant de l'oiseau, où s'affaiblissent toutes les filles du chant,","où les deux battants de la porte se ferment sur la rue quand s'abaisse le bruit de la meule, où l'on se lève au chant de l'oiseau, où s'affaiblissent toutes les filles du chant,"],[12,5,"où l'on redoute ce qui est élevé, où l'on a des terreurs en chemin, où l'amandier fleurit, où la sauterelle devient pesante, et où la câpre n'a plus d'effet, car l'homme s'en va vers sa demeure éternelle, et les pleureurs parcourent les rues;","où l'on redoute ce qui est élevé, où l'on a des terreurs en chemin, où l'amandier fleurit, où la sauterelle devient pesante, et où la câpre n'a plus d'effet, car l'homme s'en va vers sa demeure éternelle, et les pleureurs parcourent les rues;"],[12,6,"avant que le cordon d'argent se détache, que le vase d'or se brise, que le seau se rompe sur la source, et que la roue se casse sur la citerne;","avant que le cordon d'argent se détache, que le vase d'or se brise, que le seau se rompe sur la source, et que la roue se casse sur la citerne;"],[12,7,"avant que la poussière retourne à la terre, comme elle y était, et que l'esprit retourne à Dieu qui l'a donné.","avant que la poussière retourne à la terre, comme elle y était, et que l'esprit retourne à Dieu qui l'a donné."],[12,8,"Vanité des vanités, dit l'Ecclésiaste, tout est vanité.","Vanité des vanités, dit l'Ecclésiaste, tout est vanité."],[12,9,"Outre que l'Ecclésiaste fut un sage, il a encore enseigné la science au peuple, et il a examiné, sondé, mis en ordre un grand nombre de sentences.","Outre que l'Ecclésiaste fut un sage, il a encore enseigné la science au peuple, et il a examiné, sondé, mis en ordre un grand nombre de sentences."],[12,10,"L'Ecclésiaste s'est efforcé de trouver des paroles agréables; et ce qui a été écrit avec droiture, ce sont des paroles de vérité.","L'Ecclésiaste s'est efforcé de trouver des paroles agréables; et ce qui a été écrit avec droiture, ce sont des paroles de vérité."],[12,11,"Les paroles des sages sont comme des aiguillons; et, rassemblées en un recueil, elles sont comme des clous plantés, données par un seul maître.","Les paroles des sages sont comme des aiguillons; et, rassemblées en un recueil, elles sont comme des clous plantés, données par un seul maître."],[12,12,"Du reste, mon fils, tire instruction de ces choses; on ne finirait pas, si l'on voulait faire un grand nombre de livres, et beaucoup d'étude est une fatigue pour le corps.","Du reste, mon fils, tire instruction de ces choses; on ne finirait pas, si l'on voulait faire un grand nombre de livres, et beaucoup d'étude est une fatigue pour le corps."],[12,13,"Écoutons la fin du discours: Crains Dieu et observe ses commandements. C'est là ce que doit faire tout homme.","Écoutons la fin du discours: Crains Dieu et observe ses commandements. C'est là ce que doit faire tout homme."],[12,14,"Car Dieu amènera toute oeuvre en jugement, au sujet de tout ce qui est caché, soit bien, soit mal.","Car Dieu amènera toute oeuvre en jugement, au sujet de tout ce qui est caché, soit bien, soit mal."]],"spa-rv1909":[[1,1,"PALABRASdel Predicador, hijode David, reyen Jerusalem.","PALABRASdel Predicador, hijode David, reyen Jerusalem."],[1,2,"Vanidadde vanidades, dijoel Predicador; vanidadde vanidades, todovanidad.","Vanidadde vanidades, dijoel Predicador; vanidadde vanidades, todovanidad."],[1,3,"¿Quéprovechotiene el hombrede todosu trabajocon que se afanadebajodel sol?","¿Quéprovechotiene el hombrede todosu trabajocon que se afanadebajodel sol?"],[1,4,"Generaciónva, y generaciónviene: mas la tierrasiemprepermanece.","Generaciónva, y generaciónviene: mas la tierrasiemprepermanece."],[1,5,"Y saleel sol, y pónese el sol, y con deseo vuelve á su lugardondetorna á nacer.","Y saleel sol, y pónese el sol, y con deseo vuelve á su lugardondetorna á nacer."],[1,6,"El vientotirahaciael mediodía, y rodeaalnorte; vagirandode continuo, y ásus girostornael vientode nuevo.","El vientotirahaciael mediodía, y rodeaalnorte; vagirandode continuo, y ásus girostornael vientode nuevo."],[1,7,"Los ríostodosvaná la mar, y la marnose hinche; allugarde donde los ríosvinieron, allítornan para correrde nuevo.","Los ríostodosvaná la mar, y la marnose hinche; allugarde donde los ríosvinieron, allítornan para correrde nuevo."],[1,8,"Todaslas cosasandan en trabajomásque el hombrepueda decir: nilos ojosviendose hartande ver, nilos oídosse hinchende oir.","Todaslas cosasandan en trabajomásque el hombrepueda decir: nilos ojosviendose hartande ver, nilos oídosse hinchende oir."],[1,9,"¿Quées lo que fué? Lo mismoque será. ¿Quées lo que ha sido hecho? Lo mismoque se hará: y nadahay nuevodebajodel sol.","¿Quées lo que fué? Lo mismoque será. ¿Quées lo que ha sido hecho? Lo mismoque se hará: y nadahay nuevodebajodel sol."],[1,10,"¿Hayalgode que se pueda decir: He aquíestoes nuevo? Yafuéen los siglosquenos han precedido.","¿Hayalgode que se pueda decir: He aquíestoes nuevo? Yafuéen los siglosquenos han precedido."],[1,11,"Nohay memoriade lo que precedió, ni tampocode lo que sucederáhabrámemoriaenlos que serándespués.","Nohay memoriade lo que precedió, ni tampocode lo que sucederáhabrámemoriaenlos que serándespués."],[1,12,"Yoel PredicadorfuíreysobreIsraelen Jerusalem.","Yoel PredicadorfuíreysobreIsraelen Jerusalem."],[1,13,"Y dími corazóná inquiriry buscar con sabiduríasobretodolo quese hacedebajodel cielo: estepenosotrabajodióDiosá los hijosde los hombres, en quese ocupen.","Y dími corazóná inquiriry buscar con sabiduríasobretodolo quese hacedebajodel cielo: estepenosotrabajodióDiosá los hijosde los hombres, en quese ocupen."],[1,14,"Yo mirétodaslas obrasque se hacendebajodel sol; y he aquí, todoello es vanidady aflicciónde espíritu.","Yo mirétodaslas obrasque se hacendebajodel sol; y he aquí, todoello es vanidady aflicciónde espíritu."],[1,15,"Lo torcidonose puede enderezar; y lo falto nopuede contarse.","Lo torcidonose puede enderezar; y lo falto nopuede contarse."],[1,16,"Habléyocon micorazón, diciendo: He aquíhállome yoengrandecido, y he crecidoen sabiduríasobretodoslos quefueronantesde míenJerusalem; y micorazónha percibidomuchedumbre de sabiduríay ciencia.","Habléyocon micorazón, diciendo: He aquíhállome yoengrandecido, y he crecidoen sabiduríasobretodoslos quefueronantesde míenJerusalem; y micorazónha percibidomuchedumbre de sabiduríay ciencia."],[1,17,"Y dí mi corazóná conocerla sabiduría, y también á entenderlas locurasy los desvaríos: conocíque aunestoera aflicciónde espíritu.","Y dí mi corazóná conocerla sabiduría, y también á entenderlas locurasy los desvaríos: conocíque aunestoera aflicciónde espíritu."],[1,18,"Porqueen la muchasabiduríahay muchamolestia; y quien añadeciencia, añadedolor.","Porqueen la muchasabiduríahay muchamolestia; y quien añadeciencia, añadedolor."],[2,1,"DIJEyoen micorazón: Venahora, te probarécon alegría, y gozarásde bienes. Mas he aquíestotambiénera vanidad.","DIJEyoen micorazón: Venahora, te probarécon alegría, y gozarásde bienes. Mas he aquíestotambiénera vanidad."],[2,2,"A la risadije: Enloqueces; y al placer: ¿De quésirveesto?","A la risadije: Enloqueces; y al placer: ¿De quésirveesto?"],[2,3,"Propuseen mi corazónagasajar mi carnecon vino, y que anduviesemi corazónen sabiduría, con retenciónde la necedad, hastavercuál fuese el biende los hijosde los hombres, en el cualse ocuparandebajodel cielotodoslos díasde su vida.","Propuseen mi corazónagasajar mi carnecon vino, y que anduviesemi corazónen sabiduría, con retenciónde la necedad, hastavercuál fuese el biende los hijosde los hombres, en el cualse ocuparandebajodel cielotodoslos díasde su vida."],[2,4,"Engrandecímis obras, edifiquémecasas, plantémeviñas;","Engrandecímis obras, edifiquémecasas, plantémeviñas;"],[2,5,"Híceme huertosy jardines, y plantéen ellos árbolesde todos frutos;","Híceme huertosy jardines, y plantéen ellos árbolesde todos frutos;"],[2,6,"Híceme estanquesde aguas, para regarde ellosel bosquedonde los árbolescrecían.","Híceme estanquesde aguas, para regarde ellosel bosquedonde los árbolescrecían."],[2,7,"Poseísiervosy siervas, y tuvehijosde familia; tambiéntuveposesióngrandede vacasy ovejas, sobre todoslos que fueronantesde mí en Jerusalem;","Poseísiervosy siervas, y tuvehijosde familia; tambiéntuveposesióngrandede vacasy ovejas, sobre todoslos que fueronantesde mí en Jerusalem;"],[2,8,"Alleguémetambiénplatay oro, y tesoropreciado de reyesy de provincias; híceme de cantoresy cantoras, y los deleitesde los hijosde los hombres, instrumentosmúsicos y de todas suertes.","Alleguémetambiénplatay oro, y tesoropreciado de reyesy de provincias; híceme de cantoresy cantoras, y los deleitesde los hijosde los hombres, instrumentosmúsicos y de todas suertes."],[2,9,"Y fuí engrandecido, y aumentadomás que todoslos que fueronantesde mí en Jerusalem: á más de esto perseveró conmigomi sabiduría.","Y fuí engrandecido, y aumentadomás que todoslos que fueronantesde mí en Jerusalem: á más de esto perseveró conmigomi sabiduría."],[2,10,"Noneguéá mis ojosningunacosa quedesearan, niapartémi corazónde placeralguno, porquemi corazóngozóde todomi trabajo: y éstafuémi parte de todami faena.","Noneguéá mis ojosningunacosa quedesearan, niapartémi corazónde placeralguno, porquemi corazóngozóde todomi trabajo: y éstafuémi parte de todami faena."],[2,11,"Miréyoluego todaslas obrasque habían hechomismanos, y el trabajoque tomépara hacerlas: y he aquí, todovanidady aflicciónde espíritu, y no hay provechodebajodel sol.","Miréyoluego todaslas obrasque habían hechomismanos, y el trabajoque tomépara hacerlas: y he aquí, todovanidady aflicciónde espíritu, y no hay provechodebajodel sol."],[2,12,"Después torné yoá mirar para verla sabiduríay los desvaríosy la necedad; (porque¿quéhombrehayque puedaseguiral reyenlo queyahicieron?)","Después torné yoá mirar para verla sabiduríay los desvaríosy la necedad; (porque¿quéhombrehayque puedaseguiral reyenlo queyahicieron?)"],[2,13,"Y he vistoque la sabiduríasobrepujaála necedad, como la luzálas tinieblas.","Y he vistoque la sabiduríasobrepujaála necedad, como la luzálas tinieblas."],[2,14,"El sabiotiene sus ojosen su cabeza, mas el necioandaen tinieblas: empero tambiénentendíyoque unmismo sucesoacaeceráal uno queal otro.","El sabiotiene sus ojosen su cabeza, mas el necioandaen tinieblas: empero tambiénentendíyoque unmismo sucesoacaeceráal uno queal otro."],[2,15,"Entonces dijeyoen micorazón: Como sucederáal neciomesucederátambiéná mí: ¿para quépues he trabajado hasta ahorapor hacerme más sabio? Y dijeen micorazón, que tambiénestoera vanidad.","Entonces dijeyoen micorazón: Como sucederáal neciomesucederátambiéná mí: ¿para quépues he trabajado hasta ahorapor hacerme más sabio? Y dijeen micorazón, que tambiénestoera vanidad."],[2,16,"Porquenidel sabionidel neciohabrá memoriapara siempre; pues en los díasveniderosyatodoserá olvidado, y tambiénmoriráel sabiocomoel necio.","Porquenidel sabionidel neciohabrá memoriapara siempre; pues en los díasveniderosyatodoserá olvidado, y tambiénmoriráel sabiocomoel necio."],[2,17,"Aborrecípor tanto la vida; porquela obraque se hacedebajodel solmeera fastidiosa; porcuanto todoes vanidady aflicciónde espíritu.","Aborrecípor tanto la vida; porquela obraque se hacedebajodel solmeera fastidiosa; porcuanto todoes vanidady aflicciónde espíritu."],[2,18,"Yo asimismo aborrecítodomitrabajoque había puesto por obradebajodel sol; el cual dejaré á otroque vendrádespuésde mí.","Yo asimismo aborrecítodomitrabajoque había puesto por obradebajodel sol; el cual dejaré á otroque vendrádespuésde mí."],[2,19,"¿Y quiénsabesi serásabio, ónecio, el que se enseñorearáde todomi trabajoen que yo me afané, y en que ocupé debajodel solmi sabiduría? Estotambiénes vanidad.","¿Y quiénsabesi serásabio, ónecio, el que se enseñorearáde todomi trabajoen que yo me afané, y en que ocupé debajodel solmi sabiduría? Estotambiénes vanidad."],[2,20,"Tornémepor tanto á desesperanzarmicorazónacerca detodoel trabajoen que me afané, y en que había ocupado debajodel solmisabiduría.","Tornémepor tanto á desesperanzarmicorazónacerca detodoel trabajoen que me afané, y en que había ocupado debajodel solmisabiduría."],[2,21,"¡Queel hombretrabajecon sabiduría, y con ciencia, y con rectitud, y quehaya de darsu haciendaá hombrequenuncatrabajóen ello! Tambiénes estovanidady malgrande.","¡Queel hombretrabajecon sabiduría, y con ciencia, y con rectitud, y quehaya de darsu haciendaá hombrequenuncatrabajóen ello! Tambiénes estovanidady malgrande."],[2,22,"Porque¿quétiene el hombrede todosutrabajo, y fatigade sucorazón, con que debajodel solél se afanara?","Porque¿quétiene el hombrede todosutrabajo, y fatigade sucorazón, con que debajodel solél se afanara?"],[2,23,"Porquetodossusdíasnoson sinodolores, y sustrabajosmolestias: aunde nochesucorazónnoreposa. Estotambiénes vanidad.","Porquetodossusdíasnoson sinodolores, y sustrabajosmolestias: aunde nochesucorazónnoreposa. Estotambiénes vanidad."],[2,24,"Nohay cosa mejorpara el hombresinoque comay beba, y que sualmavea el bien de sutrabajo. Tambiéntengo yo vistoqueestoes de la manode Dios.","Nohay cosa mejorpara el hombresinoque comay beba, y que sualmavea el bien de sutrabajo. Tambiéntengo yo vistoqueestoes de la manode Dios."],[2,25,"Porque¿quiéncomerá, y quiénse cuidará, mejorqueyo?","Porque¿quiéncomerá, y quiénse cuidará, mejorqueyo?"],[2,26,"Porqueal hombreque le agrada, Diosle dasabiduríay cienciay gozo: mas al pecadordatrabajo, el que allegue y amontone, para que dé al que agradaá Dios. Tambiénestoes vanidady aflicciónde espíritu.","Porqueal hombreque le agrada, Diosle dasabiduríay cienciay gozo: mas al pecadordatrabajo, el que allegue y amontone, para que dé al que agradaá Dios. Tambiénestoes vanidady aflicciónde espíritu."],[3,1,"PARA todas las cosas hay sazón, y todolo que se quieredebajodel cielo, tiene sutiempo:","PARA todas las cosas hay sazón, y todolo que se quieredebajodel cielo, tiene sutiempo:"],[3,2,"Tiempode nacer, y tiempode morir; tiempode plantar, y tiempode arrancarlo plantado;","Tiempode nacer, y tiempode morir; tiempode plantar, y tiempode arrancarlo plantado;"],[3,3,"Tiempode matar, y tiempode curar; tiempode destruir, y tiempode edificar;","Tiempode matar, y tiempode curar; tiempode destruir, y tiempode edificar;"],[3,4,"Tiempode llorar, y tiempode reir; tiempode endechar, y tiempode bailar;","Tiempode llorar, y tiempode reir; tiempode endechar, y tiempode bailar;"],[3,5,"Tiempode esparcirlas piedras, y tiempode allegar las piedras; tiempode abrazar, y tiempode alejarse de abrazar;","Tiempode esparcirlas piedras, y tiempode allegar las piedras; tiempode abrazar, y tiempode alejarse de abrazar;"],[3,6,"Tiempode agenciar, y tiempode perder; tiempode guardar, y tiempode arrojar;","Tiempode agenciar, y tiempode perder; tiempode guardar, y tiempode arrojar;"],[3,7,"Tiempode romper, y tiempode coser; tiempode callar, y tiempode hablar;","Tiempode romper, y tiempode coser; tiempode callar, y tiempode hablar;"],[3,8,"Tiempode amar, y tiempode aborrecer; tiempode guerra, y tiempode paz.","Tiempode amar, y tiempode aborrecer; tiempode guerra, y tiempode paz."],[3,9,"¿Quéprovechotiene el que trabajaen lo quetrabaja?","¿Quéprovechotiene el que trabajaen lo quetrabaja?"],[3,10,"Yo he vistoel trabajoqueDiosha dadoá los hijosde los hombrespara queen él se ocupasen.","Yo he vistoel trabajoqueDiosha dadoá los hijosde los hombrespara queen él se ocupasen."],[3,11,"Todolo hizohermosoen su tiempo: yaun el mundo dió en su corazón, de tal manera queno alcanceel hombrela obrade Diosdesde el principiohastael cabo.","Todolo hizohermosoen su tiempo: yaun el mundo dió en su corazón, de tal manera queno alcanceel hombrela obrade Diosdesde el principiohastael cabo."],[3,12,"Yo he conocido quenohaymejorpara ellos, quealegrarse, y hacerbienen su vida:","Yo he conocido quenohaymejorpara ellos, quealegrarse, y hacerbienen su vida:"],[3,13,"Y tambiénque es donde Diosque todohombrecomay beba, y goceel biende todasulabor.","Y tambiénque es donde Diosque todohombrecomay beba, y goceel biende todasulabor."],[3,14,"He entendidoquetodolo queDioshace, eso seráperpetuo: sobreaquellonose añadirá, nide ellosedisminuirá; y háceloDios, para quedelantede él temanlos hombres.","He entendidoquetodolo queDioshace, eso seráperpetuo: sobreaquellonose añadirá, nide ellosedisminuirá; y háceloDios, para quedelantede él temanlos hombres."],[3,15,"Aquelloque fué, yaes: y lo queha de ser, fuéya; y Diosrestauralo quepasó.","Aquelloque fué, yaes: y lo queha de ser, fuéya; y Diosrestauralo quepasó."],[3,16,"Vimásdebajodel sol: en lugardel juicio, allíla impiedad; y en lugarde la justicia, allíla iniquidad.","Vimásdebajodel sol: en lugardel juicio, allíla impiedad; y en lugarde la justicia, allíla iniquidad."],[3,17,"Y dijeyoen micorazón: Al justoy al impíojuzgaráDios; porqueallíhay tiempoá todolo que se quierey sobre todolo que se hace.","Y dijeyoen micorazón: Al justoy al impíojuzgaráDios; porqueallíhay tiempoá todolo que se quierey sobre todolo que se hace."],[3,18,"Dijeen micorazón, en ordená la condiciónde los hijosde los hombres, que Dioslosprobaría, para que así echaran de ver ellosmismosque son semejantesá las bestias.","Dijeen micorazón, en ordená la condiciónde los hijosde los hombres, que Dioslosprobaría, para que así echaran de ver ellosmismosque son semejantesá las bestias."],[3,19,"Porqueel sucesode los hijosde los hombres, y el sucesodel animal, el mismo sucesoes: como muerenlos unos, asímuerenlos otros; y unamisma respiracióntienen todos; ni tiene másel hombreque la bestia: porquetodoes vanidad.","Porqueel sucesode los hijosde los hombres, y el sucesodel animal, el mismo sucesoes: como muerenlos unos, asímuerenlos otros; y unamisma respiracióntienen todos; ni tiene másel hombreque la bestia: porquetodoes vanidad."],[3,20,"Todovaáunlugar: todoes hechodelpolvo, y todose tornará en el mismo polvo.","Todovaáunlugar: todoes hechodelpolvo, y todose tornará en el mismo polvo."],[3,21,"¿Quiénsabeque el espíritude los hijosde los hombressuba arriba, y que el espíritudel animaldescienda debajo de la tierra?","¿Quiénsabeque el espíritude los hijosde los hombressuba arriba, y que el espíritudel animaldescienda debajo de la tierra?"],[3,22,"Así que he vistoquenohay cosa mejorque alegrarseel hombrecon loque hiciere; porqueestaes suparte: porque¿quiénlollevarápara que vealoque ha de serdespuésde él?","Así que he vistoquenohay cosa mejorque alegrarseel hombrecon loque hiciere; porqueestaes suparte: porque¿quiénlollevarápara que vealoque ha de serdespuésde él?"],[4,1,"Y TORNÉME yo, y vitodaslas violenciasquese hacendebajodel sol: y he aquílas lágrimasde los oprimidos, y sintener quien los consuele; y la fuerzaestaba en la manode sus opresores, y para ellos nohabía consolador.","Y TORNÉME yo, y vitodaslas violenciasquese hacendebajodel sol: y he aquílas lágrimasde los oprimidos, y sintener quien los consuele; y la fuerzaestaba en la manode sus opresores, y para ellos nohabía consolador."],[4,2,"Y alabéyolos finadosque yamurieron, más quelos vivientesquehasta ahora están vivos.","Y alabéyolos finadosque yamurieron, más quelos vivientesquehasta ahora están vivos."],[4,3,"Y tuvepor mejor que unos y otrosal quenoha sidoaún, quenoha vistolas malasobrasquedebajodel solse hacen.","Y tuvepor mejor que unos y otrosal quenoha sidoaún, quenoha vistolas malasobrasquedebajodel solse hacen."],[4,4,"Vistohe asimismo quetodotrabajoy todaexcelenciade obrasmueve la envidiadel hombrecontra su prójimo. Tambiénestoes vanidady aflicciónde espíritu.","Vistohe asimismo quetodotrabajoy todaexcelenciade obrasmueve la envidiadel hombrecontra su prójimo. Tambiénestoes vanidady aflicciónde espíritu."],[4,5,"El neciodoblasus manosy comesu carne.","El neciodoblasus manosy comesu carne."],[4,6,"Mas valeel un puñollenocon descanso, que ambos puñosllenoscon trabajoy aflicciónde espíritu.","Mas valeel un puñollenocon descanso, que ambos puñosllenoscon trabajoy aflicciónde espíritu."],[4,7,"Yome torné otra vez, y vivanidaddebajodel sol.","Yome torné otra vez, y vivanidaddebajodel sol."],[4,8,"Estáun hombre soloy sinsucesor; queni tiene hijoni hermano; mas nuncacesade trabajar, nisusojosse hartande susriquezas, ni se pregunta: ¿Para quiéntrabajoyo, y defraudomialmadel bien? También estoesvanidad, y durotrabajo.","Estáun hombre soloy sinsucesor; queni tiene hijoni hermano; mas nuncacesade trabajar, nisusojosse hartande susriquezas, ni se pregunta: ¿Para quiéntrabajoyo, y defraudomialmadel bien? También estoesvanidad, y durotrabajo."],[4,9,"Mejoresson dosqueuno; porquetienenmejorpagade sutrabajo.","Mejoresson dosqueuno; porquetienenmejorpagade sutrabajo."],[4,10,"Porquesicayeren, el unolevantaráá su compañero: mas ¡aydel solo! que cuando cayere, nohabrá segundoque lo levante.","Porquesicayeren, el unolevantaráá su compañero: mas ¡aydel solo! que cuando cayere, nohabrá segundoque lo levante."],[4,11,"Tambiénsidosdurmierenjuntos, se calentarán; mas ¿cómose calentaráunosolo?","Tambiénsidosdurmierenjuntos, se calentarán; mas ¿cómose calentaráunosolo?"],[4,12,"Y sialguno prevalecierecontra el uno, dosestaráncontra él; y cordónde tresdobleces noprestose rompe.","Y sialguno prevalecierecontra el uno, dosestaráncontra él; y cordónde tresdobleces noprestose rompe."],[4,13,"Mejores el muchachopobrey sabio, que el reyviejoy fatuo quenosabe ser aconsejado.","Mejores el muchachopobrey sabio, que el reyviejoy fatuo quenosabe ser aconsejado."],[4,14,"Porquede la cárcelsaliópara reinar; mientras el nacido en su reinose hizo pobre.","Porquede la cárcelsaliópara reinar; mientras el nacido en su reinose hizo pobre."],[4,15,"Vitodoslos vivientes debajodel solcaminandoconel muchachosucesor, que estaráen lugarde aquél.","Vitodoslos vivientes debajodel solcaminandoconel muchachosucesor, que estaráen lugarde aquél."],[4,16,"Notiene fintodo el puebloquefué antes de ellos: tampocolos quevendrán despuésestarán con élcontentos. Y estoes tambiénvanidady aflicciónde espíritu.","Notiene fintodo el puebloquefué antes de ellos: tampocolos quevendrán despuésestarán con élcontentos. Y estoes tambiénvanidady aflicciónde espíritu."],[5,1,"CUANDO fueresála casade Dios, guardatu pie; y acércatemás para oirque para dar el sacrificiode los necios: porquenosabenque hacenmal.","CUANDO fueresála casade Dios, guardatu pie; y acércatemás para oirque para dar el sacrificiode los necios: porquenosabenque hacenmal."],[5,2,"Note des priesacontuboca, nitucorazónse apresureá proferirpalabradelantede Dios; porqueDiosestá en el cielo, y túsobrela tierra: portanto, seanpocastuspalabras.","Note des priesacontuboca, nitucorazónse apresureá proferirpalabradelantede Dios; porqueDiosestá en el cielo, y túsobrela tierra: portanto, seanpocastuspalabras."],[5,3,"Porquede la muchaocupaciónvieneel sueño, y de la multitudde las palabrasla vozdel necio.","Porquede la muchaocupaciónvieneel sueño, y de la multitudde las palabrasla vozdel necio."],[5,4,"Cuando á Dioshicierespromesa, notardesen pagarla; porquenose agradade los insensatos. Pagalo queprometieres.","Cuando á Dioshicierespromesa, notardesen pagarla; porquenose agradade los insensatos. Pagalo queprometieres."],[5,5,"Mejores quenoprometas, que noque prometasy nopagues.","Mejores quenoprometas, que noque prometasy nopagues."],[5,6,"Nosueltes tu bocapara hacer pecar á tu carne; nidigasdelantedel ángel, que fué ignorancia. ¿Por quéharás queDiosse aire á causa detu voz, y que destruyala obradetus manos?","Nosueltes tu bocapara hacer pecar á tu carne; nidigasdelantedel ángel, que fué ignorancia. ¿Por quéharás queDiosse aire á causa detu voz, y que destruyala obradetus manos?"],[5,7,"Donde los sueñossonen multitud, también lo sonlas vanidadesy muchaslas palabras; mastú temeá Dios.","Donde los sueñossonen multitud, también lo sonlas vanidadesy muchaslas palabras; mastú temeá Dios."],[5,8,"Siviolenciasde pobres, y extorsiónde derechoy de justiciavieresen la provincia, note maravillesde esta licencia; porquealtoestá mirando sobre alto, y unomás altoestásobreellos.","Siviolenciasde pobres, y extorsiónde derechoy de justiciavieresen la provincia, note maravillesde esta licencia; porquealtoestá mirando sobre alto, y unomás altoestásobreellos."],[5,9,"Además el provechode la tierraes para todos: el reymismoestá sujetoá los campos.","Además el provechode la tierraes para todos: el reymismoestá sujetoá los campos."],[5,10,"El que amael dinero, nose hartará de dinero; y el que amael muchotener, nosacaráfruto. Tambiénestoes vanidad.","El que amael dinero, nose hartará de dinero; y el que amael muchotener, nosacaráfruto. Tambiénestoes vanidad."],[5,11,"Cuando los bienesse aumentan, también se aumentansus comedores. ¿Québien, pues, tendrá su dueño, sino verloscon sus ojos?","Cuando los bienesse aumentan, también se aumentansus comedores. ¿Québien, pues, tendrá su dueño, sino verloscon sus ojos?"],[5,12,"Dulcees el sueñodel trabajador, ora comamuchoó poco; mas al rico nole dejadormir la hartura.","Dulcees el sueñodel trabajador, ora comamuchoó poco; mas al rico nole dejadormir la hartura."],[5,13,"Hayuna trabajosa enfermedad que he vistodebajodel sol: las riquezasguardadasde sus dueñospara su mal;","Hayuna trabajosa enfermedad que he vistodebajodel sol: las riquezasguardadasde sus dueñospara su mal;"],[5,14,"Las cualesse pierdenen malasocupaciones, y á los hijosque engendraron nadalesqueda en la mano.","Las cualesse pierdenen malasocupaciones, y á los hijosque engendraron nadalesqueda en la mano."],[5,15,"Comosaliódel vientrede su madre, desnudo, así se vuelve, tornandocomovino; y nadatuvode su trabajopara llevaren su mano.","Comosaliódel vientrede su madre, desnudo, así se vuelve, tornandocomovino; y nadatuvode su trabajopara llevaren su mano."],[5,16,"Estetambiénes un granmal, que como vino, asíhaya de volver. ¿Y de quéle aprovechótrabajaral viento?","Estetambiénes un granmal, que como vino, asíhaya de volver. ¿Y de quéle aprovechótrabajaral viento?"],[5,17,"Demás de esto, todoslos díasde su vida comeráen tinieblas, con muchoenojo y dolory miseria.","Demás de esto, todoslos díasde su vida comeráen tinieblas, con muchoenojo y dolory miseria."],[5,18,"He aquí puesel bienqueyohe visto: Quelo buenoes comery beber, y gozaruno del biende todosutrabajocon quese fatigadebajodel sol, todoslos díasde suvidaqueDiosle ha dado; porqueestaes suparte.","He aquí puesel bienqueyohe visto: Quelo buenoes comery beber, y gozaruno del biende todosutrabajocon quese fatigadebajodel sol, todoslos díasde suvidaqueDiosle ha dado; porqueestaes suparte."],[5,19,"Asimismo, á todohombreá quienDiosdióriquezasy hacienda, y ledió también facultadpara que comadeellas, y tome suparte, y gocesutrabajo; estoes dondeDios.","Asimismo, á todohombreá quienDiosdióriquezasy hacienda, y ledió también facultadpara que comadeellas, y tome suparte, y gocesutrabajo; estoes dondeDios."],[5,20,"Porquenose acordarámuchode los díasde su vida; puesDiosle responderá con alegríade su corazón.","Porquenose acordarámuchode los díasde su vida; puesDiosle responderá con alegríade su corazón."],[6,1,"HAYun malquehe vistodebajodel cielo, y muycomún entrelos hombres:","HAYun malquehe vistodebajodel cielo, y muycomún entrelos hombres:"],[6,2,"Hombreá quienDiosdióriquezas, y hacienda, y honra, y nadale faltadetodolo que sualmadesea; mas Diosnoledió facultaddecomer deello, sino quelos extrañosse locomen. Estovanidades, y enfermedadtrabajosa.","Hombreá quienDiosdióriquezas, y hacienda, y honra, y nadale faltadetodolo que sualmadesea; mas Diosnoledió facultaddecomer deello, sino quelos extrañosse locomen. Estovanidades, y enfermedadtrabajosa."],[6,3,"Si el hombreengendrareciento, y vivieremuchosaños, y los díasde su edadfuerennumerosos; si su almanose hartó delbien, y tambiéncarecióde sepultura, yo digoque el abortivoes mejorqueél.","Si el hombreengendrareciento, y vivieremuchosaños, y los díasde su edadfuerennumerosos; si su almanose hartó delbien, y tambiéncarecióde sepultura, yo digoque el abortivoes mejorqueél."],[6,4,"Porqueen vanovino, y á tinieblasva, y con tinieblasserá cubiertosu nombre.","Porqueen vanovino, y á tinieblasva, y con tinieblasserá cubiertosu nombre."],[6,5,"Aunque nohaya vistoel sol, niconocidonada, más reposotiene ésteque aquél.","Aunque nohaya vistoel sol, niconocidonada, más reposotiene ésteque aquél."],[6,6,"Porque siviviereaquélmilañosdosveces, sinoha gozado del bien, cierto todosvaná un lugar.","Porque siviviereaquélmilañosdosveces, sinoha gozado del bien, cierto todosvaná un lugar."],[6,7,"Todoel trabajodel hombrees para su boca, ycon todoeso su almanose harta.","Todoel trabajodel hombrees para su boca, ycon todoeso su almanose harta."],[6,8,"Porque¿quémás tiene el sabioqueel necio? ¿quémástiene el pobrequesupocaminar entrelos vivos?","Porque¿quémás tiene el sabioqueel necio? ¿quémástiene el pobrequesupocaminar entrelos vivos?"],[6,9,"Más valevistade ojosque deseoque pasa. Y también estoesvanidady aflicciónde espíritu.","Más valevistade ojosque deseoque pasa. Y también estoesvanidady aflicciónde espíritu."],[6,10,"El quees, yasu nombrehasido nombrado; y se sabeque eshombre, y que nopodrá contendercon el queesmás fuerteque él.","El quees, yasu nombrehasido nombrado; y se sabeque eshombre, y que nopodrá contendercon el queesmás fuerteque él."],[6,11,"Ciertamentelas muchaspalabrasmultiplicanla vanidad. ¿Quémás tiene el hombre?","Ciertamentelas muchaspalabrasmultiplicanla vanidad. ¿Quémás tiene el hombre?"],[6,12,"Porque¿quiénsabecuáles el biendel hombreen la vida, todoslos díasde la vidade su vanidad, los cuales él pasacomo sombra? Porque¿quiénenseñaráal hombrequéserádespuésde él debajodel sol?","Porque¿quiénsabecuáles el biendel hombreen la vida, todoslos díasde la vidade su vanidad, los cuales él pasacomo sombra? Porque¿quiénenseñaráal hombrequéserádespuésde él debajodel sol?"],[7,1,"MEJORes la buenafamaque el buenungüento; y el díade la muerteque el díadel nacimiento.","MEJORes la buenafamaque el buenungüento; y el díade la muerteque el díadel nacimiento."],[7,2,"Mejores irála casadel lutoque ála casadel convite: porque aquelloes el finde todoslos hombres; y el que viveparará mientes.","Mejores irála casadel lutoque ála casadel convite: porque aquelloes el finde todoslos hombres; y el que viveparará mientes."],[7,3,"Mejores el enojo que la risa: porquecon la tristezadel rostrose enmendaráel corazón.","Mejores el enojo que la risa: porquecon la tristezadel rostrose enmendaráel corazón."],[7,4,"El corazónde los sabios, en la casadel luto; masel corazónde los insensatos, en la casadel placer.","El corazónde los sabios, en la casadel luto; masel corazónde los insensatos, en la casadel placer."],[7,5,"Mejores oirla reprensióndel sabio, que la canciónde los necios.","Mejores oirla reprensióndel sabio, que la canciónde los necios."],[7,6,"Porquela risadel necioes como el estrépitode las espinasdebajode la olla. Y tambiénestoes vanidad.","Porquela risadel necioes como el estrépitode las espinasdebajode la olla. Y tambiénestoes vanidad."],[7,7,"Ciertamentela opresiónhace enloquecer al sabio: y el presente corrompe el corazón.","Ciertamentela opresiónhace enloquecer al sabio: y el presente corrompe el corazón."],[7,8,"Mejores el findel negocioque su principio: mejores el sufridode espírituque el altivode espíritu.","Mejores el findel negocioque su principio: mejores el sufridode espírituque el altivode espíritu."],[7,9,"Note apresuresen tu espírituá enojarte: porquela ira en el senode los neciosreposa.","Note apresuresen tu espírituá enojarte: porquela ira en el senode los neciosreposa."],[7,10,"Nuncadigas: ¿Qué esla causa que los tiempospasadosfueronmejoresque éstos? Porquenuncade esto preguntaráscon sabiduría.","Nuncadigas: ¿Qué esla causa que los tiempospasadosfueronmejoresque éstos? Porquenuncade esto preguntaráscon sabiduría."],[7,11,"Buenaes la cienciaconherencia; y más á los que venel sol.","Buenaes la cienciaconherencia; y más á los que venel sol."],[7,12,"Porqueescudoes la ciencia, y escudoes el dinero: mas la sabiduríaexcedeen que da vidaá sus poseedores.","Porqueescudoes la ciencia, y escudoes el dinero: mas la sabiduríaexcedeen que da vidaá sus poseedores."],[7,13,"Mirala obrade Dios; porque¿quiénpodráenderezar lo queél torció?","Mirala obrade Dios; porque¿quiénpodráenderezar lo queél torció?"],[7,14,"En el díadel biengozadel bien; y en el díadel mal considera. Diostambién hizoesto delante de lo otro, porque el hombreno hallenadatrasde él.","En el díadel biengozadel bien; y en el díadel mal considera. Diostambién hizoesto delante de lo otro, porque el hombreno hallenadatrasde él."],[7,15,"Todoesto he vistoen los díasde mi vanidad. Justohayque perecepor su justicia, y hayimpíoque por su maldadalargasus días.","Todoesto he vistoen los díasde mi vanidad. Justohayque perecepor su justicia, y hayimpíoque por su maldadalargasus días."],[7,16,"Noseasdemasiadojusto, niseassabiocon exceso: ¿por quéte destruirás?","Noseasdemasiadojusto, niseassabiocon exceso: ¿por quéte destruirás?"],[7,17,"Nohagasmal mucho, niseasinsensato: ¿por quémorirás antes de tu tiempo?","Nohagasmal mucho, niseasinsensato: ¿por quémorirás antes de tu tiempo?"],[7,18,"Buenoes quetomesesto, y tambiénde estotro noapartestu mano; porqueel queá Diosteme, saldrácon todo.","Buenoes quetomesesto, y tambiénde estotro noapartestu mano; porqueel queá Diosteme, saldrácon todo."],[7,19,"La sabiduríafortifica al sabiomás que diezpoderososla ciudaden quefueron.","La sabiduríafortifica al sabiomás que diezpoderososla ciudaden quefueron."],[7,20,"Ciertamentenohay hombrejustoen la tierra, quehagabieny nuncapeque.","Ciertamentenohay hombrejustoen la tierra, quehagabieny nuncapeque."],[7,21,"Tampocoapliquestu corazóná todaslas cosasquese hablaren, porque nooigasá tu siervoquedice malde ti:","Tampocoapliquestu corazóná todaslas cosasquese hablaren, porque nooigasá tu siervoquedice malde ti:"],[7,22,"Porquetucorazónsabe, como tútambiéndijiste malde otrosmuchasveces.","Porquetucorazónsabe, como tútambiéndijiste malde otrosmuchasveces."],[7,23,"Todasestascosas probécon sabiduría, diciendo: Hacerme he sabio: mas ella se alejódemí.","Todasestascosas probécon sabiduría, diciendo: Hacerme he sabio: mas ella se alejódemí."],[7,24,"Lejosestá loque fué; y lomuy profundo¿quiénlohallará?","Lejosestá loque fué; y lomuy profundo¿quiénlohallará?"],[7,25,"Yo he rodeado con micorazónpor saber, y examinar, é inquirirla sabiduría, y la razón; y por conocerla maldadde la insensatez, y el desvaríodel error;","Yo he rodeado con micorazónpor saber, y examinar, é inquirirla sabiduría, y la razón; y por conocerla maldadde la insensatez, y el desvaríodel error;"],[7,26,"Y yo he halladomás amargaquela muertela mujer, la cual es redes, y lazossu corazón; susmanoscomoligaduras. El queagradaá Diosescaparádeella; mas el pecadorserá presoen ella.","Y yo he halladomás amargaquela muertela mujer, la cual es redes, y lazossu corazón; susmanoscomoligaduras. El queagradaá Diosescaparádeella; mas el pecadorserá presoen ella."],[7,27,"He aquí, estohe hallado, diceel Predicador, pesandolas cosas unapor unapara hallarla razón;","He aquí, estohe hallado, diceel Predicador, pesandolas cosas unapor unapara hallarla razón;"],[7,28,"Lo queaun buscamialma, y noencuentro: unhombreentre milhe hallado; mas mujerde todaséstasnunca hallé.","Lo queaun buscamialma, y noencuentro: unhombreentre milhe hallado; mas mujerde todaséstasnunca hallé."],[7,29,"He aquí, solamentehe halladoesto: queDioshizoal hombrerecto, mas ellosbuscaronmuchascuentas.","He aquí, solamentehe halladoesto: queDioshizoal hombrerecto, mas ellosbuscaronmuchascuentas."],[8,1,"¿QUIÉNcomo el sabio? ¿y quiéncomoel que sabela declaraciónde las cosas? La sabiduríadel hombrehará relucirsu rostro, y mudarásela tosquedadde su semblante.","¿QUIÉNcomo el sabio? ¿y quiéncomoel que sabela declaraciónde las cosas? La sabiduríadel hombrehará relucirsu rostro, y mudarásela tosquedadde su semblante."],[8,2,"Yo te avisoque guardesel mandamientodel reyy la palabradeljuramentode Dios.","Yo te avisoque guardesel mandamientodel reyy la palabradeljuramentode Dios."],[8,3,"Note apresuresá irtede delantede él, nien cosamalapersistas; porqueél harátodolo quequisiere:","Note apresuresá irtede delantede él, nien cosamalapersistas; porqueél harátodolo quequisiere:"],[8,4,"Pues la palabradel reyes conpotestad, ¿y quiénle dirá, Quéhaces?","Pues la palabradel reyes conpotestad, ¿y quiénle dirá, Quéhaces?"],[8,5,"El que guardael mandamientonoexperimentarámal; y el tiempoy el juicioconoce el corazóndel sabio.","El que guardael mandamientonoexperimentarámal; y el tiempoy el juicioconoce el corazóndel sabio."],[8,6,"Porquepara todolo que quisiereshaytiempoy juicio; mas el trabajo del hombrees grandesobreél;","Porquepara todolo que quisiereshaytiempoy juicio; mas el trabajo del hombrees grandesobreél;"],[8,7,"Porque nosabeloque ha de ser; y el cuándo haya de ser, ¿quiénse loenseñará?","Porque nosabeloque ha de ser; y el cuándo haya de ser, ¿quiénse loenseñará?"],[8,8,"Nohay hombreque tenga potestadsobre el espíritupara retenerel espíritu, nipotestadsobre el díade la muerte: y novalenarmasen talguerra; nila impiedadlibraráal que la posee.","Nohay hombreque tenga potestadsobre el espíritupara retenerel espíritu, nipotestadsobre el díade la muerte: y novalenarmasen talguerra; nila impiedadlibraráal que la posee."],[8,9,"Todoestohe visto, y puestohe mi corazónen todolo quedebajodel solse hace: hay tiempoen queel hombrese enseñoreadel hombrepara malsuyo.","Todoestohe visto, y puestohe mi corazónen todolo quedebajodel solse hace: hay tiempoen queel hombrese enseñoreadel hombrepara malsuyo."],[8,10,"Estovitambién: que los impíossepultadosvinieron aún en memoria; mas los que partierondel lugarsanto, fueronluego puestos en olvidoen la ciudaddondecon rectitudhabían obrado. Estotambiénes vanidad.","Estovitambién: que los impíossepultadosvinieron aún en memoria; mas los que partierondel lugarsanto, fueronluego puestos en olvidoen la ciudaddondecon rectitudhabían obrado. Estotambiénes vanidad."],[8,11,"Porque nose ejecutaluego sentenciasobre la malaobra, el corazónde los hijosde los hombresestá en elloslleno para hacermal.","Porque nose ejecutaluego sentenciasobre la malaobra, el corazónde los hijosde los hombresestá en elloslleno para hacermal."],[8,12,"Bien queel pecadorhagamalcienveces, y le sea dilatado el castigo, contodo yotambiénséquelos que á Diostementendrán bien, los quetemierenante su presencia;","Bien queel pecadorhagamalcienveces, y le sea dilatado el castigo, contodo yotambiénséquelos que á Diostementendrán bien, los quetemierenante su presencia;"],[8,13,"Y que el impíonotendrá bien, nile serán prolongadoslos días, que soncomo sombra; por cuantonotemió delante de la presenciade Dios.","Y que el impíonotendrá bien, nile serán prolongadoslos días, que soncomo sombra; por cuantonotemió delante de la presenciade Dios."],[8,14,"Hayvanidadquese hacesobrela tierra: quehayjustosá quienessucedecomo si hicieranobrasde impíos; y hayimpíosá quienes acaececomo si hicieranobrasde justos. Digoqueestotambiénes vanidad.","Hayvanidadquese hacesobrela tierra: quehayjustosá quienessucedecomo si hicieranobrasde impíos; y hayimpíosá quienes acaececomo si hicieranobrasde justos. Digoqueestotambiénes vanidad."],[8,15,"Por tanto alabéyo la alegría; quenotiene el hombrebiendebajodel sol, sino quecomay beba, y se alegre; y queesto se lequedede su trabajolos díasde su vidaqueDioslediódebajodel sol.","Por tanto alabéyo la alegría; quenotiene el hombrebiendebajodel sol, sino quecomay beba, y se alegre; y queesto se lequedede su trabajolos díasde su vidaqueDioslediódebajodel sol."],[8,16,"Yo puesdí mi corazóná conocersabiduría, y á verla faenaquese hacesobrela tierra; (porque hayquien ni de nochenide díavesueñoen su ojos;)","Yo puesdí mi corazóná conocersabiduría, y á verla faenaquese hacesobrela tierra; (porque hayquien ni de nochenide díavesueñoen su ojos;)"],[8,17,"Y he vistotodaslas obrasde Dios, queel hombrenopuedealcanzar la obraquedebajodel solse hace; por mucho quetrabajeel hombrebuscándola, nola hallará: aunquedigael sabioquela sabe, nopor eso podráalcanzarla.","Y he vistotodaslas obrasde Dios, queel hombrenopuedealcanzar la obraquedebajodel solse hace; por mucho quetrabajeel hombrebuscándola, nola hallará: aunquedigael sabioquela sabe, nopor eso podráalcanzarla."],[9,1,"CIERTAMENTEdadohe mi corazóná todasestascosas, para declarar todoesto: quelos justosy los sabios, y sus obras, están en la manode Dios; y quenosabe el hombre ni el amorni el odiopor todolo quepasadelantede él.","CIERTAMENTEdadohe mi corazóná todasestascosas, para declarar todoesto: quelos justosy los sabios, y sus obras, están en la manode Dios; y quenosabe el hombre ni el amorni el odiopor todolo quepasadelantede él."],[9,2,"Todoacontece de la mismamanera á todos: unmismosucesoocurre al justoy al impío; al buenoy al limpioy al no limpio; al que sacrifica, y al quenosacrifica: como el bueno, así el quepeca; el quejura, como el quetemeel juramento.","Todoacontece de la mismamanera á todos: unmismosucesoocurre al justoy al impío; al buenoy al limpioy al no limpio; al que sacrifica, y al quenosacrifica: como el bueno, así el quepeca; el quejura, como el quetemeel juramento."],[9,3,"Estemalhay entre todolo quese hacedebajodel sol, quetodostengan unmismo suceso, y tambiénqueel corazónde los hijosde los hombresesté llenode mal, y de enloquecimientoen su corazóndurante su vida: y después, álos muertos.","Estemalhay entre todolo quese hacedebajodel sol, quetodostengan unmismo suceso, y tambiénqueel corazónde los hijosde los hombresesté llenode mal, y de enloquecimientoen su corazóndurante su vida: y después, álos muertos."],[9,4,"Aun hayesperanzaparatodoaquél queestá entrelos vivos; porquemejores perrovivoqueleónmuerto.","Aun hayesperanzaparatodoaquél queestá entrelos vivos; porquemejores perrovivoqueleónmuerto."],[9,5,"Porquelos que vivensabenque han de morir: mas los muertosnadasaben, nitienen máspaga; porquesu memoriaes puesta en olvido.","Porquelos que vivensabenque han de morir: mas los muertosnadasaben, nitienen máspaga; porquesu memoriaes puesta en olvido."],[9,6,"Tambiénsuamor, y suodioysuenvidia, fenecióya: ni tiene yamásparte en el siglo, en todolo quese hacedebajodel sol.","Tambiénsuamor, y suodioysuenvidia, fenecióya: ni tiene yamásparte en el siglo, en todolo quese hacedebajodel sol."],[9,7,"Anda, y cometu pancon gozo, y bebetu vinocon alegrecorazón: porquetus obrasyason agradablesá Dios.","Anda, y cometu pancon gozo, y bebetu vinocon alegrecorazón: porquetus obrasyason agradablesá Dios."],[9,8,"En todotiemposeanblancostus vestidos, y nuncafalteungüentosobretu cabeza.","En todotiemposeanblancostus vestidos, y nuncafalteungüentosobretu cabeza."],[9,9,"Gozade la vidaconla mujerqueamas, todoslos díasde la vidade tuvanidad, quete son dadosdebajodel sol, todoslos díasde tuvanidad; porqueestaes tuparte en la vida, y en tutrabajoconquete afanasdebajodel sol.","Gozade la vidaconla mujerqueamas, todoslos díasde la vidade tuvanidad, quete son dadosdebajodel sol, todoslos díasde tuvanidad; porqueestaes tuparte en la vida, y en tutrabajoconquete afanasdebajodel sol."],[9,10,"Todolo quete viniereá la manopara hacer, hazlosegún tusfuerzas; porqueen el sepulcro, adondetú vas, nohay obra, ni industria, ni ciencia, ni sabiduría.","Todolo quete viniereá la manopara hacer, hazlosegún tusfuerzas; porqueen el sepulcro, adondetú vas, nohay obra, ni industria, ni ciencia, ni sabiduría."],[9,11,"Tornéme, y videbajodel sol, quenies de los ligerosla carrera, nila guerrade los fuertes, niaunde los sabiosel pan, nide los prudenteslas riquezas, nide los elocuentesel favor; sino quetiempoy ocasiónacontece á todos.","Tornéme, y videbajodel sol, quenies de los ligerosla carrera, nila guerrade los fuertes, niaunde los sabiosel pan, nide los prudenteslas riquezas, nide los elocuentesel favor; sino quetiempoy ocasiónacontece á todos."],[9,12,"Porqueel hombretampococonocesu tiempo: como los pecesque son presosen la malared, y como las avesque se prenden en lazo, así son enlazadoslos hijosde los hombresen el tiempomalo, cuando caede repentesobreellos.","Porqueel hombretampococonocesu tiempo: como los pecesque son presosen la malared, y como las avesque se prenden en lazo, así son enlazadoslos hijosde los hombresen el tiempomalo, cuando caede repentesobreellos."],[9,13,"Tambiénviestasabiduríadebajodel sol, la cual meparece grande:","Tambiénviestasabiduríadebajodel sol, la cual meparece grande:"],[9,14,"Una pequeñaciudad, y pocoshombresen ella; y vienecontraella un granrey, y cércala, y edifica contraella grandesbaluartes:","Una pequeñaciudad, y pocoshombresen ella; y vienecontraella un granrey, y cércala, y edifica contraella grandesbaluartes:"],[9,15,"Y hállase en ellaun hombrepobre, sabio, el cuallibrala ciudadcon susabiduría; y nadiese acordabade aquel pobrehombre.","Y hállase en ellaun hombrepobre, sabio, el cuallibrala ciudadcon susabiduría; y nadiese acordabade aquel pobrehombre."],[9,16,"Entonces dijeyo: Mejores la sabiduríaque la fortaleza; aunque la cienciadel pobresea menospreciada, y nosean escuchadassus palabras.","Entonces dijeyo: Mejores la sabiduríaque la fortaleza; aunque la cienciadel pobresea menospreciada, y nosean escuchadassus palabras."],[9,17,"Las palabrasdel sabiocon reposo sonoídas, más que el clamordel señorentre los necios.","Las palabrasdel sabiocon reposo sonoídas, más que el clamordel señorentre los necios."],[9,18,"Mejores la sabiduríaque las armasde guerra; mas unpecadordestruyemuchobien.","Mejores la sabiduríaque las armasde guerra; mas unpecadordestruyemuchobien."],[10,1,"LAS moscasmuertashacen hederydar mal olorel perfumedel perfumista: asíuna pequeñalocura, al estimadopor sabiduríay honra.","LAS moscasmuertashacen hederydar mal olorel perfumedel perfumista: asíuna pequeñalocura, al estimadopor sabiduríay honra."],[10,2,"El corazóndel sabioestá á su mano derecha; mas el corazóndel necioá su mano izquierda.","El corazóndel sabioestá á su mano derecha; mas el corazóndel necioá su mano izquierda."],[10,3,"Y aunmientras vael neciopor el camino, fáltalesu cordura, y diceá todos, quees necio.","Y aunmientras vael neciopor el camino, fáltalesu cordura, y diceá todos, quees necio."],[10,4,"Siel espíritudel príncipese exaltarecontrati, nodejestu lugar; porquela lenidad hará cesargrandesofensas.","Siel espíritudel príncipese exaltarecontrati, nodejestu lugar; porquela lenidad hará cesargrandesofensas."],[10,5,"Hayun malque debajodel solhe visto, á manera de erroremanadodel príncipe:","Hayun malque debajodel solhe visto, á manera de erroremanadodel príncipe:"],[10,6,"La necedadestá colocadaen grandesalturas, y los ricos están sentadosen lugar bajo.","La necedadestá colocadaen grandesalturas, y los ricos están sentadosen lugar bajo."],[10,7,"Visiervosen caballos, y príncipesque andabancomo siervossobrela tierra.","Visiervosen caballos, y príncipesque andabancomo siervossobrela tierra."],[10,8,"El que hiciere el hoyocaeráen él; y el que aportillareel vallado, morderálela serpiente.","El que hiciere el hoyocaeráen él; y el que aportillareel vallado, morderálela serpiente."],[10,9,"El que mudarelas piedras, trabajotendrá en ellas: el que cortarela leña, en ella peligrará.","El que mudarelas piedras, trabajotendrá en ellas: el que cortarela leña, en ella peligrará."],[10,10,"Sise embotareel hierro, y su filo nofuere amolado, hay que añadirentonces más fuerza: empero excede la bondad de la sabiduría.","Sise embotareel hierro, y su filo nofuere amolado, hay que añadirentonces más fuerza: empero excede la bondad de la sabiduría."],[10,11,"Muerdela serpientecuando no está encantada, y el lenguaraz no es mejor.","Muerdela serpientecuando no está encantada, y el lenguaraz no es mejor."],[10,12,"Las palabrasde la bocadel sabioson gracia; mas los labiosdel neciocausan su propia ruina.","Las palabrasde la bocadel sabioson gracia; mas los labiosdel neciocausan su propia ruina."],[10,13,"El principiode las palabrasde su bocaes necedad; y el finde su charlanocivodesvarío.","El principiode las palabrasde su bocaes necedad; y el finde su charlanocivodesvarío."],[10,14,"El neciomultiplicapalabras: nosabehombre loque ha de ser; ¿y quiénle hará saberloquedespuésde él será?","El neciomultiplicapalabras: nosabehombre loque ha de ser; ¿y quiénle hará saberloquedespuésde él será?"],[10,15,"El trabajode los necioslos fatiga; porquenosabenpor dónde irála ciudad.","El trabajode los necioslos fatiga; porquenosabenpor dónde irála ciudad."],[10,16,"¡Ayde ti, tierra, cuando tu reyes muchacho, y tus príncipescomen de mañana!","¡Ayde ti, tierra, cuando tu reyes muchacho, y tus príncipescomen de mañana!"],[10,17,"¡Bienaventurada, tú, tierra, cuando tu reyes hijode nobles, y tus príncipescomená su hora, por refección, y nopor el beber!","¡Bienaventurada, tú, tierra, cuando tu reyes hijode nobles, y tus príncipescomená su hora, por refección, y nopor el beber!"],[10,18,"Por la perezase caela techumbre, y por flojedad de manosse lluevela casa.","Por la perezase caela techumbre, y por flojedad de manosse lluevela casa."],[10,19,"Por el placerse haceel convite, y el vinoalegralos vivos: y el dineroresponde á todo.","Por el placerse haceel convite, y el vinoalegralos vivos: y el dineroresponde á todo."],[10,20,"Niaunen tu pensamientodigas maldel rey, nien los secretosde tu cámaradigas maldel rico; porquelas avesdel cielollevaránla voz, y las que tienenalasharán saberla palabra.","Niaunen tu pensamientodigas maldel rey, nien los secretosde tu cámaradigas maldel rico; porquelas avesdel cielollevaránla voz, y las que tienenalasharán saberla palabra."],[11,1,"ECHAtu pansobrelas aguas; que después de muchosdíaslo hallarás.","ECHAtu pansobrelas aguas; que después de muchosdíaslo hallarás."],[11,2,"Reparteá siete, y auná ocho: porquenosabesel malquevendrásobrela tierra.","Reparteá siete, y auná ocho: porquenosabesel malquevendrásobrela tierra."],[11,3,"Silas nubesfueren llenasde agua, sobrela tierrala derramarán: y siel árbolcayereal mediodía, ó al norte, al lugarque el árbolcayere, allíquedará.","Silas nubesfueren llenasde agua, sobrela tierrala derramarán: y siel árbolcayereal mediodía, ó al norte, al lugarque el árbolcayere, allíquedará."],[11,4,"El que al vientomira, nosembrará; y el que miraá las nubes, nosegará.","El que al vientomira, nosembrará; y el que miraá las nubes, nosegará."],[11,5,"Como tú nosabescuáles el caminodel viento, ó cómo se críanlos huesosen el vientrede la mujer preñada, asíignorasla obrade Dios, el cualhacetodaslas cosas.","Como tú nosabescuáles el caminodel viento, ó cómo se críanlos huesosen el vientrede la mujer preñada, asíignorasla obrade Dios, el cualhacetodaslas cosas."],[11,6,"Por la mañanasiembratu simiente, y á la tardenodejes reposartu mano: porquetú nosabescuál es lo mejor, si estoólo otro, ó siambas á doscosas son buenas.","Por la mañanasiembratu simiente, y á la tardenodejes reposartu mano: porquetú nosabescuál es lo mejor, si estoólo otro, ó siambas á doscosas son buenas."],[11,7,"Suaveciertamente es la luz, y agradableá los ojosverel sol:","Suaveciertamente es la luz, y agradableá los ojosverel sol:"],[11,8,"Mas si el hombrevivieremuchosaños, y en todosellos hubiere gozadoalegría; si después trajere á la memorialos díasde las tinieblas, queseránmuchos, todolo quelehabrá pasado, dirá haber sidovanidad.","Mas si el hombrevivieremuchosaños, y en todosellos hubiere gozadoalegría; si después trajere á la memorialos díasde las tinieblas, queseránmuchos, todolo quelehabrá pasado, dirá haber sidovanidad."],[11,9,"Alégrate, mancebo, en tu mocedad, y tome placertu corazónen los díasde tu juventud; y andaen los caminosde tu corazón, y en la vistade tus ojos: mas sabe, quesobretodasestascosas te traeráDiosá juicio.","Alégrate, mancebo, en tu mocedad, y tome placertu corazónen los díasde tu juventud; y andaen los caminosde tu corazón, y en la vistade tus ojos: mas sabe, quesobretodasestascosas te traeráDiosá juicio."],[11,10,"Quitapues el enojode tu corazón, y apartael malde tu carne: porquela mocedady la juventudson vanidad.","Quitapues el enojode tu corazón, y apartael malde tu carne: porquela mocedady la juventudson vanidad."],[12,1,"Y ACUÉRDATEde tu Criadoren los díasde tu juventud, antesquevenganlos malosdías, y lleguenlos años, de los cualesdigas, Notengo en ellos contentamiento;","Y ACUÉRDATEde tu Criadoren los díasde tu juventud, antesquevenganlos malosdías, y lleguenlos años, de los cualesdigas, Notengo en ellos contentamiento;"],[12,2,"Antesquese oscurezcael sol, y la luz, y la lunay las estrellas, y las nubesse tornen trasla lluvia:","Antesquese oscurezcael sol, y la luz, y la lunay las estrellas, y las nubesse tornen trasla lluvia:"],[12,3,"Cuandotemblaránlos guardasde la casa, y se encorvaránlos hombresfuertes, y cesaránlas muelas, porquehan disminuído, y se oscureceránlos que miranpor las ventanas;","Cuandotemblaránlos guardasde la casa, y se encorvaránlos hombresfuertes, y cesaránlas muelas, porquehan disminuído, y se oscureceránlos que miranpor las ventanas;"],[12,4,"Y las puertasde afuerase cerrarán, por la bajeza de la vozde la muela; y levantaráseá la vozdel ave, y todaslas hijasde canciónserán humilladas;","Y las puertasde afuerase cerrarán, por la bajeza de la vozde la muela; y levantaráseá la vozdel ave, y todaslas hijasde canciónserán humilladas;"],[12,5,"Cuandotambiéntemeránde lo alto, y los tropezonesen el camino; y floreceráel almendro, y se agravarála langosta, y perderáseel apetito: porqueel hombrevaála casade su siglo, y los endechadoresandarán en derredorpor la plaza:","Cuandotambiéntemeránde lo alto, y los tropezonesen el camino; y floreceráel almendro, y se agravarála langosta, y perderáseel apetito: porqueel hombrevaála casade su siglo, y los endechadoresandarán en derredorpor la plaza:"],[12,6,"Antesquela cadenade platase quiebre, y se rompael cuenco de oro, y el cántarose quiebrejunto ála fuente, y la ruedasea rotasobreel pozo;","Antesquela cadenade platase quiebre, y se rompael cuenco de oro, y el cántarose quiebrejunto ála fuente, y la ruedasea rotasobreel pozo;"],[12,7,"Y el polvose torneála tierra, como era, y el espírituse vuelvaáDiosquelo dió.","Y el polvose torneála tierra, como era, y el espírituse vuelvaáDiosquelo dió."],[12,8,"Vanidadde vanidades, dijoel Predicador, todovanidad.","Vanidadde vanidades, dijoel Predicador, todovanidad."],[12,9,"Y cuanto mássabiofuéel Predicador, tanto másenseñósabiduríaal pueblo; é hizo escuchar, é hizo escudriñar, y compusomuchosproverbios.","Y cuanto mássabiofuéel Predicador, tanto másenseñósabiduríaal pueblo; é hizo escuchar, é hizo escudriñar, y compusomuchosproverbios."],[12,10,"Procuróel Predicadorhallar palabrasagradables, y escriturarecta, palabrasde verdad.","Procuróel Predicadorhallar palabrasagradables, y escriturarecta, palabrasde verdad."],[12,11,"Las palabrasde los sabiosson como aguijones; y como clavoshincados, lasde los maestrosde las congregaciones, dadaspor unPastor.","Las palabrasde los sabiosson como aguijones; y como clavoshincados, lasde los maestrosde las congregaciones, dadaspor unPastor."],[12,12,"Ahora, hijomío, á másde esto, séavisado. Nohay finde hacermuchoslibros; y el muchoestudioaflicción es de la carne.","Ahora, hijomío, á másde esto, séavisado. Nohay finde hacermuchoslibros; y el muchoestudioaflicción es de la carne."],[12,13,"El finde todoel discursooídoes este: Temeá Dios, y guardasus mandamientos; porqueestoes el tododel hombre.","El finde todoel discursooídoes este: Temeá Dios, y guardasus mandamientos; porqueestoes el tododel hombre."],[12,14,"PorqueDiostraerátodaobraá juicio, el cual se harásobre todacosa oculta, buenaó mala.","PorqueDiostraerátodaobraá juicio, el cual se harásobre todacosa oculta, buenaó mala."]],"rus-synodal":[[1,1,"Слова Екклесиаста, сына Давидова, царя в Иерусалиме.","Slova Ekklesiasta, syna Davidova, carâ v Ierusalime."],[1,2,"Суета сует, сказал Екклесиаст, суета сует, – все суета!","Sueta suet, skazal Ekklesiast, sueta suet, – vse sueta!"],[1,3,"Что пользы человеку от всех трудов его, которыми трудится он под солнцем?","Čto polʹzy čeloveku ot vseh trudov ego, kotorymi truditsâ on pod solncem?"],[1,4,"Род проходит, и род приходит, а земля пребывает вовеки.","Rod prohodit, i rod prihodit, a zemlâ prebyvaet voveki."],[1,5,"Восходит солнце, и заходит солнце, и спешит к месту своему, где оно восходит.","Voshodit solnce, i zahodit solnce, i spešit k mestu svoemu, gde ono voshodit."],[1,6,"Идет ветер к югу, и переходит к северу, кружится, кружится на ходу своем, и возвращается ветер на круги свои.","Idet veter k ûgu, i perehodit k severu, kružitsâ, kružitsâ na hodu svoem, i vozvraŝaetsâ veter na krugi svoi."],[1,7,"Все реки текут в море, но море не переполняется: к тому месту, откуда реки текут, они возвращаются, чтобы опять течь.","Vse reki tekut v more, no more ne perepolnâetsâ: k tomu mestu, otkuda reki tekut, oni vozvraŝaûtsâ, čtoby opâtʹ tečʹ."],[1,8,"Все вещи – в труде: не может человек пересказать всего; не насытится око зрением, не наполнится ухо слушанием.","Vse veŝi – v trude: ne možet čelovek pereskazatʹ vsego; ne nasytitsâ oko zreniem, ne napolnitsâ uho slušaniem."],[1,9,"Что было, то и будет; и что делалось, то и будет делаться, и нет ничего нового под солнцем.","Čto bylo, to i budet; i čto delalosʹ, to i budet delatʹsâ, i net ničego novogo pod solncem."],[1,10,"Бывает нечто, о чем говорят: «смотри, вот, это новое»; но это было уже в веках, бывших прежде нас.","Byvaet nečto, o čem govorât: «smotri, vot, éto novoe»; no éto bylo uže v vekah, byvših prežde nas."],[1,11,"Нет памяти о прежнем; да и о том, что будет, не останется памяти у тех, которые будут после.","Net pamâti o prežnem; da i o tom, čto budet, ne ostanetsâ pamâti u teh, kotorye budut posle."],[1,12,"Я, Екклесиаст, был царем над Израилем в Иерусалиме;","Â, Ekklesiast, byl carem nad Izrailem v Ierusalime;"],[1,13,"и предал я сердце мое тому, чтобы исследовать и испытать мудростью все, что делается под небом: это тяжелое занятие дал Бог сынам человеческим, чтобы они упражнялись в нем.","i predal â serdce moe tomu, čtoby issledovatʹ i ispytatʹ mudrostʹû vse, čto delaetsâ pod nebom: éto tâželoe zanâtie dal Bog synam čelovečeskim, čtoby oni upražnâlisʹ v nem."],[1,14,"Видел я все дела, какие делаются под солнцем, и вот, все – суета и томление духа!","Videl â vse dela, kakie delaûtsâ pod solncem, i vot, vse – sueta i tomlenie duha!"],[1,15,"Кривое не может сделаться прямым, и чего нет, того нельзя считать.","Krivoe ne možet sdelatʹsâ prâmym, i čego net, togo nelʹzâ sčitatʹ."],[1,16,"Говорил я с сердцем моим так: вот, я возвеличился и приобрел мудрости больше всех, которые были прежде меня над Иерусалимом, и сердце мое видело много мудрости и знания.","Govoril â s serdcem moim tak: vot, â vozveličilsâ i priobrel mudrosti bolʹše vseh, kotorye byli prežde menâ nad Ierusalimom, i serdce moe videlo mnogo mudrosti i znaniâ."],[1,17,"И предал я сердце мое тому, чтобы познать мудрость и познать безумие и глупость: узнал, что и это – томление духа;","I predal â serdce moe tomu, čtoby poznatʹ mudrostʹ i poznatʹ bezumie i glupostʹ: uznal, čto i éto – tomlenie duha;"],[1,18,"потому что во многой мудрости много печали; и кто умножает познания, умножает скорбь.","potomu čto vo mnogoj mudrosti mnogo pečali; i kto umnožaet poznaniâ, umnožaet skorbʹ."],[2,1,"Сказал я в сердце моем: «дай, испытаю я тебя весельем, и насладись добром»; но и это – суета!","Skazal â v serdce moem: «daj, ispytaû â tebâ veselʹem, i nasladisʹ dobrom»; no i éto – sueta!"],[2,2,"О смехе сказал я: «глупость!», а о веселье: «что оно делает?»","O smehe skazal â: «glupostʹ!», a o veselʹe: «čto ono delaet?»"],[2,3,"Вздумал я в сердце моем услаждать вином тело мое и, между тем, как сердце мое руководилось мудростью, придержаться и глупости, доколе не увижу, что хорошо для сынов человеческих, что должны были бы они делать под небом в немногие дни жизни своей.","Vzdumal â v serdce moem uslaždatʹ vinom telo moe i, meždu tem, kak serdce moe rukovodilosʹ mudrostʹû, prideržatʹsâ i gluposti, dokole ne uvižu, čto horošo dlâ synov čelovečeskih, čto dolžny byli by oni delatʹ pod nebom v nemnogie dni žizni svoej."],[2,4,"Я предпринял большие дела: построил себе домы, посадил себе виноградники,","Â predprinâl bolʹšie dela: postroil sebe domy, posadil sebe vinogradniki,"],[2,5,"устроил себе сады и рощи и насадил в них всякие плодовитые дерева;","ustroil sebe sady i roŝi i nasadil v nih vsâkie plodovitye dereva;"],[2,6,"сделал себе водоемы для орошения из них рощей, произращающих деревья;","sdelal sebe vodoemy dlâ orošeniâ iz nih roŝej, proizraŝaûŝih derevʹâ;"],[2,7,"приобрел себе слуг и служанок, и домочадцы были у меня; также крупного и мелкого скота было у меня больше, нежели у всех, бывших прежде меня в Иерусалиме;","priobrel sebe slug i služanok, i domočadcy byli u menâ; takže krupnogo i melkogo skota bylo u menâ bolʹše, neželi u vseh, byvših prežde menâ v Ierusalime;"],[2,8,"собрал себе серебра и золота и драгоценностей от царей и областей; завел у себя певцов и певиц и услаждения сынов человеческих – разные музыкальные орудия.","sobral sebe serebra i zolota i dragocennostej ot carej i oblastej; zavel u sebâ pevcov i pevic i uslaždeniâ synov čelovečeskih – raznye muzykalʹnye orudiâ."],[2,9,"И сделался я великим и богатым больше всех, бывших прежде меня в Иерусалиме; и мудрость моя пребыла со мною.","I sdelalsâ â velikim i bogatym bolʹše vseh, byvših prežde menâ v Ierusalime; i mudrostʹ moâ prebyla so mnoû."],[2,10,"Чего бы глаза мои ни пожелали, я не отказывал им, не возбранял сердцу моему никакого веселья, потому что сердце мое радовалось во всех трудах моих, и это было моею долею от всех трудов моих.","Čego by glaza moi ni poželali, â ne otkazyval im, ne vozbranâl serdcu moemu nikakogo veselʹâ, potomu čto serdce moe radovalosʹ vo vseh trudah moih, i éto bylo moeû doleû ot vseh trudov moih."],[2,11,"И оглянулся я на все дела мои, которые сделали руки мои, и на труд, которым трудился я, делая их: и вот, все – суета и томление духа, и нет от них пользы под солнцем!","I oglânulsâ â na vse dela moi, kotorye sdelali ruki moi, i na trud, kotorym trudilsâ â, delaâ ih: i vot, vse – sueta i tomlenie duha, i net ot nih polʹzy pod solncem!"],[2,12,"И обратился я, чтобы взглянуть на мудрость и безумие и глупость: ибо что может сделать человек после царя сверх того, что уже сделано?","I obratilsâ â, čtoby vzglânutʹ na mudrostʹ i bezumie i glupostʹ: ibo čto možet sdelatʹ čelovek posle carâ sverh togo, čto uže sdelano?"],[2,13,"И увидел я, что преимущество мудрости перед глупостью такое же, как преимущество света перед тьмою:","I uvidel â, čto preimuŝestvo mudrosti pered glupostʹû takoe že, kak preimuŝestvo sveta pered tʹmoû:"],[2,14,"у мудрого глаза его – в голове его, а глупый ходит во тьме; но узнал я, что одна участь постигает их всех.","u mudrogo glaza ego – v golove ego, a glupyj hodit vo tʹme; no uznal â, čto odna učastʹ postigaet ih vseh."],[2,15,"И сказал я в сердце моем: «и меня постигнет та же участь, как и глупого: к чему же я сделался очень мудрым?» И сказал я в сердце моем, что и это – суета;","I skazal â v serdce moem: «i menâ postignet ta že učastʹ, kak i glupogo: k čemu že â sdelalsâ očenʹ mudrym?» I skazal â v serdce moem, čto i éto – sueta;"],[2,16,"потому что мудрого не будут помнить вечно, как и глупого; в грядущие дни все будет забыто, и увы! мудрый умирает наравне с глупым.","potomu čto mudrogo ne budut pomnitʹ večno, kak i glupogo; v grâduŝie dni vse budet zabyto, i uvy! mudryj umiraet naravne s glupym."],[2,17,"И возненавидел я жизнь, потому что противны стали мне дела, которые делаются под солнцем; ибо все – суета и томление духа!","I voznenavidel â žiznʹ, potomu čto protivny stali mne dela, kotorye delaûtsâ pod solncem; ibo vse – sueta i tomlenie duha!"],[2,18,"И возненавидел я весь труд мой, которым трудился под солнцем, потому что должен оставить его человеку, который будет после меня.","I voznenavidel â vesʹ trud moj, kotorym trudilsâ pod solncem, potomu čto dolžen ostavitʹ ego čeloveku, kotoryj budet posle menâ."],[2,19,"И кто знает: мудрый ли будет он, или глупый? А он будет распоряжаться всем трудом моим, которым я трудился и которым показал себя мудрым под солнцем. И это – суета!","I kto znaet: mudryj li budet on, ili glupyj? A on budet rasporâžatʹsâ vsem trudom moim, kotorym â trudilsâ i kotorym pokazal sebâ mudrym pod solncem. I éto – sueta!"],[2,20,"И обратился я, чтобы внушить сердцу моему отречься от всего труда, которым я трудился под солнцем,","I obratilsâ â, čtoby vnušitʹ serdcu moemu otrečʹsâ ot vsego truda, kotorym â trudilsâ pod solncem,"],[2,21,"потому что иной человек трудится мудро, с знанием и успехом, и должен отдать все человеку, не трудившемуся в том, как бы часть его. И это – суета и зло великое!","potomu čto inoj čelovek truditsâ mudro, s znaniem i uspehom, i dolžen otdatʹ vse čeloveku, ne trudivšemusâ v tom, kak by častʹ ego. I éto – sueta i zlo velikoe!"],[2,22,"Ибо что будет иметь человек от всего труда своего и заботы сердца своего, что трудится он под солнцем?","Ibo čto budet imetʹ čelovek ot vsego truda svoego i zaboty serdca svoego, čto truditsâ on pod solncem?"],[2,23,"Потому что все дни его – скорби, и его труды – беспокойство; даже и ночью сердце его не знает покоя. И это – суета!","Potomu čto vse dni ego – skorbi, i ego trudy – bespokojstvo; daže i nočʹû serdce ego ne znaet pokoâ. I éto – sueta!"],[2,24,"Не во власти человека и то благо, чтобы есть и пить и услаждать душу свою от труда своего. Я увидел, что и это – от руки Божией;","Ne vo vlasti čeloveka i to blago, čtoby estʹ i pitʹ i uslaždatʹ dušu svoû ot truda svoego. Â uvidel, čto i éto – ot ruki Božiej;"],[2,25,"потому что кто может есть и кто может наслаждаться без Него?","potomu čto kto možet estʹ i kto možet naslaždatʹsâ bez Nego?"],[2,26,"Ибо человеку, который добр пред лицом Его, Он дает мудрость и знание и радость; а грешнику дает заботу собирать и копить, чтобы после отдать доброму пред лицом Божиим. И это – суета и томление духа!","Ibo čeloveku, kotoryj dobr pred licom Ego, On daet mudrostʹ i znanie i radostʹ; a grešniku daet zabotu sobiratʹ i kopitʹ, čtoby posle otdatʹ dobromu pred licom Božiim. I éto – sueta i tomlenie duha!"],[3,1,"Всему свое время, и время всякой вещи под небом:","Vsemu svoe vremâ, i vremâ vsâkoj veŝi pod nebom:"],[3,2,"время рождаться, и время умирать; время насаждать, и время вырывать посаженное;","vremâ roždatʹsâ, i vremâ umiratʹ; vremâ nasaždatʹ, i vremâ vyryvatʹ posažennoe;"],[3,3,"время убивать, и время врачевать; время разрушать, и время строить;","vremâ ubivatʹ, i vremâ vračevatʹ; vremâ razrušatʹ, i vremâ stroitʹ;"],[3,4,"время плакать, и время смеяться; время сетовать, и время плясать;","vremâ plakatʹ, i vremâ smeâtʹsâ; vremâ setovatʹ, i vremâ plâsatʹ;"],[3,5,"время разбрасывать камни, и время собирать камни; время обнимать, и время уклоняться от объятий;","vremâ razbrasyvatʹ kamni, i vremâ sobiratʹ kamni; vremâ obnimatʹ, i vremâ uklonâtʹsâ ot obʺâtij;"],[3,6,"время искать, и время терять; время сберегать, и время бросать;","vremâ iskatʹ, i vremâ terâtʹ; vremâ sberegatʹ, i vremâ brosatʹ;"],[3,7,"время раздирать, и время сшивать; время молчать, и время говорить;","vremâ razdiratʹ, i vremâ sšivatʹ; vremâ molčatʹ, i vremâ govoritʹ;"],[3,8,"время любить, и время ненавидеть; время войне, и время миру.","vremâ lûbitʹ, i vremâ nenavidetʹ; vremâ vojne, i vremâ miru."],[3,9,"Что пользы работающему от того, над чем он трудится?","Čto polʹzy rabotaûŝemu ot togo, nad čem on truditsâ?"],[3,10,"Видел я эту заботу, которую дал Бог сынам человеческим, чтобы они упражнялись в том.","Videl â étu zabotu, kotoruû dal Bog synam čelovečeskim, čtoby oni upražnâlisʹ v tom."],[3,11,"Все соделал Он прекрасным в свое время, и вложил мир в сердце их, хотя человек не может постигнуть дел, которые Бог делает, от начала до конца.","Vse sodelal On prekrasnym v svoe vremâ, i vložil mir v serdce ih, hotâ čelovek ne možet postignutʹ del, kotorye Bog delaet, ot načala do konca."],[3,12,"Познал я, что нет для них ничего лучшего, как веселиться и делать доброе в жизни своей.","Poznal â, čto net dlâ nih ničego lučšego, kak veselitʹsâ i delatʹ dobroe v žizni svoej."],[3,13,"И если какой человек ест и пьет, и видит доброе во всяком труде своем, то это – дар Божий.","I esli kakoj čelovek est i pʹet, i vidit dobroe vo vsâkom trude svoem, to éto – dar Božij."],[3,14,"Познал я, что все, что делает Бог, пребывает вовек: к тому нечего прибавлять и от того нечего убавить, – и Бог делает так, чтобы благоговели пред лицом Его.","Poznal â, čto vse, čto delaet Bog, prebyvaet vovek: k tomu nečego pribavlâtʹ i ot togo nečego ubavitʹ, – i Bog delaet tak, čtoby blagogoveli pred licom Ego."],[3,15,"Что было, то и теперь есть, и что будет, то уже было, – и Бог воззовет прошедшее.","Čto bylo, to i teperʹ estʹ, i čto budet, to uže bylo, – i Bog vozzovet prošedšee."],[3,16,"Еще видел я под солнцем: место суда, а там беззаконие; место правды, а там неправда.","Eŝe videl â pod solncem: mesto suda, a tam bezzakonie; mesto pravdy, a tam nepravda."],[3,17,"И сказал я в сердце своем: «праведного и нечестивого будет судить Бог; потому что время для всякой вещи и суд над всяким делом там».","I skazal â v serdce svoem: «pravednogo i nečestivogo budet suditʹ Bog; potomu čto vremâ dlâ vsâkoj veŝi i sud nad vsâkim delom tam»."],[3,18,"Сказал я в сердце своем о сынах человеческих, чтобы испытал их Бог, и чтобы они видели, что они сами по себе животные;","Skazal â v serdce svoem o synah čelovečeskih, čtoby ispytal ih Bog, i čtoby oni videli, čto oni sami po sebe životnye;"],[3,19,"потому что участь сынов человеческих и участь животных – участь одна: как те умирают, так умирают и эти, и одно дыхание у всех, и нет у человека преимущества перед скотом, потому что все – суета!","potomu čto učastʹ synov čelovečeskih i učastʹ životnyh – učastʹ odna: kak te umiraût, tak umiraût i éti, i odno dyhanie u vseh, i net u čeloveka preimuŝestva pered skotom, potomu čto vse – sueta!"],[3,20,"Все идет в одно место: все произошло из праха и все возвратится в прах.","Vse idet v odno mesto: vse proizošlo iz praha i vse vozvratitsâ v prah."],[3,21,"Кто знает: дух сынов человеческих восходит ли вверх, и дух животных сходит ли вниз, в землю?","Kto znaet: duh synov čelovečeskih voshodit li vverh, i duh životnyh shodit li vniz, v zemlû?"],[3,22,"Итак, увидел я, что нет ничего лучше, как наслаждаться человеку делами своими: потому что это – доля его; ибо кто приведет его посмотреть на то, что будет после него?","Itak, uvidel â, čto net ničego lučše, kak naslaždatʹsâ čeloveku delami svoimi: potomu čto éto – dolâ ego; ibo kto privedet ego posmotretʹ na to, čto budet posle nego?"],[4,1,"И обратился я и увидел всякие угнетения, какие делаются под солнцем: и вот слезы угнетенных, а утешителя у них нет; и в руке угнетающих их – сила, а утешителя у них нет.","I obratilsâ â i uvidel vsâkie ugneteniâ, kakie delaûtsâ pod solncem: i vot slezy ugnetennyh, a utešitelâ u nih net; i v ruke ugnetaûŝih ih – sila, a utešitelâ u nih net."],[4,2,"И ублажил я мертвых, которые давно умерли, более живых, которые живут доселе;","I ublažil â mertvyh, kotorye davno umerli, bolee živyh, kotorye živut dosele;"],[4,3,"а блаженнее их обоих тот, кто еще не существовал, кто не видал злых дел, какие делаются под солнцем.","a blažennee ih oboih tot, kto eŝe ne suŝestvoval, kto ne vidal zlyh del, kakie delaûtsâ pod solncem."],[4,4,"Видел я также, что всякий труд и всякий успех в делах производят взаимную между людьми зависть. И это – суета и томление духа!","Videl â takže, čto vsâkij trud i vsâkij uspeh v delah proizvodât vzaimnuû meždu lûdʹmi zavistʹ. I éto – sueta i tomlenie duha!"],[4,5,"Глупый сидит, сложив свои руки, и съедает плоть свою.","Glupyj sidit, složiv svoi ruki, i sʺedaet plotʹ svoû."],[4,6,"Лучше горсть с покоем, нежели пригоршни с трудом и томлением духа.","Lučše gorstʹ s pokoem, neželi prigoršni s trudom i tomleniem duha."],[4,7,"И обратился я и увидел еще суету под солнцем;","I obratilsâ â i uvidel eŝe suetu pod solncem;"],[4,8,"человек одинокий, и другого нет; ни сына, ни брата нет у него; а всем трудам его нет конца, и глаз его не насыщается богатством. «Для кого же я тружусь и лишаю душу мою блага?» И это – суета и недоброе дело!","čelovek odinokij, i drugogo net; ni syna, ni brata net u nego; a vsem trudam ego net konca, i glaz ego ne nasyŝaetsâ bogatstvom. «Dlâ kogo že â tružusʹ i lišaû dušu moû blaga?» I éto – sueta i nedobroe delo!"],[4,9,"Двоим лучше, нежели одному; потому что у них есть доброе вознаграждение в труде их:","Dvoim lučše, neželi odnomu; potomu čto u nih estʹ dobroe voznagraždenie v trude ih:"],[4,10,"ибо если упадет один, то другой поднимет товарища своего. Но горе одному, когда упадет, а другого нет, который поднял бы его.","ibo esli upadet odin, to drugoj podnimet tovariŝa svoego. No gore odnomu, kogda upadet, a drugogo net, kotoryj podnâl by ego."],[4,11,"Также, если лежат двое, то тепло им; а одному как согреться?","Takže, esli ležat dvoe, to teplo im; a odnomu kak sogretʹsâ?"],[4,12,"И если станет преодолевать кто-либо одного, то двое устоят против него: и нитка, втрое скрученная, не скоро порвется.","I esli stanet preodolevatʹ kto-libo odnogo, to dvoe ustoât protiv nego: i nitka, vtroe skručennaâ, ne skoro porvetsâ."],[4,13,"Лучше бедный, но умный юноша, нежели старый, но неразумный царь, который не умеет принимать советы;","Lučše bednyj, no umnyj ûnoša, neželi staryj, no nerazumnyj carʹ, kotoryj ne umeet prinimatʹ sovety;"],[4,14,"ибо тот из темницы выйдет на царство, хотя родился в царстве своем бедным.","ibo tot iz temnicy vyjdet na carstvo, hotâ rodilsâ v carstve svoem bednym."],[4,15,"Видел я всех живущих, которые ходят под солнцем, с этим другим юношею, который займет место того.","Videl â vseh živuŝih, kotorye hodât pod solncem, s étim drugim ûnošeû, kotoryj zajmet mesto togo."],[4,16,"Не было числа всему народу, который был перед ним, хотя позднейшие не порадуются им. И это – суета и томление духа!","Ne bylo čisla vsemu narodu, kotoryj byl pered nim, hotâ pozdnejšie ne poraduûtsâ im. I éto – sueta i tomlenie duha!"],[4,17,"Наблюдай за ногою твоею, когда идешь в дом Божий, и будь готов более к слушанию, нежели к жертвоприношению; ибо они не думают, что худо делают.","Nablûdaj za nogoû tvoeû, kogda idešʹ v dom Božij, i budʹ gotov bolee k slušaniû, neželi k žertvoprinošeniû; ibo oni ne dumaût, čto hudo delaût."],[5,1,"Не торопись языком твоим, и сердце твое да не спешит произнести слово пред Богом; потому что Бог на небе, а ты на земле; поэтому слова твои да будут немноги.","Ne toropisʹ âzykom tvoim, i serdce tvoe da ne spešit proiznesti slovo pred Bogom; potomu čto Bog na nebe, a ty na zemle; poétomu slova tvoi da budut nemnogi."],[5,2,"Ибо, как сновидения бывают при множестве забот, так голос глупого познается при множестве слов.","Ibo, kak snovideniâ byvaût pri množestve zabot, tak golos glupogo poznaetsâ pri množestve slov."],[5,3,"Когда даешь обет Богу, то не медли исполнить его, потому что Он не благоволит к глупым: что обещал, исполни.","Kogda daešʹ obet Bogu, to ne medli ispolnitʹ ego, potomu čto On ne blagovolit k glupym: čto obeŝal, ispolni."],[5,4,"Лучше тебе не обещать, нежели обещать и не исполнить.","Lučše tebe ne obeŝatʹ, neželi obeŝatʹ i ne ispolnitʹ."],[5,5,"Не дозволяй устам твоим вводить в грех плоть твою, и не говори пред Ангелом [Божиим] «это – ошибка!» Для чего тебе делать, чтобы Бог прогневался на слово твое и разрушил дело рук твоих?","Ne dozvolâj ustam tvoim vvoditʹ v greh plotʹ tvoû, i ne govori pred Angelom [Božiim] «éto – ošibka!» Dlâ čego tebe delatʹ, čtoby Bog prognevalsâ na slovo tvoe i razrušil delo ruk tvoih?"],[5,6,"Ибо во множестве сновидений, как и во множестве слов, – много суеты; но ты бойся Бога.","Ibo vo množestve snovidenij, kak i vo množestve slov, – mnogo suety; no ty bojsâ Boga."],[5,7,"Если ты увидишь в какой области притеснение бедному и нарушение суда и правды, то не удивляйся этому: потому что над высоким наблюдает высший, а над ними еще высший;","Esli ty uvidišʹ v kakoj oblasti pritesnenie bednomu i narušenie suda i pravdy, to ne udivlâjsâ étomu: potomu čto nad vysokim nablûdaet vysšij, a nad nimi eŝe vysšij;"],[5,8,"превосходство же страны в целом есть царь, заботящийся о стране.","prevoshodstvo že strany v celom estʹ carʹ, zabotâŝijsâ o strane."],[5,9,"Кто любит серебро, тот не насытится серебром, и кто любит богатство, тому нет пользы от того. И это – суета!","Kto lûbit serebro, tot ne nasytitsâ serebrom, i kto lûbit bogatstvo, tomu net polʹzy ot togo. I éto – sueta!"],[5,10,"Умножается имущество, умножаются и потребляющие его; и какое благо для владеющего им: разве только смотреть своими глазами?","Umnožaetsâ imuŝestvo, umnožaûtsâ i potreblâûŝie ego; i kakoe blago dlâ vladeûŝego im: razve tolʹko smotretʹ svoimi glazami?"],[5,11,"Сладок сон трудящегося, мало ли, много ли он съест; но пресыщение богатого не дает ему уснуть.","Sladok son trudâŝegosâ, malo li, mnogo li on sʺest; no presyŝenie bogatogo ne daet emu usnutʹ."],[5,12,"Есть мучительный недуг, который видел я под солнцем: богатство, сберегаемое владетелем его во вред ему.","Estʹ mučitelʹnyj nedug, kotoryj videl â pod solncem: bogatstvo, sberegaemoe vladetelem ego vo vred emu."],[5,13,"И гибнет богатство это от несчастных случаев: родил он сына, и ничего нет в руках у него.","I gibnet bogatstvo éto ot nesčastnyh slučaev: rodil on syna, i ničego net v rukah u nego."],[5,14,"Как вышел он нагим из утробы матери своей, таким и отходит, каким пришел, и ничего не возьмет от труда своего, что мог бы он понести в руке своей.","Kak vyšel on nagim iz utroby materi svoej, takim i othodit, kakim prišel, i ničego ne vozʹmet ot truda svoego, čto mog by on ponesti v ruke svoej."],[5,15,"И это тяжкий недуг: каким пришел он, таким и отходит. Какая же польза ему, что он трудился на ветер?","I éto tâžkij nedug: kakim prišel on, takim i othodit. Kakaâ že polʹza emu, čto on trudilsâ na veter?"],[5,16,"А он во все дни свои ел впотьмах, в большом раздражении, в огорчении и досаде.","A on vo vse dni svoi el vpotʹmah, v bolʹšom razdraženii, v ogorčenii i dosade."],[5,17,"Вот еще, что я нашел доброго и приятного: есть и пить и наслаждаться добром во всех трудах своих, какими кто трудится под солнцем во все дни жизни своей, которые дал ему Бог; потому что это его доля.","Vot eŝe, čto â našel dobrogo i priâtnogo: estʹ i pitʹ i naslaždatʹsâ dobrom vo vseh trudah svoih, kakimi kto truditsâ pod solncem vo vse dni žizni svoej, kotorye dal emu Bog; potomu čto éto ego dolâ."],[5,18,"И если какому человеку Бог дал богатство и имущество, и дал ему власть пользоваться от них и брать свою долю и наслаждаться от трудов своих, то это – дар Божий.","I esli kakomu čeloveku Bog dal bogatstvo i imuŝestvo, i dal emu vlastʹ polʹzovatʹsâ ot nih i bratʹ svoû dolû i naslaždatʹsâ ot trudov svoih, to éto – dar Božij."],[5,19,"Недолго будут у него в памяти дни жизни его; поэтому Бог и вознаграждает его радостью сердца его.","Nedolgo budut u nego v pamâti dni žizni ego; poétomu Bog i voznagraždaet ego radostʹû serdca ego."],[6,1,"Есть зло, которое видел я под солнцем, и оно часто бывает между людьми:","Estʹ zlo, kotoroe videl â pod solncem, i ono často byvaet meždu lûdʹmi:"],[6,2,"Бог дает человеку богатство и имущество и славу, и нет для души его недостатка ни в чем, чего не пожелал бы он; но не дает ему Бог пользоваться этим, а пользуется тем чужой человек: это – суета и тяжкий недуг!","Bog daet čeloveku bogatstvo i imuŝestvo i slavu, i net dlâ duši ego nedostatka ni v čem, čego ne poželal by on; no ne daet emu Bog polʹzovatʹsâ étim, a polʹzuetsâ tem čužoj čelovek: éto – sueta i tâžkij nedug!"],[6,3,"Если бы какой человек родил сто детей, и прожил многие годы, и еще умножились дни жизни его, но душа его не наслаждалась бы добром и не было бы ему и погребения, то я сказал бы: выкидыш счастливее его,","Esli by kakoj čelovek rodil sto detej, i prožil mnogie gody, i eŝe umnožilisʹ dni žizni ego, no duša ego ne naslaždalasʹ by dobrom i ne bylo by emu i pogrebeniâ, to â skazal by: vykidyš sčastlivee ego,"],[6,4,"потому что он напрасно пришел и отошел во тьму, и его имя покрыто мраком.","potomu čto on naprasno prišel i otošel vo tʹmu, i ego imâ pokryto mrakom."],[6,5,"Он даже не видел и не знал солнца: ему покойнее, нежели тому.","On daže ne videl i ne znal solnca: emu pokojnee, neželi tomu."],[6,6,"А тот, хотя бы прожил две тысячи лет и не наслаждался добром, не все ли пойдет в одно место?","A tot, hotâ by prožil dve tysâči let i ne naslaždalsâ dobrom, ne vse li pojdet v odno mesto?"],[6,7,"Все труды человека – для рта его, а душа его не насыщается.","Vse trudy čeloveka – dlâ rta ego, a duša ego ne nasyŝaetsâ."],[6,8,"Какое же преимущество мудрого перед глупым, какое – бедняка, умеющего ходить перед живущими?","Kakoe že preimuŝestvo mudrogo pered glupym, kakoe – bednâka, umeûŝego hoditʹ pered živuŝimi?"],[6,9,"Лучше видеть глазами, нежели бродить душою. И это – также суета и томление духа!","Lučše videtʹ glazami, neželi broditʹ dušoû. I éto – takže sueta i tomlenie duha!"],[6,10,"Что существует, тому уже наречено имя, и известно, что это – человек, и что он не может препираться с тем, кто сильнее его.","Čto suŝestvuet, tomu uže narečeno imâ, i izvestno, čto éto – čelovek, i čto on ne možet prepiratʹsâ s tem, kto silʹnee ego."],[6,11,"Много таких вещей, которые умножают суету: что же для человека лучше?","Mnogo takih veŝej, kotorye umnožaût suetu: čto že dlâ čeloveka lučše?"],[6,12,"Ибо кто знает, что хорошо для человека в жизни, во все дни суетной жизни его, которые он проводит как тень? И кто скажет человеку, что будет после него под солнцем?","Ibo kto znaet, čto horošo dlâ čeloveka v žizni, vo vse dni suetnoj žizni ego, kotorye on provodit kak tenʹ? I kto skažet čeloveku, čto budet posle nego pod solncem?"],[7,1,"Доброе имя лучше дорогой масти, и день смерти – дня рождения.","Dobroe imâ lučše dorogoj masti, i denʹ smerti – dnâ roždeniâ."],[7,2,"Лучше ходить в дом плача об умершем, нежели ходить в дом пира; ибо таков конец всякого человека, и живой приложит это к своему сердцу.","Lučše hoditʹ v dom plača ob umeršem, neželi hoditʹ v dom pira; ibo takov konec vsâkogo čeloveka, i živoj priložit éto k svoemu serdcu."],[7,3,"Сетование лучше смеха; потому что при печали лица сердце делается лучше.","Setovanie lučše smeha; potomu čto pri pečali lica serdce delaetsâ lučše."],[7,4,"Сердце мудрых – в доме плача, а сердце глупых – в доме веселья.","Serdce mudryh – v dome plača, a serdce glupyh – v dome veselʹâ."],[7,5,"Лучше слушать обличения от мудрого, нежели слушать песни глупых;","Lučše slušatʹ obličeniâ ot mudrogo, neželi slušatʹ pesni glupyh;"],[7,6,"потому что смех глупых то же, что треск тернового хвороста под котлом. И это – суета!","potomu čto smeh glupyh to že, čto tresk ternovogo hvorosta pod kotlom. I éto – sueta!"],[7,7,"Притесняя других, мудрый делается глупым, и подарки портят сердце.","Pritesnââ drugih, mudryj delaetsâ glupym, i podarki portât serdce."],[7,8,"Конец дела лучше начала его; терпеливый лучше высокомерного.","Konec dela lučše načala ego; terpelivyj lučše vysokomernogo."],[7,9,"Не будь духом твоим поспешен на гнев, потому что гнев гнездится в сердце глупых.","Ne budʹ duhom tvoim pospešen na gnev, potomu čto gnev gnezditsâ v serdce glupyh."],[7,10,"Не говори: «отчего это прежние дни были лучше нынешних?», потому что не от мудрости ты спрашиваешь об этом.","Ne govori: «otčego éto prežnie dni byli lučše nynešnih?», potomu čto ne ot mudrosti ty sprašivaešʹ ob étom."],[7,11,"Хороша мудрость с наследством, и особенно для видящих солнце:","Horoša mudrostʹ s nasledstvom, i osobenno dlâ vidâŝih solnce:"],[7,12,"потому что под сенью ее то же, что под сенью серебра; но превосходство знания в том, что мудрость дает жизнь владеющему ею.","potomu čto pod senʹû ee to že, čto pod senʹû serebra; no prevoshodstvo znaniâ v tom, čto mudrostʹ daet žiznʹ vladeûŝemu eû."],[7,13,"Смотри на действование Божие: ибо кто может выпрямить то, что Он сделал кривым?","Smotri na dejstvovanie Božie: ibo kto možet vyprâmitʹ to, čto On sdelal krivym?"],[7,14,"Во дни благополучия пользуйся благом, а во дни несчастья размышляй: то и другое соделал Бог для того, чтобы человек ничего не мог сказать против Него.","Vo dni blagopolučiâ polʹzujsâ blagom, a vo dni nesčastʹâ razmyšlâj: to i drugoe sodelal Bog dlâ togo, čtoby čelovek ničego ne mog skazatʹ protiv Nego."],[7,15,"Всего насмотрелся я в суетные дни мои: праведник гибнет в праведности своей; нечестивый живет долго в нечестии своем.","Vsego nasmotrelsâ â v suetnye dni moi: pravednik gibnet v pravednosti svoej; nečestivyj živet dolgo v nečestii svoem."],[7,16,"Не будь слишком строг, и не выставляй себя слишком мудрым; зачем тебе губить себя?","Ne budʹ sliškom strog, i ne vystavlâj sebâ sliškom mudrym; začem tebe gubitʹ sebâ?"],[7,17,"Не предавайся греху, и не будь безумен: зачем тебе умирать не в свое время?","Ne predavajsâ grehu, i ne budʹ bezumen: začem tebe umiratʹ ne v svoe vremâ?"],[7,18,"Хорошо, если ты будешь держаться одного и не отнимать руки от другого; потому что кто боится Бога, тот избежит всего того.","Horošo, esli ty budešʹ deržatʹsâ odnogo i ne otnimatʹ ruki ot drugogo; potomu čto kto boitsâ Boga, tot izbežit vsego togo."],[7,19,"Мудрость делает мудрого сильнее десяти властителей, которые в городе.","Mudrostʹ delaet mudrogo silʹnee desâti vlastitelej, kotorye v gorode."],[7,20,"Нет человека праведного на земле, который делал бы добро и не грешил бы;","Net čeloveka pravednogo na zemle, kotoryj delal by dobro i ne grešil by;"],[7,21,"поэтому не на всякое слово, которое говорят, обращай внимание, чтобы не услышать тебе раба твоего, когда он злословит тебя;","poétomu ne na vsâkoe slovo, kotoroe govorât, obraŝaj vnimanie, čtoby ne uslyšatʹ tebe raba tvoego, kogda on zloslovit tebâ;"],[7,22,"ибо сердце твое знает много случаев, когда и сам ты злословил других.","ibo serdce tvoe znaet mnogo slučaev, kogda i sam ty zloslovil drugih."],[7,23,"Все это испытал я мудростью; я сказал: «буду я мудрым»; но мудрость далека от меня.","Vse éto ispytal â mudrostʹû; â skazal: «budu â mudrym»; no mudrostʹ daleka ot menâ."],[7,24,"Далеко то, что было, и глубоко-глубоко: кто постигнет его?","Daleko to, čto bylo, i gluboko-gluboko: kto postignet ego?"],[7,25,"Обратился я сердцем моим к тому, чтобы узнать, исследовать и изыскать мудрость и разум, и познать нечестие глупости, невежества и безумия, –","Obratilsâ â serdcem moim k tomu, čtoby uznatʹ, issledovatʹ i izyskatʹ mudrostʹ i razum, i poznatʹ nečestie gluposti, nevežestva i bezumiâ, –"],[7,26,"и нашел я, что горше смерти женщина, потому что она – сеть, и сердце ее – силки, руки ее – оковы; добрый пред Богом спасется от нее, а грешник уловлен будет ею.","i našel â, čto gorše smerti ženŝina, potomu čto ona – setʹ, i serdce ee – silki, ruki ee – okovy; dobryj pred Bogom spasetsâ ot nee, a grešnik ulovlen budet eû."],[7,27,"Вот это нашел я, сказал Екклесиаст, испытывая одно за другим.","Vot éto našel â, skazal Ekklesiast, ispytyvaâ odno za drugim."],[7,28,"Чего еще искала душа моя, и я не нашел? – Мужчину одного из тысячи я нашел, а женщину между всеми ими не нашел.","Čego eŝe iskala duša moâ, i â ne našel? – Mužčinu odnogo iz tysâči â našel, a ženŝinu meždu vsemi imi ne našel."],[7,29,"Только это я нашел, что Бог сотворил человека правым, а люди пустились во многие помыслы.","Tolʹko éto â našel, čto Bog sotvoril čeloveka pravym, a lûdi pustilisʹ vo mnogie pomysly."],[8,1,"Кто – как мудрый, и кто понимает значение вещей? Мудрость человека просветляет лицо его, и суровость лица его изменяется.","Kto – kak mudryj, i kto ponimaet značenie veŝej? Mudrostʹ čeloveka prosvetlâet lico ego, i surovostʹ lica ego izmenâetsâ."],[8,2,"Я говорю: слово царское храни, и это ради клятвы пред Богом.","Â govorû: slovo carskoe hrani, i éto radi klâtvy pred Bogom."],[8,3,"Не спеши уходить от лица его, и не упорствуй в худом деле; потому что он, что захочет, все может сделать.","Ne speši uhoditʹ ot lica ego, i ne uporstvuj v hudom dele; potomu čto on, čto zahočet, vse možet sdelatʹ."],[8,4,"Где слово царя, там власть; и кто скажет ему: «что ты делаешь?»","Gde slovo carâ, tam vlastʹ; i kto skažet emu: «čto ty delaešʹ?»"],[8,5,"Соблюдающий заповедь не испытает никакого зла: сердце мудрого знает и время и устав;","Soblûdaûŝij zapovedʹ ne ispytaet nikakogo zla: serdce mudrogo znaet i vremâ i ustav;"],[8,6,"потому что для всякой вещи есть свое время и устав; а человеку великое зло оттого,","potomu čto dlâ vsâkoj veŝi estʹ svoe vremâ i ustav; a čeloveku velikoe zlo ottogo,"],[8,7,"что он не знает, что будет; и как это будет – кто скажет ему?","čto on ne znaet, čto budet; i kak éto budet – kto skažet emu?"],[8,8,"Человек не властен над духом, чтобы удержать дух, и нет власти у него над днем смерти, и нет избавления в этой борьбе, и не спасет нечестие нечестивого.","Čelovek ne vlasten nad duhom, čtoby uderžatʹ duh, i net vlasti u nego nad dnem smerti, i net izbavleniâ v étoj borʹbe, i ne spaset nečestie nečestivogo."],[8,9,"Все это я видел, и обращал сердце мое на всякое дело, какое делается под солнцем. Бывает время, когда человек властвует над человеком во вред ему.","Vse éto â videl, i obraŝal serdce moe na vsâkoe delo, kakoe delaetsâ pod solncem. Byvaet vremâ, kogda čelovek vlastvuet nad čelovekom vo vred emu."],[8,10,"Видел я тогда, что хоронили нечестивых, и приходили и отходили от святого места, и они забываемы были в городе, где они так поступали. И это – суета!","Videl â togda, čto horonili nečestivyh, i prihodili i othodili ot svâtogo mesta, i oni zabyvaemy byli v gorode, gde oni tak postupali. I éto – sueta!"],[8,11,"Не скоро совершается суд над худыми делами; от этого и не страшится сердце сынов человеческих делать зло.","Ne skoro soveršaetsâ sud nad hudymi delami; ot étogo i ne strašitsâ serdce synov čelovečeskih delatʹ zlo."],[8,12,"Хотя грешник сто раз делает зло и коснеет в нем, но я знаю, что благо будет боящимся Бога, которые благоговеют пред лицом Его;","Hotâ grešnik sto raz delaet zlo i kosneet v nem, no â znaû, čto blago budet boâŝimsâ Boga, kotorye blagogoveût pred licom Ego;"],[8,13,"а нечестивому не будет добра, и, подобно тени, недолго продержится тот, кто не благоговеет пред Богом.","a nečestivomu ne budet dobra, i, podobno teni, nedolgo proderžitsâ tot, kto ne blagogoveet pred Bogom."],[8,14,"Есть и такая суета на земле: праведников постигает то, чего заслуживали бы дела нечестивых, а с нечестивыми бывает то, чего заслуживали бы дела праведников. И сказал я: и это – суета!","Estʹ i takaâ sueta na zemle: pravednikov postigaet to, čego zasluživali by dela nečestivyh, a s nečestivymi byvaet to, čego zasluživali by dela pravednikov. I skazal â: i éto – sueta!"],[8,15,"И похвалил я веселье; потому что нет лучшего для человека под солнцем, как есть, пить и веселиться: это сопровождает его в трудах во дни жизни его, которые дал ему Бог под солнцем.","I pohvalil â veselʹe; potomu čto net lučšego dlâ čeloveka pod solncem, kak estʹ, pitʹ i veselitʹsâ: éto soprovoždaet ego v trudah vo dni žizni ego, kotorye dal emu Bog pod solncem."],[8,16,"Когда я обратил сердце мое на то, чтобы постигнуть мудрость и обозреть дела, которые делаются на земле, и среди которых человек ни днем, ни ночью не знает сна, –","Kogda â obratil serdce moe na to, čtoby postignutʹ mudrostʹ i obozretʹ dela, kotorye delaûtsâ na zemle, i sredi kotoryh čelovek ni dnem, ni nočʹû ne znaet sna, –"],[8,17,"тогда я увидел все дела Божии и нашел, что человек не может постигнуть дел, которые делаются под солнцем. Сколько бы человек ни трудился в исследовании, он все-таки не постигнет этого; и если бы какой мудрец сказал, что он знает, он не может постигнуть этого.","togda â uvidel vse dela Božii i našel, čto čelovek ne možet postignutʹ del, kotorye delaûtsâ pod solncem. Skolʹko by čelovek ni trudilsâ v issledovanii, on vse-taki ne postignet étogo; i esli by kakoj mudrec skazal, čto on znaet, on ne možet postignutʹ étogo."],[9,1,"На все это я обратил сердце мое для исследования, что праведные и мудрые и деяния их – в руке Божией, и что человек ни любви, ни ненависти не знает во всем том, что перед ним.","Na vse éto â obratil serdce moe dlâ issledovaniâ, čto pravednye i mudrye i deâniâ ih – v ruke Božiej, i čto čelovek ni lûbvi, ni nenavisti ne znaet vo vsem tom, čto pered nim."],[9,2,"Всему и всем – одно: одна участь праведнику и нечестивому, доброму и [злому], чистому и нечистому, приносящему жертву и не приносящему жертвы; как добродетельному, так и грешнику; как клянущемуся, так и боящемуся клятвы.","Vsemu i vsem – odno: odna učastʹ pravedniku i nečestivomu, dobromu i [zlomu], čistomu i nečistomu, prinosâŝemu žertvu i ne prinosâŝemu žertvy; kak dobrodetelʹnomu, tak i grešniku; kak klânuŝemusâ, tak i boâŝemusâ klâtvy."],[9,3,"Это-то и худо во всем, что делается под солнцем, что одна участь всем, и сердце сынов человеческих исполнено зла, и безумие в сердце их, в жизни их; а после того они отходят к умершим.","Éto-to i hudo vo vsem, čto delaetsâ pod solncem, čto odna učastʹ vsem, i serdce synov čelovečeskih ispolneno zla, i bezumie v serdce ih, v žizni ih; a posle togo oni othodât k umeršim."],[9,4,"Кто находится между живыми, тому есть еще надежда, так как и псу живому лучше, нежели мертвому льву.","Kto nahoditsâ meždu živymi, tomu estʹ eŝe nadežda, tak kak i psu živomu lučše, neželi mertvomu lʹvu."],[9,5,"Живые знают, что умрут, а мертвые ничего не знают, и уже нет им воздаяния, потому что и память о них предана забвению,","Živye znaût, čto umrut, a mertvye ničego ne znaût, i uže net im vozdaâniâ, potomu čto i pamâtʹ o nih predana zabveniû,"],[9,6,"и любовь их и ненависть их и ревность их уже исчезли, и нет им более части вовеки ни в чем, что делается под солнцем.","i lûbovʹ ih i nenavistʹ ih i revnostʹ ih uže isčezli, i net im bolee časti voveki ni v čem, čto delaetsâ pod solncem."],[9,7,"Итак иди, ешь с весельем хлеб твой, и пей в радости сердца вино твое, когда Бог благоволит к делам твоим.","Itak idi, ešʹ s veselʹem hleb tvoj, i pej v radosti serdca vino tvoe, kogda Bog blagovolit k delam tvoim."],[9,8,"Да будут во всякое время одежды твои светлы, и да не оскудевает елей на голове твоей.","Da budut vo vsâkoe vremâ odeždy tvoi svetly, i da ne oskudevaet elej na golove tvoej."],[9,9,"Наслаждайся жизнью с женою, которую любишь, во все дни суетной жизни твоей, и которую дал тебе Бог под солнцем на все суетные дни твои; потому что это – доля твоя в жизни и в трудах твоих, какими ты трудишься под солнцем.","Naslaždajsâ žiznʹû s ženoû, kotoruû lûbišʹ, vo vse dni suetnoj žizni tvoej, i kotoruû dal tebe Bog pod solncem na vse suetnye dni tvoi; potomu čto éto – dolâ tvoâ v žizni i v trudah tvoih, kakimi ty trudišʹsâ pod solncem."],[9,10,"Все, что может рука твоя делать, по силам делай; потому что в могиле, куда ты пойдешь, нет ни работы, ни размышления, ни знания, ни мудрости.","Vse, čto možet ruka tvoâ delatʹ, po silam delaj; potomu čto v mogile, kuda ty pojdešʹ, net ni raboty, ni razmyšleniâ, ni znaniâ, ni mudrosti."],[9,11,"И обратился я, и видел под солнцем, что не проворным достается успешный бег, не храбрым – победа, не мудрым – хлеб, и не у разумных – богатство, и не искусным – благорасположение, но время и случай для всех их.","I obratilsâ â, i videl pod solncem, čto ne provornym dostaetsâ uspešnyj beg, ne hrabrym – pobeda, ne mudrym – hleb, i ne u razumnyh – bogatstvo, i ne iskusnym – blagoraspoloženie, no vremâ i slučaj dlâ vseh ih."],[9,12,"Ибо человек не знает своего времени. Как рыбы попадаются в пагубную сеть, и как птицы запутываются в силках, так сыны человеческие уловляются в бедственное время, когда оно неожиданно находит на них.","Ibo čelovek ne znaet svoego vremeni. Kak ryby popadaûtsâ v pagubnuû setʹ, i kak pticy zaputyvaûtsâ v silkah, tak syny čelovečeskie ulovlâûtsâ v bedstvennoe vremâ, kogda ono neožidanno nahodit na nih."],[9,13,"Вот еще какую мудрость видел я под солнцем, и она показалась мне важною:","Vot eŝe kakuû mudrostʹ videl â pod solncem, i ona pokazalasʹ mne važnoû:"],[9,14,"город небольшой, и людей в нем немного; к нему подступил великий царь и обложил его и произвел против него большие осадные работы;","gorod nebolʹšoj, i lûdej v nem nemnogo; k nemu podstupil velikij carʹ i obložil ego i proizvel protiv nego bolʹšie osadnye raboty;"],[9,15,"но в нем нашелся мудрый бедняк, и он спас своею мудростью этот город; и, однако же, никто не вспоминал об этом бедном человеке.","no v nem našelsâ mudryj bednâk, i on spas svoeû mudrostʹû étot gorod; i, odnako že, nikto ne vspominal ob étom bednom čeloveke."],[9,16,"И сказал я: мудрость лучше силы, и, однако же, мудрость бедняка пренебрегается, и слов его не слушают.","I skazal â: mudrostʹ lučše sily, i, odnako že, mudrostʹ bednâka prenebregaetsâ, i slov ego ne slušaût."],[9,17,"Слова мудрых, высказанные спокойно, выслушиваются лучше, нежели крик властелина между глупыми.","Slova mudryh, vyskazannye spokojno, vyslušivaûtsâ lučše, neželi krik vlastelina meždu glupymi."],[9,18,"Мудрость лучше воинских орудий; но один погрешивший погубит много доброго.","Mudrostʹ lučše voinskih orudij; no odin pogrešivšij pogubit mnogo dobrogo."],[10,1,"Мертвые мухи портят и делают зловонною благовонную масть мироварника: то же делает небольшая глупость уважаемого человека с его мудростью и честью.","Mertvye muhi portât i delaût zlovonnoû blagovonnuû mastʹ mirovarnika: to že delaet nebolʹšaâ glupostʹ uvažaemogo čeloveka s ego mudrostʹû i čestʹû."],[10,2,"Сердце мудрого – на правую сторону, а сердце глупого – на левую.","Serdce mudrogo – na pravuû storonu, a serdce glupogo – na levuû."],[10,3,"По какой бы дороге ни шел глупый, у него всегда недостает смысла, и всякому он выскажет, что он глуп.","Po kakoj by doroge ni šel glupyj, u nego vsegda nedostaet smysla, i vsâkomu on vyskažet, čto on glup."],[10,4,"Если гнев начальника вспыхнет на тебя, то не оставляй места твоего; потому что кротость покрывает и большие проступки.","Esli gnev načalʹnika vspyhnet na tebâ, to ne ostavlâj mesta tvoego; potomu čto krotostʹ pokryvaet i bolʹšie prostupki."],[10,5,"Есть зло, которое видел я под солнцем, это – как бы погрешность, происходящая от властелина;","Estʹ zlo, kotoroe videl â pod solncem, éto – kak by pogrešnostʹ, proishodâŝaâ ot vlastelina;"],[10,6,"невежество поставляется на большой высоте, а богатые сидят низко.","nevežestvo postavlâetsâ na bolʹšoj vysote, a bogatye sidât nizko."],[10,7,"Видел я рабов на конях, а князей, ходящих, подобно рабам, пешком.","Videl â rabov na konâh, a knâzej, hodâŝih, podobno rabam, peškom."],[10,8,"Кто копает яму, тот упадет в нее, и кто разрушает ограду, того ужалит змей.","Kto kopaet âmu, tot upadet v nee, i kto razrušaet ogradu, togo užalit zmej."],[10,9,"Кто передвигает камни, тот может надсадить себя, и кто колет дрова, тот может подвергнуться опасности от них.","Kto peredvigaet kamni, tot možet nadsaditʹ sebâ, i kto kolet drova, tot možet podvergnutʹsâ opasnosti ot nih."],[10,10,"Если притупится топор, и если лезвие его не будет отточено, то надобно будет напрягать силы; мудрость умеет это исправить.","Esli pritupitsâ topor, i esli lezvie ego ne budet ottočeno, to nadobno budet naprâgatʹ sily; mudrostʹ umeet éto ispravitʹ."],[10,11,"Если змей ужалит без заговаривания, то не лучше его и злоязычный.","Esli zmej užalit bez zagovarivaniâ, to ne lučše ego i zloâzyčnyj."],[10,12,"Слова из уст мудрого – благодать, а уста глупого губят его же:","Slova iz ust mudrogo – blagodatʹ, a usta glupogo gubât ego že:"],[10,13,"начало слов из уст его – глупость, а конец речи из уст его – безумие.","načalo slov iz ust ego – glupostʹ, a konec reči iz ust ego – bezumie."],[10,14,"Глупый наговорит много, хотя человек не знает, что будет, и кто скажет ему, что будет после него?","Glupyj nagovorit mnogo, hotâ čelovek ne znaet, čto budet, i kto skažet emu, čto budet posle nego?"],[10,15,"Труд глупого утомляет его, потому что не знает даже дороги в город.","Trud glupogo utomlâet ego, potomu čto ne znaet daže dorogi v gorod."],[10,16,"Горе тебе, земля, когда царь твой отрок, и когда князья твои едят рано!","Gore tebe, zemlâ, kogda carʹ tvoj otrok, i kogda knâzʹâ tvoi edât rano!"],[10,17,"Благо тебе, земля, когда царь у тебя из благородного рода, и князья твои едят вовремя, для подкрепления, а не для пресыщения!","Blago tebe, zemlâ, kogda carʹ u tebâ iz blagorodnogo roda, i knâzʹâ tvoi edât vovremâ, dlâ podkrepleniâ, a ne dlâ presyŝeniâ!"],[10,18,"От лености обвиснет потолок, и когда опустятся руки, то протечет дом.","Ot lenosti obvisnet potolok, i kogda opustâtsâ ruki, to protečet dom."],[10,19,"Пиры устраиваются для удовольствия, и вино веселит жизнь; а за все отвечает серебро.","Piry ustraivaûtsâ dlâ udovolʹstviâ, i vino veselit žiznʹ; a za vse otvečaet serebro."],[10,20,"Даже и в мыслях твоих не злословь царя, и в спальной комнате твоей не злословь богатого; потому что птица небесная может перенести слово твое, и крылатая – пересказать речь твою.","Daže i v myslâh tvoih ne zloslovʹ carâ, i v spalʹnoj komnate tvoej ne zloslovʹ bogatogo; potomu čto ptica nebesnaâ možet perenesti slovo tvoe, i krylataâ – pereskazatʹ rečʹ tvoû."],[11,1,"Отпускай хлеб твой по водам, потому что по прошествии многих дней опять найдешь его.","Otpuskaj hleb tvoj po vodam, potomu čto po prošestvii mnogih dnej opâtʹ najdešʹ ego."],[11,2,"Давай часть семи и даже восьми, потому что не знаешь, какая беда будет на земле.","Davaj častʹ semi i daže vosʹmi, potomu čto ne znaešʹ, kakaâ beda budet na zemle."],[11,3,"Когда облака будут полны, то они прольют на землю дождь; и если упадет дерево на юг или на север, то оно там и останется, куда упадет.","Kogda oblaka budut polny, to oni prolʹût na zemlû doždʹ; i esli upadet derevo na ûg ili na sever, to ono tam i ostanetsâ, kuda upadet."],[11,4,"Кто наблюдает ветер, тому не сеять; и кто смотрит на облака, тому не жать.","Kto nablûdaet veter, tomu ne seâtʹ; i kto smotrit na oblaka, tomu ne žatʹ."],[11,5,"Как ты не знаешь путей ветра и того, как образуются кости во чреве беременной, так не можешь знать дело Бога, Который делает все.","Kak ty ne znaešʹ putej vetra i togo, kak obrazuûtsâ kosti vo čreve beremennoj, tak ne možešʹ znatʹ delo Boga, Kotoryj delaet vse."],[11,6,"Утром сей семя твое, и вечером не давай отдыха руке твоей, потому что ты не знаешь, то или другое будет удачнее, или то и другое равно хорошо будет.","Utrom sej semâ tvoe, i večerom ne davaj otdyha ruke tvoej, potomu čto ty ne znaešʹ, to ili drugoe budet udačnee, ili to i drugoe ravno horošo budet."],[11,7,"Сладок свет, и приятно для глаз видеть солнце.","Sladok svet, i priâtno dlâ glaz videtʹ solnce."],[11,8,"Если человек проживет и много лет, то пусть веселится он в продолжение всех их, и пусть помнит о днях темных, которых будет много: все, что будет, – суета!","Esli čelovek proživet i mnogo let, to pustʹ veselitsâ on v prodolženie vseh ih, i pustʹ pomnit o dnâh temnyh, kotoryh budet mnogo: vse, čto budet, – sueta!"],[11,9,"Веселись, юноша, в юности твоей, и да вкушает сердце твое радости во дни юности твоей, и ходи по путям сердца твоего и по видению очей твоих; только знай, что за все это Бог приведет тебя на суд.","Veselisʹ, ûnoša, v ûnosti tvoej, i da vkušaet serdce tvoe radosti vo dni ûnosti tvoej, i hodi po putâm serdca tvoego i po videniû očej tvoih; tolʹko znaj, čto za vse éto Bog privedet tebâ na sud."],[11,10,"И удаляй печаль от сердца твоего, и уклоняй злое от тела твоего, потому что детство и юность – суета.","I udalâj pečalʹ ot serdca tvoego, i uklonâj zloe ot tela tvoego, potomu čto detstvo i ûnostʹ – sueta."],[12,1,"И помни Создателя твоего в дни юности твоей, доколе не пришли тяжелые дни и не наступили годы, о которых ты будешь говорить: «нет мне удовольствия в них!»","I pomni Sozdatelâ tvoego v dni ûnosti tvoej, dokole ne prišli tâželye dni i ne nastupili gody, o kotoryh ty budešʹ govoritʹ: «net mne udovolʹstviâ v nih!»"],[12,2,"Доколе не померкли солнце и свет и луна и звезды, и не нашли новые тучи вслед за дождем.","Dokole ne pomerkli solnce i svet i luna i zvezdy, i ne našli novye tuči vsled za doždem."],[12,3,"В тот день, когда задрожат стерегущие дом и согнутся мужи силы; и перестанут молоть мелющие, потому что их немного осталось; и помрачатся смотрящие в окно;","V tot denʹ, kogda zadrožat stereguŝie dom i sognutsâ muži sily; i perestanut molotʹ melûŝie, potomu čto ih nemnogo ostalosʹ; i pomračatsâ smotrâŝie v okno;"],[12,4,"и запираться будут двери на улицу; когда замолкнет звук жернова, и будет вставать человек по крику петуха и замолкнут дщери пения;","i zapiratʹsâ budut dveri na ulicu; kogda zamolknet zvuk žernova, i budet vstavatʹ čelovek po kriku petuha i zamolknut dŝeri peniâ;"],[12,5,"и высоты будут им страшны, и на дороге ужасы; и зацветет миндаль, и отяжелеет кузнечик, и рассыплется каперс. Ибо отходит человек в вечный дом свой, и готовы окружить его по улице плакальщицы; –","i vysoty budut im strašny, i na doroge užasy; i zacvetet mindalʹ, i otâželeet kuznečik, i rassypletsâ kapers. Ibo othodit čelovek v večnyj dom svoj, i gotovy okružitʹ ego po ulice plakalʹŝicy; –"],[12,6,"доколе не порвалась серебряная цепочка, и не разорвалась золотая повязка, и не разбился кувшин у источника, и не обрушилось колесо над колодезем.","dokole ne porvalasʹ serebrânaâ cepočka, i ne razorvalasʹ zolotaâ povâzka, i ne razbilsâ kuvšin u istočnika, i ne obrušilosʹ koleso nad kolodezem."],[12,7,"И возвратится прах в землю, чем он и был; а дух возвратится к Богу, Который дал его.","I vozvratitsâ prah v zemlû, čem on i byl; a duh vozvratitsâ k Bogu, Kotoryj dal ego."],[12,8,"Суета сует, сказал Екклесиаст, все – суета!","Sueta suet, skazal Ekklesiast, vse – sueta!"],[12,9,"Кроме того, что Екклесиаст был мудр, он учил еще народ знанию. Он все испытывал, исследовал, и составил много притчей.","Krome togo, čto Ekklesiast byl mudr, on učil eŝe narod znaniû. On vse ispytyval, issledoval, i sostavil mnogo pritčej."],[12,10,"Старался Екклесиаст приискивать изящные изречения, и слова истины написаны им верно.","Staralsâ Ekklesiast priiskivatʹ izâŝnye izrečeniâ, i slova istiny napisany im verno."],[12,11,"Слова мудрых – как иглы и как вбитые гвозди, и составители их – от Единого Пастыря.","Slova mudryh – kak igly i kak vbitye gvozdi, i sostaviteli ih – ot Edinogo Pastyrâ."],[12,12,"А что сверх всего этого, сын мой, того берегись: составлять много книг – конца не будет, и много читать – утомительно для тела.","A čto sverh vsego étogo, syn moj, togo beregisʹ: sostavlâtʹ mnogo knig – konca ne budet, i mnogo čitatʹ – utomitelʹno dlâ tela."],[12,13,"Выслушаем сущность всего: бойся Бога и заповеди Его соблюдай, потому что в этом все для человека;","Vyslušaem suŝnostʹ vsego: bojsâ Boga i zapovedi Ego soblûdaj, potomu čto v étom vse dlâ čeloveka;"],[12,14,"ибо всякое дело Бог приведет на суд, и все тайное, хорошо ли оно, или худо.","ibo vsâkoe delo Bog privedet na sud, i vse tajnoe, horošo li ono, ili hudo."]],"cmn-cuv-hant":[[1,1,"在 耶路撒冷作王、 大衛的兒子、傳道者的言語。","zài yé lù sā lěng zuò wáng, dà wèi de ér zǐ, chuán dào zhě de yán yǔ."],[1,2,"傳道者說：虛空的虛空， 虛空的虛空，凡事都是虛空。","chuán dào zhě shuō： xū kōng de xū kōng， xū kōng de xū kōng， fán shì dōu shì xū kōng."],[1,3,"人一切的勞碌， 就是他在日光之下的勞碌，有甚麼益處呢？","rén yī qiè de láo lù， jiù shì tā zài rì guāng zhī xià de láo lù， yǒu shèn me yì chù ne？"],[1,4,"一代過去，一代又來， 地卻永遠長存。","yī dài guò qù， yī dài yòu lái， de què yǒng yuǎn zhǎng cún."],[1,5,"日頭出來，日頭落下， 急歸所出之地。","rì tóu chū lái， rì tóu luò xià， jí guī suǒ chū zhī de."],[1,6,"風往南颳，又向北轉， 不住地旋轉，而且返回轉行原道。","fēng wǎng nán guā， yòu xiàng běi zhuǎn， bù zhù de xuán zhuǎn， ér qiě fǎn huí zhuǎn xíng yuán dào."],[1,7,"江河都往海裏流，海卻不滿； 江河從何處流，仍歸還何處。","jiāng hé dōu wǎng hǎi lǐ liú， hǎi què bù mǎn； jiāng hé cóng hé chù liú， réng guī hái hé chù."],[1,8,"萬事令人厭煩， 人不能說盡。 眼看，看不飽； 耳聽，聽不足。","wàn shì lìng rén yàn fán， rén bù néng shuō jǐn. yǎn kàn， kàn bù bǎo； ěr tīng， tīng bù zú."],[1,9,"已有的事後必再有； 已行的事後必再行。 日光之下並無新事。","yǐ yǒu de shì hòu bì zài yǒu； yǐ xíng de shì hòu bì zài xíng. rì guāng zhī xià bìng wú xīn shì."],[1,10,"豈有一件事人能指着說這是新的？ 哪知，在我們以前的世代早已有了。","qǐ yǒu yī jiàn shì rén néng zhǐ zhe shuō zhè shì xīn de？ nǎ zhī， zài wǒ men yǐ qián de shì dài zǎo yǐ yǒu le."],[1,11,"已過的 世代，無人記念； 將來的 世代，後來的人也不記念。","yǐ guò de shì dài， wú rén jì niàn； jiāng lái de shì dài， hòu lái de rén yě bù jì niàn."],[1,12,"我傳道者在 耶路撒冷作過 以色列的王。","wǒ chuán dào zhě zài yé lù sā lěng zuò guò yǐ sè liè de wáng."],[1,13,"我專心用智慧尋求、查究天下所做的一切事， 乃知神叫世人所經練的是極重的勞苦。","wǒ zhuān xīn yòng zhì huì xún qiú, chá jiū tiān xià suǒ zuò de yī qiè shì， nǎi zhī shén jiào shì rén suǒ jīng liàn de shì jí zhòng de láo kǔ."],[1,14,"我見日光之下所做的一切事，都是虛空，都是捕風。","wǒ jiàn rì guāng zhī xià suǒ zuò de yī qiè shì， dōu shì xū kōng， dōu shì bǔ fēng."],[1,15,"彎曲的，不能變直； 缺少的，不能足數。","wān qū de， bù néng biàn zhí； quē shǎo de， bù néng zú shù."],[1,16,"我心裏議論說：我得了大智慧，勝過我以前在 耶路撒冷的眾人，而且我心中多經歷智慧和知識的事。","wǒ xīn lǐ yì lùn shuō： wǒ dé le dà zhì huì， shèng guò wǒ yǐ qián zài yé lù sā lěng de zhòng rén， ér qiě wǒ xīn zhōng duō jīng lì zhì huì hé zhī shí de shì."],[1,17,"我又專心察明智慧、狂妄，和愚昧，乃知這也是捕風。","wǒ yòu zhuān xīn chá míng zhì huì, kuáng wàng， hé yú mèi， nǎi zhī zhè yě shì bǔ fēng."],[1,18,"因為多有智慧，就多有愁煩； 加增知識的，就加增憂傷。","yīn wèi duō yǒu zhì huì， jiù duō yǒu chóu fán； jiā zēng zhī shí de， jiù jiā zēng yōu shāng."],[2,1,"我心裏說：「來吧，我以喜樂試試你，你好享福！」誰知，這也是虛空。","wǒ xīn lǐ shuō：‘lái ba， wǒ yǐ xǐ lè shì shì nǐ， nǐ hǎo xiǎng fú！’ shuí zhī， zhè yě shì xū kōng."],[2,2,"我指嬉笑說：「這是狂妄。」論喜樂說：「有何功效呢？」","wǒ zhǐ xī xiào shuō：‘zhè shì kuáng wàng.’ lùn xǐ lè shuō：‘yǒu hé gōng xiào ne？’"],[2,3,"我心裏察究，如何用酒使我肉體舒暢，我心卻仍以智慧引導 我；又如何持住愚昧，等我看明世人，在天下一生當行何事為美。","wǒ xīn lǐ chá jiū， rú hé yòng jiǔ shǐ wǒ ròu tǐ shū chàng， wǒ xīn què réng yǐ zhì huì yǐn dǎo wǒ； yòu rú hé chí zhù yú mèi， děng wǒ kàn míng shì rén， zài tiān xià yī shēng dāng xíng hé shì wèi měi."],[2,4,"我為自己動大工程，建造房屋，栽種葡萄園，","wǒ wèi zì jǐ dòng dà gōng chéng， jiàn zào fáng wū， zāi zhǒng pú táo yuán，"],[2,5,"修造園囿，在其中栽種各樣果木樹；","xiū zào yuán yòu， zài qí zhōng zāi zhǒng gè yàng guǒ mù shù；"],[2,6,"挖造水池，用以澆灌嫩小的樹木。","wā zào shuǐ chí， yòng yǐ jiāo guàn nèn xiǎo de shù mù."],[2,7,"我買了僕婢，也有生在家中的僕婢；又有許多牛群羊群，勝過以前在 耶路撒冷眾人所有的。","wǒ mǎi le pú bì， yě yǒu shēng zài jiā zhōng de pú bì； yòu yǒu xǔ duō niú qún yáng qún， shèng guò yǐ qián zài yé lù sā lěng zhòng rén suǒ yǒu de."],[2,8,"我又為自己積蓄金銀和君王的財寶，並各省的財寶；又得唱歌的男女和世人所喜愛的物，並許多的妃嬪。","wǒ yòu wèi zì jǐ jī xù jīn yín hé jūn wáng de cái bǎo， bìng gè shěng de cái bǎo； yòu dé chàng gē de nán nǚ hé shì rén suǒ xǐ ài de wù， bìng xǔ duō de fēi pín."],[2,9,"這樣，我就日見昌盛，勝過以前在 耶路撒冷的眾人。我的智慧仍然存留。","zhè yàng， wǒ jiù rì jiàn chāng shèng， shèng guò yǐ qián zài yé lù sā lěng de zhòng rén. wǒ de zhì huì réng rán cún liú."],[2,10,"凡我眼所求的，我沒有留下不給它的；我心所樂的，我沒有禁止不享受的；因我的心為我一切所勞碌的快樂，這就是我從勞碌中所得的分。","fán wǒ yǎn suǒ qiú de， wǒ méi yǒu liú xià bù gěi tā de； wǒ xīn suǒ lè de， wǒ méi yǒu jìn zhǐ bù xiǎng shòu de； yīn wǒ de xīn wèi wǒ yī qiè suǒ láo lù de kuài lè， zhè jiù shì wǒ cóng láo lù zhōng suǒ dé de fēn."],[2,11,"後來，我察看我手所經營的一切事和我勞碌所成的功。誰知都是虛空，都是捕風；在日光之下毫無益處。","hòu lái， wǒ chá kàn wǒ shǒu suǒ jīng yíng de yī qiè shì hé wǒ láo lù suǒ chéng de gōng. shuí zhī dōu shì xū kōng， dōu shì bǔ fēng； zài rì guāng zhī xià háo wú yì chù."],[2,12,"我轉念觀看智慧、狂妄，和愚昧。在王以後而來的人還能做甚麼呢？也不過行早先所行的就是了。","wǒ zhuǎn niàn guān kàn zhì huì, kuáng wàng， hé yú mèi. zài wáng yǐ hòu ér lái de rén hái néng zuò shèn me ne？ yě bù guò xíng zǎo xiān suǒ xíng de jiù shì le."],[2,13,"我便看出智慧勝過愚昧，如同光明勝過黑暗。","wǒ biàn kàn chū zhì huì shèng guò yú mèi， rú tóng guāng míng shèng guò hēi àn."],[2,14,"智慧人的眼目光明，愚昧人在黑暗裏行。我卻看明有一件事，這兩等人都必遇見。","zhì huì rén de yǎn mù guāng míng， yú mèi rén zài hēi àn lǐ xíng. wǒ què kàn míng yǒu yī jiàn shì， zhè liǎng děng rén dōu bì yù jiàn."],[2,15,"我就心裏說：「愚昧人所遇見的，我也必遇見，我為何更有智慧呢？」我心裏說，這也是虛空。","wǒ jiù xīn lǐ shuō：‘yú mèi rén suǒ yù jiàn de， wǒ yě bì yù jiàn， wǒ wèi hé gèng yǒu zhì huì ne？’ wǒ xīn lǐ shuō， zhè yě shì xū kōng."],[2,16,"智慧人和愚昧人一樣，永遠無人記念，因為日後都被忘記；可歎智慧人死亡，與愚昧人無異。","zhì huì rén hé yú mèi rén yī yàng， yǒng yuǎn wú rén jì niàn， yīn wèi rì hòu dōu bèi wàng jì； kě tàn zhì huì rén sǐ wáng， yǔ yú mèi rén wú yì."],[2,17,"我所以恨惡生命；因為在日光之下所行的事我都以為煩惱，都是虛空，都是捕風。","wǒ suǒ yǐ hèn è shēng mìng； yīn wèi zài rì guāng zhī xià suǒ xíng de shì wǒ dōu yǐ wèi fán nǎo， dōu shì xū kōng， dōu shì bǔ fēng."],[2,18,"我恨惡一切的勞碌，就是我在日光之下的勞碌，因為我得來的必留給我以後的人。","wǒ hèn è yī qiè de láo lù， jiù shì wǒ zài rì guāng zhī xià de láo lù， yīn wèi wǒ dé lái de bì liú gěi wǒ yǐ hòu de rén."],[2,19,"那人是智慧是愚昧，誰能知道？他竟要管理我勞碌所得的，就是我在日光之下用智慧所得的。這也是虛空。","nà rén shì zhì huì shì yú mèi， shuí néng zhī dào？ tā jìng yào guǎn lǐ wǒ láo lù suǒ dé de， jiù shì wǒ zài rì guāng zhī xià yòng zhì huì suǒ dé de. zhè yě shì xū kōng."],[2,20,"故此，我轉想我在日光之下所勞碌的一切工作，心便絕望。","gù cǐ， wǒ zhuǎn xiǎng wǒ zài rì guāng zhī xià suǒ láo lù de yī qiè gōng zuò， xīn biàn jué wàng."],[2,21,"因為有人用智慧、知識、靈巧所勞碌得來的，卻要留給未曾勞碌的人為分。這也是虛空，也是大患。","yīn wèi yǒu rén yòng zhì huì, zhī shí, líng qiǎo suǒ láo lù dé lái de， què yào liú gěi wèi céng láo lù de rén wèi fēn. zhè yě shì xū kōng， yě shì dà huàn."],[2,22,"人在日光之下勞碌累心，在他一切的勞碌上得着甚麼呢？","rén zài rì guāng zhī xià láo lù lèi xīn， zài tā yī qiè de láo lù shàng dé zhe shèn me ne？"],[2,23,"因為他日日憂慮，他的勞苦成為愁煩，連夜間心也不安。這也是虛空。","yīn wèi tā rì rì yōu lǜ， tā de láo kǔ chéng wèi chóu fán， lián yè jiān xīn yě bù ān. zhè yě shì xū kōng."],[2,24,"人莫強如吃喝，且在勞碌中享福，我看這也是出於神的手。","rén mò qiáng rú chī hē， qiě zài láo lù zhōng xiǎng fú， wǒ kàn zhè yě shì chū yú shén de shǒu."],[2,25,"論到吃用、享福，誰能勝過我呢？","lùn dào chī yòng, xiǎng fú， shuí néng shèng guò wǒ ne？"],[2,26,"神喜悅誰，就給誰智慧、知識，和喜樂；惟有罪人，神使他勞苦，叫他將所收聚的、所堆積的歸給神所喜悅的人。這也是虛空，也是捕風。","shén xǐ yuè shuí， jiù gěi shuí zhì huì, zhī shí， hé xǐ lè； wéi yǒu zuì rén， shén shǐ tā láo kǔ， jiào tā jiāng suǒ shōu jù de, suǒ duī jī de guī gěi shén suǒ xǐ yuè de rén. zhè yě shì xū kōng， yě shì bǔ fēng."],[3,1,"凡事都有定期， 天下萬務都有定時。","fán shì dōu yǒu dìng qī， tiān xià wàn wù dōu yǒu dìng shí."],[3,2,"生有時，死有時； 栽種有時，拔出所栽種的也有時；","shēng yǒu shí， sǐ yǒu shí； zāi zhǒng yǒu shí， bá chū suǒ zāi zhǒng de yě yǒu shí；"],[3,3,"殺戮有時，醫治有時； 拆毀有時，建造有時；","shā lù yǒu shí， yī zhì yǒu shí； chāi huǐ yǒu shí， jiàn zào yǒu shí；"],[3,4,"哭有時，笑有時； 哀慟有時，跳舞有時；","kū yǒu shí， xiào yǒu shí； āi tòng yǒu shí， tiào wǔ yǒu shí；"],[3,5,"拋擲石頭有時，堆聚石頭有時； 懷抱有時，不懷抱有時；","pāo zhì shí tóu yǒu shí， duī jù shí tóu yǒu shí； huái bào yǒu shí， bù huái bào yǒu shí；"],[3,6,"尋找有時，失落有時； 保守有時，捨棄有時；","xún zhǎo yǒu shí， shī luò yǒu shí； bǎo shǒu yǒu shí， shě qì yǒu shí；"],[3,7,"撕裂有時，縫補有時； 靜默有時，言語有時；","sī liè yǒu shí， fèng bǔ yǒu shí； jìng mò yǒu shí， yán yǔ yǒu shí；"],[3,8,"喜愛有時，恨惡有時； 爭戰有時，和好有時。","xǐ ài yǒu shí， hèn è yǒu shí； zhēng zhàn yǒu shí， hé hǎo yǒu shí."],[3,9,"這樣看來，做事的人在他的勞碌上有甚麼益處呢？","zhè yàng kàn lái， zuò shì de rén zài tā de láo lù shàng yǒu shèn me yì chù ne？"],[3,10,"我見神叫世人勞苦，使他們在其中受經練。","wǒ jiàn shén jiào shì rén láo kǔ， shǐ tā men zài qí zhōng shòu jīng liàn."],[3,11,"神造萬物，各按其時成為美好，又將永生安置在世人心裏。然而神從始至終的作為，人不能參透。","shén zào wàn wù， gè àn qí shí chéng wèi měi hǎo， yòu jiāng yǒng shēng ān zhì zài shì rén xīn lǐ. rán ér shén cóng shǐ zhì zhōng de zuò wèi， rén bù néng cān tòu."],[3,12,"我知道世人，莫強如終身喜樂行善；","wǒ zhī dào shì rén， mò qiáng rú zhōng shēn xǐ lè xíng shàn；"],[3,13,"並且人人吃喝，在他一切勞碌中享福，這也是神的恩賜。","bìng qiě rén rén chī hē， zài tā yī qiè láo lù zhōng xiǎng fú， zhè yě shì shén de ēn cì."],[3,14,"我知道神一切所做的都必永存；無所增添，無所減少。神這樣行，是要人在他面前存敬畏的心。","wǒ zhī dào shén yī qiè suǒ zuò de dōu bì yǒng cún； wú suǒ zēng tiān， wú suǒ jiǎn shǎo. shén zhè yàng xíng， shì yào rén zài tā miàn qián cún jìng wèi de xīn."],[3,15,"現今的事早先就有了，將來的事早已也有了，並且神使已過的事重新再來。","xiàn jīn de shì zǎo xiān jiù yǒu le， jiāng lái de shì zǎo yǐ yě yǒu le， bìng qiě shén shǐ yǐ guò de shì zhòng xīn zài lái."],[3,16,"我又見日光之下，在審判之處有奸惡，在公義之處也有奸惡。","wǒ yòu jiàn rì guāng zhī xià， zài shěn pàn zhī chù yǒu jiān è， zài gōng yì zhī chù yě yǒu jiān è."],[3,17,"我心裏說，神必審判義人和惡人；因為在那裏，各樣事務，一切工作，都有定時。","wǒ xīn lǐ shuō， shén bì shěn pàn yì rén hé è rén； yīn wèi zài nà lǐ， gè yàng shì wù， yī qiè gōng zuò， dōu yǒu dìng shí."],[3,18,"我心裏說， 這乃為世人的緣故，是神要試驗他們，使他們覺得自己 不過像獸一樣。","wǒ xīn lǐ shuō， zhè nǎi wèi shì rén de yuán gù， shì shén yào shì yàn tā men， shǐ tā men jué dé zì jǐ bù guò xiàng shòu yī yàng."],[3,19,"因為世人遭遇的，獸也遭遇，所遭遇的都是一樣：這個怎樣死，那個也怎樣死，氣息都是一樣。人不能強於獸，都是虛空。","yīn wèi shì rén zāo yù de， shòu yě zāo yù， suǒ zāo yù de dōu shì yī yàng： zhè gè zěn yàng sǐ， nà gè yě zěn yàng sǐ， qì xī dōu shì yī yàng. rén bù néng qiáng yú shòu， dōu shì xū kōng."],[3,20,"都歸一處，都是出於塵土，也都歸於塵土。","dōu guī yī chù， dōu shì chū yú chén tǔ， yě dōu guī yú chén tǔ."],[3,21,"誰知道人的靈是往上升，獸的魂是下入地呢？","shuí zhī dào rén de líng shì wǎng shàng shēng， shòu de hún shì xià rù de ne？"],[3,22,"故此，我見人莫強如在他經營的事上喜樂，因為這是他的分。他身後的事誰能使他回來得見呢？","gù cǐ， wǒ jiàn rén mò qiáng rú zài tā jīng yíng de shì shàng xǐ lè， yīn wèi zhè shì tā de fēn. tā shēn hòu de shì shuí néng shǐ tā huí lái dé jiàn ne？"],[4,1,"我又轉念，見日光之下所行的一切欺壓。看哪，受欺壓的流淚，且無人安慰；欺壓他們的有勢力，也無人安慰他們。","wǒ yòu zhuǎn niàn， jiàn rì guāng zhī xià suǒ xíng de yī qiè qī yā. kàn nǎ， shòu qī yā de liú lèi， qiě wú rén ān wèi； qī yā tā men de yǒu shì lì， yě wú rén ān wèi tā men."],[4,2,"因此，我讚歎那早已死的死人，勝過那還活着的活人。","yīn cǐ， wǒ zàn tàn nà zǎo yǐ sǐ de sǐ rén， shèng guò nà hái huó zhe de huó rén."],[4,3,"並且我以為那未曾生的，就是未見過日光之下惡事的，比這兩等人更強。","bìng qiě wǒ yǐ wèi nà wèi céng shēng de， jiù shì wèi jiàn guò rì guāng zhī xià è shì de， bǐ zhè liǎng děng rén gèng qiáng."],[4,4,"我又見人為一切的勞碌和各樣靈巧的工作就被鄰舍嫉妒。這也是虛空，也是捕風。","wǒ yòu jiàn rén wèi yī qiè de láo lù hé gè yàng líng qiǎo de gōng zuò jiù bèi lín shě jí dù. zhè yě shì xū kōng， yě shì bǔ fēng."],[4,5,"愚昧人抱着手，吃自己的肉。","yú mèi rén bào zhe shǒu， chī zì jǐ de ròu."],[4,6,"滿了一把，得享安靜，強如滿了兩把，勞碌捕風。","mǎn le yī bǎ， dé xiǎng ān jìng， qiáng rú mǎn le liǎng bǎ， láo lù bǔ fēng."],[4,7,"我又轉念，見日光之下有一件虛空的事：","wǒ yòu zhuǎn niàn， jiàn rì guāng zhī xià yǒu yī jiàn xū kōng de shì："],[4,8,"有人孤單無二，無子無兄，竟勞碌不息，眼目也不以錢財為足。 他說：「我勞勞碌碌，刻苦自己，不享福樂，到底是為誰呢？」這也是虛空，是極重的勞苦。","yǒu rén gū dān wú èr， wú zǐ wú xiōng， jìng láo lù bù xī， yǎn mù yě bù yǐ qián cái wèi zú. tā shuō：‘wǒ láo láo lù lù， kè kǔ zì jǐ， bù xiǎng fú lè， dào dǐ shì wèi shuí ne？’ zhè yě shì xū kōng， shì jí zhòng de láo kǔ."],[4,9,"兩個人總比一個人好，因為二人勞碌同得美好的果效。","liǎng gè rén zǒng bǐ yī gè rén hǎo， yīn wèi èr rén láo lù tóng dé měi hǎo de guǒ xiào."],[4,10,"若是跌倒，這人可以扶起他的同伴；若是孤身跌倒，沒有別人扶起他來，這人就有禍了。","ruò shì diē dào， zhè rén kě yǐ fú qǐ tā de tóng bàn； ruò shì gū shēn diē dào， méi yǒu bié rén fú qǐ tā lái， zhè rén jiù yǒu huò le."],[4,11,"再者，二人同睡就都暖和，一人獨睡怎能暖和呢？","zài zhě， èr rén tóng shuì jiù dōu nuǎn hé， yī rén dú shuì zěn néng nuǎn hé ne？"],[4,12,"有人攻勝孤身一人，若有二人便能敵擋他；三股合成的繩子不容易折斷。","yǒu rén gōng shèng gū shēn yī rén， ruò yǒu èr rén biàn néng dí dǎng tā； sān gǔ hé chéng de shéng zǐ bù róng yì zhé duàn."],[4,13,"貧窮而有智慧的少年人勝過年老不肯納諫的愚昧王。","pín qióng ér yǒu zhì huì de shǎo nián rén shèng guò nián lǎo bù kěn nà jiàn de yú mèi wáng."],[4,14,"這人是從監牢中出來作王，在他國中，生來原是貧窮的。","zhè rén shì cóng jiān láo zhōng chū lái zuò wáng， zài tā guó zhōng， shēng lái yuán shì pín qióng de."],[4,15,"我見日光之下一切行動的活人都隨從那第二位，就是起來代替老王的少年人。","wǒ jiàn rì guāng zhī xià yī qiè xíng dòng de huó rén dōu suí cóng nà dì èr wèi， jiù shì qǐ lái dài tì lǎo wáng de shǎo nián rén."],[4,16,"他所治理的眾人就是他的百姓，多得無數；在他後來的人尚且不喜悅他。這真是虛空，也是捕風。","tā suǒ zhì lǐ de zhòng rén jiù shì tā de bǎi xìng， duō dé wú shù； zài tā hòu lái de rén shàng qiě bù xǐ yuè tā. zhè zhēn shì xū kōng， yě shì bǔ fēng."],[5,1,"你到神的殿要謹慎腳步；因為近前聽，勝過愚昧人獻祭，他們本不知道所做的是惡。","nǐ dào shén de diàn yào jǐn shèn jiǎo bù； yīn wèi jìn qián tīng， shèng guò yú mèi rén xiàn jì， tā men běn bù zhī dào suǒ zuò de shì è."],[5,2,"你在神面前不可冒失開口，也不可心急發言；因為神在天上，你在地下，所以你的言語要寡少。","nǐ zài shén miàn qián bù kě mào shī kāi kǒu， yě bù kě xīn jí fā yán； yīn wèi shén zài tiān shàng， nǐ zài de xià， suǒ yǐ nǐ de yán yǔ yào guǎ shǎo."],[5,3,"事務多，就令人做夢；言語多，就顯出愚昧。","shì wù duō， jiù lìng rén zuò mèng； yán yǔ duō， jiù xiǎn chū yú mèi."],[5,4,"你向神許願，償還不可遲延，因他不喜悅愚昧人，所以你許的願應當償還。","nǐ xiàng shén xǔ yuàn， cháng hái bù kě chí yán， yīn tā bù xǐ yuè yú mèi rén， suǒ yǐ nǐ xǔ de yuàn yīng dāng cháng hái."],[5,5,"你許願不還，不如不許。","nǐ xǔ yuàn bù hái， bù rú bù xǔ."],[5,6,"不可任你的口使肉體犯罪，也不可在祭司面前說是錯許了。為何使神因你的聲音發怒，敗壞你手所做的呢？","bù kě rèn nǐ de kǒu shǐ ròu tǐ fàn zuì， yě bù kě zài jì sī miàn qián shuō shì cuò xǔ le. wèi hé shǐ shén yīn nǐ de shēng yīn fā nù， bài huài nǐ shǒu suǒ zuò de ne？"],[5,7,"多夢和多言，其中多有虛幻，你只要敬畏神。","duō mèng hé duō yán， qí zhōng duō yǒu xū huàn， nǐ zhǐ yào jìng wèi shén."],[5,8,"你若在一省之中見窮人受欺壓，並奪去公義公平的事，不要因此詫異；因有一位高過居高位的鑒察，在他們以上還有更高的。","nǐ ruò zài yī shěng zhī zhōng jiàn qióng rén shòu qī yā， bìng duó qù gōng yì gōng píng de shì， bù yào yīn cǐ chà yì； yīn yǒu yī wèi gāo guò jū gāo wèi de jiàn chá， zài tā men yǐ shàng hái yǒu gèng gāo de."],[5,9,"況且地的益處歸眾人，就是君王也受田地的供應。","kuàng qiě de de yì chù guī zhòng rén， jiù shì jūn wáng yě shòu tián de de gōng yīng."],[5,10,"貪愛銀子的，不因得銀子知足；貪愛豐富的，也不因得利益知足。這也是虛空。","tān ài yín zǐ de， bù yīn dé yín zǐ zhī zú； tān ài fēng fù de， yě bù yīn dé lì yì zhī zú. zhè yě shì xū kōng."],[5,11,"貨物增添，吃的人也增添，物主得甚麼益處呢？不過眼看而已！","huò wù zēng tiān， chī de rén yě zēng tiān， wù zhǔ dé shèn me yì chù ne？ bù guò yǎn kàn ér yǐ！"],[5,12,"勞碌的人不拘吃多吃少，睡得香甜；富足人的豐滿卻不容他睡覺。","láo lù de rén bù jū chī duō chī shǎo， shuì dé xiāng tián； fù zú rén de fēng mǎn què bù róng tā shuì jué."],[5,13,"我見日光之下有一宗大禍患，就是財主積存資財，反害自己。","wǒ jiàn rì guāng zhī xià yǒu yī zōng dà huò huàn， jiù shì cái zhǔ jī cún zī cái， fǎn hài zì jǐ."],[5,14,"因遭遇禍患，這些資財就消滅；那人若生了兒子，手裏也一無所有。","yīn zāo yù huò huàn， zhè xiē zī cái jiù xiāo miè； nà rén ruò shēng le ér zǐ， shǒu lǐ yě yī wú suǒ yǒu."],[5,15,"他怎樣從母胎赤身而來，也必照樣赤身而去；他所勞碌得來的，手中分毫不能帶去。","tā zěn yàng cóng mǔ tāi chì shēn ér lái， yě bì zhào yàng chì shēn ér qù； tā suǒ láo lù dé lái de， shǒu zhōng fēn háo bù néng dài qù."],[5,16,"他來的情形怎樣，他去的情形也怎樣。這也是一宗大禍患。他為風勞碌有甚麼益處呢？","tā lái de qíng xíng zěn yàng， tā qù de qíng xíng yě zěn yàng. zhè yě shì yī zōng dà huò huàn. tā wèi fēng láo lù yǒu shèn me yì chù ne？"],[5,17,"並且他終身在黑暗中吃喝，多有煩惱，又有病患嘔氣。","bìng qiě tā zhōng shēn zài hēi àn zhōng chī hē， duō yǒu fán nǎo， yòu yǒu bìng huàn ǒu qì."],[5,18,"我所見為善為美的，就是人在神賜他一生的日子吃喝，享受日光之下勞碌得來的好處，因為這是他的分。","wǒ suǒ jiàn wèi shàn wèi měi de， jiù shì rén zài shén cì tā yī shēng de rì zǐ chī hē， xiǎng shòu rì guāng zhī xià láo lù dé lái de hǎo chù， yīn wèi zhè shì tā de fēn."],[5,19,"神賜人資財豐富，使他能以吃用，能取自己的分，在他勞碌中喜樂，這乃是神的恩賜。","shén cì rén zī cái fēng fù， shǐ tā néng yǐ chī yòng， néng qǔ zì jǐ de fēn， zài tā láo lù zhōng xǐ lè， zhè nǎi shì shén de ēn cì."],[5,20,"他不多思念自己一生的年日，因為神應他的心使他喜樂。","tā bù duō sī niàn zì jǐ yī shēng de nián rì， yīn wèi shén yīng tā de xīn shǐ tā xǐ lè."],[6,1,"我見日光之下有一宗禍患重壓在人身上，","wǒ jiàn rì guāng zhī xià yǒu yī zōng huò huàn zhòng yā zài rén shēn shàng，"],[6,2,"就是人蒙神賜他資財、豐富、尊榮，以致他心裏所願的一樣都不缺，只是神使他不能吃用，反有外人來吃用。這是虛空，也是禍患。","jiù shì rén méng shén cì tā zī cái, fēng fù, zūn róng， yǐ zhì tā xīn lǐ suǒ yuàn de yī yàng dōu bù quē， zhǐ shì shén shǐ tā bù néng chī yòng， fǎn yǒu wài rén lái chī yòng. zhè shì xū kōng， yě shì huò huàn."],[6,3,"人若生一百個兒子，活許多歲數，以致他的年日甚多，心裏卻不得滿享福樂，又不得埋葬；據我說，那不到期而落的胎比他倒好。","rén ruò shēng yī bǎi gè ér zǐ， huó xǔ duō suì shù， yǐ zhì tā de nián rì shèn duō， xīn lǐ què bù dé mǎn xiǎng fú lè， yòu bù dé mái zàng； jù wǒ shuō， nà bù dào qī ér luò de tāi bǐ tā dào hǎo."],[6,4,"因為虛虛而來，暗暗而去，名字被黑暗遮蔽，","yīn wèi xū xū ér lái， àn àn ér qù， míng zì bèi hēi àn zhē bì，"],[6,5,"並且沒有見過天日，也毫無知覺；這胎，比那人倒享安息。","bìng qiě méi yǒu jiàn guò tiān rì， yě háo wú zhī jué； zhè tāi， bǐ nà rén dào xiǎng ān xī."],[6,6,"那人雖然活千年，再活千年，卻不享福，眾人豈不都歸一個地方去嗎？","nà rén suī rán huó qiān nián， zài huó qiān nián， què bù xiǎng fú， zhòng rén qǐ bù dōu guī yī gè de fāng qù ma？"],[6,7,"人的勞碌都為口腹，心裏卻不知足。","rén de láo lù dōu wèi kǒu fù， xīn lǐ què bù zhī zú."],[6,8,"這樣看來，智慧人比愚昧人有甚麼長處呢？窮人在眾人面前知道如何行，有甚麼長處呢？","zhè yàng kàn lái， zhì huì rén bǐ yú mèi rén yǒu shèn me zhǎng chù ne？ qióng rén zài zhòng rén miàn qián zhī dào rú hé xíng， yǒu shèn me zhǎng chù ne？"],[6,9,"眼睛所看的比心裏妄想的倒好。這也是虛空，也是捕風。","yǎn jīng suǒ kàn de bǐ xīn lǐ wàng xiǎng de dào hǎo. zhè yě shì xū kōng， yě shì bǔ fēng."],[6,10,"先前所有的，早已起了名，並知道何為人，他也不能與那比自己力大的相爭。","xiān qián suǒ yǒu de， zǎo yǐ qǐ le míng， bìng zhī dào hé wèi rén， tā yě bù néng yǔ nà bǐ zì jǐ lì dà de xiāng zhēng."],[6,11,"加增虛浮的事既多，這與人有甚麼益處呢？","jiā zēng xū fú de shì jì duō， zhè yǔ rén yǒu shèn me yì chù ne？"],[6,12,"人一生虛度的日子，就如影兒經過，誰知道甚麼與他有益呢？誰能告訴他身後在日光之下有甚麼事呢？","rén yī shēng xū dù de rì zǐ， jiù rú yǐng ér jīng guò， shuí zhī dào shèn me yǔ tā yǒu yì ne？ shuí néng gào sù tā shēn hòu zài rì guāng zhī xià yǒu shèn me shì ne？"],[7,1,"名譽強如美好的膏油；人死的日子勝過人生的日子。","míng yù qiáng rú měi hǎo de gāo yóu； rén sǐ de rì zǐ shèng guò rén shēng de rì zǐ."],[7,2,"往遭喪的家去， 強如往宴樂的家去； 因為 死是眾人的結局， 活人也必將這事放在心上。","wǎng zāo sàng de jiā qù， qiáng rú wǎng yàn lè de jiā qù； yīn wèi sǐ shì zhòng rén de jié jú， huó rén yě bì jiāng zhè shì fàng zài xīn shàng."],[7,3,"憂愁強如喜笑； 因為面帶愁容，終必使心喜樂。","yōu chóu qiáng rú xǐ xiào； yīn wèi miàn dài chóu róng， zhōng bì shǐ xīn xǐ lè."],[7,4,"智慧人的心在遭喪之家； 愚昧人的心在快樂之家。","zhì huì rén de xīn zài zāo sàng zhī jiā； yú mèi rén de xīn zài kuài lè zhī jiā."],[7,5,"聽智慧人的責備， 強如聽愚昧人的歌唱。","tīng zhì huì rén de zé bèi， qiáng rú tīng yú mèi rén de gē chàng."],[7,6,"愚昧人的笑聲， 好像鍋下燒荊棘的爆聲； 這也是虛空。","yú mèi rén de xiào shēng， hǎo xiàng guō xià shāo jīng jí de bào shēng； zhè yě shì xū kōng."],[7,7,"勒索使智慧人變為愚妄； 賄賂能敗壞人的慧心。","lēi suǒ shǐ zhì huì rén biàn wèi yú wàng； huì lù néng bài huài rén de huì xīn."],[7,8,"事情的終局強如事情的起頭； 存心忍耐的，勝過居心驕傲的。","shì qíng de zhōng jú qiáng rú shì qíng de qǐ tóu； cún xīn rěn nài de， shèng guò jū xīn jiāo ào de."],[7,9,"你不要心裏急躁惱怒， 因為惱怒存在愚昧人的懷中。","nǐ bù yào xīn lǐ jí zào nǎo nù， yīn wèi nǎo nù cún zài yú mèi rén de huái zhōng."],[7,10,"不要說： 先前的日子強過如今的日子， 是甚麼緣故呢？ 你這樣問，不是出於智慧。","bù yào shuō： xiān qián de rì zǐ qiáng guò rú jīn de rì zǐ， shì shèn me yuán gù ne？ nǐ zhè yàng wèn， bù shì chū yú zhì huì."],[7,11,"智慧和產業並好， 而且見天日的人得智慧更為有益。","zhì huì hé chǎn yè bìng hǎo， ér qiě jiàn tiān rì de rén dé zhì huì gèng wèi yǒu yì."],[7,12,"因為智慧護庇人， 好像銀錢護庇人一樣。 惟獨智慧能保全智慧人的生命。 這就是知識的益處。","yīn wèi zhì huì hù bì rén， hǎo xiàng yín qián hù bì rén yī yàng. wéi dú zhì huì néng bǎo quán zhì huì rén de shēng mìng. zhè jiù shì zhī shí de yì chù."],[7,13,"你要察看神的作為； 因神使為曲的，誰能變為直呢？","nǐ yào chá kàn shén de zuò wèi； yīn shén shǐ wèi qū de， shuí néng biàn wèi zhí ne？"],[7,14,"遇亨通的日子你當喜樂；遭患難的日子你當思想；因為神使這兩樣並列，為的是叫人查不出身後有甚麼事。","yù hēng tōng de rì zǐ nǐ dāng xǐ lè； zāo huàn nán de rì zǐ nǐ dāng sī xiǎng； yīn wèi shén shǐ zhè liǎng yàng bìng liè， wèi de shì jiào rén chá bù chū shēn hòu yǒu shèn me shì."],[7,15,"有義人行義，反致滅亡；有惡人行惡，倒享長壽。這都是我在虛度之日中所見過的。","yǒu yì rén xíng yì， fǎn zhì miè wáng； yǒu è rén xíng è， dào xiǎng zhǎng shòu. zhè dōu shì wǒ zài xū dù zhī rì zhōng suǒ jiàn guò de."],[7,16,"不要行義過分，也不要過於自逞智慧，何必自取敗亡呢？","bù yào xíng yì guò fēn， yě bù yào guò yú zì chěng zhì huì， hé bì zì qǔ bài wáng ne？"],[7,17,"不要行惡過分，也不要為人愚昧，何必不到期而死呢？","bù yào xíng è guò fēn， yě bù yào wèi rén yú mèi， hé bì bù dào qī ér sǐ ne？"],[7,18,"你持守這個為美，那個也不要鬆手；因為敬畏神的人，必從這兩樣出來。","nǐ chí shǒu zhè gè wèi měi， nà gè yě bù yào sōng shǒu； yīn wèi jìng wèi shén de rén， bì cóng zhè liǎng yàng chū lái."],[7,19,"智慧使有智慧的人比城中十個官長更有能力。","zhì huì shǐ yǒu zhì huì de rén bǐ chéng zhōng shí gè guān zhǎng gèng yǒu néng lì."],[7,20,"時常行善而不犯罪的義人，世上實在沒有。","shí cháng xíng shàn ér bù fàn zuì de yì rén， shì shàng shí zài méi yǒu."],[7,21,"人所說的一切話，你不要放在心上，恐怕聽見你的僕人咒詛你。","rén suǒ shuō de yī qiè huà， nǐ bù yào fàng zài xīn shàng， kǒng pà tīng jiàn nǐ de pú rén zhòu zǔ nǐ."],[7,22,"因為你心裏知道，自己也曾屢次咒詛別人。","yīn wèi nǐ xīn lǐ zhī dào， zì jǐ yě céng lǚ cì zhòu zǔ bié rén."],[7,23,"我曾用智慧試驗這一切事；我說，要得智慧，智慧卻離我遠。","wǒ céng yòng zhì huì shì yàn zhè yī qiè shì； wǒ shuō， yào dé zhì huì， zhì huì què lí wǒ yuǎn."],[7,24,"萬事 之理，離 我甚遠，而且最深，誰能測透呢？","wàn shì zhī lǐ， lí wǒ shèn yuǎn， ér qiě zuì shēn， shuí néng cè tòu ne？"],[7,25,"我轉念，一心要知道，要考察，要尋求智慧和 萬事的理由；又要知道邪惡為愚昧，愚昧為狂妄。","wǒ zhuǎn niàn， yī xīn yào zhī dào， yào kǎo chá， yào xún qiú zhì huì hé wàn shì de lǐ yóu； yòu yào zhī dào xié è wèi yú mèi， yú mèi wèi kuáng wàng."],[7,26,"我得知有等婦人比死還苦：她的心是網羅，手是鎖鍊。凡蒙神喜悅的人必能躲避她；有罪的人卻被她纏住了。","wǒ dé zhī yǒu děng fù rén bǐ sǐ hái kǔ： tā de xīn shì wǎng luó， shǒu shì suǒ liàn. fán méng shén xǐ yuè de rén bì néng duǒ bì tā； yǒu zuì de rén què bèi tā chán zhù le."],[7,27,"傳道者說：「看哪，一千男子中，我找到一個 正直人，但眾女子中，沒有找到一個。」我 將這事一一比較，要尋求其理，我心仍要尋找，卻未曾找到。","chuán dào zhě shuō：‘kàn nǎ， yī qiān nán zǐ zhōng， wǒ zhǎo dào yī gè zhèng zhí rén， dàn zhòng nǚ zǐ zhōng， méi yǒu zhǎo dào yī gè.’ wǒ jiāng zhè shì yī yī bǐ jiào， yào xún qiú qí lǐ， wǒ xīn réng yào xún zhǎo， què wèi céng zhǎo dào."],[7,29,"我所找到的只有一件，就是神造人原是正直，但他們尋出許多巧計。","wǒ suǒ zhǎo dào de zhǐ yǒu yī jiàn， jiù shì shén zào rén yuán shì zhèng zhí， dàn tā men xún chū xǔ duō qiǎo jì."],[8,1,"誰如智慧人呢？ 誰知道事情的解釋呢？ 人的智慧使他的臉發光， 並使他臉上的暴氣改變。","shuí rú zhì huì rén ne？ shuí zhī dào shì qíng de jiě shì ne？ rén de zhì huì shǐ tā de liǎn fā guāng， bìng shǐ tā liǎn shàng de bào qì gǎi biàn."],[8,2,"我 勸你遵守王的命令；既指神起誓，理當如此。","wǒ quàn nǐ zūn shǒu wáng de mìng lìng； jì zhǐ shén qǐ shì， lǐ dāng rú cǐ."],[8,3,"不要急躁離開王的面前，不要固執行惡，因為他凡事都隨自己的心意而行。","bù yào jí zào lí kāi wáng de miàn qián， bù yào gù zhí xíng è， yīn wèi tā fán shì dōu suí zì jǐ de xīn yì ér xíng."],[8,4,"王的話本有權力，誰敢問他說「你做甚麼」呢？","wáng de huà běn yǒu quán lì， shuí gǎn wèn tā shuō‘nǐ zuò shèn me’ ne？"],[8,5,"凡遵守命令的，必不經歷禍患；智慧人的心能辨明時候和定理。","fán zūn shǒu mìng lìng de， bì bù jīng lì huò huàn； zhì huì rén de xīn néng biàn míng shí hòu hé dìng lǐ."],[8,6,"各樣事務 成就都有時候和定理，因為人的苦難重壓在他身上。","gè yàng shì wù chéng jiù dōu yǒu shí hòu hé dìng lǐ， yīn wèi rén de kǔ nán zhòng yā zài tā shēn shàng."],[8,7,"他不知道將來的事，因為將來如何，誰能告訴他呢？","tā bù zhī dào jiāng lái de shì， yīn wèi jiāng lái rú hé， shuí néng gào sù tā ne？"],[8,8,"無人有權力掌管生命，將生命留住；也無人有權力掌管死期；這場爭戰，無人能免；邪惡也不能救那好行邪惡的人。","wú rén yǒu quán lì zhǎng guǎn shēng mìng， jiāng shēng mìng liú zhù； yě wú rén yǒu quán lì zhǎng guǎn sǐ qī； zhè chǎng zhēng zhàn， wú rén néng miǎn； xié è yě bù néng jiù nà hǎo xíng xié è de rén."],[8,9,"這一切我都見過，也專心查考日光之下所做的一切事。有時這人管轄那人，令人受害。","zhè yī qiè wǒ dōu jiàn guò， yě zhuān xīn chá kǎo rì guāng zhī xià suǒ zuò de yī qiè shì. yǒu shí zhè rén guǎn xiá nà rén， lìng rén shòu hài."],[8,10,"我見惡人埋葬，歸入 墳墓；又見行正直事的離開聖地，在城中被人忘記。這也是虛空。","wǒ jiàn è rén mái zàng， guī rù fén mù； yòu jiàn xíng zhèng zhí shì de lí kāi shèng de， zài chéng zhōng bèi rén wàng jì. zhè yě shì xū kōng."],[8,11,"因為斷定罪名不立刻施刑，所以世人滿心作惡。","yīn wèi duàn dìng zuì míng bù lì kè shī xíng， suǒ yǐ shì rén mǎn xīn zuò è."],[8,12,"罪人雖然作惡百次，倒享長久的年日；然而我準知道，敬畏神的，就是在他面前敬畏的人，終久必得福樂。","zuì rén suī rán zuò è bǎi cì， dào xiǎng zhǎng jiǔ de nián rì； rán ér wǒ zhǔn zhī dào， jìng wèi shén de， jiù shì zài tā miàn qián jìng wèi de rén， zhōng jiǔ bì dé fú lè."],[8,13,"惡人卻不得福樂，也不得長久的年日；這年日好像影兒，因他不敬畏神。","è rén què bù dé fú lè， yě bù dé zhǎng jiǔ de nián rì； zhè nián rì hǎo xiàng yǐng ér， yīn tā bù jìng wèi shén."],[8,14,"世上有一件虛空的事，就是義人所遭遇的，反照惡人所行的；又有惡人所遭遇的，反照義人所行的。我說，這也是虛空。","shì shàng yǒu yī jiàn xū kōng de shì， jiù shì yì rén suǒ zāo yù de， fǎn zhào è rén suǒ xíng de； yòu yǒu è rén suǒ zāo yù de， fǎn zhào yì rén suǒ xíng de. wǒ shuō， zhè yě shì xū kōng."],[8,15,"我就稱讚快樂，原來人在日光之下，莫強如吃喝快樂；因為他在日光之下，神賜他一生的年日，要從勞碌中，時常享受所得的。","wǒ jiù chēng zàn kuài lè， yuán lái rén zài rì guāng zhī xià， mò qiáng rú chī hē kuài lè； yīn wèi tā zài rì guāng zhī xià， shén cì tā yī shēng de nián rì， yào cóng láo lù zhōng， shí cháng xiǎng shòu suǒ dé de."],[8,16,"我專心求智慧，要看世上所做的事。（有晝夜不睡覺不合眼的。）","wǒ zhuān xīn qiú zhì huì， yào kàn shì shàng suǒ zuò de shì.（yǒu zhòu yè bù shuì jué bù hé yǎn de.）"],[8,17,"我就看明神一切的作為，知道人查不出日光之下所做的事；任憑他費多少力尋查，都查不出來，就是智慧人雖想知道，也是查不出來。","wǒ jiù kàn míng shén yī qiè de zuò wèi， zhī dào rén chá bù chū rì guāng zhī xià suǒ zuò de shì； rèn píng tā fèi duō shǎo lì xún chá， dōu chá bù chū lái， jiù shì zhì huì rén suī xiǎng zhī dào， yě shì chá bù chū lái."],[9,1,"我將這一切事放在心上，詳細考究，就知道義人和智慧人，並他們的作為都在神手中；或是愛，或是恨，都在他們的前面，人不能知道。","wǒ jiāng zhè yī qiè shì fàng zài xīn shàng， xiáng xì kǎo jiū， jiù zhī dào yì rén hé zhì huì rén， bìng tā men de zuò wèi dōu zài shén shǒu zhōng； huò shì ài， huò shì hèn， dōu zài tā men de qián miàn， rén bù néng zhī dào."],[9,2,"凡臨到眾人的事都是一樣：義人和惡人都遭遇一樣的事；好人，潔淨人和不潔淨人，獻祭的與不獻祭的，也是一樣。好人如何，罪人也如何；起誓的如何，怕起誓的也如何。","fán lín dào zhòng rén de shì dōu shì yī yàng： yì rén hé è rén dōu zāo yù yī yàng de shì； hǎo rén， jié jìng rén hé bù jié jìng rén， xiàn jì de yǔ bù xiàn jì de， yě shì yī yàng. hǎo rén rú hé， zuì rén yě rú hé； qǐ shì de rú hé， pà qǐ shì de yě rú hé."],[9,3,"在日光之下所行的一切事上有一件禍患，就是眾人所遭遇的都是一樣，並且世人的心充滿了惡；活着的時候心裏狂妄，後來就歸死人那裏去了。","zài rì guāng zhī xià suǒ xíng de yī qiè shì shàng yǒu yī jiàn huò huàn， jiù shì zhòng rén suǒ zāo yù de dōu shì yī yàng， bìng qiě shì rén de xīn chōng mǎn le è； huó zhe de shí hòu xīn lǐ kuáng wàng， hòu lái jiù guī sǐ rén nà lǐ qù le."],[9,4,"與一切活人相連的，那人還有指望，因為活着的狗比死了的獅子更強。","yǔ yī qiè huó rén xiāng lián de， nà rén hái yǒu zhǐ wàng， yīn wèi huó zhe de gǒu bǐ sǐ le de shī zǐ gèng qiáng."],[9,5,"活着的人知道必死；死了的人毫無所知，也不再得賞賜；他們的名無人記念。","huó zhe de rén zhī dào bì sǐ； sǐ le de rén háo wú suǒ zhī， yě bù zài dé shǎng cì； tā men de míng wú rén jì niàn."],[9,6,"他們的愛，他們的恨，他們的嫉妒，早都消滅了。在日光之下所行的一切事上，他們永不再有分了。","tā men de ài， tā men de hèn， tā men de jí dù， zǎo dōu xiāo miè le. zài rì guāng zhī xià suǒ xíng de yī qiè shì shàng， tā men yǒng bù zài yǒu fēn le."],[9,7,"你只管去歡歡喜喜吃你的飯，心中快樂喝你的酒，因為神已經悅納你的作為。","nǐ zhǐ guǎn qù huān huān xǐ xǐ chī nǐ de fàn， xīn zhōng kuài lè hē nǐ de jiǔ， yīn wèi shén yǐ jīng yuè nà nǐ de zuò wèi."],[9,8,"你的衣服當時常潔白，你頭上也不要缺少膏油。","nǐ de yī fú dāng shí cháng jié bái， nǐ tóu shàng yě bù yào quē shǎo gāo yóu."],[9,9,"在你一生虛空的年日，就是神賜你在日光之下虛空的年日，當同你所愛的妻，快活度日，因為那是你生前在日光之下勞碌的事上所得的分。","zài nǐ yī shēng xū kōng de nián rì， jiù shì shén cì nǐ zài rì guāng zhī xià xū kōng de nián rì， dāng tóng nǐ suǒ ài de qī， kuài huó dù rì， yīn wèi nà shì nǐ shēng qián zài rì guāng zhī xià láo lù de shì shàng suǒ dé de fēn."],[9,10,"凡你手所當做的事要盡力去做；因為在你所必去的陰間沒有工作，沒有謀算，沒有知識，也沒有智慧。","fán nǐ shǒu suǒ dāng zuò de shì yào jǐn lì qù zuò； yīn wèi zài nǐ suǒ bì qù de yīn jiān méi yǒu gōng zuò， méi yǒu móu suàn， méi yǒu zhī shí， yě méi yǒu zhì huì."],[9,11,"我又轉念：見日光之下，快跑的未必能贏；力戰的未必得勝；智慧的未必得糧食；明哲的未必得資財；靈巧的未必得喜悅。所臨到眾人的是在乎當時的機會。","wǒ yòu zhuǎn niàn： jiàn rì guāng zhī xià， kuài pǎo de wèi bì néng yíng； lì zhàn de wèi bì dé shèng； zhì huì de wèi bì dé liáng shí； míng zhé de wèi bì dé zī cái； líng qiǎo de wèi bì dé xǐ yuè. suǒ lín dào zhòng rén de shì zài hū dāng shí de jī huì."],[9,12,"原來人也不知道自己的定期。魚被惡網圈住，鳥被網羅捉住，禍患忽然臨到的時候，世人陷在其中也是如此。","yuán lái rén yě bù zhī dào zì jǐ de dìng qī. yú bèi è wǎng quān zhù， niǎo bèi wǎng luó zhuō zhù， huò huàn hū rán lín dào de shí hòu， shì rén xiàn zài qí zhōng yě shì rú cǐ."],[9,13,"我見日光之下有一樣智慧，據我看乃是廣大，","wǒ jiàn rì guāng zhī xià yǒu yī yàng zhì huì， jù wǒ kàn nǎi shì guǎng dà，"],[9,14,"就是有一小城，其中的人數稀少，有大君王來攻擊，修築營壘，將城圍困。","jiù shì yǒu yī xiǎo chéng， qí zhōng de rén shù xī shǎo， yǒu dà jūn wáng lái gōng jī， xiū zhú yíng lěi， jiāng chéng wéi kùn."],[9,15,"城中有一個貧窮的智慧人，他用智慧救了那城，卻沒有人記念那窮人。","chéng zhōng yǒu yī gè pín qióng de zhì huì rén， tā yòng zhì huì jiù le nà chéng， què méi yǒu rén jì niàn nà qióng rén."],[9,16,"我就說，智慧勝過勇力；然而那貧窮人的智慧被人藐視，他的話也無人聽從。","wǒ jiù shuō， zhì huì shèng guò yǒng lì； rán ér nà pín qióng rén de zhì huì bèi rén miǎo shì， tā de huà yě wú rén tīng cóng."],[9,17,"寧可在安靜之中聽智慧人的言語，不聽掌管愚昧人的喊聲。","níng kě zài ān jìng zhī zhōng tīng zhì huì rén de yán yǔ， bù tīng zhǎng guǎn yú mèi rén de hǎn shēng."],[9,18,"智慧勝過打仗的兵器；但一個罪人能敗壞許多善事。","zhì huì shèng guò dǎ zhàng de bīng qì； dàn yī gè zuì rén néng bài huài xǔ duō shàn shì."],[10,1,"死蒼蠅使做香的膏油發出臭氣； 這樣，一點愚昧也能敗壞智慧和尊榮。","sǐ cāng yíng shǐ zuò xiāng de gāo yóu fā chū chòu qì； zhè yàng， yī diǎn yú mèi yě néng bài huài zhì huì hé zūn róng."],[10,2,"智慧人的心居右； 愚昧人的心居左。","zhì huì rén de xīn jū yòu； yú mèi rén de xīn jū zuǒ."],[10,3,"並且愚昧人行路顯出無知， 對眾人說，他是愚昧人。","bìng qiě yú mèi rén xíng lù xiǎn chū wú zhī， duì zhòng rén shuō， tā shì yú mèi rén."],[10,4,"掌權者的心若向你發怒， 不要離開你的本位， 因為柔和能免大過。","zhǎng quán zhě de xīn ruò xiàng nǐ fā nù， bù yào lí kāi nǐ de běn wèi， yīn wèi róu hé néng miǎn dà guò."],[10,5,"我見日光之下有一件禍患， 似乎出於掌權的錯誤，","wǒ jiàn rì guāng zhī xià yǒu yī jiàn huò huàn， sì hū chū yú zhǎng quán de cuò wù，"],[10,6,"就是愚昧人立在高位； 富足人坐在低位。","jiù shì yú mèi rén lì zài gāo wèi； fù zú rén zuò zài dī wèi."],[10,7,"我見過僕人騎馬， 王子像僕人在地上步行。","wǒ jiàn guò pú rén qí mǎ， wáng zǐ xiàng pú rén zài de shàng bù xíng."],[10,8,"挖陷坑的，自己必掉在其中； 拆牆垣的，必為蛇所咬。","wā xiàn kēng de， zì jǐ bì diào zài qí zhōng； chāi qiáng yuán de， bì wèi shé suǒ yǎo."],[10,9,"鑿開石頭的，必受損傷； 劈開木頭的，必遭危險。","záo kāi shí tóu de， bì shòu sǔn shāng； pī kāi mù tóu de， bì zāo wēi xiǎn."],[10,10,"鐵器鈍了，若不將刃磨快，就必多費氣力； 但得智慧指教，便有益處。","tiě qì dùn le， ruò bù jiāng rèn mó kuài， jiù bì duō fèi qì lì； dàn dé zhì huì zhǐ jiào， biàn yǒu yì chù."],[10,11,"未行法術以先，蛇若咬人， 後行法術也是無益。","wèi xíng fǎ shù yǐ xiān， shé ruò yǎo rén， hòu xíng fǎ shù yě shì wú yì."],[10,12,"智慧人的口說出恩言； 愚昧人的嘴吞滅自己。","zhì huì rén de kǒu shuō chū ēn yán； yú mèi rén de zuǐ tūn miè zì jǐ."],[10,13,"他口中的言語起頭是愚昧； 他話的末尾是奸惡的狂妄。","tā kǒu zhōng de yán yǔ qǐ tóu shì yú mèi； tā huà de mò wěi shì jiān è de kuáng wàng."],[10,14,"愚昧人多有言語， 人卻不知將來有甚麼事； 他身後的事誰能告訴他呢？","yú mèi rén duō yǒu yán yǔ， rén què bù zhī jiāng lái yǒu shèn me shì； tā shēn hòu de shì shuí néng gào sù tā ne？"],[10,15,"凡愚昧人，他的勞碌使自己困乏， 因為連進城的路，他也不知道。","fán yú mèi rén， tā de láo lù shǐ zì jǐ kùn fá， yīn wèi lián jìn chéng de lù， tā yě bù zhī dào."],[10,16,"邦國啊，你的王若是孩童， 你的群臣早晨宴樂， 你就有禍了！","bāng guó a， nǐ de wáng ruò shì hái tóng， nǐ de qún chén zǎo chén yàn lè， nǐ jiù yǒu huò le！"],[10,17,"邦國啊，你的王若是貴冑之子， 你的群臣按時吃喝， 為要補力，不為酒醉， 你就有福了！","bāng guó a， nǐ de wáng ruò shì guì zhòu zhī zǐ， nǐ de qún chén àn shí chī hē， wèi yào bǔ lì， bù wèi jiǔ zuì， nǐ jiù yǒu fú le！"],[10,18,"因人懶惰，房頂塌下； 因人手懶，房屋滴漏。","yīn rén lǎn duò， fáng dǐng tā xià； yīn rén shǒu lǎn， fáng wū dī lòu."],[10,19,"設擺筵席是為喜笑。 酒能使人快活； 錢能叫萬事應心。","shè bǎi yán xí shì wèi xǐ xiào. jiǔ néng shǐ rén kuài huó； qián néng jiào wàn shì yīng xīn."],[10,20,"你不可咒詛君王， 也不可心懷此念； 在你臥房也不可咒詛富戶。 因為空中的鳥必傳揚這聲音， 有翅膀的也必述說這事。","nǐ bù kě zhòu zǔ jūn wáng， yě bù kě xīn huái cǐ niàn； zài nǐ wò fáng yě bù kě zhòu zǔ fù hù. yīn wèi kōng zhōng de niǎo bì chuán yáng zhè shēng yīn， yǒu chì bǎng de yě bì shù shuō zhè shì."],[11,1,"當將你的糧食撒在水面， 因為日久必能得着。","dāng jiāng nǐ de liáng shí sā zài shuǐ miàn， yīn wèi rì jiǔ bì néng dé zhe."],[11,2,"你要分給七人，或分給八人， 因為你不知道將來有甚麼災禍臨到地上。","nǐ yào fēn gěi qī rén， huò fēn gěi bā rén， yīn wèi nǐ bù zhī dào jiāng lái yǒu shèn me zāi huò lín dào de shàng."],[11,3,"雲若滿了雨，就必傾倒在地上。 樹若向南倒，或向北倒， 樹倒在何處，就存在何處。","yún ruò mǎn le yǔ， jiù bì qīng dào zài de shàng. shù ruò xiàng nán dào， huò xiàng běi dào， shù dào zài hé chù， jiù cún zài hé chù."],[11,4,"看風的，必不撒種； 望雲的，必不收割。","kàn fēng de， bì bù sā zhǒng； wàng yún de， bì bù shōu gē."],[11,5,"風從何道來，骨頭在懷孕婦人的胎中如何長成，你尚且不得知道；這樣，行萬事之神的作為，你更不得知道。","fēng cóng hé dào lái， gǔ tóu zài huái yùn fù rén de tāi zhōng rú hé zhǎng chéng， nǐ shàng qiě bù dé zhī dào； zhè yàng， xíng wàn shì zhī shén de zuò wèi， nǐ gèng bù dé zhī dào."],[11,6,"早晨要撒你的種，晚上也不要歇你的手，因為你不知道哪一樣發旺；或是早撒的，或是晚撒的，或是兩樣都好。","zǎo chén yào sā nǐ de zhǒng， wǎn shàng yě bù yào xiē nǐ de shǒu， yīn wèi nǐ bù zhī dào nǎ yī yàng fā wàng； huò shì zǎo sā de， huò shì wǎn sā de， huò shì liǎng yàng dōu hǎo."],[11,7,"光本是佳美的，眼見日光也是可悅的。","guāng běn shì jiā měi de， yǎn jiàn rì guāng yě shì kě yuè de."],[11,8,"人活多年，就當快樂多年；然而也當想到黑暗的日子。因為這日子必多，所要來的都是虛空。","rén huó duō nián， jiù dāng kuài lè duō nián； rán ér yě dāng xiǎng dào hēi àn de rì zǐ. yīn wèi zhè rì zǐ bì duō， suǒ yào lái de dōu shì xū kōng."],[11,9,"少年人哪，你在幼年時當快樂。在幼年的日子，使你的心歡暢，行你心所願行的，看你眼所愛看的；卻要知道，為這一切的事，神必審問你。","shǎo nián rén nǎ， nǐ zài yòu nián shí dāng kuài lè. zài yòu nián de rì zǐ， shǐ nǐ de xīn huān chàng， xíng nǐ xīn suǒ yuàn xíng de， kàn nǐ yǎn suǒ ài kàn de； què yào zhī dào， wèi zhè yī qiè de shì， shén bì shěn wèn nǐ."],[11,10,"所以，你當從心中除掉愁煩，從肉體克去邪惡；因為一生的開端和幼年之時，都是虛空的。","suǒ yǐ， nǐ dāng cóng xīn zhōng chú diào chóu fán， cóng ròu tǐ kè qù xié è； yīn wèi yī shēng de kāi duān hé yòu nián zhī shí， dōu shì xū kōng de."],[12,1,"你趁着年幼、衰敗的日子尚未來到，就是你所說，我毫無喜樂的那些年日未曾臨近之先，當記念造你的主。","nǐ chèn zhe nián yòu, shuāi bài de rì zǐ shàng wèi lái dào， jiù shì nǐ suǒ shuō， wǒ háo wú xǐ lè de nà xiē nián rì wèi céng lín jìn zhī xiān， dāng jì niàn zào nǐ de zhǔ."],[12,2,"不要等到日頭、光明、月亮、星宿變為黑暗，雨後雲彩反回，","bù yào děng dào rì tóu, guāng míng, yuè liàng, xīng sù biàn wèi hēi àn， yǔ hòu yún cǎi fǎn huí，"],[12,3,"看守房屋的發顫，有力的屈身，推磨的稀少就止息，從窗戶往外看的都昏暗；","kàn shǒu fáng wū de fā chàn， yǒu lì de qū shēn， tuī mó de xī shǎo jiù zhǐ xī， cóng chuāng hù wǎng wài kàn de dōu hūn àn；"],[12,4,"街門關閉，推磨的響聲微小，雀鳥一叫，人就起來，唱歌的女子也都衰微。","jiē mén guān bì， tuī mó de xiǎng shēng wēi xiǎo， què niǎo yī jiào， rén jiù qǐ lái， chàng gē de nǚ zǐ yě dōu shuāi wēi."],[12,5,"人怕高處，路上有驚慌，杏樹開花，蚱蜢成為重擔，人所願的也都廢掉；因為人歸他永遠的家，弔喪的在街上往來。","rén pà gāo chù， lù shàng yǒu jīng huāng， xìng shù kāi huā， zhà měng chéng wèi zhòng dān， rén suǒ yuàn de yě dōu fèi diào； yīn wèi rén guī tā yǒng yuǎn de jiā， diào sàng de zài jiē shàng wǎng lái."],[12,6,"銀鍊折斷，金罐破裂，瓶子在泉旁損壞，水輪在井口破爛，","yín liàn zhé duàn， jīn guàn pò liè， píng zǐ zài quán páng sǔn huài， shuǐ lún zài jǐng kǒu pò làn，"],[12,7,"塵土仍歸於地，靈仍歸於賜靈的神。","chén tǔ réng guī yú de， líng réng guī yú cì líng de shén."],[12,8,"傳道者說：「虛空的虛空，凡事都是虛空。」","chuán dào zhě shuō：‘xū kōng de xū kōng， fán shì dōu shì xū kōng.’"],[12,9,"再者，傳道者因有智慧，仍將知識教訓眾人；又默想，又考查，又陳說許多箴言。","zài zhě， chuán dào zhě yīn yǒu zhì huì， réng jiāng zhī shí jiào xùn zhòng rén； yòu mò xiǎng， yòu kǎo chá， yòu chén shuō xǔ duō zhēn yán."],[12,10,"傳道者專心尋求可喜悅的言語，是憑正直寫的誠實話。","chuán dào zhě zhuān xīn xún qiú kě xǐ yuè de yán yǔ， shì píng zhèng zhí xiě de chéng shí huà."],[12,11,"智慧人的言語好像刺棍；會中之師的 言語又像釘穩的釘子，都是一個牧者所賜的。","zhì huì rén de yán yǔ hǎo xiàng cì gùn； huì zhōng zhī shī de yán yǔ yòu xiàng dīng wěn de dīng zǐ， dōu shì yī gè mù zhě suǒ cì de."],[12,12,"我兒，還有一層，你當受勸戒：著書多，沒有窮盡；讀書多，身體疲倦。","wǒ ér， hái yǒu yī céng， nǐ dāng shòu quàn jiè： zhù shū duō， méi yǒu qióng jǐn； dú shū duō， shēn tǐ pí juàn."],[12,13,"這些事都已聽見了，總意就是：敬畏神，謹守他的誡命，這是人所當盡的 本分。","zhè xiē shì dōu yǐ tīng jiàn le， zǒng yì jiù shì： jìng wèi shén， jǐn shǒu tā de jiè mìng， zhè shì rén suǒ dāng jǐn de běn fēn."],[12,14,"因為人所做的事，連一切隱藏的事，無論是善是惡，神都必審問。","yīn wèi rén suǒ zuò de shì， lián yī qiè yǐn cáng de shì， wú lùn shì shàn shì è， shén dōu bì shěn wèn."]],"arb-vandyck":[[1,1,"كَلَامُ ٱلْجَامِعَةِ ٱبْنِ دَاوُدَ ٱلْمَلِكِ فِي أُورُشَلِيمَ:","kalāmu ٱl̊jāmiʿaẗi ٱb̊ni dāwuda ٱl̊maliki fī ạủwrusẖalīma:"],[1,2,"بَاطِلُ ٱلْأَبَاطِيلِ، قَالَ ٱلْجَامِعَةُ: بَاطِلُ ٱلْأَبَاطِيلِ، ٱلْكُلُّ بَاطِلٌ.","bāṭilu ٱl̊ạảbāṭīli, qāla ٱl̊jāmiʿaẗu: bāṭilu ٱl̊ạảbāṭīli, ٱl̊kulũ bāṭiluⁿ."],[1,3,"مَا ٱلْفَائِدَةُ لِلْإِنْسَانِ مِنْ كُلِّ تَعَبِهِ ٱلَّذِي يَتْعَبُهُ تَحْتَ ٱلشَّمْسِ؟","mā ٱl̊fāyỉdaẗu lil̊ại̹n̊sāni min̊ kulĩ taʿabihi ٱlãdẖī yat̊ʿabuhu taḥ̊ta ٱlsẖãm̊si?"],[1,4,"دَوْرٌ يَمْضِي وَدَوْرٌ يَجِيءُ، وَٱلْأَرْضُ قَائِمَةٌ إِلَى ٱلْأَبَدِ.","daẘruⁿ yam̊ḍī wadaẘruⁿ yajīʾu, waٱl̊ạảr̊ḍu qāyỉmaẗuⁿ ại̹lay̱ ٱl̊ạảbadi."],[1,5,"وَٱلشَّمْسُ تُشْرِقُ، وَٱلشَّمْسُ تَغْرُبُ، وَتُسْرِعُ إِلَى مَوْضِعِهَا حَيْثُ تُشْرِقُ.","waٱlsẖãm̊su tusẖ̊riqu, waٱlsẖãm̊su tagẖ̊rubu, watus̊riʿu ại̹lay̱ maẘḍiʿihā ḥaẙtẖu tusẖ̊riqu."],[1,6,"اَلرِّيحُ تَذْهَبُ إِلَى ٱلْجَنُوبِ، وَتَدُورُ إِلَى ٱلشَّمَالِ. تَذْهَبُ دَائِرَةً دَوَرَانًا، وَإِلَى مَدَارَاتِهَا تَرْجِعُ ٱلرِّيحُ.","ạalrĩyḥu tadẖ̊habu ại̹lay̱ ٱl̊janūbi, watadūru ại̹lay̱ ٱlsẖãmāli. tadẖ̊habu dāyỉraẗaⁿ dawarānaⁿạ, wāi̹lay̱ madārātihā tar̊jiʿu ٱlrĩyḥu."],[1,7,"كُلُّ ٱلْأَنْهَارِ تَجْرِي إِلَى ٱلْبَحْرِ، وَٱلْبَحْرُ لَيْسَ بِمَلآنَ. إِلَى ٱلْمَكَانِ ٱلَّذِي جَرَتْ مِنْهُ ٱلْأَنْهَارُ إِلَى هُنَاكَ تَذْهَبُ رَاجِعَةً.","kulũ ٱl̊ạản̊hāri taj̊rī ại̹lay̱ ٱl̊baḥ̊ri, waٱl̊baḥ̊ru laẙsa bimalậna. ại̹lay̱ ٱl̊makāni ٱlãdẖī jarat̊ min̊hu ٱl̊ạản̊hāru ại̹lay̱ hunāka tadẖ̊habu rājiʿaẗaⁿ."],[1,8,"كُلُّ ٱلْكَلَامِ يَقْصُرُ. لَا يَسْتَطِيعُ ٱلْإِنْسَانُ أَنْ يُخْبِرَ بِٱلْكُلِّ. ٱلْعَيْنُ لَا تَشْبَعُ مِنَ ٱلنَّظَرِ، وَٱلْأُذُنُ لَا تَمْتَلِئُ مِنَ ٱلسَّمْعِ.","kulũ ٱl̊kalāmi yaq̊ṣuru. lā yas̊taṭīʿu ٱl̊ại̹n̊sānu ạản̊ yukẖ̊bira biٱl̊kulĩ. ٱl̊ʿaẙnu lā tasẖ̊baʿu mina ٱlnãẓari, waٱl̊ạủdẖunu lā tam̊talīủ mina ٱlsãm̊ʿi."],[1,9,"مَا كَانَ فَهُوَ مَا يَكُونُ، وَٱلَّذِي صُنِعَ فَهُوَ ٱلَّذِي يُصْنَعُ، فَلَيْسَ تَحْتَ ٱلشَّمْسِ جَدِيدٌ.","mā kāna fahūa mā yakūnu, waٱlãdẖī ṣuniʿa fahūa ٱlãdẖī yuṣ̊naʿu, falaẙsa taḥ̊ta ٱlsẖãm̊si jadīduⁿ."],[1,10,"إِنْ وُجِدَ شَيْءٌ يُقَالُ عَنْهُ: «ٱنْظُرْ. هَذَا جَدِيدٌ!» فَهُوَ مُنْذُ زَمَانٍ كَانَ فِي ٱلدُّهُورِ ٱلَّتِي كَانَتْ قَبْلَنَا.","ại̹n̊ wujida sẖaẙʾuⁿ yuqālu ʿan̊hu: «ٱn̊ẓur̊. hadẖā jadīduⁿ!» fahūa mun̊dẖu zamāniⁿ kāna fī ٱldũhūri ٱlãtī kānat̊ qab̊lanā."],[1,11,"لَيْسَ ذِكْرٌ لِلْأَوَّلِينَ. وَٱلْآخِرُونَ أَيْضًا ٱلَّذِينَ سَيَكُونُونَ، لَا يَكُونُ لَهُمْ ذِكْرٌ عِنْدَ ٱلَّذِينَ يَكُونُونَ بَعْدَهُمْ.","laẙsa dẖik̊ruⁿ lil̊ạảwãlīna. waٱl̊ậkẖirūna ạảẙḍaⁿạ ٱlãdẖīna sayakūnūna, lā yakūnu lahum̊ dẖik̊ruⁿ ʿin̊da ٱlãdẖīna yakūnūna baʿ̊dahum̊."],[1,12,"أَنَا ٱلْجَامِعَةُ كُنْتُ مَلِكًا عَلَى إِسْرَائِيلَ فِي أُورُشَلِيمَ.","ạảnā ٱl̊jāmiʿaẗu kun̊tu malikaⁿạ ʿalay̱ ại̹s̊rāyỉyla fī ạủwrusẖalīma."],[1,13,"وَوَجَّهْتُ قَلْبِي لِلسُّؤَالِ وَٱلتَّفْتِيشِ بِٱلْحِكْمَةِ عَنْ كُلِّ مَا عُمِلَ تَحْتَ ٱلسَّمَاوَاتِ. هُوَ عَنَاءٌ رَدِيءٌ جَعَلَهَا ٱللهُ لِبَنِي ٱلْبَشَرِ لِيَعْنُوا فِيهِ.","wawajãh̊tu qal̊bī lilsũwảạli waٱltãf̊tīsẖi biٱl̊ḥik̊maẗi ʿan̊ kulĩ mā ʿumila taḥ̊ta ٱlsãmāwāti. hūa ʿanāʾuⁿ radīʾuⁿ jaʿalahā ٱllhu libanī ٱl̊basẖari līaʿ̊nūạ fīhi."],[1,14,"رَأَيْتُ كُلَّ ٱلْأَعْمَالِ ٱلَّتِي عُمِلَتْ تَحْتَ ٱلشَّمْسِ فَإِذَا ٱلْكُلُّ بَاطِلٌ وَقَبْضُ ٱلرِّيحِ.","rāảẙtu kulã ٱl̊ạảʿ̊māli ٱlãtī ʿumilat̊ taḥ̊ta ٱlsẖãm̊si fāi̹dẖā ٱl̊kulũ bāṭiluⁿ waqab̊ḍu ٱlrĩyḥi."],[1,15,"اَلْأَعْوَجُ لَا يُمْكِنُ أَنْ يُقَوَّمَ، وَٱلنَّقْصُ لَا يُمْكِنُ أَنْ يُجْبَرَ.","ạal̊ạảʿ̊waju lā yum̊kinu ạản̊ yuqawãma, waٱlnãq̊ṣu lā yum̊kinu ạản̊ yuj̊bara."],[1,16,"أَنَا نَاجَيْتُ قَلْبِي قَائِلًا: «هَا أَنَا قَدْ عَظُمْتُ وَٱزْدَدْتُ حِكْمَةً أَكْثَرَ مِنْ كُلِّ مَنْ كَانَ قَبْلِي عَلَى أُورُشَلِيمَ، وَقَدْ رَأَى قَلْبِي كَثِيرًا مِنَ ٱلْحِكْمَةِ وَٱلْمَعْرِفَةِ».","ạảnā nājaẙtu qal̊bī qāyỉlaⁿạ: «hā ạảnā qad̊ ʿaẓum̊tu waٱz̊dad̊tu ḥik̊maẗaⁿ ạảk̊tẖara min̊ kulĩ man̊ kāna qab̊lī ʿalay̱ ạủwrusẖalīma, waqad̊ rāảy̱ qal̊bī katẖīraⁿạ mina ٱl̊ḥik̊maẗi waٱl̊maʿ̊rifaẗi»."],[1,17,"وَوَجَّهْتُ قَلْبِي لِمَعْرِفَةِ ٱلْحِكْمَةِ وَلِمَعْرِفَةِ ٱلْحَمَاقَةِ وَٱلْجَهْلِ، فَعَرَفْتُ أَنَّ هَذَا أَيْضًا قَبْضُ ٱلرِّيحِ.","wawajãh̊tu qal̊bī limaʿ̊rifaẗi ٱl̊ḥik̊maẗi walimaʿ̊rifaẗi ٱl̊ḥamāqaẗi waٱl̊jah̊li, faʿaraf̊tu ạảnã hadẖā ạảẙḍaⁿạ qab̊ḍu ٱlrĩyḥi."],[1,18,"لِأَنَّ فِي كَثْرَةِ ٱلْحِكْمَةِ كَثْرَةُ ٱلْغَمِّ، وَٱلَّذِي يَزِيدُ عِلْمًا يَزِيدُ حُزْنًا.","liạảnã fī katẖ̊raẗi ٱl̊ḥik̊maẗi katẖ̊raẗu ٱl̊gẖamĩ, waٱlãdẖī yazīdu ʿil̊maⁿạ yazīdu ḥuz̊naⁿạ."],[2,1,"قُلْتُ أَنَا فِي قَلْبِي: «هَلُمَّ أَمْتَحِنُكَ بِٱلْفَرَحِ فَتَرَى خَيْرًا». وَإِذَا هَذَا أَيْضًا بَاطِلٌ.","qul̊tu ạảnā fī qal̊bī: «halumã ạảm̊taḥinuka biٱl̊faraḥi fataray̱ kẖaẙraⁿạ». wāi̹dẖā hadẖā ạảẙḍaⁿạ bāṭiluⁿ."],[2,2,"لِلضَّحْكِ قُلْتُ: «مَجْنُونٌ» وَلِلْفَرَحِ: «مَاذَا يَفْعَلُ؟».","lilḍãḥ̊ki qul̊tu: «maj̊nūnuⁿ» walil̊faraḥi: «mādẖā yaf̊ʿalu?»."],[2,3,"اِفْتَكَرْتُ فِي قَلْبِي أَنْ أُعَلِّلَ جَسَدِي بِٱلْخَمْرِ، وَقَلْبِي يَلْهَجُ بِٱلْحِكْمَةِ، وَأَنْ آخُذَ بِٱلْحَمَاقَةِ، حَتَّى أَرَى مَا هُوَ ٱلْخَيْرُ لِبَنِي ٱلْبَشَرِ حَتَّى يَفْعَلُوهُ تَحْتَ ٱلسَّمَاوَاتِ مُدَّةَ أَيَّامِ حَيَاتِهِمْ.","ạif̊takar̊tu fī qal̊bī ạản̊ ạủʿalĩla jasadī biٱl̊kẖam̊ri, waqal̊bī yal̊haju biٱl̊ḥik̊maẗi, wāản̊ ậkẖudẖa biٱl̊ḥamāqaẗi, ḥatãy̱ ạảray̱ mā hūa ٱl̊kẖaẙru libanī ٱl̊basẖari ḥatãy̱ yaf̊ʿalūhu taḥ̊ta ٱlsãmāwāti mudãẗa ạảyãạmi ḥayātihim̊."],[2,4,"فَعَظَّمْتُ عَمَلِي: بَنَيْتُ لِنَفْسِي بُيُوتًا، غَرَسْتُ لِنَفْسِي كُرُومًا.","faʿaẓãm̊tu ʿamalī: banaẙtu linaf̊sī buyūtaⁿạ, gẖaras̊tu linaf̊sī kurūmaⁿạ."],[2,5,"عَمِلْتُ لِنَفْسِي جَنَّاتٍ وَفَرَادِيسَ، وَغَرَسْتُ فِيهَا أَشْجَارًا مِنْ كُلِّ نَوْعِ ثَمَرٍ.","ʿamil̊tu linaf̊sī janãạtiⁿ wafarādīsa, wagẖaras̊tu fīhā ạảsẖ̊jāraⁿạ min̊ kulĩ naẘʿi tẖamariⁿ."],[2,6,"عَمِلْتُ لِنَفْسِي بِرَكَ مِيَاهٍ لِتُسْقَى بِهَا ٱلْمَغَارِسُ ٱلْمُنْبِتَةُ ٱلشَّجَرَ.","ʿamil̊tu linaf̊sī biraka mīāhiⁿ litus̊qay̱ bihā ٱl̊magẖārisu ٱl̊mun̊bitaẗu ٱlsẖãjara."],[2,7,"قَنَيْتُ عَبِيدًا وَجَوَارِيَ، وَكَانَ لِي وُلْدَانُ ٱلْبَيْتِ. وَكَانَتْ لِي أَيْضًا قِنْيَةُ بَقَرٍ وَغَنَمٍ أَكْثَرَ مِنْ جَمِيعِ ٱلَّذِينَ كَانُوا فِي أُورُشَلِيمَ قَبْلِي.","qanaẙtu ʿabīdaⁿạ wajawārīa, wakāna lī wul̊dānu ٱl̊baẙti. wakānat̊ lī ạảẙḍaⁿạ qin̊yaẗu baqariⁿ wagẖanamiⁿ ạảk̊tẖara min̊ jamīʿi ٱlãdẖīna kānūạ fī ạủwrusẖalīma qab̊lī."],[2,8,"جَمَعْتُ لِنَفْسِي أَيْضًا فِضَّةً وَذَهَبًا وَخُصُوصِيَّاتِ ٱلْمُلُوكِ وَٱلْبُلْدَانِ. ٱتَّخَذْتُ لِنَفْسِي مُغَنِّينَ وَمُغَنِّيَاتٍ وَتَنَعُّمَاتِ بَنِي ٱلْبَشَرِ، سَيِّدَةً وَسَيِّدَاتٍ.","jamaʿ̊tu linaf̊sī ạảẙḍaⁿạ fiḍãẗaⁿ wadẖahabaⁿạ wakẖuṣūṣīãạti ٱl̊mulūki waٱl̊bul̊dāni. ٱtãkẖadẖ̊tu linaf̊sī mugẖanĩyna wamugẖanĩyātiⁿ watanaʿũmāti banī ٱl̊basẖari, sayĩdaẗaⁿ wasayĩdātiⁿ."],[2,9,"فَعَظُمْتُ وَٱزْدَدْتُ أَكْثَرَ مِنْ جَمِيعِ ٱلَّذِينَ كَانُوا قَبْلِي فِي أُورُشَلِيمَ، وَبَقِيَتْ أَيْضًا حِكْمَتِي مَعِي.","faʿaẓum̊tu waٱz̊dad̊tu ạảk̊tẖara min̊ jamīʿi ٱlãdẖīna kānūạ qab̊lī fī ạủwrusẖalīma, wabaqīat̊ ạảẙḍaⁿạ ḥik̊matī maʿī."],[2,10,"وَمَهْمَا ٱشْتَهَتْهُ عَيْنَايَ لَمْ أُمْسِكْهُ عَنْهُمَا. لَمْ أَمْنَعْ قَلْبِي مِنْ كُلِّ فَرَحٍ، لِأَنَّ قَلْبِي فَرِحَ بِكُلِّ تَعَبِي. وَهَذَا كَانَ نَصِيبِي مِنْ كُلِّ تَعَبِي.","wamah̊mā ٱsẖ̊tahat̊hu ʿaẙnāya lam̊ ạủm̊sik̊hu ʿan̊humā. lam̊ ạảm̊naʿ̊ qal̊bī min̊ kulĩ faraḥiⁿ, liạảnã qal̊bī fariḥa bikulĩ taʿabī. wahadẖā kāna naṣībī min̊ kulĩ taʿabī."],[2,11,"ثُمَّ ٱلْتَفَتُّ أَنَا إِلَى كُلِّ أَعْمَالِي ٱلَّتِي عَمِلَتْهَا يَدَايَ، وَإِلَى ٱلتَّعَبِ ٱلَّذِي تَعِبْتُهُ فِي عَمَلِهِ، فَإِذَا ٱلْكُلُّ بَاطِلٌ وَقَبْضُ ٱلرِّيحِ، وَلَا مَنْفَعَةَ تَحْتَ ٱلشَّمْسِ.","tẖumã ٱl̊tafatũ ạảnā ại̹lay̱ kulĩ ạảʿ̊mālī ٱlãtī ʿamilat̊hā yadāya, wāi̹lay̱ ٱltãʿabi ٱlãdẖī taʿib̊tuhu fī ʿamalihi, fāi̹dẖā ٱl̊kulũ bāṭiluⁿ waqab̊ḍu ٱlrĩyḥi, walā man̊faʿaẗa taḥ̊ta ٱlsẖãm̊si."],[2,12,"ثُمَّ ٱلْتَفَتُّ لِأَنْظُرَ ٱلْحِكْمَةَ وَٱلْحَمَاقَةَ وَٱلْجَهْلَ. فَمَا ٱلْإِنْسَانُ ٱلَّذِي يَأْتِي وَرَاءَ ٱلْمَلِكِ ٱلَّذِي قَدْ نَصَبُوهُ مُنْذُ زَمَانٍ؟","tẖumã ٱl̊tafatũ liạản̊ẓura ٱl̊ḥik̊maẗa waٱl̊ḥamāqaẗa waٱl̊jah̊la. famā ٱl̊ại̹n̊sānu ٱlãdẖī yā̊̉tī warāʾa ٱl̊maliki ٱlãdẖī qad̊ naṣabūhu mun̊dẖu zamāniⁿ?"],[2,13,"فَرَأَيْتُ أَنَّ لِلْحِكْمَةِ مَنْفَعَةً أَكْثَرَ مِنَ ٱلْجَهْلِ، كَمَا أَنَّ لِلنُّورِ مَنْفَعَةً أَكْثَرَ مِنَ ٱلظُّلْمَةِ.","farāảẙtu ạảnã lil̊ḥik̊maẗi man̊faʿaẗaⁿ ạảk̊tẖara mina ٱl̊jah̊li, kamā ạảnã lilnũwri man̊faʿaẗaⁿ ạảk̊tẖara mina ٱlẓũl̊maẗi."],[2,14,"اَلْحَكِيمُ عَيْنَاهُ فِي رَأْسِهِ، أَمَّا ٱلْجَاهِلُ فَيَسْلُكُ فِي ٱلظَّلَامِ. وَعَرَفْتُ أَنَا أَيْضًا أَنَّ حَادِثَةً وَاحِدَةً تَحْدُثُ لِكِلَيْهِمَا.","ạal̊ḥakīmu ʿaẙnāhu fī rā̊̉sihi, ạảmãạ ٱl̊jāhilu fayas̊luku fī ٱlẓãlāmi. waʿaraf̊tu ạảnā ạảẙḍaⁿạ ạảnã ḥāditẖaẗaⁿ wāḥidaẗaⁿ taḥ̊dutẖu likilaẙhimā."],[2,15,"فَقُلْتُ فِي قَلْبِي: «كَمَا يَحْدُثُ لِلْجَاهِلِ كَذَلِكَ يَحْدُثُ أَيْضًا لِي أَنَا. وَإِذْ ذَاكَ، فَلِمَاذَا أَنَا أَوْفَرُ حِكْمَةً؟» فَقُلْتُ فِي قَلْبِي: «هَذَا أَيْضًا بَاطِلٌ».","faqul̊tu fī qal̊bī: «kamā yaḥ̊dutẖu lil̊jāhili kadẖalika yaḥ̊dutẖu ạảẙḍaⁿạ lī ạảnā. wāi̹dẖ̊ dẖāka, falimādẖā ạảnā ạảẘfaru ḥik̊maẗaⁿ?» faqul̊tu fī qal̊bī: «hadẖā ạảẙḍaⁿạ bāṭiluⁿ»."],[2,16,"لِأَنَّهُ لَيْسَ ذِكْرٌ لِلْحَكِيمِ وَلَا لِلْجَاهِلِ إِلَى ٱلْأَبَدِ. كَمَا مُنْذُ زَمَانٍ كَذَا ٱلْأَيَّامُ ٱلْآتِيَةُ: ٱلْكُلُّ يُنْسَى. وَكَيْفَ يَمُوتُ ٱلْحَكِيمُ كَٱلْجَاهِلِ!","liạảnãhu laẙsa dẖik̊ruⁿ lil̊ḥakīmi walā lil̊jāhili ại̹lay̱ ٱl̊ạảbadi. kamā mun̊dẖu zamāniⁿ kadẖā ٱl̊ạảyãạmu ٱl̊ậtīaẗu: ٱl̊kulũ yun̊say̱. wakaẙfa yamūtu ٱl̊ḥakīmu kaٱl̊jāhili!"],[2,17,"فَكَرِهْتُ ٱلْحَيَاةَ، لِأَنَّهُ رَدِيءٌ عِنْدِي، ٱلْعَمَلُ ٱلَّذِي عُمِلَ تَحْتَ ٱلشَّمْسِ، لِأَنَّ ٱلْكُلَّ بَاطِلٌ وَقَبْضُ ٱلرِّيحِ.","fakarih̊tu ٱl̊ḥayāẗa, liạảnãhu radīʾuⁿ ʿin̊dī, ٱl̊ʿamalu ٱlãdẖī ʿumila taḥ̊ta ٱlsẖãm̊si, liạảnã ٱl̊kulã bāṭiluⁿ waqab̊ḍu ٱlrĩyḥi."],[2,18,"فَكَرِهْتُ كُلَّ تَعَبِي ٱلَّذِي تَعِبْتُ فِيهِ تَحْتَ ٱلشَّمْسِ حَيْثُ أَتْرُكُهُ لِلْإِنْسَانِ ٱلَّذِي يَكُونُ بَعْدِي.","fakarih̊tu kulã taʿabī ٱlãdẖī taʿib̊tu fīhi taḥ̊ta ٱlsẖãm̊si ḥaẙtẖu ạảt̊rukuhu lil̊ại̹n̊sāni ٱlãdẖī yakūnu baʿ̊dī."],[2,19,"وَمَنْ يَعْلَمُ، هَلْ يَكُونُ حَكِيمًا أَوْ جَاهِلًا، وَيَسْتَوْلِي عَلَى كُلِّ تَعَبِي ٱلَّذِي تَعِبْتُ فِيهِ وَأَظْهَرْتُ فِيهِ حِكْمَتِي تَحْتَ ٱلشَّمْسِ؟ هَذَا أَيْضًا بَاطِلٌ.","waman̊ yaʿ̊lamu, hal̊ yakūnu ḥakīmaⁿạ ạảẘ jāhilaⁿạ, wayas̊taẘlī ʿalay̱ kulĩ taʿabī ٱlãdẖī taʿib̊tu fīhi wāảẓ̊har̊tu fīhi ḥik̊matī taḥ̊ta ٱlsẖãm̊si? hadẖā ạảẙḍaⁿạ bāṭiluⁿ."],[2,20,"فَتَحَوَّلْتُ لِكَيْ أَجْعَلَ قَلْبِي يَيْئَسُ مِنْ كُلِّ ٱلتَّعَبِ ٱلَّذِي تَعِبْتُ فِيهِ تَحْتَ ٱلشَّمْسِ.","fataḥawãl̊tu likaẙ ạảj̊ʿala qal̊bī yaẙyảsu min̊ kulĩ ٱltãʿabi ٱlãdẖī taʿib̊tu fīhi taḥ̊ta ٱlsẖãm̊si."],[2,21,"لِأَنَّهُ قَدْ يَكُونُ إِنْسَانٌ تَعَبُهُ بِٱلْحِكْمَةِ وَٱلْمَعْرِفَةِ وَبِٱلْفَلَاحِ، فَيَتْرُكُهُ نَصِيبًا لِإِنْسَانٍ لَمْ يَتْعَبْ فِيهِ. هَذَا أَيْضًا بَاطِلٌ وَشَرٌّ عَظِيمٌ.","liạảnãhu qad̊ yakūnu ại̹n̊sānuⁿ taʿabuhu biٱl̊ḥik̊maẗi waٱl̊maʿ̊rifaẗi wabiٱl̊falāḥi, fayat̊rukuhu naṣībaⁿạ liại̹n̊sāniⁿ lam̊ yat̊ʿab̊ fīhi. hadẖā ạảẙḍaⁿạ bāṭiluⁿ wasẖaruⁿ̃ ʿaẓīmuⁿ."],[2,22,"لِأَنَّهُ مَاذَا لِلْإِنْسَانِ مِنْ كُلِّ تَعَبِهِ، وَمِنِ ٱجْتِهَادِ قَلْبِهِ ٱلَّذِي تَعِبَ فِيهِ تَحْتَ ٱلشَّمْسِ؟","liạảnãhu mādẖā lil̊ại̹n̊sāni min̊ kulĩ taʿabihi, wamini ٱj̊tihādi qal̊bihi ٱlãdẖī taʿiba fīhi taḥ̊ta ٱlsẖãm̊si?"],[2,23,"لِأَنَّ كُلَّ أَيَّامِهِ أَحْزَانٌ، وَعَمَلَهُ غَمٌّ. أَيْضًا بِٱللَّيْلِ لَا يَسْتَرِيحُ قَلْبُهُ. هَذَا أَيْضًا بَاطِلٌ هُوَ.","liạảnã kulã ạảyãạmihi ạảḥ̊zānuⁿ, waʿamalahu gẖamuⁿ̃. ạảẙḍaⁿạ biٱllãẙli lā yas̊tarīḥu qal̊buhu. hadẖā ạảẙḍaⁿạ bāṭiluⁿ hūa."],[2,24,"لَيْسَ لِلْإِنْسَانِ خَيْرٌ مِنْ أَنْ يَأْكُلَ وَيَشْرَبَ وَيُرِيَ نَفْسَهُ خَيْرًا فِي تَعَبِهِ. رَأَيْتُ هَذَا أَيْضًا أَنَّهُ مِنْ يَدِ ٱللهِ.","laẙsa lil̊ại̹n̊sāni kẖaẙruⁿ min̊ ạản̊ yā̊̉kula wayasẖ̊raba wayurīa naf̊sahu kẖaẙraⁿạ fī taʿabihi. rāảẙtu hadẖā ạảẙḍaⁿạ ạảnãhu min̊ yadi ٱllhi."],[2,25,"لِأَنَّهُ مَنْ يَأْكُلُ وَمَنْ يَلْتَذُّ غَيْرِي؟","liạảnãhu man̊ yā̊̉kulu waman̊ yal̊tadẖũ gẖaẙrī?"],[2,26,"لِأَنَّهُ يُؤْتِي ٱلْإِنْسَانَ ٱلصَّالِحَ قُدَّامَهُ حِكْمَةً وَمَعْرِفَةً وَفَرَحًا، أَمَّا ٱلْخَاطِئُ فَيُعْطِيهِ شُغْلَ ٱلْجَمْعِ وَٱلتَّكْوِيمِ، لِيُعْطِيَ لِلصَّالِحِ قُدَّامَ ٱللهِ. هَذَا أَيْضًا بَاطِلٌ وَقَبْضُ ٱلرِّيحِ.","liạảnãhu yū̊̉tī ٱl̊ại̹n̊sāna ٱlṣãạliḥa qudãạmahu ḥik̊maẗaⁿ wamaʿ̊rifaẗaⁿ wafaraḥaⁿạ, ạảmãạ ٱl̊kẖāṭīủ fayuʿ̊ṭīhi sẖugẖ̊la ٱl̊jam̊ʿi waٱltãk̊wīmi, līuʿ̊ṭīa lilṣãạliḥi qudãạma ٱllhi. hadẖā ạảẙḍaⁿạ bāṭiluⁿ waqab̊ḍu ٱlrĩyḥi."],[3,1,"لِكُلِّ شَيْءٍ زَمَانٌ، وَلِكُلِّ أَمْرٍ تَحْتَ ٱلسَّمَاوَاتِ وَقْتٌ:","likulĩ sẖaẙʾiⁿ zamānuⁿ, walikulĩ ạảm̊riⁿ taḥ̊ta ٱlsãmāwāti waq̊tuⁿ:"],[3,2,"لِلْوِلَادَةِ وَقْتٌ وَلِلْمَوْتِ وَقْتٌ. لِلْغَرْسِ وَقْتٌ وَلِقَلْعِ ٱلْمَغْرُوسِ وَقْتٌ.","lil̊wilādaẗi waq̊tuⁿ walil̊maẘti waq̊tuⁿ. lil̊gẖar̊si waq̊tuⁿ waliqal̊ʿi ٱl̊magẖ̊rūsi waq̊tuⁿ."],[3,3,"لِلْقَتْلِ وَقْتٌ وَلِلشِّفَاءِ وَقْتٌ. لِلْهَدْمِ وَقْتٌ وَلِلْبِنَاءِ وَقْتٌ.","lil̊qat̊li waq̊tuⁿ walilsẖĩfāʾi waq̊tuⁿ. lil̊had̊mi waq̊tuⁿ walil̊bināʾi waq̊tuⁿ."],[3,4,"لِلْبُكَاءِ وَقْتٌ وَلِلضَّحْكِ وَقْتٌ. لِلنَّوْحِ وَقْتٌ وَلِلرَّقْصِ وَقْتٌ.","lil̊bukāʾi waq̊tuⁿ walilḍãḥ̊ki waq̊tuⁿ. lilnãẘḥi waq̊tuⁿ walilrãq̊ṣi waq̊tuⁿ."],[3,5,"لِتَفْرِيقِ ٱلْحِجَارَةِ وَقْتٌ وَلِجَمْعِ ٱلْحِجَارَةِ وَقْتٌ. لِلْمُعَانَقَةِ وَقْتٌ وَلِلِٱنْفِصَالِ عَنِ ٱلْمُعَانَقَةِ وَقْتٌ.","litaf̊rīqi ٱl̊ḥijāraẗi waq̊tuⁿ walijam̊ʿi ٱl̊ḥijāraẗi waq̊tuⁿ. lil̊muʿānaqaẗi waq̊tuⁿ waliliٱn̊fiṣāli ʿani ٱl̊muʿānaqaẗi waq̊tuⁿ."],[3,6,"لِلْكَسْبِ وَقْتٌ وَلِلْخَسَارَةِ وَقْتٌ. لِلصِّيَانَةِ وَقْتٌ وَلِلطَّرْحِ وَقْتٌ.","lil̊kas̊bi waq̊tuⁿ walil̊kẖasāraẗi waq̊tuⁿ. lilṣĩyānaẗi waq̊tuⁿ walilṭãr̊ḥi waq̊tuⁿ."],[3,7,"لِلتَّمْزِيقِ وَقْتٌ وَلِلتَّخْيِيطِ وَقْتٌ. لِلسُّكُوتِ وَقْتٌ وَلِلتَّكَلُّمِ وَقْتٌ.","liltãm̊zīqi waq̊tuⁿ waliltãkẖ̊yīṭi waq̊tuⁿ. lilsũkūti waq̊tuⁿ waliltãkalũmi waq̊tuⁿ."],[3,8,"لِلْحُبِّ وَقْتٌ وَلِلْبُغْضَةِ وَقْتٌ. لِلْحَرْبِ وَقْتٌ وَلِلصُّلْحِ وَقْتٌ.","lil̊ḥubĩ waq̊tuⁿ walil̊bugẖ̊ḍaẗi waq̊tuⁿ. lil̊ḥar̊bi waq̊tuⁿ walilṣũl̊ḥi waq̊tuⁿ."],[3,9,"فَأَيُّ مَنْفَعَةٍ لِمَنْ يَتْعَبُ مِمَّا يَتْعَبُ بِهِ؟","fāảyũ man̊faʿaẗiⁿ liman̊ yat̊ʿabu mimãạ yat̊ʿabu bihi?"],[3,10,"قَدْ رَأَيْتُ ٱلشُّغْلَ ٱلَّذِي أَعْطَاهُ ٱللهُ بَنِي ٱلْبَشَرِ لِيَشْتَغِلُوا بِهِ.","qad̊ rāảẙtu ٱlsẖũgẖ̊la ٱlãdẖī ạảʿ̊ṭāhu ٱllhu banī ٱl̊basẖari līasẖ̊tagẖilūạ bihi."],[3,11,"صَنَعَ ٱلْكُلَّ حَسَنًا فِي وَقْتِهِ، وَأَيْضًا جَعَلَ ٱلْأَبَدِيَّةَ فِي قَلْبِهِمِ، ٱلَّتِي بِلَاهَا لَا يُدْرِكُ ٱلْإِنْسَانُ ٱلْعَمَلَ ٱلَّذِي يَعْمَلُهُ ٱللهُ مِنَ ٱلْبِدَايَةِ إِلَى ٱلنِّهَايَةِ.","ṣanaʿa ٱl̊kulã ḥasanaⁿạ fī waq̊tihi, wāảẙḍaⁿạ jaʿala ٱl̊ạảbadīãẗa fī qal̊bihimi, ٱlãtī bilāhā lā yud̊riku ٱl̊ại̹n̊sānu ٱl̊ʿamala ٱlãdẖī yaʿ̊maluhu ٱllhu mina ٱl̊bidāyaẗi ại̹lay̱ ٱlnĩhāyaẗi."],[3,12,"عَرَفْتُ أَنَّهُ لَيْسَ لَهُمْ خَيْرٌ، إِلَّا أَنْ يَفْرَحُوا وَيَفْعَلُوا خَيْرًا فِي حَيَاتِهِمْ.","ʿaraf̊tu ạảnãhu laẙsa lahum̊ kẖaẙruⁿ, ại̹lãạ ạản̊ yaf̊raḥūạ wayaf̊ʿalūạ kẖaẙraⁿạ fī ḥayātihim̊."],[3,13,"وَأَيْضًا أَنْ يَأْكُلَ كُلُّ إِنْسَانٍ وَيَشْرَبَ وَيَرَى خَيْرًا مِنْ كُلِّ تَعَبِهِ، فَهُوَ عَطِيَّةُ ٱللهِ.","wāảẙḍaⁿạ ạản̊ yā̊̉kula kulũ ại̹n̊sāniⁿ wayasẖ̊raba wayaray̱ kẖaẙraⁿạ min̊ kulĩ taʿabihi, fahūa ʿaṭīãẗu ٱllhi."],[3,14,"قَدْ عَرَفْتُ أَنَّ كُلَّ مَا يَعْمَلُهُ ٱللهُ أَنَّهُ يَكُونُ إِلَى ٱلْأَبَدِ. لَا شَيْءَ يُزَادُ عَلَيْهِ، وَلَا شَيْءَ يُنْقَصُ مِنْهُ، وَأَنَّ ٱللهَ عَمِلَهُ حَتَّى يَخَافُوا أَمَامَهُ.","qad̊ ʿaraf̊tu ạảnã kulã mā yaʿ̊maluhu ٱllhu ạảnãhu yakūnu ại̹lay̱ ٱl̊ạảbadi. lā sẖaẙʾa yuzādu ʿalaẙhi, walā sẖaẙʾa yun̊qaṣu min̊hu, wāảnã ٱllha ʿamilahu ḥatãy̱ yakẖāfūạ ạảmāmahu."],[3,15,"مَا كَانَ فَمِنَ ٱلْقِدَمِ هُوَ، وَمَا يَكُونُ فَمِنَ ٱلْقِدَمِ قَدْ كَانَ. وَٱللهُ يَطْلُبُ مَا قَدْ مَضَى.","mā kāna famina ٱl̊qidami hūa, wamā yakūnu famina ٱl̊qidami qad̊ kāna. waٱllhu yaṭ̊lubu mā qad̊ maḍay̱."],[3,16,"وَأَيْضًا رَأَيْتُ تَحْتَ ٱلشَّمْسِ: مَوْضِعَ ٱلْحَقِّ هُنَاكَ ٱلظُّلْمُ، وَمَوْضِعَ ٱلْعَدْلِ هُنَاكَ ٱلْجَوْرُ!","wāảẙḍaⁿạ rāảẙtu taḥ̊ta ٱlsẖãm̊si: maẘḍiʿa ٱl̊ḥaqĩ hunāka ٱlẓũl̊mu, wamaẘḍiʿa ٱl̊ʿad̊li hunāka ٱl̊jaẘru!"],[3,17,"فَقُلْتُ فِي قَلْبِي: «ٱللهُ يَدِينُ ٱلصِّدِّيقَ وَٱلشِّرِّيرَ، لِأَنَّ لِكُلِّ أَمْرٍ وَلِكُلِّ عَمَلٍ وَقْتًا هُنَاكَ».","faqul̊tu fī qal̊bī: «ٱllhu yadīnu ٱlṣĩdĩyqa waٱlsẖĩrĩyra, liạảnã likulĩ ạảm̊riⁿ walikulĩ ʿamaliⁿ waq̊taⁿạ hunāka»."],[3,18,"قُلْتُ فِي قَلْبِي: «مِنْ جِهَةِ أُمُورِ بَنِي ٱلْبَشَرِ، إِنَّ ٱللهَ يَمْتَحِنُهُمْ لِيُرِيَهُمْ أَنَّهُ كَمَا ٱلْبَهِيمَةِ هَكَذَا هُمْ».","qul̊tu fī qal̊bī: «min̊ jihaẗi ạủmūri banī ٱl̊basẖari, ại̹nã ٱllha yam̊taḥinuhum̊ līurīahum̊ ạảnãhu kamā ٱl̊bahīmaẗi hakadẖā hum̊»."],[3,19,"لِأَنَّ مَا يَحْدُثُ لِبَنِي ٱلْبَشَرِ يَحْدُثُ لِلْبَهِيمَةِ، وَحَادِثَةٌ وَاحِدَةٌ لَهُمْ. مَوْتُ هَذَا كَمَوْتِ ذَاكَ، وَنَسَمَةٌ وَاحِدَةٌ لِلْكُلِّ. فَلَيْسَ لِلْإِنْسَانِ مَزِيَّةٌ عَلَى ٱلْبَهِيمَةِ، لِأَنَّ كِلَيْهِمَا بَاطِلٌ.","liạảnã mā yaḥ̊dutẖu libanī ٱl̊basẖari yaḥ̊dutẖu lil̊bahīmaẗi, waḥāditẖaẗuⁿ wāḥidaẗuⁿ lahum̊. maẘtu hadẖā kamaẘti dẖāka, wanasamaẗuⁿ wāḥidaẗuⁿ lil̊kulĩ. falaẙsa lil̊ại̹n̊sāni mazīãẗuⁿ ʿalay̱ ٱl̊bahīmaẗi, liạảnã kilaẙhimā bāṭiluⁿ."],[3,20,"يَذْهَبُ كِلَاهُمَا إِلَى مَكَانٍ وَاحِدٍ. كَانَ كِلَاهُمَا مِنَ ٱلتُّرَابِ، وَإِلَى ٱلتُّرَابِ يَعُودُ كِلَاهُمَا.","yadẖ̊habu kilāhumā ại̹lay̱ makāniⁿ wāḥidiⁿ. kāna kilāhumā mina ٱltũrābi, wāi̹lay̱ ٱltũrābi yaʿūdu kilāhumā."],[3,21,"مَنْ يَعْلَمُ رُوحَ بَنِي ٱلْبَشَرِ هَلْ هِيَ تَصْعَدُ إِلَى فَوْقٍ؟ وَرُوحَ ٱلْبَهِيمَةِ هَلْ هِيَ تَنْزِلُ إِلَى أَسْفَلَ، إِلَى ٱلْأَرْضِ؟","man̊ yaʿ̊lamu rūḥa banī ٱl̊basẖari hal̊ hīa taṣ̊ʿadu ại̹lay̱ faẘqiⁿ? warūḥa ٱl̊bahīmaẗi hal̊ hīa tan̊zilu ại̹lay̱ ạảs̊fala, ại̹lay̱ ٱl̊ạảr̊ḍi?"],[3,22,"فَرَأَيْتُ أَنَّهُ لَا شَيْءَ خَيْرٌ مِنْ أَنْ يَفْرَحَ ٱلْإِنْسَانُ بِأَعْمَالِهِ، لِأَنَّ ذَلِكَ نَصِيبَهُ. لِأَنَّهُ مَنْ يَأْتِي بِهِ لِيَرَى مَا سَيَكُونُ بَعْدَهُ؟","farāảẙtu ạảnãhu lā sẖaẙʾa kẖaẙruⁿ min̊ ạản̊ yaf̊raḥa ٱl̊ại̹n̊sānu biạảʿ̊mālihi, liạảnã dẖalika naṣībahu. liạảnãhu man̊ yā̊̉tī bihi līaray̱ mā sayakūnu baʿ̊dahu?"],[4,1,"ثُمَّ رَجَعْتُ وَرَأَيْتُ كُلَّ ٱلْمَظَالِمِ ٱلَّتِي تُجْرَى تَحْتَ ٱلشَّمْسِ: فَهُوَذَا دُمُوعُ ٱلْمَظْلُومِينَ وَلَا مُعَزٍّ لَهُمْ، وَمِنْ يَدِ ظَالِمِيهِمْ قَهْرٌ، أَمَّا هُمْ فَلَا مُعَزٍّ لَهُمْ.","tẖumã rajaʿ̊tu warāảẙtu kulã ٱl̊maẓālimi ٱlãtī tuj̊ray̱ taḥ̊ta ٱlsẖãm̊si: fahūadẖā dumūʿu ٱl̊maẓ̊lūmīna walā muʿaziⁿ̃ lahum̊, wamin̊ yadi ẓālimīhim̊ qah̊ruⁿ, ạảmãạ hum̊ falā muʿaziⁿ̃ lahum̊."],[4,2,"فَغَبَطْتُ أَنَا ٱلْأَمْوَاتَ ٱلَّذِينَ قَدْ مَاتُوا مُنْذُ زَمَانٍ أَكْثَرَ مِنَ ٱلْأَحْيَاءِ ٱلَّذِينَ هُمْ عَائِشُونَ بَعْدُ.","fagẖabaṭ̊tu ạảnā ٱl̊ạảm̊wāta ٱlãdẖīna qad̊ mātūạ mun̊dẖu zamāniⁿ ạảk̊tẖara mina ٱl̊ạảḥ̊yāʾi ٱlãdẖīna hum̊ ʿāyỉsẖūna baʿ̊du."],[4,3,"وَخَيْرٌ مِنْ كِلَيْهِمَا ٱلَّذِي لَمْ يُولَدْ بَعْدُ، ٱلَّذِي لَمْ يَرَ ٱلْعَمَلَ ٱلرَّدِيءَ ٱلَّذِي عُمِلَ تَحْتَ ٱلشَّمْسِ.","wakẖaẙruⁿ min̊ kilaẙhimā ٱlãdẖī lam̊ yūlad̊ baʿ̊du, ٱlãdẖī lam̊ yara ٱl̊ʿamala ٱlrãdīʾa ٱlãdẖī ʿumila taḥ̊ta ٱlsẖãm̊si."],[4,4,"وَرَأَيْتُ كُلَّ ٱلتَّعَبِ وَكُلَّ فَلَاحِ عَمَلٍ أَنَّهُ حَسَدُ ٱلْإِنْسَانِ مِنْ قَرِيبِهِ. وَهَذَا أَيْضًا بَاطِلٌ وَقَبْضُ ٱلرِّيحِ.","warāảẙtu kulã ٱltãʿabi wakulã falāḥi ʿamaliⁿ ạảnãhu ḥasadu ٱl̊ại̹n̊sāni min̊ qarībihi. wahadẖā ạảẙḍaⁿạ bāṭiluⁿ waqab̊ḍu ٱlrĩyḥi."],[4,5,"اَلْكَسْلَانُ يَأْكُلُ لَحْمَهُ وَهُوَ طَاوٍ يَدَيْهِ.","ạal̊kas̊lānu yā̊̉kulu laḥ̊mahu wahūa ṭāwiⁿ yadaẙhi."],[4,6,"حُفْنَةُ رَاحَةٍ خَيْرٌ مِنْ حُفْنَتَيْ تَعَبٍ وَقَبْضِ ٱلرِّيحِ.","ḥuf̊naẗu rāḥaẗiⁿ kẖaẙruⁿ min̊ ḥuf̊nataẙ taʿabiⁿ waqab̊ḍi ٱlrĩyḥi."],[4,7,"ثُمَّ عُدْتُ وَرَأَيْتُ بَاطِلًا تَحْتَ ٱلشَّمْسِ:","tẖumã ʿud̊tu warāảẙtu bāṭilaⁿạ taḥ̊ta ٱlsẖãm̊si:"],[4,8,"يُوجَدُ وَاحِدٌ وَلَا ثَانِيَ لَهُ، وَلَيْسَ لَهُ ٱبْنٌ وَلَا أَخٌ، وَلَا نِهَايَةَ لِكُلِّ تَعَبِهِ، وَلَا تَشْبَعُ عَيْنُهُ مِنَ ٱلْغِنَى. فَلِمَنْ أَتْعَبُ أَنَا وَأُحَرِّمُ نَفْسِي ٱلْخَيْرَ؟ هَذَا أَيْضًا بَاطِلٌ وَأَمْرٌ رَدِيءٌ هُوَ.","yūjadu wāḥiduⁿ walā tẖānīa lahu, walaẙsa lahu ٱb̊nuⁿ walā ạảkẖuⁿ, walā nihāyaẗa likulĩ taʿabihi, walā tasẖ̊baʿu ʿaẙnuhu mina ٱl̊gẖinay̱. faliman̊ ạảt̊ʿabu ạảnā wāủḥarĩmu naf̊sī ٱl̊kẖaẙra? hadẖā ạảẙḍaⁿạ bāṭiluⁿ wāảm̊ruⁿ radīʾuⁿ hūa."],[4,9,"اِثْنَانِ خَيْرٌ مِنْ وَاحِدٍ، لِأَنَّ لَهُمَا أُجْرَةً لِتَعَبِهِمَا صَالِحَةً.","ạitẖ̊nāni kẖaẙruⁿ min̊ wāḥidiⁿ, liạảnã lahumā ạủj̊raẗaⁿ litaʿabihimā ṣāliḥaẗaⁿ."],[4,10,"لِأَنَّهُ إِنْ وَقَعَ أَحَدُهُمَا يُقِيمُهُ رَفِيقُهُ. وَوَيْلٌ لِمَنْ هُوَ وَحْدَهُ إِنْ وَقَعَ، إِذْ لَيْسَ ثَانٍ لِيُقِيمَهُ.","liạảnãhu ại̹n̊ waqaʿa ạảḥaduhumā yuqīmuhu rafīquhu. wawaẙluⁿ liman̊ hūa waḥ̊dahu ại̹n̊ waqaʿa, ại̹dẖ̊ laẙsa tẖāniⁿ līuqīmahu."],[4,11,"أَيْضًا إِنِ ٱضْطَجَعَ ٱثْنَانِ يَكُونُ لَهُمَا دِفْءٌ، أَمَّا ٱلْوَحْدُ فَكَيْفَ يَدْفَأُ؟","ạảẙḍaⁿạ ại̹ni ٱḍ̊ṭajaʿa ٱtẖ̊nāni yakūnu lahumā dif̊ʾuⁿ, ạảmãạ ٱl̊waḥ̊du fakaẙfa yad̊fāủ?"],[4,12,"وَإِنْ غَلَبَ أَحَدٌ عَلَى ٱلْوَاحِدِ يَقِفُ مُقَابَلَهُ ٱلِٱثْنَانِ، وَٱلْخَيْطُ ٱلْمَثْلُوثُ لَا يَنْقَطِعُ سَرِيعًا.","wāi̹n̊ gẖalaba ạảḥaduⁿ ʿalay̱ ٱl̊wāḥidi yaqifu muqābalahu ٱliٱtẖ̊nāni, waٱl̊kẖaẙṭu ٱl̊matẖ̊lūtẖu lā yan̊qaṭiʿu sarīʿaⁿạ."],[4,13,"وَلَدٌ فَقِيرٌ وَحَكِيمٌ خَيْرٌ مِنْ مَلِكٍ شَيْخٍ جَاهِلٍ، ٱلَّذِي لَا يَعْرِفُ أَنْ يُحَذَّرَ بَعْدُ.","waladuⁿ faqīruⁿ waḥakīmuⁿ kẖaẙruⁿ min̊ malikiⁿ sẖaẙkẖiⁿ jāhiliⁿ, ٱlãdẖī lā yaʿ̊rifu ạản̊ yuḥadẖãra baʿ̊du."],[4,14,"لِأَنَّهُ مِنَ ٱلسِّجْنِ خَرَجَ إِلَى ٱلْمُلْكِ، وَٱلْمَوْلُودُ مَلِكًا قَدْ يَفْتَقِرُ.","liạảnãhu mina ٱlsĩj̊ni kẖaraja ại̹lay̱ ٱl̊mul̊ki, waٱl̊maẘlūdu malikaⁿạ qad̊ yaf̊taqiru."],[4,15,"رَأَيْتُ كُلَّ ٱلْأَحْيَاءِ ٱلسَّائِرِينَ تَحْتَ ٱلشَّمْسِ مَعَ ٱلْوَلَدِ ٱلثَّانِي ٱلَّذِي يَقُومُ عِوَضًا عَنْهُ.","rāảẙtu kulã ٱl̊ạảḥ̊yāʾi ٱlsãạyỉrīna taḥ̊ta ٱlsẖãm̊si maʿa ٱl̊waladi ٱltẖãạnī ٱlãdẖī yaqūmu ʿiwaḍaⁿạ ʿan̊hu."],[4,16,"لَا نِهَايَةَ لِكُلِّ ٱلشَّعْبِ، لِكُلِّ ٱلَّذِينَ كَانَ أَمَامَهُمْ. أَيْضًا ٱلْمُتَأَخِّرُونَ لَا يَفْرَحُونَ بِهِ. فَهَذَا أَيْضًا بَاطِلٌ وَقَبْضُ ٱلرِّيحِ.","lā nihāyaẗa likulĩ ٱlsẖãʿ̊bi, likulĩ ٱlãdẖīna kāna ạảmāmahum̊. ạảẙḍaⁿạ ٱl̊mutāảkẖĩrūna lā yaf̊raḥūna bihi. fahadẖā ạảẙḍaⁿạ bāṭiluⁿ waqab̊ḍu ٱlrĩyḥi."],[5,1,"اِحْفَظْ قَدَمَكَ حِينَ تَذْهَبُ إِلَى بَيْتِ ٱللهِ، فَٱلِٱسْتِمَاعُ أَقْرَبُ مِنْ تَقْدِيمِ ذَبِيحَةِ ٱلْجُهَّالِ، لِأَنَّهُمْ لَا يُبَالُونَ بِفَعْلِ ٱلشَّرِّ.","ạiḥ̊faẓ̊ qadamaka ḥīna tadẖ̊habu ại̹lay̱ baẙti ٱllhi, faٱliٱs̊timāʿu ạảq̊rabu min̊ taq̊dīmi dẖabīḥaẗi ٱl̊juhãạli, liạảnãhum̊ lā yubālūna bifaʿ̊li ٱlsẖãrĩ."],[5,2,"لَا تَسْتَعْجِلْ فَمَكَ وَلَا يُسْرِعْ قَلْبُكَ إِلَى نُطْقِ كَلَامٍ قُدَّامَ ٱللهِ، لِأَنَّ ٱللهَ فِي ٱلسَّمَاوَاتِ وَأَنْتَ عَلَى ٱلْأَرْضِ، فَلِذَلِكَ لِتَكُنْ كَلِمَاتُكَ قَلِيلَةً.","lā tas̊taʿ̊jil̊ famaka walā yus̊riʿ̊ qal̊buka ại̹lay̱ nuṭ̊qi kalāmiⁿ qudãạma ٱllhi, liạảnã ٱllha fī ٱlsãmāwāti wāản̊ta ʿalay̱ ٱl̊ạảr̊ḍi, falidẖalika litakun̊ kalimātuka qalīlaẗaⁿ."],[5,3,"لِأَنَّ ٱلْحُلْمَ يَأْتِي مِنْ كَثْرَةِ ٱلشُّغْلِ، وَقَوْلَ ٱلْجَهْلِ مِنْ كَثْرَةِ ٱلْكَلَامِ.","liạảnã ٱl̊ḥul̊ma yā̊̉tī min̊ katẖ̊raẗi ٱlsẖũgẖ̊li, waqaẘla ٱl̊jah̊li min̊ katẖ̊raẗi ٱl̊kalāmi."],[5,4,"إِذَا نَذَرْتَ نَذْرًا لِلهِ فَلَا تَتَأَخَّرْ عَنِ ٱلْوَفَاءِ بِهِ، لِأَنَّهُ لَا يُسَرُّ بِٱلْجُهَّالِ. فَأَوْفِ بِمَا نَذَرْتَهُ.","ại̹dẖā nadẖar̊ta nadẖ̊raⁿạ lilhi falā tatāảkẖãr̊ ʿani ٱl̊wafāʾi bihi, liạảnãhu lā yusarũ biٱl̊juhãạli. fāảẘfi bimā nadẖar̊tahu."],[5,5,"أَنْ لَا تَنْذُرُ خَيْرٌ مِنْ أَنْ تَنْذُرَ وَلَا تَفِيَ.","ạản̊ lā tan̊dẖuru kẖaẙruⁿ min̊ ạản̊ tan̊dẖura walā tafīa."],[5,6,"لَا تَدَعْ فَمَكَ يَجْعَلُ جَسَدَكَ يُخْطِئُ، وَلَا تَقُلْ قُدَّامَ ٱلْمَلَاكِ: «إِنَّهُ سَهْوٌ». لِمَاذَا يَغْضَبُ ٱللهُ عَلَى قَوْلِكَ، وَيُفْسِدُ عَمَلَ يَدَيْكَ؟","lā tadaʿ̊ famaka yaj̊ʿalu jasadaka yukẖ̊ṭīủ, walā taqul̊ qudãạma ٱl̊malāki: «ại̹nãhu sah̊wuⁿ». limādẖā yagẖ̊ḍabu ٱllhu ʿalay̱ qaẘlika, wayuf̊sidu ʿamala yadaẙka?"],[5,7,"لِأَنَّ ذَلِكَ مِنْ كَثْرَةِ ٱلْأَحْلَامِ وَٱلْأَبَاطِيلِ وَكَثْرَةِ ٱلْكَلَامِ. وَلَكِنِ ٱخْشَ ٱللهَ.","liạảnã dẖalika min̊ katẖ̊raẗi ٱl̊ạảḥ̊lāmi waٱl̊ạảbāṭīli wakatẖ̊raẗi ٱl̊kalāmi. walakini ٱkẖ̊sẖa ٱllha."],[5,8,"إِنْ رَأَيْتَ ظُلْمَ ٱلْفَقِيرِ وَنَزْعَ ٱلْحَقِّ وَٱلْعَدْلِ فِي ٱلْبِلَادِ، فَلَا تَرْتَعْ مِنَ ٱلْأَمْرِ، لِأَنَّ فَوْقَ ٱلْعَالِي عَالِيًا يُلَاحِظُ، وَٱلْأَعْلَى فَوْقَهُمَا.","ại̹n̊ rāảẙta ẓul̊ma ٱl̊faqīri wanaz̊ʿa ٱl̊ḥaqĩ waٱl̊ʿad̊li fī ٱl̊bilādi, falā tar̊taʿ̊ mina ٱl̊ạảm̊ri, liạảnã faẘqa ٱl̊ʿālī ʿālīaⁿạ yulāḥiẓu, waٱl̊ạảʿ̊lay̱ faẘqahumā."],[5,9,"وَمَنْفَعَةُ ٱلْأَرْضِ لِلْكُلِّ. ٱلْمَلِكُ مَخْدُومٌ مِنَ ٱلْحَقْلِ.","waman̊faʿaẗu ٱl̊ạảr̊ḍi lil̊kulĩ. ٱl̊maliku makẖ̊dūmuⁿ mina ٱl̊ḥaq̊li."],[5,10,"مَنْ يُحِبُّ ٱلْفِضَّةَ لَا يَشْبَعُ مِنَ ٱلْفِضَّةِ، وَمَنْ يُحِبُّ ٱلثَّرْوَةَ لَا يَشْبَعُ مِنْ دَخْلٍ. هَذَا أَيْضًا بَاطِلٌ.","man̊ yuḥibũ ٱl̊fiḍãẗa lā yasẖ̊baʿu mina ٱl̊fiḍãẗi, waman̊ yuḥibũ ٱltẖãr̊waẗa lā yasẖ̊baʿu min̊ dakẖ̊liⁿ. hadẖā ạảẙḍaⁿạ bāṭiluⁿ."],[5,11,"إِذَا كَثُرَتِ ٱلْخَيْرَاتُ كَثُرَ ٱلَّذِينَ يَأْكُلُونَهَا، وَأَيُّ مَنْفَعَةٍ لِصَاحِبِهَا إِلَّا رُؤْيَتَهَا بِعَيْنَيْهِ؟","ại̹dẖā katẖurati ٱl̊kẖaẙrātu katẖura ٱlãdẖīna yā̊̉kulūnahā, wāảyũ man̊faʿaẗiⁿ liṣāḥibihā ại̹lãạ rū̊̉yatahā biʿaẙnaẙhi?"],[5,12,"نَوْمُ ٱلْمُشْتَغِلِ حُلْوٌ، إِنْ أَكَلَ قَلِيلًا أَوْ كَثِيرًا، وَوَفْرُ ٱلْغَنِيِّ لَا يُرِيحُهُ حَتَّى يَنَامَ.","naẘmu ٱl̊musẖ̊tagẖili ḥul̊wuⁿ, ại̹n̊ ạảkala qalīlaⁿạ ạảẘ katẖīraⁿạ, wawaf̊ru ٱl̊gẖanīĩ lā yurīḥuhu ḥatãy̱ yanāma."],[5,13,"يُوجَدُ شَرٌّ خَبِيثٌ رَأَيْتُهُ تَحْتَ ٱلشَّمْسِ: ثَرْوَةٌ مَصُونَةٌ لِصَاحِبِهَا لِضَرَرِهِ.","yūjadu sẖaruⁿ̃ kẖabītẖuⁿ rāảẙtuhu taḥ̊ta ٱlsẖãm̊si: tẖar̊waẗuⁿ maṣūnaẗuⁿ liṣāḥibihā liḍararihi."],[5,14,"فَهَلَكَتْ تِلْكَ ٱلثَّرْوَةُ بِأَمْرٍ سَيِّئٍ، ثُمَّ وَلَدَ ٱبْنًا وَمَا بِيَدِهِ شَيْءٌ.","fahalakat̊ til̊ka ٱltẖãr̊waẗu biạảm̊riⁿ sayĩyiⁿ̉, tẖumã walada ٱb̊naⁿạ wamā bīadihi sẖaẙʾuⁿ."],[5,15,"كَمَا خَرَجَ مِنْ بَطْنِ أُمِّهِ عُرْيَانًا يَرْجِعُ ذَاهِبًا كَمَا جَاءَ، وَلَا يَأْخُذُ شَيْئًا مِنْ تَعَبِهِ فَيَذْهَبُ بِهِ فِي يَدِهِ.","kamā kẖaraja min̊ baṭ̊ni ạủmĩhi ʿur̊yānaⁿạ yar̊jiʿu dẖāhibaⁿạ kamā jāʾa, walā yā̊̉kẖudẖu sẖaẙyaⁿ̉ạ min̊ taʿabihi fayadẖ̊habu bihi fī yadihi."],[5,16,"وَهَذَا أَيْضًا مَصِيبَةٌ رَدِيئَةٌ، فِي كُلِّ شَيْءٍ كَمَا جَاءَ هَكَذَا يَذْهَبُ، فَأَيَّةُ مَنْفَعَةٍ لَهُ، لِلَّذِي تَعِبَ لِلرِّيحِ؟","wahadẖā ạảẙḍaⁿạ maṣībaẗuⁿ radīyảẗuⁿ, fī kulĩ sẖaẙʾiⁿ kamā jāʾa hakadẖā yadẖ̊habu, fāảyãẗu man̊faʿaẗiⁿ lahu, lilãdẖī taʿiba lilrĩyḥi?"],[5,17,"أَيْضًا يَأْكُلُ كُلَّ أَيَّامِهِ فِي ٱلظَّلَامِ، وَيَغْتَمُّ كَثِيرًا مَعَ حُزْنٍ وَغَيْظٍ.","ạảẙḍaⁿạ yā̊̉kulu kulã ạảyãạmihi fī ٱlẓãlāmi, wayagẖ̊tamũ katẖīraⁿạ maʿa ḥuz̊niⁿ wagẖaẙẓiⁿ."],[5,18,"هُوَذَا ٱلَّذِي رَأَيْتُهُ أَنَا خَيْرًا، ٱلَّذِي هُوَ حَسَنٌ: أَنْ يَأْكُلَ ٱلْإِنْسَانُ وَيَشْرَبَ وَيَرَى خَيْرًا مِنْ كُلِّ تَعَبِهِ ٱلَّذِي يَتْعَبُ فِيهِ تَحْتَ ٱلشَّمْسِ مُدَّةَ أَيَّامِ حَيَاتِهِ ٱلَّتِي أَعْطَاهُ ٱللهُ إِيَّاهَا، لِأَنَّهُ نَصِيبُهُ.","hūadẖā ٱlãdẖī rāảẙtuhu ạảnā kẖaẙraⁿạ, ٱlãdẖī hūa ḥasanuⁿ: ạản̊ yā̊̉kula ٱl̊ại̹n̊sānu wayasẖ̊raba wayaray̱ kẖaẙraⁿạ min̊ kulĩ taʿabihi ٱlãdẖī yat̊ʿabu fīhi taḥ̊ta ٱlsẖãm̊si mudãẗa ạảyãạmi ḥayātihi ٱlãtī ạảʿ̊ṭāhu ٱllhu ại̹yãạhā, liạảnãhu naṣībuhu."],[5,19,"أَيْضًا كُلُّ إِنْسَانٍ أَعْطَاهُ ٱللهُ غِنًى وَمَالًا وَسَلَّطَهُ عَلَيْهِ حَتَّى يَأْكُلَ مِنْهُ، وَيَأْخُذَ نَصِيبَهُ، وَيَفْرَحَ بِتَعَبِهِ، فَهَذَا هُوَ عَطِيَّةُ ٱللهِ.","ạảẙḍaⁿạ kulũ ại̹n̊sāniⁿ ạảʿ̊ṭāhu ٱllhu gẖinaⁿy̱ wamālaⁿạ wasalãṭahu ʿalaẙhi ḥatãy̱ yā̊̉kula min̊hu, wayā̊̉kẖudẖa naṣībahu, wayaf̊raḥa bitaʿabihi, fahadẖā hūa ʿaṭīãẗu ٱllhi."],[5,20,"لِأَنَّهُ لَا يَذْكُرُ أَيَّامَ حَيَاتِهِ كَثِيرًا، لِأَنَّ ٱللهَ مُلْهِيهِ بِفَرَحِ قَلْبِهِ.","liạảnãhu lā yadẖ̊kuru ạảyãạma ḥayātihi katẖīraⁿạ, liạảnã ٱllha mul̊hīhi bifaraḥi qal̊bihi."],[6,1,"يُوجَدُ شَرٌّ قَدْ رَأَيْتُهُ تَحْتَ ٱلشَّمْسِ وَهُوَ كَثِيرٌ بَيْنَ ٱلنَّاسِ:","yūjadu sẖaruⁿ̃ qad̊ rāảẙtuhu taḥ̊ta ٱlsẖãm̊si wahūa katẖīruⁿ baẙna ٱlnãạsi:"],[6,2,"رَجُلٌ أَعْطَاهُ ٱللهُ غِنًى وَمَالًا وَكَرَامَةً، وَلَيْسَ لِنَفْسِهِ عَوَزٌ مِنْ كُلِّ مَا يَشْتَهِيهِ، وَلَمْ يُعْطِهِ ٱللهُ ٱسْتِطَاعَةً عَلَى أَنْ يَأْكُلَ مِنْهُ، بَلْ يَأْكُلُهُ إِنْسَانٌ غَرِيبٌ. هَذَا بَاطِلٌ وَمُصِيبَةٌ رَدِيئَةٌ هُوَ.","rajuluⁿ ạảʿ̊ṭāhu ٱllhu gẖinaⁿy̱ wamālaⁿạ wakarāmaẗaⁿ, walaẙsa linaf̊sihi ʿawazuⁿ min̊ kulĩ mā yasẖ̊tahīhi, walam̊ yuʿ̊ṭihi ٱllhu ٱs̊tiṭāʿaẗaⁿ ʿalay̱ ạản̊ yā̊̉kula min̊hu, bal̊ yā̊̉kuluhu ại̹n̊sānuⁿ gẖarībuⁿ. hadẖā bāṭiluⁿ wamuṣībaẗuⁿ radīyảẗuⁿ hūa."],[6,3,"إِنْ وَلَدَ إِنْسَانٌ مِئَةً، وَعَاشَ سِنِينَ كَثِيرَةً حَتَّى تَصِيرَ أَيَّامُ سِنِيهِ كَثِيرَةً، وَلَمْ تَشْبَعْ نَفْسُهُ مِنَ ٱلْخَيْرِ، وَلَيْسَ لَهُ أَيْضًا دَفْنٌ، فَأَقُولُ إِنَّ ٱلسِّقْطَ خَيْرٌ مِنْهُ.","ại̹n̊ walada ại̹n̊sānuⁿ mīảẗaⁿ, waʿāsẖa sinīna katẖīraẗaⁿ ḥatãy̱ taṣīra ạảyãạmu sinīhi katẖīraẗaⁿ, walam̊ tasẖ̊baʿ̊ naf̊suhu mina ٱl̊kẖaẙri, walaẙsa lahu ạảẙḍaⁿạ daf̊nuⁿ, fāảqūlu ại̹nã ٱlsĩq̊ṭa kẖaẙruⁿ min̊hu."],[6,4,"لِأَنَّهُ فِي ٱلْبَاطِلِ يَجِيءُ، وَفِي ٱلظَّلَامِ يَذْهَبُ، وَٱسْمُهُ يُغَطَّى بِٱلظَّلَامِ.","liạảnãhu fī ٱl̊bāṭili yajīʾu, wafī ٱlẓãlāmi yadẖ̊habu, waٱs̊muhu yugẖaṭãy̱ biٱlẓãlāmi."],[6,5,"وَأَيْضًا لَمْ يَرَ ٱلشَّمْسَ وَلَمْ يَعْلَمْ. فَهَذَا لَهُ رَاحَةٌ أَكْثَرُ مِنْ ذَاكَ.","wāảẙḍaⁿạ lam̊ yara ٱlsẖãm̊sa walam̊ yaʿ̊lam̊. fahadẖā lahu rāḥaẗuⁿ ạảk̊tẖaru min̊ dẖāka."],[6,6,"وَإِنْ عَاشَ أَلْفَ سَنَةٍ مُضَاعَفَةً وَلَمْ يَرَ خَيْرًا، أَلَيْسَ إِلَى مَوْضِعٍ وَاحِدٍ يَذْهَبُ ٱلْجَمِيعُ؟","wāi̹n̊ ʿāsẖa ạảl̊fa sanaẗiⁿ muḍāʿafaẗaⁿ walam̊ yara kẖaẙraⁿạ, ạảlaẙsa ại̹lay̱ maẘḍiʿiⁿ wāḥidiⁿ yadẖ̊habu ٱl̊jamīʿu?"],[6,7,"كُلُّ تَعَبِ ٱلْإِنْسَانِ لِفَمِهِ، وَمَعَ ذَلِكَ فَٱلنَّفْسُ لَا تَمْتَلِئُ.","kulũ taʿabi ٱl̊ại̹n̊sāni lifamihi, wamaʿa dẖalika faٱlnãf̊su lā tam̊talīủ."],[6,8,"لِأَنَّهُ مَاذَا يَبْقَى لِلْحَكِيمِ أَكْثَرَ مِنَ ٱلْجَاهِلِ؟ مَاذَا لِلْفَقِيرِ ٱلْعَارِفِ ٱلسُّلُوكَ أَمَامَ ٱلْأَحْيَاءِ؟","liạảnãhu mādẖā yab̊qay̱ lil̊ḥakīmi ạảk̊tẖara mina ٱl̊jāhili? mādẖā lil̊faqīri ٱl̊ʿārifi ٱlsũlūka ạảmāma ٱl̊ạảḥ̊yāʾi?"],[6,9,"رُؤْيَةُ ٱلْعُيُونِ خَيْرٌ مِنْ شَهْوَةِ ٱلنَّفْسِ. هَذَا أَيْضًا بَاطِلٌ وَقَبْضُ ٱلرِّيحِ.","rū̊̉yaẗu ٱl̊ʿuyūni kẖaẙruⁿ min̊ sẖah̊waẗi ٱlnãf̊si. hadẖā ạảẙḍaⁿạ bāṭiluⁿ waqab̊ḍu ٱlrĩyḥi."],[6,10,"ٱلَّذِي كَانَ فَقَدْ دُعِيَ بِٱسْمٍ مُنْذُ زَمَانٍ، وَهُوَ مَعْرُوفٌ أَنَّهُ إِنْسَانٌ، وَلَا يَسْتَطِيعُ أَنْ يُخَاصِمَ مَنْ هُوَ أَقْوَى مِنْهُ.","ٱlãdẖī kāna faqad̊ duʿīa biٱs̊miⁿ mun̊dẖu zamāniⁿ, wahūa maʿ̊rūfuⁿ ạảnãhu ại̹n̊sānuⁿ, walā yas̊taṭīʿu ạản̊ yukẖāṣima man̊ hūa ạảq̊way̱ min̊hu."],[6,11,"لِأَنَّهُ تُوجَدُ أُمُورٌ كَثِيرَةٌ تَزِيدُ ٱلْبَاطِلَ. فَأَيُّ فَضْلٍ لِلْإِنْسَانِ؟","liạảnãhu tūjadu ạủmūruⁿ katẖīraẗuⁿ tazīdu ٱl̊bāṭila. fāảyũ faḍ̊liⁿ lil̊ại̹n̊sāni?"],[6,12,"لِأَنَّهُ مَنْ يَعْرِفُ مَا هُوَ خَيْرٌ لِلْإِنْسَانِ فِي ٱلْحَيَاةِ، مُدَّةَ أَيَّامِ حَيَاةِ بَاطِلِهِ ٱلَّتِي يَقْضِيهَا كَٱلظِّلِّ؟ لِأَنَّهُ مَنْ يُخْبِرُ ٱلْإِنْسَانَ بِمَا يَكُونُ بَعْدَهُ تَحْتَ ٱلشَّمْسِ؟","liạảnãhu man̊ yaʿ̊rifu mā hūa kẖaẙruⁿ lil̊ại̹n̊sāni fī ٱl̊ḥayāẗi, mudãẗa ạảyãạmi ḥayāẗi bāṭilihi ٱlãtī yaq̊ḍīhā kaٱlẓĩlĩ? liạảnãhu man̊ yukẖ̊biru ٱl̊ại̹n̊sāna bimā yakūnu baʿ̊dahu taḥ̊ta ٱlsẖãm̊si?"],[7,1,"اَلصِّيتُ خَيْرٌ مِنَ ٱلدُّهْنِ ٱلطَّيِّبِ، وَيَوْمُ ٱلْمَمَاتِ خَيْرٌ مِنْ يَوْمِ ٱلْوِلَادَةِ.","ạalṣĩytu kẖaẙruⁿ mina ٱldũh̊ni ٱlṭãyĩbi, wayaẘmu ٱl̊mamāti kẖaẙruⁿ min̊ yaẘmi ٱl̊wilādaẗi."],[7,2,"اَلذَّهَابُ إِلَى بَيْتِ ٱلنَّوْحِ خَيْرٌ مِنَ ٱلذَّهَابِ إِلَى بَيْتِ ٱلْوَلِيمَةِ، لِأَنَّ ذَاكَ نِهَايَةُ كُلِّ إِنْسَانٍ، وَٱلْحَيُّ يَضَعُهُ فِي قَلْبِهِ.","ạaldẖãhābu ại̹lay̱ baẙti ٱlnãẘḥi kẖaẙruⁿ mina ٱldẖãhābi ại̹lay̱ baẙti ٱl̊walīmaẗi, liạảnã dẖāka nihāyaẗu kulĩ ại̹n̊sāniⁿ, waٱl̊ḥayũ yaḍaʿuhu fī qal̊bihi."],[7,3,"اَلْحُزْنُ خَيْرٌ مِنَ ٱلضَّحِكِ، لِأَنَّهُ بِكَآبَةِ ٱلْوَجْهِ يُصْلَحُ ٱلْقَلْبُ.","ạal̊ḥuz̊nu kẖaẙruⁿ mina ٱlḍãḥiki, liạảnãhu bikā̂baẗi ٱl̊waj̊hi yuṣ̊laḥu ٱl̊qal̊bu."],[7,4,"قَلْبُ ٱلْحُكَمَاءِ فِي بَيْتِ ٱلنَّوْحِ، وَقَلْبُ ٱلْجُهَّالِ فِي بَيْتِ ٱلْفَرَحِ.","qal̊bu ٱl̊ḥukamāʾi fī baẙti ٱlnãẘḥi, waqal̊bu ٱl̊juhãạli fī baẙti ٱl̊faraḥi."],[7,5,"سَمْعُ ٱلِٱنْتِهَارِ مِنَ ٱلْحَكِيمِ خَيْرٌ لِلْإِنْسَانِ مِنْ سَمْعِ غِنَاءِ ٱلْجُهَّالِ،","sam̊ʿu ٱliٱn̊tihāri mina ٱl̊ḥakīmi kẖaẙruⁿ lil̊ại̹n̊sāni min̊ sam̊ʿi gẖināʾi ٱl̊juhãạli,"],[7,6,"لِأَنَّهُ كَصَوْتِ ٱلشَّوْكِ تَحْتَ ٱلْقِدْرِ هَكَذَا ضَحِكُ ٱلْجُهَّالِ. هَذَا أَيْضًا بَاطِلٌ.","liạảnãhu kaṣaẘti ٱlsẖãẘki taḥ̊ta ٱl̊qid̊ri hakadẖā ḍaḥiku ٱl̊juhãạli. hadẖā ạảẙḍaⁿạ bāṭiluⁿ."],[7,7,"لِأَنَّ ٱلظُّلْمَ يُحَمِّقُ ٱلْحَكِيمَ، وَٱلْعَطِيَّةَ تُفْسِدُ ٱلْقَلْبَ.","liạảnã ٱlẓũl̊ma yuḥamĩqu ٱl̊ḥakīma, waٱl̊ʿaṭīãẗa tuf̊sidu ٱl̊qal̊ba."],[7,8,"نِهَايَةُ أَمْرٍ خَيْرٌ مِنْ بَدَايَتِهِ. طُولُ ٱلرُّوحِ خَيْرٌ مِنْ تَكَبُّرِ ٱلرُّوحِ.","nihāyaẗu ạảm̊riⁿ kẖaẙruⁿ min̊ badāyatihi. ṭūlu ٱlrũwḥi kẖaẙruⁿ min̊ takabũri ٱlrũwḥi."],[7,9,"لَا تُسْرِعْ بِرُوحِكَ إِلَى ٱلْغَضَبِ، لِأَنَّ ٱلْغَضَبَ يَسْتَقِرُّ فِي حِضْنِ ٱلْجُهَّالِ.","lā tus̊riʿ̊ birūḥika ại̹lay̱ ٱl̊gẖaḍabi, liạảnã ٱl̊gẖaḍaba yas̊taqirũ fī ḥiḍ̊ni ٱl̊juhãạli."],[7,10,"لَا تَقُلْ: «لِمَاذَا كَانَتِ ٱلْأَيَّامُ ٱلْأُولَى خَيْرًا مِنْ هَذِهِ؟» لِأَنَّهُ لَيْسَ عَنْ حِكْمَةٍ تَسْأَلُ عَنْ هَذَا.","lā taqul̊: «limādẖā kānati ٱl̊ạảyãạmu ٱl̊ạủwlay̱ kẖaẙraⁿạ min̊ hadẖihi?» liạảnãhu laẙsa ʿan̊ ḥik̊maẗiⁿ tas̊ạảlu ʿan̊ hadẖā."],[7,11,"اَلْحِكْمَةُ صَالِحَةٌ مِثْلُ ٱلْمِيرَاثِ، بَلْ أَفْضَلُ لِنَاظِرِي ٱلشَّمْسِ.","ạal̊ḥik̊maẗu ṣāliḥaẗuⁿ mitẖ̊lu ٱl̊mīrātẖi, bal̊ ạảf̊ḍalu lināẓirī ٱlsẖãm̊si."],[7,12,"لِأَنَّ ٱلَّذِي فِي ظِلِّ ٱلْحِكْمَةِ هُوَ فِي ظِلِّ ٱلْفِضَّةِ، وَفَضْلُ ٱلْمَعْرِفَةِ هُوَ إِنَّ ٱلْحِكْمَةَ تُحْيِي أَصْحَابَهَا.","liạảnã ٱlãdẖī fī ẓilĩ ٱl̊ḥik̊maẗi hūa fī ẓilĩ ٱl̊fiḍãẗi, wafaḍ̊lu ٱl̊maʿ̊rifaẗi hūa ại̹nã ٱl̊ḥik̊maẗa tuḥ̊yī ạảṣ̊ḥābahā."],[7,13,"اُنْظُرْ عَمَلَ ٱللهِ: لِأَنَّهُ مَنْ يَقْدِرُ عَلَى تَقْوِيمِ مَا قَدْ عَوَّجَهُ؟","ạun̊ẓur̊ ʿamala ٱllhi: liạảnãhu man̊ yaq̊diru ʿalay̱ taq̊wīmi mā qad̊ ʿawãjahu?"],[7,14,"فِي يَوْمِ ٱلْخَيْرِ كُنْ بِخَيْرٍ، وَفِي يَوْمِ ٱلشَّرِّ ٱعْتَبِرْ. إِنَّ ٱللهَ جَعَلَ هَذَا مَعَ ذَاكَ، لِكَيْلَا يَجِدَ ٱلْإِنْسَانُ شَيْئًا بَعْدَهُ.","fī yaẘmi ٱl̊kẖaẙri kun̊ bikẖaẙriⁿ, wafī yaẘmi ٱlsẖãrĩ ٱʿ̊tabir̊. ại̹nã ٱllha jaʿala hadẖā maʿa dẖāka, likaẙlā yajida ٱl̊ại̹n̊sānu sẖaẙyaⁿ̉ạ baʿ̊dahu."],[7,15,"قَدْ رَأَيْتُ ٱلْكُلَّ فِي أَيَّامِ بُطْلِي: قَدْ يَكُونُ بَارٌّ يَبِيدُ فِي بِرِّهِ، وَقَدْ يَكُونُ شِرِّيرٌ يَطُولُ فِي شَرِّهِ.","qad̊ rāảẙtu ٱl̊kulã fī ạảyãạmi buṭ̊lī: qad̊ yakūnu bāruⁿ̃ yabīdu fī birĩhi, waqad̊ yakūnu sẖirĩyruⁿ yaṭūlu fī sẖarĩhi."],[7,16,"لَا تَكُنْ بَارًّا كَثِيرًا، وَلَا تَكُنْ حَكِيمًا بِزِيَادَةٍ. لِمَاذَا تَخْرِبُ نَفْسَكَ؟","lā takun̊ bāraⁿ̃ạ katẖīraⁿạ, walā takun̊ ḥakīmaⁿạ bizīādaẗiⁿ. limādẖā takẖ̊ribu naf̊saka?"],[7,17,"لَا تَكُنْ شِرِّيرًا كَثِيرًا، وَلَا تَكُنْ جَاهِلًا. لِمَاذَا تَمُوتُ فِي غَيْرِ وَقْتِكَ؟","lā takun̊ sẖirĩyraⁿạ katẖīraⁿạ, walā takun̊ jāhilaⁿạ. limādẖā tamūtu fī gẖaẙri waq̊tika?"],[7,18,"حَسَنٌ أَنْ تَتَمَسَّكَ بِهَذَا، وَأَيْضًا أَنْ لَا تَرْخِيَ يَدَكَ عَنْ ذَاكَ، لِأَنَّ مُتَّقِيَ ٱللهِ يَخْرُجُ مِنْهُمَا كِلَيْهِمَا.","ḥasanuⁿ ạản̊ tatamasãka bihadẖā, wāảẙḍaⁿạ ạản̊ lā tar̊kẖīa yadaka ʿan̊ dẖāka, liạảnã mutãqīa ٱllhi yakẖ̊ruju min̊humā kilaẙhimā."],[7,19,"اَلْحِكْمَةُ تُقَوِّي ٱلْحَكِيمَ أَكْثَرَ مِنْ عَشَرَةِ مُسَلَّطِينَ، ٱلَّذِينَ هُمْ فِي ٱلْمَدِينَةِ.","ạal̊ḥik̊maẗu tuqawĩy ٱl̊ḥakīma ạảk̊tẖara min̊ ʿasẖaraẗi musalãṭīna, ٱlãdẖīna hum̊ fī ٱl̊madīnaẗi."],[7,20,"لِأَنَّهُ لَا إِنْسَانٌ صِدِّيقٌ فِي ٱلْأَرْضِ يَعْمَلُ صَلَاحًا وَلَا يُخْطِئُ.","liạảnãhu lā ại̹n̊sānuⁿ ṣidĩyquⁿ fī ٱl̊ạảr̊ḍi yaʿ̊malu ṣalāḥaⁿạ walā yukẖ̊ṭīủ."],[7,21,"أَيْضًا لَا تَضَعْ قَلْبَكَ عَلَى كُلِّ ٱلْكَلَامِ ٱلَّذِي يُقَالُ، لِئَلَّا تَسْمَعَ عَبْدَكَ يَسِبُّكَ.","ạảẙḍaⁿạ lā taḍaʿ̊ qal̊baka ʿalay̱ kulĩ ٱl̊kalāmi ٱlãdẖī yuqālu, līảlãạ tas̊maʿa ʿab̊daka yasibũka."],[7,22,"لِأَنَّ قَلْبَكَ أَيْضًا يَعْلَمُ أَنَّكَ أَنْتَ كَذَلِكَ مِرَارًا كَثِيرَةً سَبَبْتَ آخَرِينَ.","liạảnã qal̊baka ạảẙḍaⁿạ yaʿ̊lamu ạảnãka ạản̊ta kadẖalika mirāraⁿạ katẖīraẗaⁿ sabab̊ta ậkẖarīna."],[7,23,"كُلُّ هَذَا ٱمْتَحَنْتُهُ بِٱلْحِكْمَةِ. قُلْتُ: «أَكُونُ حَكِيمًا». أَمَّا هِيَ فَبَعِيدَةٌ عَنِّي.","kulũ hadẖā ٱm̊taḥan̊tuhu biٱl̊ḥik̊maẗi. qul̊tu: «ạảkūnu ḥakīmaⁿạ». ạảmãạ hīa fabaʿīdaẗuⁿ ʿanĩy."],[7,24,"بَعِيدٌ مَا كَانَ بَعِيدًا، وَٱلْعَمِيقُ ٱلْعَمِيقُ مَنْ يَجِدُهُ؟","baʿīduⁿ mā kāna baʿīdaⁿạ, waٱl̊ʿamīqu ٱl̊ʿamīqu man̊ yajiduhu?"],[7,25,"دُرْتُ أَنَا وَقَلْبِي لِأَعْلَمَ وَلِأَبْحَثَ وَلِأَطْلُبَ حِكْمَةً وَعَقْلًا، وَلِأَعْرِفَ ٱلشَّرَّ أَنَّهُ جَهَالَةٌ، وَٱلْحَمَاقَةَ أَنَّهَا جُنُونٌ.","dur̊tu ạảnā waqal̊bī liạảʿ̊lama waliạảb̊ḥatẖa waliạảṭ̊luba ḥik̊maẗaⁿ waʿaq̊laⁿạ, waliạảʿ̊rifa ٱlsẖãrã ạảnãhu jahālaẗuⁿ, waٱl̊ḥamāqaẗa ạảnãhā junūnuⁿ."],[7,26,"فَوَجَدْتُ أَمَرَّ مِنَ ٱلْمَوْتِ: ٱلْمَرْأَةَ ٱلَّتِي هِيَ شِبَاكٌ، وَقَلْبُهَا أَشْرَاكٌ، وَيَدَاهَا قُيُودٌ. ٱلصَّالِحُ قُدَّامَ ٱللهِ يَنْجُو مِنْهَا. أَمَّا ٱلْخَاطِئُ فَيُؤْخَذُ بِهَا.","fawajad̊tu ạảmarã mina ٱl̊maẘti: ٱl̊mar̊ạảẗa ٱlãtī hīa sẖibākuⁿ, waqal̊buhā ạảsẖ̊rākuⁿ, wayadāhā quyūduⁿ. ٱlṣãạliḥu qudãạma ٱllhi yan̊jū min̊hā. ạảmãạ ٱl̊kẖāṭīủ fayū̊̉kẖadẖu bihā."],[7,27,"اُنْظُرْ. هَذَا وَجَدْتُهُ، قَالَ ٱلْجَامِعَةُ: وَاحِدَةً فَوَاحِدَةً لِأَجِدَ ٱلنَّتِيجَةَ","ạun̊ẓur̊. hadẖā wajad̊tuhu, qāla ٱl̊jāmiʿaẗu: wāḥidaẗaⁿ fawāḥidaẗaⁿ liạảjida ٱlnãtījaẗa"],[7,28,"ٱلَّتِي لَمْ تَزَلْ نَفْسِي تَطْلُبُهَا فَلَمْ أَجِدْهَا. رَجُلًا وَاحِدًا بَيْنَ أَلْفٍ وَجَدْتُ، أَمَّا ٱمْرَأَةً فَبَيْنَ كُلِّ أُولَئِكَ لَمْ أَجِدْ!","ٱlãtī lam̊ tazal̊ naf̊sī taṭ̊lubuhā falam̊ ạảjid̊hā. rajulaⁿạ wāḥidaⁿạ baẙna ạảl̊fiⁿ wajad̊tu, ạảmãạ ٱm̊rāảẗaⁿ fabaẙna kulĩ ạủwlayỉka lam̊ ạảjid̊!"],[7,29,"اُنْظُرْ. هَذَا وَجَدْتُ فَقَطْ: أَنَّ ٱللهَ صَنَعَ ٱلْإِنْسَانَ مُسْتَقِيمًا، أَمَّا هُمْ فَطَلَبُوا ٱخْتِرَاعَاتٍ كَثِيرَةً.","ạun̊ẓur̊. hadẖā wajad̊tu faqaṭ̊: ạảnã ٱllha ṣanaʿa ٱl̊ại̹n̊sāna mus̊taqīmaⁿạ, ạảmãạ hum̊ faṭalabūạ ٱkẖ̊tirāʿātiⁿ katẖīraẗaⁿ."],[8,1,"مَنْ كَٱلْحَكِيمِ؟ وَمَنْ يَفْهَمُ تَفْسِيرَ أَمْرٍ؟ حِكْمَةُ ٱلْإِنْسَانِ تُنِيرُ وَجْهَهُ، وَصَلَابَةُ وَجْهِهِ تَتَغَيَّرُ.","man̊ kaٱl̊ḥakīmi? waman̊ yaf̊hamu taf̊sīra ạảm̊riⁿ? ḥik̊maẗu ٱl̊ại̹n̊sāni tunīru waj̊hahu, waṣalābaẗu waj̊hihi tatagẖayãru."],[8,2,"أَنَا أَقُولُ: ٱحْفَظْ أَمْرَ ٱلْمَلِكِ، وَذَاكَ بِسَبَبِ يَمِينِ ٱللهِ.","ạảnā ạảqūlu: ٱḥ̊faẓ̊ ạảm̊ra ٱl̊maliki, wadẖāka bisababi yamīni ٱllhi."],[8,3,"لَا تَعْجَلْ إِلَى ٱلذَّهَابِ مِنْ وَجْهِهِ. لَا تَقِفْ فِي أَمْرٍ شَاقٍّ، لِأَنَّهُ يَفْعَلُ كُلَّ مَا شَاءَ.","lā taʿ̊jal̊ ại̹lay̱ ٱldẖãhābi min̊ waj̊hihi. lā taqif̊ fī ạảm̊riⁿ sẖāqiⁿ̃, liạảnãhu yaf̊ʿalu kulã mā sẖāʾa."],[8,4,"حَيْثُ تَكُونُ كَلِمَةُ ٱلْمَلِكِ فَهُنَاكَ سُلْطَانٌ. وَمَنْ يَقُولُ لَهُ: «مَاذَا تَفْعَلُ؟».","ḥaẙtẖu takūnu kalimaẗu ٱl̊maliki fahunāka sul̊ṭānuⁿ. waman̊ yaqūlu lahu: «mādẖā taf̊ʿalu?»."],[8,5,"حَافِظُ ٱلْوَصِيَّةِ لَا يَشْعُرُ بِأَمْرٍ شَاقٍّ، وَقَلْبُ ٱلْحَكِيمِ يَعْرِفُ ٱلْوَقْتَ وَٱلْحُكْمَ.","ḥāfiẓu ٱl̊waṣīãẗi lā yasẖ̊ʿuru biạảm̊riⁿ sẖāqiⁿ̃, waqal̊bu ٱl̊ḥakīmi yaʿ̊rifu ٱl̊waq̊ta waٱl̊ḥuk̊ma."],[8,6,"لِأَنَّ لِكُلِّ أَمْرٍ وَقْتًا وَحُكْمًا. لِأَنَّ شَرَّ ٱلْإِنْسَانِ عَظِيمٌ عَلَيْهِ،","liạảnã likulĩ ạảm̊riⁿ waq̊taⁿạ waḥuk̊maⁿạ. liạảnã sẖarã ٱl̊ại̹n̊sāni ʿaẓīmuⁿ ʿalaẙhi,"],[8,7,"لِأَنَّهُ لَا يَعْلَمُ مَا سَيَكُونُ. لِأَنَّهُ مَنْ يُخْبِرُهُ كَيْفَ يَكُونُ؟","liạảnãhu lā yaʿ̊lamu mā sayakūnu. liạảnãhu man̊ yukẖ̊biruhu kaẙfa yakūnu?"],[8,8,"لَيْسَ لِإِنْسَانٍ سُلْطَانٌ عَلَى ٱلرُّوحِ لِيُمْسِكَ ٱلرُّوحَ، وَلَا سُلْطَانٌ عَلَى يَوْمِ ٱلْمَوْتِ، وَلَا تَخْلِيَةٌ فِي ٱلْحَرْبِ، وَلَا يُنَجِّي ٱلشَّرُّ أَصْحَابَهُ.","laẙsa liại̹n̊sāniⁿ sul̊ṭānuⁿ ʿalay̱ ٱlrũwḥi līum̊sika ٱlrũwḥa, walā sul̊ṭānuⁿ ʿalay̱ yaẘmi ٱl̊maẘti, walā takẖ̊līaẗuⁿ fī ٱl̊ḥar̊bi, walā yunajĩy ٱlsẖãrũ ạảṣ̊ḥābahu."],[8,9,"كُلُّ هَذَا رَأَيْتُهُ إِذْ وَجَّهْتُ قَلْبِي لِكُلِّ عَمَلٍ عُمِلَ تَحْتَ ٱلشَّمْسِ، وَقْتَمَا يَتَسَلَّطُ إِنْسَانٌ عَلَى إِنْسَانٍ لِضَرَرِ نَفْسِهِ.","kulũ hadẖā rāảẙtuhu ại̹dẖ̊ wajãh̊tu qal̊bī likulĩ ʿamaliⁿ ʿumila taḥ̊ta ٱlsẖãm̊si, waq̊tamā yatasalãṭu ại̹n̊sānuⁿ ʿalay̱ ại̹n̊sāniⁿ liḍarari naf̊sihi."],[8,10,"وَهَكَذَا رَأَيْتُ أَشْرَارًا يُدْفَنُونَ وَضُمُّوا، وَٱلَّذِينَ عَمِلُوا بِٱلْحَقِّ ذَهَبُوا مِنْ مَكَانِ ٱلْقُدْسِ وَنُسُوا فِي ٱلْمَدِينَةِ. هَذَا أَيْضًا بَاطِلٌ.","wahakadẖā rāảẙtu ạảsẖ̊rāraⁿạ yud̊fanūna waḍumũwạ, waٱlãdẖīna ʿamilūạ biٱl̊ḥaqĩ dẖahabūạ min̊ makāni ٱl̊qud̊si wanusūạ fī ٱl̊madīnaẗi. hadẖā ạảẙḍaⁿạ bāṭiluⁿ."],[8,11,"لِأَنَّ ٱلْقَضَاءَ عَلَى ٱلْعَمَلِ ٱلرَّدِيءِ لَا يُجْرَى سَرِيعًا، فَلِذَلِكَ قَدِ ٱمْتَلَأَ قَلْبُ بَنِي ٱلْبَشَرِ فِيهِمْ لِفَعْلِ ٱلشَّرِّ.","liạảnã ٱl̊qaḍāʾa ʿalay̱ ٱl̊ʿamali ٱlrãdīʾi lā yuj̊ray̱ sarīʿaⁿạ, falidẖalika qadi ٱm̊talāả qal̊bu banī ٱl̊basẖari fīhim̊ lifaʿ̊li ٱlsẖãrĩ."],[8,12,"اَلْخَاطِئُ وَإِنْ عَمِلَ شَرًّا مِئَةَ مَرَّةٍ وَطَالَتْ أَيَّامُهُ، إِلَّا أَنِّي أَعْلَمُ أَنَّهُ يَكُونُ خَيْرٌ لِلْمُتَّقِينَ ٱللهَ ٱلَّذِينَ يَخَافُونَ قُدَّامَهُ.","ạal̊kẖāṭīủ wāi̹n̊ ʿamila sẖaraⁿ̃ạ mīảẗa marãẗiⁿ waṭālat̊ ạảyãạmuhu, ại̹lãạ ạảnĩy ạảʿ̊lamu ạảnãhu yakūnu kẖaẙruⁿ lil̊mutãqīna ٱllha ٱlãdẖīna yakẖāfūna qudãạmahu."],[8,13,"وَلَا يَكُونُ خَيْرٌ لِلشِّرِّيرِ، وَكَٱلظِّلِّ لَا يُطِيلُ أَيَّامَهُ لِأَنَّهُ لَا يَخْشَى قُدَّامَ ٱللهِ.","walā yakūnu kẖaẙruⁿ lilsẖĩrĩyri, wakaٱlẓĩlĩ lā yuṭīlu ạảyãạmahu liạảnãhu lā yakẖ̊sẖay̱ qudãạma ٱllhi."],[8,14,"يُوجَدُ بَاطِلٌ يُجْرَى عَلَى ٱلْأَرْضِ: أَنْ يُوجَدَ صِدِّيقُونَ يُصِيبُهُمْ مِثْلَ عَمَلِ ٱلْأَشْرَارِ، وَيُوجَدُ أَشْرَارٌ يُصِيبُهُمْ مِثْلَ عَمَلِ ٱلصِّدِّيقِينَ. فَقُلْتُ: إِنَّ هَذَا أَيْضًا بَاطِلٌ.","yūjadu bāṭiluⁿ yuj̊ray̱ ʿalay̱ ٱl̊ạảr̊ḍi: ạản̊ yūjada ṣidĩyqūna yuṣībuhum̊ mitẖ̊la ʿamali ٱl̊ạảsẖ̊rāri, wayūjadu ạảsẖ̊rāruⁿ yuṣībuhum̊ mitẖ̊la ʿamali ٱlṣĩdĩyqīna. faqul̊tu: ại̹nã hadẖā ạảẙḍaⁿạ bāṭiluⁿ."],[8,15,"فَمَدَحْتُ ٱلْفَرَحَ، لِأَنَّهُ لَيْسَ لِلْإِنْسَانِ خَيْرٌ تَحْتَ ٱلشَّمْسِ، إِلَّا أَنْ يَأْكُلَ وَيَشْرَبَ وَيَفْرَحَ، وَهَذَا يَبْقَى لَهُ فِي تَعَبِهِ مُدَّةَ أَيَّامِ حَيَاتِهِ ٱلَّتِي يُعْطِيهِ ٱللهُ إِيَّاهَا تَحْتَ ٱلشَّمْسِ.","famadaḥ̊tu ٱl̊faraḥa, liạảnãhu laẙsa lil̊ại̹n̊sāni kẖaẙruⁿ taḥ̊ta ٱlsẖãm̊si, ại̹lãạ ạản̊ yā̊̉kula wayasẖ̊raba wayaf̊raḥa, wahadẖā yab̊qay̱ lahu fī taʿabihi mudãẗa ạảyãạmi ḥayātihi ٱlãtī yuʿ̊ṭīhi ٱllhu ại̹yãạhā taḥ̊ta ٱlsẖãm̊si."],[8,16,"لَمَّا وَجَّهْتُ قَلْبِي لِأَعْرِفَ ٱلْحِكْمَةَ، وَأَنْظُرَ ٱلْعَمَلَ ٱلَّذِي عُمِلَ عَلَى ٱلْأَرْضِ، وَأَنَّهُ نَهَارًا وَلَيْلًا لَا يَرَى ٱلنَّوْمَ بِعَيْنَيْهِ،","lamãạ wajãh̊tu qal̊bī liạảʿ̊rifa ٱl̊ḥik̊maẗa, wāản̊ẓura ٱl̊ʿamala ٱlãdẖī ʿumila ʿalay̱ ٱl̊ạảr̊ḍi, wāảnãhu nahāraⁿạ walaẙlaⁿạ lā yaray̱ ٱlnãẘma biʿaẙnaẙhi,"],[8,17,"رَأَيْتُ كُلَّ عَمَلِ ٱللهِ أَنَّ ٱلْإِنْسَانَ لَا يَسْتَطِيعُ أَنْ يَجِدَ ٱلْعَمَلَ ٱلَّذِي عُمِلَ تَحْتَ ٱلشَّمْسِ. مَهْمَا تَعِبَ ٱلْإِنْسَانُ فِي ٱلطَّلَبِ فَلَا يَجِدُهُ، وَٱلْحَكِيمُ أَيْضًا، وَإِنْ قَالَ بِمَعْرِفَتِهِ، لَا يَقْدِرُ أَنْ يَجِدَهُ.","rāảẙtu kulã ʿamali ٱllhi ạảnã ٱl̊ại̹n̊sāna lā yas̊taṭīʿu ạản̊ yajida ٱl̊ʿamala ٱlãdẖī ʿumila taḥ̊ta ٱlsẖãm̊si. mah̊mā taʿiba ٱl̊ại̹n̊sānu fī ٱlṭãlabi falā yajiduhu, waٱl̊ḥakīmu ạảẙḍaⁿạ, wāi̹n̊ qāla bimaʿ̊rifatihi, lā yaq̊diru ạản̊ yajidahu."],[9,1,"لِأَنَّ هَذَا كُلَّهُ جَعَلْتُهُ فِي قَلْبِي، وَٱمْتَحَنْتُ هَذَا كُلَّهُ: أَنَّ ٱلصِّدِّيقِينَ وَٱلْحُكَمَاءَ وَأَعْمَالَهُمْ فِي يَدِ ٱللهِ. ٱلْإِنْسَانُ لَا يَعْلَمُ حُبًّا وَلَا بُغْضًا. ٱلْكُلُّ أَمَامَهُمُ.","liạảnã hadẖā kulãhu jaʿal̊tuhu fī qal̊bī, waٱm̊taḥan̊tu hadẖā kulãhu: ạảnã ٱlṣĩdĩyqīna waٱl̊ḥukamāʾa wāảʿ̊mālahum̊ fī yadi ٱllhi. ٱl̊ại̹n̊sānu lā yaʿ̊lamu ḥubaⁿ̃ạ walā bugẖ̊ḍaⁿạ. ٱl̊kulũ ạảmāmahumu."],[9,2,"ٱلْكُلُّ عَلَى مَا لِلْكُلِّ. حَادِثَةٌ وَاحِدَةٌ لِلصِّدِّيقِ وَلِلشِّرِّيرِ، لِلصَّالِحِ وَلِلطَّاهِرِ وَلِلنَّجِسِ، لِلذَّابِحِ وَلِلَّذِي لَا يَذْبَحُ، كَٱلصَّالِحِ ٱلْخَاطِئُ. ٱلْحَالِفُ كَٱلَّذِي يَخَافُ ٱلْحَلْفَ.","ٱl̊kulũ ʿalay̱ mā lil̊kulĩ. ḥāditẖaẗuⁿ wāḥidaẗuⁿ lilṣĩdĩyqi walilsẖĩrĩyri, lilṣãạliḥi walilṭãạhiri walilnãjisi, lildẖãạbiḥi walilãdẖī lā yadẖ̊baḥu, kaٱlṣãạliḥi ٱl̊kẖāṭīủ. ٱl̊ḥālifu kaٱlãdẖī yakẖāfu ٱl̊ḥal̊fa."],[9,3,"هَذَا أَشَرُّ كُلِّ مَا عُمِلَ تَحْتَ ٱلشَّمْسِ: أَنَّ حَادِثَةً وَاحِدَةً لِلْجَمِيعِ. وَأَيْضًا قَلْبُ بَنِي ٱلْبَشَرِ مَلآنُ مِنَ ٱلشَّرِّ، وَٱلْحَمَاقَةُ فِي قَلْبِهِمْ وَهُمْ أَحْيَاءٌ، وَبَعْدَ ذَلِكَ يَذْهَبُونَ إِلَى ٱلْأَمْوَاتِ.","hadẖā ạảsẖarũ kulĩ mā ʿumila taḥ̊ta ٱlsẖãm̊si: ạảnã ḥāditẖaẗaⁿ wāḥidaẗaⁿ lil̊jamīʿi. wāảẙḍaⁿạ qal̊bu banī ٱl̊basẖari malậnu mina ٱlsẖãrĩ, waٱl̊ḥamāqaẗu fī qal̊bihim̊ wahum̊ ạảḥ̊yāʾuⁿ, wabaʿ̊da dẖalika yadẖ̊habūna ại̹lay̱ ٱl̊ạảm̊wāti."],[9,4,"لِأَنَّهُ مَنْ يُسْتَثْنَى؟ لِكُلِّ ٱلْأَحْيَاءِ يُوجَدُ رَجَاءٌ، فَإِنَّ ٱلْكَلْبَ ٱلْحَيَّ خَيْرٌ مِنَ ٱلْأَسَدِ ٱلْمَيْتِ.","liạảnãhu man̊ yus̊tatẖ̊nay̱? likulĩ ٱl̊ạảḥ̊yāʾi yūjadu rajāʾuⁿ, fāi̹nã ٱl̊kal̊ba ٱl̊ḥayã kẖaẙruⁿ mina ٱl̊ạảsadi ٱl̊maẙti."],[9,5,"لِأَنَّ ٱلْأَحْيَاءَ يَعْلَمُونَ أَنَّهُمْ سَيَمُوتُونَ، أَمَّا ٱلْمَوْتَى فَلَا يَعْلَمُونَ شَيْئًا، وَلَيْسَ لَهُمْ أَجْرٌ بَعْدُ لِأَنَّ ذِكْرَهُمْ نُسِيَ.","liạảnã ٱl̊ạảḥ̊yāʾa yaʿ̊lamūna ạảnãhum̊ sayamūtūna, ạảmãạ ٱl̊maẘtay̱ falā yaʿ̊lamūna sẖaẙyaⁿ̉ạ, walaẙsa lahum̊ ạảj̊ruⁿ baʿ̊du liạảnã dẖik̊rahum̊ nusīa."],[9,6,"وَمَحَبَّتُهُمْ وَبُغْضَتُهُمْ وَحَسَدُهُمْ هَلَكَتْ مُنْذُ زَمَانٍ، وَلَا نَصِيبَ لَهُمْ بَعْدُ إِلَى ٱلْأَبَدِ، فِي كُلِّ مَا عُمِلَ تَحْتَ ٱلشَّمْسِ.","wamaḥabãtuhum̊ wabugẖ̊ḍatuhum̊ waḥasaduhum̊ halakat̊ mun̊dẖu zamāniⁿ, walā naṣība lahum̊ baʿ̊du ại̹lay̱ ٱl̊ạảbadi, fī kulĩ mā ʿumila taḥ̊ta ٱlsẖãm̊si."],[9,7,"اِذْهَبْ كُلْ خُبْزَكَ بِفَرَحٍ، وَٱشْرَبْ خَمْرَكَ بِقَلْبٍ طَيِّبٍ، لِأَنَّ ٱللهَ مُنْذُ زَمَانٍ قَدْ رَضِيَ عَمَلَكَ.","ạidẖ̊hab̊ kul̊ kẖub̊zaka bifaraḥiⁿ, waٱsẖ̊rab̊ kẖam̊raka biqal̊biⁿ ṭayĩbiⁿ, liạảnã ٱllha mun̊dẖu zamāniⁿ qad̊ raḍīa ʿamalaka."],[9,8,"لِتَكُنْ ثِيَابُكَ فِي كُلِّ حِينٍ بَيْضَاءَ، وَلَا يُعْوِزْ رَأْسَكَ ٱلدُّهْنُ.","litakun̊ tẖīābuka fī kulĩ ḥīniⁿ baẙḍāʾa, walā yuʿ̊wiz̊ rā̊̉saka ٱldũh̊nu."],[9,9,"اِلْتَذَّ عَيْشًا مَعَ ٱلْمَرْأَةِ ٱلَّتِي أَحْبَبْتَهَا كُلَّ أَيَّامِ حَيَاةِ بَاطِلِكَ ٱلَّتِي أَعْطَاكَ إِيَّاهَا تَحْتَ ٱلشَّمْسِ، كُلَّ أَيَّامِ بَاطِلِكَ، لِأَنَّ ذَلِكَ نَصِيبُكَ فِي ٱلْحَيَاةِ وَفِي تَعَبِكَ ٱلَّذِي تَتْعَبُهُ تَحْتَ ٱلشَّمْسِ.","ạil̊tadẖã ʿaẙsẖaⁿạ maʿa ٱl̊mar̊ạảẗi ٱlãtī ạảḥ̊bab̊tahā kulã ạảyãạmi ḥayāẗi bāṭilika ٱlãtī ạảʿ̊ṭāka ại̹yãạhā taḥ̊ta ٱlsẖãm̊si, kulã ạảyãạmi bāṭilika, liạảnã dẖalika naṣībuka fī ٱl̊ḥayāẗi wafī taʿabika ٱlãdẖī tat̊ʿabuhu taḥ̊ta ٱlsẖãm̊si."],[9,10,"كُلُّ مَا تَجِدُهُ يَدُكَ لِتَفْعَلَهُ فَٱفْعَلْهُ بِقُوَّتِكَ، لِأَنَّهُ لَيْسَ مِنْ عَمَلٍ وَلَا ٱخْتِرَاعٍ وَلَا مَعْرِفَةٍ وَلَا حِكْمَةٍ فِي ٱلْهَاوِيَةِ ٱلَّتِي أَنْتَ ذَاهِبٌ إِلَيْهَا.","kulũ mā tajiduhu yaduka litaf̊ʿalahu faٱf̊ʿal̊hu biqūãtika, liạảnãhu laẙsa min̊ ʿamaliⁿ walā ٱkẖ̊tirāʿiⁿ walā maʿ̊rifaẗiⁿ walā ḥik̊maẗiⁿ fī ٱl̊hāwīaẗi ٱlãtī ạản̊ta dẖāhibuⁿ ại̹laẙhā."],[9,11,"فَعُدْتُ وَرَأَيْتُ تَحْتَ ٱلشَّمْسِ: أَنَّ ٱلسَّعْيَ لَيْسَ لِلْخَفِيفِ، وَلَا ٱلْحَرْبَ لِلْأَقْوِيَاءِ، وَلَا ٱلْخُبْزَ لِلْحُكَمَاءِ، وَلَا ٱلْغِنَى لِلْفُهَمَاءِ، وَلَا ٱلنِّعْمَةَ لِذَوِي ٱلْمَعْرِفَةِ، لِأَنَهُ ٱلْوَقْتُ وَٱلْعَرَضُ يُلَاقِيَانِهِمْ كَافَّةً.","faʿud̊tu warāảẙtu taḥ̊ta ٱlsẖãm̊si: ạảnã ٱlsãʿ̊ya laẙsa lil̊kẖafīfi, walā ٱl̊ḥar̊ba lil̊ạảq̊wīāʾi, walā ٱl̊kẖub̊za lil̊ḥukamāʾi, walā ٱl̊gẖinay̱ lil̊fuhamāʾi, walā ٱlnĩʿ̊maẗa lidẖawī ٱl̊maʿ̊rifaẗi, liạảnahu ٱl̊waq̊tu waٱl̊ʿaraḍu yulāqīānihim̊ kāfãẗaⁿ."],[9,12,"لِأَنَّ ٱلْإِنْسَانَ أَيْضًا لَا يَعْرِفُ وَقْتَهُ. كَٱلْأَسْمَاكِ ٱلَّتِي تُؤْخَذُ بِشَبَكَةٍ مُهْلِكَةٍ، وَكَالْعَصَافِيرِ ٱلَّتِي تُؤْخَذُ بِٱلشَّرَكِ، كَذَلِكَ تُقْتَنَصُ بَنُو ٱلْبَشَرِ فِي وَقْتِ شَرٍّ، إِذْ يَقَعُ عَلَيْهِمْ بَغْتَةً.","liạảnã ٱl̊ại̹n̊sāna ạảẙḍaⁿạ lā yaʿ̊rifu waq̊tahu. kaٱl̊ạảs̊māki ٱlãtī tū̊̉kẖadẖu bisẖabakaẗiⁿ muh̊likaẗiⁿ, wakāl̊ʿaṣāfīri ٱlãtī tū̊̉kẖadẖu biٱlsẖãraki, kadẖalika tuq̊tanaṣu banū ٱl̊basẖari fī waq̊ti sẖariⁿ̃, ại̹dẖ̊ yaqaʿu ʿalaẙhim̊ bagẖ̊taẗaⁿ."],[9,13,"هَذِهِ ٱلْحِكْمَةُ رَأَيْتُهَا أَيْضًا تَحْتَ ٱلشَّمْسِ، وَهِيَ عَظِيمَةٌ عِنْدِي:","hadẖihi ٱl̊ḥik̊maẗu rāảẙtuhā ạảẙḍaⁿạ taḥ̊ta ٱlsẖãm̊si, wahīa ʿaẓīmaẗuⁿ ʿin̊dī:"],[9,14,"مَدِينَةٌ صَغِيرَةٌ فِيهَا أُنَاسٌ قَلِيلُونَ، فَجَاءَ عَلَيْهَا مَلِكٌ عَظِيمٌ وَحَاصَرَهَا وَبَنَى عَلَيْهَا أَبْرَاجًا عَظِيمَةً.","madīnaẗuⁿ ṣagẖīraẗuⁿ fīhā ạủnāsuⁿ qalīlūna, fajāʾa ʿalaẙhā malikuⁿ ʿaẓīmuⁿ waḥāṣarahā wabanay̱ ʿalaẙhā ạảb̊rājaⁿạ ʿaẓīmaẗaⁿ."],[9,15,"وَوُجِدَ فِيهَا رَجُلٌ مِسْكِينٌ حَكِيمٌ، فَنَجَّى هُوَ ٱلْمَدِينَةَ بِحِكْمَتِهِ. وَمَا أَحَدٌ ذَكَرَ ذَلِكَ ٱلرَّجُلَ ٱلْمِسْكِينَ!","wawujida fīhā rajuluⁿ mis̊kīnuⁿ ḥakīmuⁿ, fanajãy̱ hūa ٱl̊madīnaẗa biḥik̊matihi. wamā ạảḥaduⁿ dẖakara dẖalika ٱlrãjula ٱl̊mis̊kīna!"],[9,16,"فَقُلْتُ: «ٱلْحِكْمَةُ خَيْرٌ مِنَ ٱلْقُوَّةِ». أَمَّا حِكْمَةُ ٱلْمِسْكِينِ فَمُحْتَقَرَةٌ، وَكَلَامُهُ لَا يُسْمَعُ.","faqul̊tu: «ٱl̊ḥik̊maẗu kẖaẙruⁿ mina ٱl̊qūãẗi». ạảmãạ ḥik̊maẗu ٱl̊mis̊kīni famuḥ̊taqaraẗuⁿ, wakalāmuhu lā yus̊maʿu."],[9,17,"كَلِمَاتُ ٱلْحُكَمَاءِ تُسْمَعُ فِي ٱلْهُدُوءِ، أَكْثَرَ مِنْ صُرَاخِ ٱلْمُتَسَلِّطِ بَيْنَ ٱلْجُهَّالِ.","kalimātu ٱl̊ḥukamāʾi tus̊maʿu fī ٱl̊hudūʾi, ạảk̊tẖara min̊ ṣurākẖi ٱl̊mutasalĩṭi baẙna ٱl̊juhãạli."],[9,18,"اَلْحِكْمَةُ خَيْرٌ مِنْ أَدَوَاتِ ٱلْحَرْبِ. أَمَّا خَاطِئٌ وَاحِدٌ فَيُفْسِدُ خَيْرًا جَزِيلًا.","ạal̊ḥik̊maẗu kẖaẙruⁿ min̊ ạảdawāti ٱl̊ḥar̊bi. ạảmãạ kẖāṭīuⁿ̉ wāḥiduⁿ fayuf̊sidu kẖaẙraⁿạ jazīlaⁿạ."],[10,1,"اَلذُّبَابُ ٱلْمَيِّتُ يُنَتِّنُ وَيُخَمِّرُ طِيبَ ٱلْعَطَّارِ. جَهَالَةٌ قَلِيلَةٌ أَثْقَلُ مِنَ ٱلْحِكْمَةِ وَمِنَ ٱلْكَرَامَةِ.","ạaldẖũbābu ٱl̊mayĩtu yunatĩnu wayukẖamĩru ṭība ٱl̊ʿaṭãạri. jahālaẗuⁿ qalīlaẗuⁿ ạảtẖ̊qalu mina ٱl̊ḥik̊maẗi wamina ٱl̊karāmaẗi."],[10,2,"قَلْبُ ٱلْحَكِيمِ عَنْ يَمِينِهِ، وَقَلْبُ ٱلْجَاهِلِ عَنْ يَسَارِهِ.","qal̊bu ٱl̊ḥakīmi ʿan̊ yamīnihi, waqal̊bu ٱl̊jāhili ʿan̊ yasārihi."],[10,3,"أَيْضًا إِذَا مَشَى ٱلْجَاهِلُ فِي ٱلطَّرِيقِ يَنْقُصُ فَهْمُهُ، وَيَقُولُ لِكُلِّ وَاحِدٍ: إِنَّهُ جَاهِلٌ.","ạảẙḍaⁿạ ại̹dẖā masẖay̱ ٱl̊jāhilu fī ٱlṭãrīqi yan̊quṣu fah̊muhu, wayaqūlu likulĩ wāḥidiⁿ: ại̹nãhu jāhiluⁿ."],[10,4,"إِنْ صَعِدَتْ عَلَيْكَ رُوحُ ٱلْمُتَسَلِّطِ، فَلَا تَتْرُكْ مَكَانَكَ، لِأَنَّ ٱلْهُدُوءَ يُسَكِّنُ خَطَايَا عَظِيمَةً.","ại̹n̊ ṣaʿidat̊ ʿalaẙka rūḥu ٱl̊mutasalĩṭi, falā tat̊ruk̊ makānaka, liạảnã ٱl̊hudūʾa yusakĩnu kẖaṭāyā ʿaẓīmaẗaⁿ."],[10,5,"يُوجَدُ شَرٌّ رَأَيْتُهُ تَحْتَ ٱلشَّمْسِ، كَسَهْوٍ صَادِرٍ مِنْ قِبَلِ ٱلْمُتَسَلِّطِ:","yūjadu sẖaruⁿ̃ rāảẙtuhu taḥ̊ta ٱlsẖãm̊si, kasah̊wiⁿ ṣādiriⁿ min̊ qibali ٱl̊mutasalĩṭi:"],[10,6,"ٱلْجَهَالَةُ جُعِلَتْ فِي مَعَالِيَ كَثِيرَةٍ، وَٱلْأَغْنِيَاءُ يَجْلِسُونَ فِي ٱلسَّافِلِ.","ٱl̊jahālaẗu juʿilat̊ fī maʿālīa katẖīraẗiⁿ, waٱl̊ạảgẖ̊nīāʾu yaj̊lisūna fī ٱlsãạfili."],[10,7,"قَدْ رَأَيْتُ عَبِيدًا عَلَى ٱلْخَيْلِ، وَرُؤَسَاءَ مَاشِينَ عَلَى ٱلْأَرْضِ كَٱلْعَبِيدِ.","qad̊ rāảẙtu ʿabīdaⁿạ ʿalay̱ ٱl̊kẖaẙli, warūảsāʾa māsẖīna ʿalay̱ ٱl̊ạảr̊ḍi kaٱl̊ʿabīdi."],[10,8,"مَنْ يَحْفُرْ هُوَّةً يَقَعْ فِيهَا، وَمَنْ يَنْقُضْ جِدَارًا تَلْدَغْهُ حَيَّةٌ.","man̊ yaḥ̊fur̊ hūãẗaⁿ yaqaʿ̊ fīhā, waman̊ yan̊quḍ̊ jidāraⁿạ tal̊dagẖ̊hu ḥayãẗuⁿ."],[10,9,"مَنْ يَقْلَعْ حِجَارَةً يُوجَعْ بِهَا. مَنْ يُشَقِّقُ حَطَبًا يَكُونُ فِي خَطَرٍ مِنْهُ.","man̊ yaq̊laʿ̊ ḥijāraẗaⁿ yūjaʿ̊ bihā. man̊ yusẖaqĩqu ḥaṭabaⁿạ yakūnu fī kẖaṭariⁿ min̊hu."],[10,10,"إِنْ كَلَّ ٱلْحَدِيدُ وَلَمْ يُسَنِّنْ هُوَ حَدَّهُ، فَلْيَزِدِ ٱلْقُوَّةَ. أَمَّا ٱلْحِكْمَةُ فَنَافِعَةٌ لِلْإِنْجَاحِ.","ại̹n̊ kalã ٱl̊ḥadīdu walam̊ yusanĩn̊ hūa ḥadãhu, fal̊yazidi ٱl̊qūãẗa. ạảmãạ ٱl̊ḥik̊maẗu fanāfiʿaẗuⁿ lil̊ại̹n̊jāḥi."],[10,11,"إِنْ لَدَغَتِ ٱلْحَيَّةُ بِلَا رُقْيَةٍ، فَلَا مَنْفَعَةَ لِلرَّاقِي.","ại̹n̊ ladagẖati ٱl̊ḥayãẗu bilā ruq̊yaẗiⁿ, falā man̊faʿaẗa lilrãạqī."],[10,12,"كَلِمَاتُ فَمِ ٱلْحَكِيمِ نِعْمَةٌ، وَشَفَتَا ٱلْجَاهِلِ تَبْتَلِعَانِهِ.","kalimātu fami ٱl̊ḥakīmi niʿ̊maẗuⁿ, wasẖafatā ٱl̊jāhili tab̊taliʿānihi."],[10,13,"اِبْتِدَاءُ كَلَامِ فَمِهِ جَهَالَةٌ، وَآخِرُ فَمِهِ جُنُونٌ رَدِيءٌ.","ạib̊tidāʾu kalāmi famihi jahālaẗuⁿ, wā̂kẖiru famihi junūnuⁿ radīʾuⁿ."],[10,14,"وَٱلْجَاهِلُ يُكَثِّرُ ٱلْكَلَامَ. لَا يَعْلَمُ إِنْسَانٌ مَا يَكُونُ. وَمَاذَا يَصِيرُ بَعْدَهُ مَنْ يُخْبِرُهُ؟","waٱl̊jāhilu yukatẖĩru ٱl̊kalāma. lā yaʿ̊lamu ại̹n̊sānuⁿ mā yakūnu. wamādẖā yaṣīru baʿ̊dahu man̊ yukẖ̊biruhu?"],[10,15,"تَعَبُ ٱلْجُهَلَاءِ يُعْيِيهِمْ، لِأَنَّهُ لَا يَعْلَمُ كَيْفَ يَذْهَبُ إِلَى ٱلْمَدِينَةِ","taʿabu ٱl̊juhalāʾi yuʿ̊yīhim̊, liạảnãhu lā yaʿ̊lamu kaẙfa yadẖ̊habu ại̹lay̱ ٱl̊madīnaẗi"],[10,16,"وَيْلٌ لَكِ أَيَّتُهَا ٱلْأَرْضُ إِذَا كَانَ مَلِكُكِ وَلَدًا، وَرُؤَسَاؤُكِ يَأْكُلُونَ فِي ٱلصَّبَاحِ.","waẙluⁿ laki ạảyãtuhā ٱl̊ạảr̊ḍu ại̹dẖā kāna malikuki waladaⁿạ, warūảsāwủki yā̊̉kulūna fī ٱlṣãbāḥi."],[10,17,"طُوبَى لَكِ أَيَّتُهَا ٱلْأَرْضُ إِذَا كَانَ مَلِكُكِ ٱبْنَ شُرَفَاءَ، وَرُؤَسَاؤُكِ يَأْكُلُونَ فِي ٱلْوَقْتِ لِلْقُوَّةِ لَا لِلسُّكْرِ.","ṭūbay̱ laki ạảyãtuhā ٱl̊ạảr̊ḍu ại̹dẖā kāna malikuki ٱb̊na sẖurafāʾa, warūảsāwủki yā̊̉kulūna fī ٱl̊waq̊ti lil̊qūãẗi lā lilsũk̊ri."],[10,18,"بِٱلْكَسَلِ ٱلْكَثِيرِ يَهْبِطُ ٱلسَّقْفُ، وَبِتَدَلِّي ٱلْيَدَيْنِ يَكِفُ ٱلْبَيْتُ.","biٱl̊kasali ٱl̊katẖīri yah̊biṭu ٱlsãq̊fu, wabitadalĩy ٱl̊yadaẙni yakifu ٱl̊baẙtu."],[10,19,"لِلْضَّحِكِ يَعْمَلُونَ وَلِيمَةً، وَٱلْخَمْرُ تُفَرِّحُ ٱلْعَيْشَ. أَمَّا ٱلْفِضَّةُ فَتُحَصِّلُ ٱلْكُلَّ.","lil̊ḍãḥiki yaʿ̊malūna walīmaẗaⁿ, waٱl̊kẖam̊ru tufarĩḥu ٱl̊ʿaẙsẖa. ạảmãạ ٱl̊fiḍãẗu fatuḥaṣĩlu ٱl̊kulã."],[10,20,"لَا تَسُبَّ ٱلْمَلِكَ وَلَا فِي فِكْرِكَ، وَلَا تَسُبَّ ٱلْغَنِيَّ فِي مَضْجَعِكَ، لِأَنَّ طَيْرَ ٱلسَّمَاءِ يَنْقُلُ ٱلصَّوْتَ، وَذُو ٱلْجَنَاحِ يُخْبِرُ بِٱلْأَمْرِ.","lā tasubã ٱl̊malika walā fī fik̊rika, walā tasubã ٱl̊gẖanīã fī maḍ̊jaʿika, liạảnã ṭaẙra ٱlsãmāʾi yan̊qulu ٱlṣãẘta, wadẖū ٱl̊janāḥi yukẖ̊biru biٱl̊ạảm̊ri."],[11,1,"اِرْمِ خُبْزَكَ عَلَى وَجْهِ ٱلْمِيَاهِ فَإِنَّكَ تَجِدُهُ بَعْدَ أَيَّامٍ كَثِيرَةٍ.","ạir̊mi kẖub̊zaka ʿalay̱ waj̊hi ٱl̊mīāhi fāi̹nãka tajiduhu baʿ̊da ạảyãạmiⁿ katẖīraẗiⁿ."],[11,2,"أَعْطِ نَصِيبًا لِسَبْعَةٍ، وَلِثَمَانِيَةٍ أَيْضًا، لِأَنَّكَ لَسْتَ تَعْلَمُ أَيَّ شَرٍّ يَكُونُ عَلَى ٱلْأَرْضِ.","ạảʿ̊ṭi naṣībaⁿạ lisab̊ʿaẗiⁿ, walitẖamānīaẗiⁿ ạảẙḍaⁿạ, liạảnãka las̊ta taʿ̊lamu ạảyã sẖariⁿ̃ yakūnu ʿalay̱ ٱl̊ạảr̊ḍi."],[11,3,"إِذَا ٱمْتَلَأَتِ ٱلسُّحُبُ مَطَرًا تُرِيقُهُ عَلَى ٱلْأَرْضِ. وَإِذَا وَقَعَتِ ٱلشَّجَرَةُ نَحْوَ ٱلْجَنُوبِ أَوْ نَحْوَ ٱلشَّمَالِ، فَفِي ٱلْمَوْضِعِ حَيْثُ تَقَعُ ٱلشَّجَرَةُ هُنَاكَ تَكُونُ.","ại̹dẖā ٱm̊talāảti ٱlsũḥubu maṭaraⁿạ turīquhu ʿalay̱ ٱl̊ạảr̊ḍi. wāi̹dẖā waqaʿati ٱlsẖãjaraẗu naḥ̊wa ٱl̊janūbi ạảẘ naḥ̊wa ٱlsẖãmāli, fafī ٱl̊maẘḍiʿi ḥaẙtẖu taqaʿu ٱlsẖãjaraẗu hunāka takūnu."],[11,4,"مَنْ يَرْصُدِ ٱلرِّيحَ لَا يَزْرَعْ، وَمَنْ يُرَاقِبِ ٱلسُّحُبَ لَا يَحْصُدْ.","man̊ yar̊ṣudi ٱlrĩyḥa lā yaz̊raʿ̊, waman̊ yurāqibi ٱlsũḥuba lā yaḥ̊ṣud̊."],[11,5,"كَمَا أَنَّكَ لَسْتَ تَعْلَمُ مَا هِيَ طَرِيقُ ٱلرِّيحِ، وَلَا كَيْفَ ٱلْعِظَامُ فِي بَطْنِ ٱلْحُبْلَى، كَذَلِكَ لَا تَعْلَمُ أَعْمَالَ ٱللهِ ٱلَّذِي يَصْنَعُ ٱلْجَمِيعَ.","kamā ạảnãka las̊ta taʿ̊lamu mā hīa ṭarīqu ٱlrĩyḥi, walā kaẙfa ٱl̊ʿiẓāmu fī baṭ̊ni ٱl̊ḥub̊lay̱, kadẖalika lā taʿ̊lamu ạảʿ̊māla ٱllhi ٱlãdẖī yaṣ̊naʿu ٱl̊jamīʿa."],[11,6,"فِي ٱلصَّبَاحِ ٱزْرَعْ زَرْعَكَ، وَفِي ٱلْمَسَاءِ لَا تَرْخِ يَدَكَ، لِأَنَّكَ لَا تَعْلَمُ أَيُّهُمَا يَنْمُو: هَذَا أَوْ ذَاكَ، أَوْ أَنْ يَكُونَ كِلَاهُمَا جَيِّدَيْنِ سَوَاءً.","fī ٱlṣãbāḥi ٱz̊raʿ̊ zar̊ʿaka, wafī ٱl̊masāʾi lā tar̊kẖi yadaka, liạảnãka lā taʿ̊lamu ạảyũhumā yan̊mū: hadẖā ạảẘ dẖāka, ạảẘ ạản̊ yakūna kilāhumā jayĩdaẙni sawāʾaⁿ."],[11,7,"اَلنُّورُ حُلْوٌ، وَخَيْرٌ لِلْعَيْنَيْنِ أَنْ تَنْظُرَا ٱلشَّمْسَ.","ạalnũwru ḥul̊wuⁿ, wakẖaẙruⁿ lil̊ʿaẙnaẙni ạản̊ tan̊ẓurā ٱlsẖãm̊sa."],[11,8,"لِأَنَّهُ إِنْ عَاشَ ٱلْإِنْسَانُ سِنِينَ كَثِيرَةً فَلْيَفْرَحْ فِيهَا كُلِّهَا، وَلْيَتَذَكَّرْ أَيَّامَ ٱلظُّلْمَةِ لِأَنَّهَا تَكُونُ كَثِيرَةً. كُلُّ مَا يَأْتِي بَاطِلٌ.","liạảnãhu ại̹n̊ ʿāsẖa ٱl̊ại̹n̊sānu sinīna katẖīraẗaⁿ fal̊yaf̊raḥ̊ fīhā kulĩhā, wal̊yatadẖakãr̊ ạảyãạma ٱlẓũl̊maẗi liạảnãhā takūnu katẖīraẗaⁿ. kulũ mā yā̊̉tī bāṭiluⁿ."],[11,9,"اِفْرَحْ أَيُّهَا ٱلشَّابُّ في حَدَاثَتِكَ، وَلْيَسُرَّكَ قَلْبُكَ فِي أَيَّامِ شَبَابِكَ، وَٱسْلُكْ فِي طُرُقِ قَلْبِكَ وَبِمَرْأَى عَيْنَيْكَ، وَٱعْلَمْ أَنَّهُ عَلَى هَذِهِ ٱلْأُمُورِ كُلِّهَا يَأْتِي بِكَ ٱللهُ إِلَى ٱلدَّيْنُونَةِ.","ạif̊raḥ̊ ạảyũhā ٱlsẖãạbũ fy ḥadātẖatika, wal̊yasurãka qal̊buka fī ạảyãạmi sẖabābika, waٱs̊luk̊ fī ṭuruqi qal̊bika wabimar̊ạảy̱ ʿaẙnaẙka, waٱʿ̊lam̊ ạảnãhu ʿalay̱ hadẖihi ٱl̊ạủmūri kulĩhā yā̊̉tī bika ٱllhu ại̹lay̱ ٱldãẙnūnaẗi."],[11,10,"فَٱنْزِعِ ٱلْغَمَّ مِنْ قَلْبِكَ، وَأَبْعِدِ ٱلشَّرَّ عَنْ لَحْمِكَ، لِأَنَّ ٱلْحَدَاثَةَ وَٱلشَّبَابَ بَاطِلَانِ.","faٱn̊ziʿi ٱl̊gẖamã min̊ qal̊bika, wāảb̊ʿidi ٱlsẖãrã ʿan̊ laḥ̊mika, liạảnã ٱl̊ḥadātẖaẗa waٱlsẖãbāba bāṭilāni."],[12,1,"فَٱذْكُرْ خَالِقَكَ فِي أَيَّامِ شَبَابِكَ، قَبْلَ أَنْ تَأْتِيَ أَيَّامُ ٱلشَّرِّ أَوْ تَجِيءَ ٱلسِّنُونَ إِذْ تَقُولُ: «لَيْسَ لِي فِيهَا سُرُورٌ».","faٱdẖ̊kur̊ kẖāliqaka fī ạảyãạmi sẖabābika, qab̊la ạản̊ tā̊̉tīa ạảyãạmu ٱlsẖãrĩ ạảẘ tajīʾa ٱlsĩnūna ại̹dẖ̊ taqūlu: «laẙsa lī fīhā surūruⁿ»."],[12,2,"قَبْلَ مَا تَظْلُمُ ٱلشَّمْسُ وَٱلنُّورُ وَٱلْقَمَرُ وَٱلنُّجُومُ، وَتَرْجِعُ ٱلسُّحُبُ بَعْدَ ٱلْمَطَرِ.","qab̊la mā taẓ̊lumu ٱlsẖãm̊su waٱlnũwru waٱl̊qamaru waٱlnũjūmu, watar̊jiʿu ٱlsũḥubu baʿ̊da ٱl̊maṭari."],[12,3,"فِي يَوْمٍ يَتَزَعْزَعُ فِيهِ حَفَظَةُ ٱلْبَيْتِ، وَتَتَلَوَّى رِجَالُ ٱلْقُوَّةِ، وَتَبْطُلُ ٱلطَّوَاحِنُ لِأَنَّهَا قَلَّتْ، وَتُظْلِمُ ٱلنَّوَاظِرُ مِنَ ٱلشَّبَابِيكِ.","fī yaẘmiⁿ yatazaʿ̊zaʿu fīhi ḥafaẓaẗu ٱl̊baẙti, watatalawãy̱ rijālu ٱl̊qūãẗi, watab̊ṭulu ٱlṭãwāḥinu liạảnãhā qalãt̊, watuẓ̊limu ٱlnãwāẓiru mina ٱlsẖãbābīki."],[12,4,"وَتُغْلَقُ ٱلْأَبْوَابُ فِي ٱلسُّوقِ. حِينَ يَنْخَفِضُ صَوْتُ ٱلْمِطْحَنَةِ، وَيَقُومُ لِصَوْتِ ٱلْعُصْفُورِ، وَتُحَطُّ كُلُّ بَنَاتِ ٱلْغِنَاءِ.","watugẖ̊laqu ٱl̊ạảb̊wābu fī ٱlsũwqi. ḥīna yan̊kẖafiḍu ṣaẘtu ٱl̊miṭ̊ḥanaẗi, wayaqūmu liṣaẘti ٱl̊ʿuṣ̊fūri, watuḥaṭũ kulũ banāti ٱl̊gẖināʾi."],[12,5,"وَأَيْضًا يَخَافُونَ مِنَ ٱلْعَالِي، وَفِي ٱلطَّرِيقِ أَهْوَالٌ، وَٱللَّوْزُ يُزْهِرُ، وَٱلْجُنْدُبُ يُسْتَثْقَلُ، وَٱلشَّهْوَةُ تَبْطُلُ. لِأَنَّ ٱلْإِنْسَانَ ذَاهِبٌ إِلَى بَيْتِهِ ٱلْأَبَدِيِّ، وَٱلنَّادِبُونَ يَطُوفُونَ فِي ٱلسُّوقِ.","wāảẙḍaⁿạ yakẖāfūna mina ٱl̊ʿālī, wafī ٱlṭãrīqi ạảh̊wāluⁿ, waٱllãẘzu yuz̊hiru, waٱl̊jun̊dubu yus̊tatẖ̊qalu, waٱlsẖãh̊waẗu tab̊ṭulu. liạảnã ٱl̊ại̹n̊sāna dẖāhibuⁿ ại̹lay̱ baẙtihi ٱl̊ạảbadīĩ, waٱlnãạdibūna yaṭūfūna fī ٱlsũwqi."],[12,6,"قَبْلَ مَا يَنْفَصِمُ حَبْلُ ٱلْفِضَّةِ، أَوْ يَنْسَحِقُ كُوزُ ٱلذَّهَبِ، أَوْ تَنْكَسِرُ ٱلْجَرَّةُ عَلَى ٱلْعَيْنِ، أَوْ تَنْقَصِفُ ٱلْبَكَرَةُ عِنْدَ ٱلْبِئْرِ.","qab̊la mā yan̊faṣimu ḥab̊lu ٱl̊fiḍãẗi, ạảẘ yan̊saḥiqu kūzu ٱldẖãhabi, ạảẘ tan̊kasiru ٱl̊jarãẗu ʿalay̱ ٱl̊ʿaẙni, ạảẘ tan̊qaṣifu ٱl̊bakaraẗu ʿin̊da ٱl̊bī̊̉ri."],[12,7,"فَيَرْجِعُ ٱلتُّرَابُ إِلَى ٱلْأَرْضِ كَمَا كَانَ، وَتَرْجِعُ ٱلرُّوحُ إِلَى ٱللهِ ٱلَّذِي أَعْطَاهَا.","fayar̊jiʿu ٱltũrābu ại̹lay̱ ٱl̊ạảr̊ḍi kamā kāna, watar̊jiʿu ٱlrũwḥu ại̹lay̱ ٱllhi ٱlãdẖī ạảʿ̊ṭāhā."],[12,8,"بَاطِلُ ٱلْأَبَاطِيلِ، قَالَ ٱلْجَامِعَةُ: ٱلْكُلُّ بَاطِلٌ.","bāṭilu ٱl̊ạảbāṭīli, qāla ٱl̊jāmiʿaẗu: ٱl̊kulũ bāṭiluⁿ."],[12,9,"بَقِيَ أَنَّ ٱلْجَامِعَةَ كَانَ حَكِيمًا، وَأَيْضًا عَلَّمَ ٱلشَّعْبَ عِلْمًا، وَوَزَنَ وَبَحَثَ وَأَتْقَنَ أَمْثَالًا كَثِيرَةً.","baqīa ạảnã ٱl̊jāmiʿaẗa kāna ḥakīmaⁿạ, wāảẙḍaⁿạ ʿalãma ٱlsẖãʿ̊ba ʿil̊maⁿạ, wawazana wabaḥatẖa wāảt̊qana ạảm̊tẖālaⁿạ katẖīraẗaⁿ."],[12,10,"اَلْجَامِعَةُ طَلَبَ أَنْ يَجِدَ كَلِمَاتٍ مُسِرَّةً مَكْتُوبَةً بِٱلِٱسْتِقَامَةِ، كَلِمَاتِ حَقٍّ.","ạal̊jāmiʿaẗu ṭalaba ạản̊ yajida kalimātiⁿ musirãẗaⁿ mak̊tūbaẗaⁿ biٱliٱs̊tiqāmaẗi, kalimāti ḥaqiⁿ̃."],[12,11,"كَلَامُ ٱلْحُكَمَاءِ كَٱلْمَنَاسِيسِ، وَكَأَوْتَادٍ مُنْغَرِزَةٍ، أَرْبَابُ ٱلْجَمَاعَاتِ، قَدْ أُعْطِيَتْ مِنْ رَاعٍ وَاحِدٍ.","kalāmu ٱl̊ḥukamāʾi kaٱl̊manāsīsi, wakāảẘtādiⁿ mun̊gẖarizaẗiⁿ, ạảr̊bābu ٱl̊jamāʿāti, qad̊ ạủʿ̊ṭīat̊ min̊ rāʿiⁿ wāḥidiⁿ."],[12,12,"وَبَقِيَ، فَمِنْ هَذَا يَاٱبْنِي تَحَذَّرْ: لِعَمَلِ كُتُبٍ كَثِيرَةٍ لَا نِهَايَةَ، وَٱلدَّرْسُ ٱلْكَثِيرُ تَعَبٌ لِلْجَسَدِ.","wabaqīa, famin̊ hadẖā yāٱb̊nī taḥadẖãr̊: liʿamali kutubiⁿ katẖīraẗiⁿ lā nihāyaẗa, waٱldãr̊su ٱl̊katẖīru taʿabuⁿ lil̊jasadi."],[12,13,"فَلْنَسْمَعْ خِتَامَ ٱلْأَمْرِ كُلِّهِ: ٱتَّقِ ٱللهَ وَٱحْفَظْ وَصَايَاهُ، لِأَنَّ هَذَا هُوَ ٱلْإِنْسَانُ كُلُّهُ.","fal̊nas̊maʿ̊ kẖitāma ٱl̊ạảm̊ri kulĩhi: ٱtãqi ٱllha waٱḥ̊faẓ̊ waṣāyāhu, liạảnã hadẖā hūa ٱl̊ại̹n̊sānu kulũhu."],[12,14,"لِأَنَّ ٱللهَ يُحْضِرُ كُلَّ عَمَلٍ إِلَى ٱلدَّيْنُونَةِ، عَلَى كُلِّ خَفِيٍّ، إِنْ كَانَ خَيْرًا أَوْ شَرًّا.","liạảnã ٱllha yuḥ̊ḍiru kulã ʿamaliⁿ ại̹lay̱ ٱldãẙnūnaẗi, ʿalay̱ kulĩ kẖafīiⁿ̃, ại̹n̊ kāna kẖaẙraⁿạ ạảẘ sẖaraⁿ̃ạ."]],"bis-obbr":[[1,1,"Tok blong buk ya i tok blong wan man we i waes gud long ol fasin blong wol ya. Man ya i pikinini blong King Deved. Hem i king, mo hedkwota blong hem i stap long Jerusalem*.","Tok blong buk ya i tok blong wan man we i waes gud long ol fasin blong wol ya. Man ya i pikinini blong King Deved. Hem i king, mo hedkwota blong hem i stap long Jerusalem*."],[1,2,"Tok blong man ya i olsem. Hem i talem se, “!Laef blong yumi long wol ya, hem i blong nating nomo! !Tru, mi talem long yufala, olgeta samting blong hem i blong nating nomo!","Tok blong man ya i olsem. Hem i talem se, “!Laef blong yumi long wol ya, hem i blong nating nomo! !Tru, mi talem long yufala, olgeta samting blong hem i blong nating nomo!"],[1,3,"?Long laef ya blong yumi, oltaem yumi stap hadwok we yumi hadwok tumas, be yumi stap kasem wanem long ol hadwok ya blong yumi? !I no gat!","?Long laef ya blong yumi, oltaem yumi stap hadwok we yumi hadwok tumas, be yumi stap kasem wanem long ol hadwok ya blong yumi? !I no gat!"],[1,4,"Ol man oli bon long wol ya, oli stap smoltaem nomo, nao oli ded. Biaen, ol narafala man oli bon, oli stap smoltaem, nao biaen olgeta ya tu oli ded bakegen, be wol ya, hem i stap sem mak nomo, i no jenis nating.","Ol man oli bon long wol ya, oli stap smoltaem nomo, nao oli ded. Biaen, ol narafala man oli bon, oli stap smoltaem, nao biaen olgeta ya tu oli ded bakegen, be wol ya, hem i stap sem mak nomo, i no jenis nating."],[1,5,"Evri dei, san i girap, mo i kam antap, mo i godaon bakegen, nao i goraon gogo, i girap long sem ples bakegen long nekis dei.","Evri dei, san i girap, mo i kam antap, mo i godaon bakegen, nao i goraon gogo, i girap long sem ples bakegen long nekis dei."],[1,6,"Win i blu i go long saot, mo i blu i go long not, nao i stap goraon olsem, gogo i folem rod blong hem i kambak bakegen.","Win i blu i go long saot, mo i blu i go long not, nao i stap goraon olsem, gogo i folem rod blong hem i kambak bakegen."],[1,7,"Oltaem ol reva oli stap ron i godaon long solwota, be solwota i stap sem mak nomo, i no kam fulap we i bitim mak. Oltaem nomo, wota i stap gobak long ples we i kamaot long hem fastaem, nao i folem rod blong hem, i stap ron i godaon bakegen.","Oltaem ol reva oli stap ron i godaon long solwota, be solwota i stap sem mak nomo, i no kam fulap we i bitim mak. Oltaem nomo, wota i stap gobak long ples we i kamaot long hem fastaem, nao i folem rod blong hem, i stap ron i godaon bakegen."],[1,8,"Evri samting i stap mekem yumi taed tumas we i no blong talem. Yumi stap luk ol samting long ae blong yumi gogo, be neva yumi talem se i naf ya. Yumi stap harem ol samting long sora blong yumi gogo, be neva yumi talem se i naf ya.","Evri samting i stap mekem yumi taed tumas we i no blong talem. Yumi stap luk ol samting long ae blong yumi gogo, be neva yumi talem se i naf ya. Yumi stap harem ol samting long sora blong yumi gogo, be neva yumi talem se i naf ya."],[1,9,"Wanem samting we i kamtru bifo, be bambae i stap kamtru bakegen. Wanem samting we oli wokem bifo, be bambae oli stap wokem bakegen. Long wol ya, i no gat wan niufala samting nating we i save kamtru.","Wanem samting we i kamtru bifo, be bambae i stap kamtru bakegen. Wanem samting we oli wokem bifo, be bambae oli stap wokem bakegen. Long wol ya, i no gat wan niufala samting nating we i save kamtru."],[1,10,"Oltaem ol man oli stap talem se, ‘!Yufala i luk! !I gat wan niufala samting ya!’ !Be giaman ya! Samting ya i stap bifo finis, yumi ya yumi bon biaen.","Oltaem ol man oli stap talem se, ‘!Yufala i luk! !I gat wan niufala samting ya!’ !Be giaman ya! Samting ya i stap bifo finis, yumi ya yumi bon biaen."],[1,11,"Ol man naoia oli no save tingbaot ol samting we ol man blong bifo oli mekem, mo ol man long fiuja bambae oli no save tingbaot ol samting we yumi stap mekem, i stat naoia gogo kasem taem blong olgeta.","Ol man naoia oli no save tingbaot ol samting we ol man blong bifo oli mekem, mo ol man long fiuja bambae oli no save tingbaot ol samting we yumi stap mekem, i stat naoia gogo kasem taem blong olgeta."],[1,12,"“Mi mi wan man we mi waes gud long ol samting blong wol ya, mo mi king blong ol laen* blong Isrel*, we hedkwota blong mi i stap long Jerusalem.","“Mi mi wan man we mi waes gud long ol samting blong wol ya, mo mi king blong ol laen* blong Isrel*, we hedkwota blong mi i stap long Jerusalem."],[1,13,"Mi mekem tingting blong mi i strong se bambae mi stap luklukgud long ol fasin we ol man oli stap mekem long wol ya, blong mi save makemgud olgeta. “Laef ya we God i givim long yumi, we yumi stap long hem i stat taem yumi bon, hem i strong we i strong.","Mi mekem tingting blong mi i strong se bambae mi stap luklukgud long ol fasin we ol man oli stap mekem long wol ya, blong mi save makemgud olgeta. “Laef ya we God i givim long yumi, we yumi stap long hem i stat taem yumi bon, hem i strong we i strong."],[1,14,"Mi mi bin gotru long olgeta fasin ya finis we ol man oli stap mekem long wol ya, be mi save talem se ol samting ya i blong nating nomo. I olsem we yumi stap resis olbaot nomo.","Mi mi bin gotru long olgeta fasin ya finis we ol man oli stap mekem long wol ya, be mi save talem se ol samting ya i blong nating nomo. I olsem we yumi stap resis olbaot nomo."],[1,15,"Ol samting we i kruked, yumi no save stretem, mo ol samting we i no stap, oli plante tumas, yumi no save kaontem.","Ol samting we i kruked, yumi no save stretem, mo ol samting we i no stap, oli plante tumas, yumi no save kaontem."],[1,16,"“Nao mi stap tingting mi wan se, ‘O yes, mi mi kam wan haeman finis, mo mi waes moa, mi winim olgeta king we oli bin rul long ples ya fastaem long mi. Mo mi savegud ol fasin blong waes mo ol fasin blong save.’","“Nao mi stap tingting mi wan se, ‘O yes, mi mi kam wan haeman finis, mo mi waes moa, mi winim olgeta king we oli bin rul long ples ya fastaem long mi. Mo mi savegud ol fasin blong waes mo ol fasin blong save.’"],[1,17,"Nao mi mekem tingting blong mi i strong blong faenemaot wanem i defren long fasin we i gat save mo fasin we i krangke, mo wanem i defren long tok blong man we i waes mo tok blong man we i no gat hed. Be mi luk se i olsem we mi stap resis olbaot nomo.","Nao mi mekem tingting blong mi i strong blong faenemaot wanem i defren long fasin we i gat save mo fasin we i krangke, mo wanem i defren long tok blong man we i waes mo tok blong man we i no gat hed. Be mi luk se i olsem we mi stap resis olbaot nomo."],[1,18,"Taem we man i stap kam waes moa, samting ya i stap mekem hem i wari moa, mo taem we hem i stap kasem moa save, save ya i stap mekem hem i harem nogud moa.","Taem we man i stap kam waes moa, samting ya i stap mekem hem i wari moa, mo taem we hem i stap kasem moa save, save ya i stap mekem hem i harem nogud moa."],[2,1,"“Nao mi talem se bambae mi traem kasem hapi taem we mi save harem gud long hem, blong mi save faenemaot se hapi taem ya i olsem wanem, be mi faenemaot se hem tu i blong nating nomo.","“Nao mi talem se bambae mi traem kasem hapi taem we mi save harem gud long hem, blong mi save faenemaot se hapi taem ya i olsem wanem, be mi faenemaot se hem tu i blong nating nomo."],[2,2,"Mo mi faenemaot tu se fasin we man i stap laf tumas, hem tu i krangke, mo ol samting ya we i mekem man i glad oli no save givhan long hem nating.","Mo mi faenemaot tu se fasin we man i stap laf tumas, hem tu i krangke, mo ol samting ya we i mekem man i glad oli no save givhan long hem nating."],[2,3,"Mi mi wantem tumas blong kam waes long evri samting, nao mi go dring waen blong i mekem mi mi hapi. Long tingting blong mi, mi ting se maet fasin ya nao i nambawan rod blong mekem mi mi harem gud long sotfala taem ya we mi gat long wol ya, be nogat.","Mi mi wantem tumas blong kam waes long evri samting, nao mi go dring waen blong i mekem mi mi hapi. Long tingting blong mi, mi ting se maet fasin ya nao i nambawan rod blong mekem mi mi harem gud long sotfala taem ya we mi gat long wol ya, be nogat."],[2,4,"“Long laef blong mi, mi mi mekem plante bigbigfala wok. Mi wokem ol haos blong mi, mo mi mekem ol plantesen blong grep*.","“Long laef blong mi, mi mi mekem plante bigbigfala wok. Mi wokem ol haos blong mi, mo mi mekem ol plantesen blong grep*."],[2,5,"Mi planem plante garen, mo mi wokem plante plantesen blong ol defrenkaen frut.","Mi planem plante garen, mo mi wokem plante plantesen blong ol defrenkaen frut."],[2,6,"Mo mi digim ol wel blong kasem wota blong wasem ol garen blong mi.","Mo mi digim ol wel blong kasem wota blong wasem ol garen blong mi."],[2,7,"Mi gat plante slef* blong mi we mi pem long ol narafala man, mo mi gat plante bakegen we oli bon long ples blong mi. Mo ol sipsip mo ol nani blong mi oli plante we plante. I stat bifo, i kam kasem taem ya, i no gat wan man long Jerusalem* we i gat plante olsem.","Mi gat plante slef* blong mi we mi pem long ol narafala man, mo mi gat plante bakegen we oli bon long ples blong mi. Mo ol sipsip mo ol nani blong mi oli plante we plante. I stat bifo, i kam kasem taem ya, i no gat wan man long Jerusalem* we i gat plante olsem."],[2,8,"Mo mi stap tekem ol silva mo gol blong ol king blong olgeta ples ya we mi stap rul long olgeta, mi karem i kam, nao mi stap hivimap i kam plante long ples blong mi. Mo mi gat ol man mo woman oli stap singsing blong mekem mi mi glad. Mo mi gat plante woman finis, i bitim we man i wantem.","Mo mi stap tekem ol silva mo gol blong ol king blong olgeta ples ya we mi stap rul long olgeta, mi karem i kam, nao mi stap hivimap i kam plante long ples blong mi. Mo mi gat ol man mo woman oli stap singsing blong mekem mi mi glad. Mo mi gat plante woman finis, i bitim we man i wantem."],[2,9,"“Long ol fasin ya, mi mi kam wan bigman, we nem blong mi i hae we i hae. I stat bifo, i kam kasem taem ya, i no gat wan man long Jerusalem we i gat hae nem olsem mi. Mo oltaem nomo, waes ya blong mi i stap givhan gud long mi, neva hem i letem mi mi foldaon.","“Long ol fasin ya, mi mi kam wan bigman, we nem blong mi i hae we i hae. I stat bifo, i kam kasem taem ya, i no gat wan man long Jerusalem we i gat hae nem olsem mi. Mo oltaem nomo, waes ya blong mi i stap givhan gud long mi, neva hem i letem mi mi foldaon."],[2,10,"Nao olgeta samting we mi wantem, mi mi kasem. Mo mi no tanem baksaed nating long ol samting we i save mekem mi mi harem gud. Mi stap glad tumas long ol samting ya we mi bin hadwok from, mo ol samting ya nao we i stap mekem mi mi harem gud, hemia nao pei blong mi.","Nao olgeta samting we mi wantem, mi mi kasem. Mo mi no tanem baksaed nating long ol samting we i save mekem mi mi harem gud. Mi stap glad tumas long ol samting ya we mi bin hadwok from, mo ol samting ya nao we i stap mekem mi mi harem gud, hemia nao pei blong mi."],[2,11,"Be taem mi tingting gud bakegen long ol samting ya we mi bin mekem, we mi stap hadwok tumas from, mi luk we ol hadwok ya blong mi i blong nating nomo. I olsem we mi stap resis olbaot nomo. Mi no faenem wan gud samting nating long hem.","Be taem mi tingting gud bakegen long ol samting ya we mi bin mekem, we mi stap hadwok tumas from, mi luk we ol hadwok ya blong mi i blong nating nomo. I olsem we mi stap resis olbaot nomo. Mi no faenem wan gud samting nating long hem."],[2,12,"Be hemia nao. King i no save mekem wan niufala samting. Oltaem hem i stap mekem ol sem samting ya nomo we ol narafala king we oli stap rul fastaem long hem oli stap mekem. “Nao mi stap luklukgud bakegen long fasin blong waes, wetem fasin blong man we i no kea, mo fasin blong man we i no gat hed.","Be hemia nao. King i no save mekem wan niufala samting. Oltaem hem i stap mekem ol sem samting ya nomo we ol narafala king we oli stap rul fastaem long hem oli stap mekem. “Nao mi stap luklukgud bakegen long fasin blong waes, wetem fasin blong man we i no kea, mo fasin blong man we i no gat hed."],[2,13,"Nao mi luk se fasin blong waes i moa gud, i winim ol krangke fasin ya, olsem we laet i moa gud, i winim tudak.","Nao mi luk se fasin blong waes i moa gud, i winim ol krangke fasin ya, olsem we laet i moa gud, i winim tudak."],[2,14,"Man we i waes i save luksave rod blong hem blong i wokbaot long hem, be man we i no gat hed i stap wokbaot long tudak nomo.","Man we i waes i save luksave rod blong hem blong i wokbaot long hem, be man we i no gat hed i stap wokbaot long tudak nomo."],[2,15,"Be biaen, mi luksave tu se ol samting we i stap kasem man we i no gat hed, bambae oli mas kasem mi tu. ?Mi mi waes gud, be wanem rod nao we bambae mi save win long hem, from waes ya blong mi? !I no gat! !Waes ya blong mi i blong nating nomo!","Be biaen, mi luksave tu se ol samting we i stap kasem man we i no gat hed, bambae oli mas kasem mi tu. ?Mi mi waes gud, be wanem rod nao we bambae mi save win long hem, from waes ya blong mi? !I no gat! !Waes ya blong mi i blong nating nomo!"],[2,16,"Nating we man i waes no i no gat hed, be taem hem i ded, yumi no save tingbaot hem longtaem. Mo long sem fasin, long fiuja, bambae i no gat man we i save tingbaot yumi. Mo man we i waes wetem man we i no gat hed, bambae tufala evriwan i ded.","Nating we man i waes no i no gat hed, be taem hem i ded, yumi no save tingbaot hem longtaem. Mo long sem fasin, long fiuja, bambae i no gat man we i save tingbaot yumi. Mo man we i waes wetem man we i no gat hed, bambae tufala evriwan i ded."],[2,17,"Nao mi luk we gudfala laef ya blong mi i blong nating nomo, from we olgeta samting we mi stap kasem long hem oli no givim wan gud samting nating long mi, oli stap givim trabol nomo. Laef ya i blong nating nomo. Mi luk se i olsem we mi stap resis olbaot nomo.","Nao mi luk we gudfala laef ya blong mi i blong nating nomo, from we olgeta samting we mi stap kasem long hem oli no givim wan gud samting nating long mi, oli stap givim trabol nomo. Laef ya i blong nating nomo. Mi luk se i olsem we mi stap resis olbaot nomo."],[2,18,"“Ol samting ya we mi stap wok strong long hem, we mi kasem finis, bambae oli no givhan long mi nating, from we mi save se bambae mi livim olgeta i stap, oli blong man we bambae i tekem ples blong mi.","“Ol samting ya we mi stap wok strong long hem, we mi kasem finis, bambae oli no givhan long mi nating, from we mi save se bambae mi livim olgeta i stap, oli blong man we bambae i tekem ples blong mi."],[2,19,"?Be man ya, maet i waes gud no i no gat hed, hu i save? Be bambae hem i kasem olgeta samting ya we mi mi hadwok long hem, wetem olgeta samting we mi kasem from waes blong mi long wol ya. Ol hadwok ya i blong nating nomo.","?Be man ya, maet i waes gud no i no gat hed, hu i save? Be bambae hem i kasem olgeta samting ya we mi mi hadwok long hem, wetem olgeta samting we mi kasem from waes blong mi long wol ya. Ol hadwok ya i blong nating nomo."],[2,20,"Ol samting ya i mekem mi mi sore tumas from we mi bin hadwok tumas long olgeta.","Ol samting ya i mekem mi mi sore tumas from we mi bin hadwok tumas long olgeta."],[2,21,"Fasin ya we man i stap hadwok tumas long wan samting long olgeta waes mo save mo gudhan blong hem, be biaen i mas livim i stap, nao wan narafala man we i no mekem wan wok nating long hem i kam tekem, hem i no stret nating. Long fasin ya, ol hadwok ya blong yumi i blong nating nomo.","Fasin ya we man i stap hadwok tumas long wan samting long olgeta waes mo save mo gudhan blong hem, be biaen i mas livim i stap, nao wan narafala man we i no mekem wan wok nating long hem i kam tekem, hem i no stret nating. Long fasin ya, ol hadwok ya blong yumi i blong nating nomo."],[2,22,"?Long laef ya blong yumi, oltaem yumi stap wari, mo yumi stap hadwok tumas, be wanem samting bambae yumi kasem long ol hadwok ya? !I no gat!","?Long laef ya blong yumi, oltaem yumi stap wari, mo yumi stap hadwok tumas, be wanem samting bambae yumi kasem long ol hadwok ya? !I no gat!"],[2,23,"Olwe nomo long laef blong yumi, olgeta samting ya we yumi stap mekem oli stap mekem yumi wari nomo, mo yumi stap harem nogud tumas, we long naet, yumi no save slip from. Laef ya we yumi stap long hem i blong nating nomo.","Olwe nomo long laef blong yumi, olgeta samting ya we yumi stap mekem oli stap mekem yumi wari nomo, mo yumi stap harem nogud tumas, we long naet, yumi no save slip from. Laef ya we yumi stap long hem i blong nating nomo."],[2,24,"“I moa gud yumi gohed nomo, yumi stap kakae, yumi stap dring mo yumi stap glad long ol samting ya we yumi stap kasem. Hemia nomo i gudfala rod blong man i folem. Be mi save tu se ol samting ya, God nomo i givim.","“I moa gud yumi gohed nomo, yumi stap kakae, yumi stap dring mo yumi stap glad long ol samting ya we yumi stap kasem. Hemia nomo i gudfala rod blong man i folem. Be mi save tu se ol samting ya, God nomo i givim."],[2,25,"?Sipos God i no stap givim ol samting ya long yumi, bambae yumi save kasem kakae olsem wanem? ?Mo bambae yumi save glad olsem wanem?","?Sipos God i no stap givim ol samting ya long yumi, bambae yumi save kasem kakae olsem wanem? ?Mo bambae yumi save glad olsem wanem?"],[2,26,"Oltaem God i stap givim waes mo save mo glad long ol man we oli mekem hem i glad long olgeta. Mo hem i stap mekem ol man nogud oli wok strong tumas blong kasem ol samting we oli wantem, mo blong hivimap olgeta, be i stap mekem olsem blong bambae ol man we oli mekem hem i glad long olgeta oli save kasem ol samting ya. Ol hadwok ya blong yumi i blong nating nomo. I olsem we yumi stap resis olbaot nomo.","Oltaem God i stap givim waes mo save mo glad long ol man we oli mekem hem i glad long olgeta. Mo hem i stap mekem ol man nogud oli wok strong tumas blong kasem ol samting we oli wantem, mo blong hivimap olgeta, be i stap mekem olsem blong bambae ol man we oli mekem hem i glad long olgeta oli save kasem ol samting ya. Ol hadwok ya blong yumi i blong nating nomo. I olsem we yumi stap resis olbaot nomo."],[3,1,"“Olgeta samting we oli stap kamtru long wol ya, oli stap kamtru stret long taem we God i putum.","“Olgeta samting we oli stap kamtru long wol ya, oli stap kamtru stret long taem we God i putum."],[3,2,"“Hem i putum taem blong man i bon, mo i putum taem blong man i ded. Hem i putum taem blong man i planem garen, mo i putum taem blong man i tekemaot kakae long garen.","“Hem i putum taem blong man i bon, mo i putum taem blong man i ded. Hem i putum taem blong man i planem garen, mo i putum taem blong man i tekemaot kakae long garen."],[3,3,"Hem i putum taem blong man i kilim man i ded, mo i putum taem blong man i wokem sikman i gud bakegen. Hem i putum taem blong man i brekemdaon samting, mo i putum taem blong man i wokem samting i gud bakegen.","Hem i putum taem blong man i kilim man i ded, mo i putum taem blong man i wokem sikman i gud bakegen. Hem i putum taem blong man i brekemdaon samting, mo i putum taem blong man i wokem samting i gud bakegen."],[3,4,"Hem i putum taem blong man i harem nogud, mo i putum taem blong man i harem gud bakegen. Hem i putum taem blong man i krae, mo i putum taem blong man i danis.","Hem i putum taem blong man i harem nogud, mo i putum taem blong man i harem gud bakegen. Hem i putum taem blong man i krae, mo i putum taem blong man i danis."],[3,5,"Hem i putum taem blong man i sakem ol ston i go olbaot, mo i putum taem blong man i hivimap ol ston i stap wanples. Hem i putum taem blong man i kis, mo i putum taem blong man i no kis.","Hem i putum taem blong man i sakem ol ston i go olbaot, mo i putum taem blong man i hivimap ol ston i stap wanples. Hem i putum taem blong man i kis, mo i putum taem blong man i no kis."],[3,6,"Hem i putum taem blong man i faenem samting, mo i putum taem blong man i lusum samting. Hem i putum taem blong man i hivimap ol samting, mo i putum taem blong man i sakemaot ol samting.","Hem i putum taem blong man i faenem samting, mo i putum taem blong man i lusum samting. Hem i putum taem blong man i hivimap ol samting, mo i putum taem blong man i sakemaot ol samting."],[3,7,"Hem i putum taem blong man i terem* klos, mo i putum taem blong man i somap klos. Hem i putum taem blong man i stap kwaet, mo i putum taem blong man i tok.","Hem i putum taem blong man i terem* klos, mo i putum taem blong man i somap klos. Hem i putum taem blong man i stap kwaet, mo i putum taem blong man i tok."],[3,8,"Hem i putum taem blong man i laekem narafala man, mo i putum taem blong man i no laekem narafala man, i agensem hem. Hem i putum taem blong man i go mekem faet, mo i putum taem blong man i go mekem pis.","Hem i putum taem blong man i laekem narafala man, mo i putum taem blong man i no laekem narafala man, i agensem hem. Hem i putum taem blong man i go mekem faet, mo i putum taem blong man i go mekem pis."],[3,9,"“?Yumi stap kasem wanem long ol hadwok ya blong yumi?","“?Yumi stap kasem wanem long ol hadwok ya blong yumi?"],[3,10,"Mi mi savegud ol hevi samting we God i givim long yumi, blong yumi karem long laef ya blong yumi.","Mi mi savegud ol hevi samting we God i givim long yumi, blong yumi karem long laef ya blong yumi."],[3,11,"Hem nao i putum stret taem blong ol samting ya oli kamtru. Mo hem i mekem yumi, we long tingting blong yumi, oltaem yumi wantem tumas blong save ol samting we bambae i kamtru long fiuja. Yumi wantem tumas blong savegud ol samting we hem i stap mekem, be neva hem i letem blong yumi save.","Hem nao i putum stret taem blong ol samting ya oli kamtru. Mo hem i mekem yumi, we long tingting blong yumi, oltaem yumi wantem tumas blong save ol samting we bambae i kamtru long fiuja. Yumi wantem tumas blong savegud ol samting we hem i stap mekem, be neva hem i letem blong yumi save."],[3,12,"Nao from samting ya, mi mi luksave se wan rod nomo i stap, we oltaem long laef ya blong yumi, yumi mas traehad blong stap long gudfala laef, mo blong mekem ol gudfala fasin.","Nao from samting ya, mi mi luksave se wan rod nomo i stap, we oltaem long laef ya blong yumi, yumi mas traehad blong stap long gudfala laef, mo blong mekem ol gudfala fasin."],[3,13,"I gud yumi evriwan i gohed, yumi stap kakae, mo yumi stap dring, mo yumi stap glad long ol samting ya we yumi stap hadwok long hem, from we ol samting ya oli kam long God nomo.","I gud yumi evriwan i gohed, yumi stap kakae, mo yumi stap dring, mo yumi stap glad long ol samting ya we yumi stap hadwok long hem, from we ol samting ya oli kam long God nomo."],[3,14,"“Fasin blong God i no save jenis. Olgeta samting we hem i mekem, mi mi save se bambae oli stap olwe, gogo i no save finis. Yumi no save ademap wan samting long hem, mo yumi no save tekemaot wan samting long hem tu. Mo God i stap mekem olsem blong mekem yumi tinghevi long hem, blong yumi ona long hem.","“Fasin blong God i no save jenis. Olgeta samting we hem i mekem, mi mi save se bambae oli stap olwe, gogo i no save finis. Yumi no save ademap wan samting long hem, mo yumi no save tekemaot wan samting long hem tu. Mo God i stap mekem olsem blong mekem yumi tinghevi long hem, blong yumi ona long hem."],[3,15,"Olgeta samting we oli stap kamtru long laef blong yumi, no we bambae oli save kamtru, be oli olsem ol samting ya nomo we oli stap kamtru bifo. Oltaem, ol samting we God i stap mekem i kamtru, oli stret olsem ol samting ya we hem i mekem olgeta oli kamtru finis.","Olgeta samting we oli stap kamtru long laef blong yumi, no we bambae oli save kamtru, be oli olsem ol samting ya nomo we oli stap kamtru bifo. Oltaem, ol samting we God i stap mekem i kamtru, oli stret olsem ol samting ya we hem i mekem olgeta oli kamtru finis."],[3,16,"“Nao i gat wan narafala samting bakegen we mi mi luk se i nogud. Long wol ya, ol man oli no wantem stret fasin, mo oli no wantem jajem man long stret fasin, oltaem oli stap folem ol rabis fasin nomo.","“Nao i gat wan narafala samting bakegen we mi mi luk se i nogud. Long wol ya, ol man oli no wantem stret fasin, mo oli no wantem jajem man long stret fasin, oltaem oli stap folem ol rabis fasin nomo."],[3,17,"Nao mi stap tingting mi wan se, ‘No, be oli no save win. God bambae i jajem olgeta man. Hem i putum taem blong olgeta samting, mo olgeta wok blong hem bambae oli mas kamtru. Ol stret man wetem ol man nogud bambae oli mas stanap long fes blong hem.’","Nao mi stap tingting mi wan se, ‘No, be oli no save win. God bambae i jajem olgeta man. Hem i putum taem blong olgeta samting, mo olgeta wok blong hem bambae oli mas kamtru. Ol stret man wetem ol man nogud bambae oli mas stanap long fes blong hem.’"],[3,18,"Be biaen, mi luk se God i stap mekem i strong long yumi blong traem yumi, blong soemaot long yumi we yumi sem mak nomo wetem ol anamol.","Be biaen, mi luk se God i stap mekem i strong long yumi blong traem yumi, blong soemaot long yumi we yumi sem mak nomo wetem ol anamol."],[3,19,"Man mo anamol, tufala i sem mak nomo. Man i no save talem se hem i moa gud, i winim anamol, from we laef blong tufala i blong nating nomo. Rod blong ded i stap wet long tufala. Bambae tufala tugeta i mas ded.","Man mo anamol, tufala i sem mak nomo. Man i no save talem se hem i moa gud, i winim anamol, from we laef blong tufala i blong nating nomo. Rod blong ded i stap wet long tufala. Bambae tufala tugeta i mas ded."],[3,20,"Bambae tufala tugeta i mas gobak long graon. Tufala i kamaot long graon, mo bambae tufala i gobak long hem bakegen.","Bambae tufala tugeta i mas gobak long graon. Tufala i kamaot long graon, mo bambae tufala i gobak long hem bakegen."],[3,21,"?Olsem wanem man i save talem se taem hem i ded, spirit blong hem bambae i go antap long heven, be taem anamol i ded, bambae spirit blong hem i godaon long graon?","?Olsem wanem man i save talem se taem hem i ded, spirit blong hem bambae i go antap long heven, be taem anamol i ded, bambae spirit blong hem i godaon long graon?"],[3,22,"Nao from samting ya, mi mi luksave se wan rod nomo i stap blong yumi. I gud yumi stap glad long ol samting ya we yumi stap hadwok long hem. I no gat wan narafala samting we yumi save mekem. I no gat rod blong faenemaot ol samting we bambae i kamtru long ples ya, biaen long taem ya we bambae yumi ded.","Nao from samting ya, mi mi luksave se wan rod nomo i stap blong yumi. I gud yumi stap glad long ol samting ya we yumi stap hadwok long hem. I no gat wan narafala samting we yumi save mekem. I no gat rod blong faenemaot ol samting we bambae i kamtru long ples ya, biaen long taem ya we bambae yumi ded."],[4,1,"“Nao mi lukluk bakegen long ol fasin nogud we i stap gohed long wol ya, we ol man we oli gat paoa oli stap mekem i strong tumas long ol narafala man. Oli stap spolem olgeta, mo oli stap mekem olgeta oli harem nogud, we oli stap krae from, be i no gat man i save givhan long olgeta. Ol man raonabaot oli stap talem se, ‘No, mifala i no save mekem wan samting blong givhan long yufala, from we ol man ya oli strong tumas.’","“Nao mi lukluk bakegen long ol fasin nogud we i stap gohed long wol ya, we ol man we oli gat paoa oli stap mekem i strong tumas long ol narafala man. Oli stap spolem olgeta, mo oli stap mekem olgeta oli harem nogud, we oli stap krae from, be i no gat man i save givhan long olgeta. Ol man raonabaot oli stap talem se, ‘No, mifala i no save mekem wan samting blong givhan long yufala, from we ol man ya oli strong tumas.’"],[4,2,"Nao mi luk se olgeta we oli ded finis oli laki, oli stap gud, i winim olgeta we oli stap laef yet.","Nao mi luk se olgeta we oli ded finis oli laki, oli stap gud, i winim olgeta we oli stap laef yet."],[4,3,"Be ol man we oli no bon yet oli laki moa, i winim olgeta we oli ded finis, wetem olgeta we oli stap laef, from we oli no luk ol fasin nogud blong ol man ya we oli stap spolem ol narafala man long wol ya.","Be ol man we oli no bon yet oli laki moa, i winim olgeta we oli ded finis, wetem olgeta we oli stap laef, from we oli no luk ol fasin nogud blong ol man ya we oli stap spolem ol narafala man long wol ya."],[4,4,"“Mo mi luk tu, stamba blong fasin ya we ol man oli stap wok strong blong kasem plante samting. Oli stap wok strong olsem from we oli jalus tumas long ol narafala man we oli stap raonabaot long olgeta, oli wantem tumas blong winim olgeta. Be fasin ya tu i blong nating nomo. Hemia i olsem we man i stap resis olbaot nomo.","“Mo mi luk tu, stamba blong fasin ya we ol man oli stap wok strong blong kasem plante samting. Oli stap wok strong olsem from we oli jalus tumas long ol narafala man we oli stap raonabaot long olgeta, oli wantem tumas blong winim olgeta. Be fasin ya tu i blong nating nomo. Hemia i olsem we man i stap resis olbaot nomo."],[4,5,"Oli stap talem se fasin ya we man i no wantem wok, i wantem stap nomo olsem, hemia i krangke, bambae man olsem i hanggri gogo i ded.","Oli stap talem se fasin ya we man i no wantem wok, i wantem stap nomo olsem, hemia i krangke, bambae man olsem i hanggri gogo i ded."],[4,6,"Maet tok ya blong olgeta i tru lelebet, be mi mi luk se i nomata we yumi no gat plante samting, be sipos tingting blong yumi i stap gud, yumi no wari, hemia i winim fasin ya we yumi stap hadwok tumas oltaem, be yumi no winim wan samting nating. Fasin ya i olsem we yumi stap resis olbaot nomo.","Maet tok ya blong olgeta i tru lelebet, be mi mi luk se i nomata we yumi no gat plante samting, be sipos tingting blong yumi i stap gud, yumi no wari, hemia i winim fasin ya we yumi stap hadwok tumas oltaem, be yumi no winim wan samting nating. Fasin ya i olsem we yumi stap resis olbaot nomo."],[4,7,"“Mo long laef ya, mi mi luk wan narafala samting tu we i krangke.","“Mo long laef ya, mi mi luk wan narafala samting tu we i krangke."],[4,8,"Samtaem i gat man we i no gat brata blong hem, mo i no gat pikinini blong hem tu, hem wan nomo i stap, be i stap wok strong oltaem nomo. Nating we hem i gat plante samting, be neva hem i save talem se i naf, oltaem i stap wantem moa. Neva hem i save spel blong harem gud lelebet long ol samting ya we hem i gat. ?Be ol samting ya bambae i blong hu? Fasin ya i blong nating nomo, mo i wan fasin we i stap mekem man i harem nogud oltaem nomo.","Samtaem i gat man we i no gat brata blong hem, mo i no gat pikinini blong hem tu, hem wan nomo i stap, be i stap wok strong oltaem nomo. Nating we hem i gat plante samting, be neva hem i save talem se i naf, oltaem i stap wantem moa. Neva hem i save spel blong harem gud lelebet long ol samting ya we hem i gat. ?Be ol samting ya bambae i blong hu? Fasin ya i blong nating nomo, mo i wan fasin we i stap mekem man i harem nogud oltaem nomo."],[4,9,"“Fasin ya we tu man i stap joen wanples blong mekem wan wok, hem i moa gud, i winim we wan man nomo i stap wok, from we wok i save gohed gud moa.","“Fasin ya we tu man i stap joen wanples blong mekem wan wok, hem i moa gud, i winim we wan man nomo i stap wok, from we wok i save gohed gud moa."],[4,10,"Sipos wan long tufala i foldaon, narawan i save givhan long hem blong i girap bakegen. Be sipos wan man we i stap hem wan nomo, taem hem i foldaon, i nogud olgeta, from we i no gat man blong givhan long hem.","Sipos wan long tufala i foldaon, narawan i save givhan long hem blong i girap bakegen. Be sipos wan man we i stap hem wan nomo, taem hem i foldaon, i nogud olgeta, from we i no gat man blong givhan long hem."],[4,11,"Long koltaem, sipos tu man i slip wanples, bambae tufala i save stap wom, be wan man nomo i no save stap wom olsem.","Long koltaem, sipos tu man i slip wanples, bambae tufala i save stap wom, be wan man nomo i no save stap wom olsem."],[4,12,"Plante taem, wan enemi i save kam we wan man nomo i no save winim, be tu man i save joen blong winim hem. Mo rop ya we oli tantanem tri rop i go wanples, hem i no save brok kwik.","Plante taem, wan enemi i save kam we wan man nomo i no save winim, be tu man i save joen blong winim hem. Mo rop ya we oli tantanem tri rop i go wanples, hem i no save brok kwik."],[4,13,"“Sipos king i kam olfala tumas, nao i no moa save harem ol waestok we ol man blong hem oli stap givim long hem, bambae i moa gud oli tekem wan yang boe we i gat hed, oli putumap hem i kam king.","“Sipos king i kam olfala tumas, nao i no moa save harem ol waestok we ol man blong hem oli stap givim long hem, bambae i moa gud oli tekem wan yang boe we i gat hed, oli putumap hem i kam king."],[4,14,"Nating we fastaem, yang boe ya i stap long kalabus, no i puaman we i no gat nem nating, be bambae i moa gud, i winim olfala king ya.","Nating we fastaem, yang boe ya i stap long kalabus, no i puaman we i no gat nem nating, be bambae i moa gud, i winim olfala king ya."],[4,15,"Mo mi luk we olgeta man olbaot long kantri olsem bambae oli glad moa long yang boe ya we i tekem ples blong olfala king.","Mo mi luk we olgeta man olbaot long kantri olsem bambae oli glad moa long yang boe ya we i tekem ples blong olfala king."],[4,16,"Mo nating we king i stap rul long hamas man, be sipos hem i ded, bambae i no gat wan long ol man blong hem, we bambae i stap glad long ol samting ya we hem i mekem. Hae nem ya king i blong nating nomo. I olsem we man i stap resis olbaot nomo.","Mo nating we king i stap rul long hamas man, be sipos hem i ded, bambae i no gat wan long ol man blong hem, we bambae i stap glad long ol samting ya we hem i mekem. Hae nem ya king i blong nating nomo. I olsem we man i stap resis olbaot nomo."],[5,1,"“Taem yu go long haos* blong God, yu mas tingting gud long fasin we yu stap mekem. I moa gud yu go long ples ya blong lanem samting. Fasin ya i moa gud, i winim we yu go blong mekem sakrefaes, olsem we ol man we oli no gat hed oli stap mekem. Olgeta ya oli no save fasin we i stret mo fasin we i no stret.","“Taem yu go long haos* blong God, yu mas tingting gud long fasin we yu stap mekem. I moa gud yu go long ples ya blong lanem samting. Fasin ya i moa gud, i winim we yu go blong mekem sakrefaes, olsem we ol man we oli no gat hed oli stap mekem. Olgeta ya oli no save fasin we i stret mo fasin we i no stret."],[5,2,"Sipos yu wantem talem wan samting, be yu mas tingting gud fastaem, ale, biaen yu tok. Mo i nogud yu kwik blong mekem promes long God. Hem i stap long heven, mo yu yu stap long wol ya, nao i nogud yu stap talem plante samting long hem.","Sipos yu wantem talem wan samting, be yu mas tingting gud fastaem, ale, biaen yu tok. Mo i nogud yu kwik blong mekem promes long God. Hem i stap long heven, mo yu yu stap long wol ya, nao i nogud yu stap talem plante samting long hem."],[5,3,"Sipos yu stap wari tumas, bambae long naet, yu save luk ol drim we bambae oli mekem yu yu fraet moa. Mo long sem fasin, sipos yu stap toktok tumas, bambae yu save talem ol krangke tok.","Sipos yu stap wari tumas, bambae long naet, yu save luk ol drim we bambae oli mekem yu yu fraet moa. Mo long sem fasin, sipos yu stap toktok tumas, bambae yu save talem ol krangke tok."],[5,4,"Sipos yu mekem wan promes long God, bambae yu mas mekem samting ya we yu promes blong mekem. Mo yu mas mekem kwiktaem, from we hem i no glad long krangke man we i save mekem promes be i no save holem.","Sipos yu mekem wan promes long God, bambae yu mas mekem samting ya we yu promes blong mekem. Mo yu mas mekem kwiktaem, from we hem i no glad long krangke man we i save mekem promes be i no save holem."],[5,5,"I moa gud yu no mekem wan promes nating, i winim we yu mekem promes be yu no holem.","I moa gud yu no mekem wan promes nating, i winim we yu mekem promes be yu no holem."],[5,6,"Mo i nogud yu talem ol toktok we bambae i mekem yu yu foldaon long sin, nao biaen, bambae yu mas go talemaot long man blong God bakegen, se yu yu no minim blong mekem olsem. ?From wanem yu wantem mekem God i kros long yu? ?From wanem yu wantem mekem hem i spolem ol samting ya we yu yu bin hadwok from?","Mo i nogud yu talem ol toktok we bambae i mekem yu yu foldaon long sin, nao biaen, bambae yu mas go talemaot long man blong God bakegen, se yu yu no minim blong mekem olsem. ?From wanem yu wantem mekem God i kros long yu? ?From wanem yu wantem mekem hem i spolem ol samting ya we yu yu bin hadwok from?"],[5,7,"Nating we yu stap tingting blong mekem plante samting olsem wanem, no yu stap talem plante toktok olsem wanem, be ol samting ya i blong nating nomo. Yu yu mas tinghevi long God, mo yu mas ona gud long hem.","Nating we yu stap tingting blong mekem plante samting olsem wanem, no yu stap talem plante toktok olsem wanem, be ol samting ya i blong nating nomo. Yu yu mas tinghevi long God, mo yu mas ona gud long hem."],[5,8,"“Sipos yu luk we ol haeman blong gavman oli stap spolem ol puaman, we oli stap blokem olgeta blong oli no kasem raet blong olgeta, no oli no save jajem olgeta long stret fasin, bambae yu no sapraes long samting ya. Ol haeman ya oli no save tinghevi long ol puaman, from we oli stap aninit long ol narafala haeman we oli bos long olgeta, mo oltaem oli mas mekem olgeta ya oli glad. Mo ol narafala haeman ya tu oli stap mekem sem fasin, from we olgeta tu oli gat ol bos blong olgeta bakegen we oli mas mekem olgeta oli glad.","“Sipos yu luk we ol haeman blong gavman oli stap spolem ol puaman, we oli stap blokem olgeta blong oli no kasem raet blong olgeta, no oli no save jajem olgeta long stret fasin, bambae yu no sapraes long samting ya. Ol haeman ya oli no save tinghevi long ol puaman, from we oli stap aninit long ol narafala haeman we oli bos long olgeta, mo oltaem oli mas mekem olgeta ya oli glad. Mo ol narafala haeman ya tu oli stap mekem sem fasin, from we olgeta tu oli gat ol bos blong olgeta bakegen we oli mas mekem olgeta oli glad."],[5,9,"“Nating we man i king no i no gat nem nating, be yumi evriwan i stap hang long ol garen blong yumi blong kasem kakae.","“Nating we man i king no i no gat nem nating, be yumi evriwan i stap hang long ol garen blong yumi blong kasem kakae."],[5,10,"“Sipos yu laekem mane tumas, nating we mane blong yu i plante olsem wanem, be neva yu save talem se yu harem gud, mane blong yu i naf. Mo sipos yu wantem tumas blong kam rijman, neva yu save kasem ol samting we yu yu wantem. Tingting ya i blong nating nomo.","“Sipos yu laekem mane tumas, nating we mane blong yu i plante olsem wanem, be neva yu save talem se yu harem gud, mane blong yu i naf. Mo sipos yu wantem tumas blong kam rijman, neva yu save kasem ol samting we yu yu wantem. Tingting ya i blong nating nomo."],[5,11,"Mo sipos yu stap kam rij moa, ol man we oli stap lukluk long yu blong yu givim kakae long olgeta bambae oli stap kam plante moa. I gat wan poen nomo long fasin ya we yu save win long hem, hemia we yu save talem se yu wan rijman, be hemia nomo.","Mo sipos yu stap kam rij moa, ol man we oli stap lukluk long yu blong yu givim kakae long olgeta bambae oli stap kam plante moa. I gat wan poen nomo long fasin ya we yu save win long hem, hemia we yu save talem se yu wan rijman, be hemia nomo."],[5,12,"Man blong wok we i stap wok strong oltaem, maet hem i kakae we i fulap gud no i no fulap gud, be long naet, hem i save slip gud. Be rijman, hem i no save slip gud, oltaem i stap wekap nomo, from we i stap tingting tumas long ol samting we hem i gat.","Man blong wok we i stap wok strong oltaem, maet hem i kakae we i fulap gud no i no fulap gud, be long naet, hem i save slip gud. Be rijman, hem i no save slip gud, oltaem i stap wekap nomo, from we i stap tingting tumas long ol samting we hem i gat."],[5,13,"“Mi luk wan narafala fasin tu we ol man oli stap mekem long wol ya, we i nogud we i nogud. Oli lego plante gudfala samting long laef blong olgeta, blong oli save putumgud ol mane blong olgeta i stap.","“Mi luk wan narafala fasin tu we ol man oli stap mekem long wol ya, we i nogud we i nogud. Oli lego plante gudfala samting long laef blong olgeta, blong oli save putumgud ol mane blong olgeta i stap."],[5,14,"Be biaen, oli mestem, nao oli spenem mane ya long wan rod we oli no win nating long hem, mo oli no moa gat mane i stap blong livim i blong ol pikinini blong olgeta.","Be biaen, oli mestem, nao oli spenem mane ya long wan rod we oli no win nating long hem, mo oli no moa gat mane i stap blong livim i blong ol pikinini blong olgeta."],[5,15,"Taem yumi bon long wol ya, yumi no karem wan samting i kam, mo taem yumi ded, bambae yumi no save karem wan samting i go wetem yumi. Nating we yumi wokem plante samting, be taem yumi ded, bambae yumi no save karem wan samting nating i go.","Taem yumi bon long wol ya, yumi no karem wan samting i kam, mo taem yumi ded, bambae yumi no save karem wan samting i go wetem yumi. Nating we yumi wokem plante samting, be taem yumi ded, bambae yumi no save karem wan samting nating i go."],[5,16,"Yumi gobak olsem nomo we yumi bon long wol ya. Be fasin ya i no stret nating. I stret blong man i karem sam samting long ol hadwok blong hem, be ol hadwok ya blong yumi i olsem we yumi stap resis olbaot nomo. !Yumi no kasem wan samting nating long hem!","Yumi gobak olsem nomo we yumi bon long wol ya. Be fasin ya i no stret nating. I stret blong man i karem sam samting long ol hadwok blong hem, be ol hadwok ya blong yumi i olsem we yumi stap resis olbaot nomo. !Yumi no kasem wan samting nating long hem!"],[5,17,"Oltaem long laef ya blong yumi, yumi stap kamhom we i let finis, yumi stap kakae long tudak nomo, mo yumi stap harem nogud tumas. Oltaem yumi stap wari, mo yumi stap kros, mo yumi stap sik.","Oltaem long laef ya blong yumi, yumi stap kamhom we i let finis, yumi stap kakae long tudak nomo, mo yumi stap harem nogud tumas. Oltaem yumi stap wari, mo yumi stap kros, mo yumi stap sik."],[5,18,"“Mi mi luksave se nambawan samting we man i save mekem, i blong hem i gohed nomo, i stap kakae mo i stap dring, mo i stap glad long ol samting ya we i stap hadwok long hem long sotfala laef ya we God i givim long hem. Hemia nao rod blong laef blong yumi.","“Mi mi luksave se nambawan samting we man i save mekem, i blong hem i gohed nomo, i stap kakae mo i stap dring, mo i stap glad long ol samting ya we i stap hadwok long hem long sotfala laef ya we God i givim long hem. Hemia nao rod blong laef blong yumi."],[5,19,"Sipos God i givim bigfala graon wetem plante samting long wan man, we i mekem man ya i rijman, mo i letem hem i stap glad long ol samting ya, i gud man ya i stap talem tangkiu long hem from, nao oltaem, bambae i stap glad long ol samting ya we i stap hadwok long hem.","Sipos God i givim bigfala graon wetem plante samting long wan man, we i mekem man ya i rijman, mo i letem hem i stap glad long ol samting ya, i gud man ya i stap talem tangkiu long hem from, nao oltaem, bambae i stap glad long ol samting ya we i stap hadwok long hem."],[5,20,"Nating we man ya i savegud we laef blong hem i sotfala, be bambae i no save wari tumas long samting ya, from we God i letem hem blong i stap glad long ol samting ya we i stap hadwok long hem.","Nating we man ya i savegud we laef blong hem i sotfala, be bambae i no save wari tumas long samting ya, from we God i letem hem blong i stap glad long ol samting ya we i stap hadwok long hem."],[6,1,"“Mi mi luk wan narafala fasin tu we i stap long wol ya, we i nogud tumas, mo i stap spolem ol man.","“Mi mi luk wan narafala fasin tu we i stap long wol ya, we i nogud tumas, mo i stap spolem ol man."],[6,2,"Oltaem, God i stap mekem we man i kam rijman, i gat hae nem, mo i gat plante samting. Man ya i gat olgeta samting we hem i wantem, be biaen, bambae God i no letem blong hem i stap glad long ol samting ya. Bambae wan strenja nomo i kam karem ol samting ya, i stap glad long hem. Laef ya blong yumi i blong nating nomo, mo fasin ya i nogud we i nogud.","Oltaem, God i stap mekem we man i kam rijman, i gat hae nem, mo i gat plante samting. Man ya i gat olgeta samting we hem i wantem, be biaen, bambae God i no letem blong hem i stap glad long ol samting ya. Bambae wan strenja nomo i kam karem ol samting ya, i stap glad long hem. Laef ya blong yumi i blong nating nomo, mo fasin ya i nogud we i nogud."],[6,3,"Sipos wan man i gat longfala laef, mo i gat wan handred pikinini blong hem, be long laef ya, hem i no stap glad, mo biaen, ol pikinini blong hem oli no berem hem long gudfala fasin, be hemia, longfala laef ya blong hem i blong nating nomo. Long tingting blong mi, fasin ya we i kasem hem i nogud moa, i winim fasin ya we i kasem pikinini we i bon we i ded finis.","Sipos wan man i gat longfala laef, mo i gat wan handred pikinini blong hem, be long laef ya, hem i no stap glad, mo biaen, ol pikinini blong hem oli no berem hem long gudfala fasin, be hemia, longfala laef ya blong hem i blong nating nomo. Long tingting blong mi, fasin ya we i kasem hem i nogud moa, i winim fasin ya we i kasem pikinini we i bon we i ded finis."],[6,4,"Pikinini olsem, hem i go lus long tudak, nao ol man oli no moa tingbaot hem bakegen. Hem i bon blong nating nomo.","Pikinini olsem, hem i go lus long tudak, nao ol man oli no moa tingbaot hem bakegen. Hem i bon blong nating nomo."],[6,5,"Neva hem i luk delaet, mo i no save nating se laef i olsem wanem. Wan samting nomo, hem i kasem spel.","Neva hem i luk delaet, mo i no save nating se laef i olsem wanem. Wan samting nomo, hem i kasem spel."],[6,6,"Be long tingting blong mi, nating we olfala ya i stap kasem tu taosen yia, be sipos hem i no stap glad long laef blong hem, fasin ya we i kasem pikinini i moa gud yet, from we tufala evriwan i go long sem ples nomo.","Be long tingting blong mi, nating we olfala ya i stap kasem tu taosen yia, be sipos hem i no stap glad long laef blong hem, fasin ya we i kasem pikinini i moa gud yet, from we tufala evriwan i go long sem ples nomo."],[6,7,"“Oltaem man i stap mekem ol wok blong hem from wan samting nomo, from we i wantem kasem kakae blong hem, be neva i save talem se i kasem plante.","“Oltaem man i stap mekem ol wok blong hem from wan samting nomo, from we i wantem kasem kakae blong hem, be neva i save talem se i kasem plante."],[6,8,"?Wanem samting i mekem laef blong waes man i moa gud i winim laef blong man we i no gat hed? !I no gat! !Laef blong tufala i sem mak nomo! ?Maet wan puaman i savegud ol fasin we i stret blong mekem long fes blong ol man, be save ya bambae i givhan long hem olsem wanem?","?Wanem samting i mekem laef blong waes man i moa gud i winim laef blong man we i no gat hed? !I no gat! !Laef blong tufala i sem mak nomo! ?Maet wan puaman i savegud ol fasin we i stret blong mekem long fes blong ol man, be save ya bambae i givhan long hem olsem wanem?"],[6,9,"Laef ya blong yumi i blong nating nomo. I olsem we yumi stap resis olbaot nomo. I moa gud yumi stap glad long ol samting ya we yumi gat finis, i winim we oltaem yumi stap wantem sam samting moa.","Laef ya blong yumi i blong nating nomo. I olsem we yumi stap resis olbaot nomo. I moa gud yumi stap glad long ol samting ya we yumi gat finis, i winim we oltaem yumi stap wantem sam samting moa."],[6,10,"“Olgeta samting we oli stap kamtru naoia, be God i makemaot olgeta bifo finis se bambae oli olsem. Mo yumi evriwan i save se i no gat man i save go rao long man we i strong moa long hem.","“Olgeta samting we oli stap kamtru naoia, be God i makemaot olgeta bifo finis se bambae oli olsem. Mo yumi evriwan i save se i no gat man i save go rao long man we i strong moa long hem."],[6,11,"Sipos tu man i stap rao longtaem, hemia i no givhan long tufala nating, mo sipos tufala i stap pulum i kam longfala moa, bambae i kam mowas.","Sipos tu man i stap rao longtaem, hemia i no givhan long tufala nating, mo sipos tufala i stap pulum i kam longfala moa, bambae i kam mowas."],[6,12,"Laef blong yumi long wol ya i sotfala tumas, mo i blong nating nomo. ?Olsem wanem bambae yumi save luksave se fasin ya i beswan blong yumi folem? ?Olsem wanem bambae yumi save faenemaot ol samting we bambae i kamtru long wol ya, biaen long taem we bambae yumi ded?","Laef blong yumi long wol ya i sotfala tumas, mo i blong nating nomo. ?Olsem wanem bambae yumi save luksave se fasin ya i beswan blong yumi folem? ?Olsem wanem bambae yumi save faenemaot ol samting we bambae i kamtru long wol ya, biaen long taem we bambae yumi ded?"],[7,1,"“Sipos yu yu gat gud nem long fes blong ol man, hemia i gud moa long yu, i winim we yu putum gudfala senta ya we praes blong hem i antap tumas. Nao dei ya we bambae yu yu ded long hem, bambae hem i bigfala dei moa blong yu, i winim dei ya we yu yu bon long hem.","“Sipos yu yu gat gud nem long fes blong ol man, hemia i gud moa long yu, i winim we yu putum gudfala senta ya we praes blong hem i antap tumas. Nao dei ya we bambae yu yu ded long hem, bambae hem i bigfala dei moa blong yu, i winim dei ya we yu yu bon long hem."],[7,2,"“Sipos yu go long wan haos we dedman i stap long hem, we ol man oli stap krae long hem, hemia i save givhan moa long yu, i winim we yu go long wan haos we i gat lafet long hem, from we yumi ya we i stap laef yet, i stret blong yumi stap tingbaot oltaem, we bambae yumi evriwan i mas ded.","“Sipos yu go long wan haos we dedman i stap long hem, we ol man oli stap krae long hem, hemia i save givhan moa long yu, i winim we yu go long wan haos we i gat lafet long hem, from we yumi ya we i stap laef yet, i stret blong yumi stap tingbaot oltaem, we bambae yumi evriwan i mas ded."],[7,3,"“Sipos yu stap harem nogud, hemia i save givhan moa long yu, i winim we yu stap laf. Maet samting ya i mekem fes blong yu i kam nogud, be i save mekem yu yu lan tu, nao bambae yu gat save moa.","“Sipos yu stap harem nogud, hemia i save givhan moa long yu, i winim we yu stap laf. Maet samting ya i mekem fes blong yu i kam nogud, be i save mekem yu yu lan tu, nao bambae yu gat save moa."],[7,4,"“Man we i wantem glad oltaem nomo, hem i no gat hed. Man we i gat hed, hem i no save fogetem se bambae hem i save ded.","“Man we i wantem glad oltaem nomo, hem i no gat hed. Man we i gat hed, hem i no save fogetem se bambae hem i save ded."],[7,5,"“Sipos ol waes man oli stap tok long yu blong stretem yu, hemia i save givhan moa long yu, i winim we ol man we oli no gat hed oli stap sing blong presem yu.","“Sipos ol waes man oli stap tok long yu blong stretem yu, hemia i save givhan moa long yu, i winim we ol man we oli no gat hed oli stap sing blong presem yu."],[7,6,"“Taem wan man we i no gat hed i laf, hemia i no minim wan samting nating, i olsem we yu sakem ol drae stik i go long faea, nao oli stap faefaerap.","“Taem wan man we i no gat hed i laf, hemia i no minim wan samting nating, i olsem we yu sakem ol drae stik i go long faea, nao oli stap faefaerap."],[7,7,"“Nating we yu yu waes tumas, be sipos yu stap giaman long wan man nao yu stap stil long hem, hemia, yu stap mekem yu yu kam olsem man we i no gat hed. Mo sipos yu letem wan man i pem yu blong yu mekem wan samting we i no stret, hemia, yu spolem gudnem blong yu nomo.","“Nating we yu yu waes tumas, be sipos yu stap giaman long wan man nao yu stap stil long hem, hemia, yu stap mekem yu yu kam olsem man we i no gat hed. Mo sipos yu letem wan man i pem yu blong yu mekem wan samting we i no stret, hemia, yu spolem gudnem blong yu nomo."],[7,8,"“Taem man i statem wan wok, hem i save glad long hem, be taem hem i finisim, bambae i save harem gud moa. Mo man we i gat longfala tingting, hem i moa gud, i winim man we i stap flas.","“Taem man i statem wan wok, hem i save glad long hem, be taem hem i finisim, bambae i save harem gud moa. Mo man we i gat longfala tingting, hem i moa gud, i winim man we i stap flas."],[7,9,"“I nogud yu yu man blong kros kwik. Mo i nogud yu holem kros blong yu i stap longtaem, from we hemia i fasin blong man we i no gat hed.","“I nogud yu yu man blong kros kwik. Mo i nogud yu holem kros blong yu i stap longtaem, from we hemia i fasin blong man we i no gat hed."],[7,10,"“I nogud yu stap talem se, ‘?From wanem we bifo ol samting i gud we i gud, i winim tede?’ Hemia i no tok blong man we i gat hed ya.","“I nogud yu stap talem se, ‘?From wanem we bifo ol samting i gud we i gud, i winim tede?’ Hemia i no tok blong man we i gat hed ya."],[7,11,"“Waes i wan samting we i gud yumi evriwan i kasem. Sipos yu kasem waes, hemia i olsem we yu kasem graon blong papa blong yu wetem olgeta samting we i stap long hem, we hem i promes finis, se bambae i blong yu.","“Waes i wan samting we i gud yumi evriwan i kasem. Sipos yu kasem waes, hemia i olsem we yu kasem graon blong papa blong yu wetem olgeta samting we i stap long hem, we hem i promes finis, se bambae i blong yu."],[7,12,"Mane i save givhan blong mekem laef blong yu i gud, be waes tu i save mekem samting ya, mo hem i save go moa. Hem i save mekem we laef blong yu bambae i stap gud olwe.","Mane i save givhan blong mekem laef blong yu i gud, be waes tu i save mekem samting ya, mo hem i save go moa. Hem i save mekem we laef blong yu bambae i stap gud olwe."],[7,13,"“Yu mas tingting gud long ol samting we God i stap mekem. Sipos God i mekem wan samting i kruked, bambae i no gat man i save stretem.","“Yu mas tingting gud long ol samting we God i stap mekem. Sipos God i mekem wan samting i kruked, bambae i no gat man i save stretem."],[7,14,"Sipos evri samting long laef blong yu oli stap ron gud nomo, i gud yu glad long hem. Be sipos oli no ron gud, i gat tu samting we i moa gud yu stap tingbaot, wan we man i harem gud, mo narawan, we man i harem nogud. Tufala samting ya, God nomo i mekem, mo i no gat man i save makem wanem samting bambae i kamtru.","Sipos evri samting long laef blong yu oli stap ron gud nomo, i gud yu glad long hem. Be sipos oli no ron gud, i gat tu samting we i moa gud yu stap tingbaot, wan we man i harem gud, mo narawan, we man i harem nogud. Tufala samting ya, God nomo i mekem, mo i no gat man i save makem wanem samting bambae i kamtru."],[7,15,"“Laef ya blong mi i blong nating nomo, be long taem ya we mi mi stap, mi luk plante samting. Mi luk we samtaem, gudfala man i save ded kwiktaem nomo, mo man we i nogud i save stap gogo i olfala gud.","“Laef ya blong mi i blong nating nomo, be long taem ya we mi mi stap, mi luk plante samting. Mi luk we samtaem, gudfala man i save ded kwiktaem nomo, mo man we i nogud i save stap gogo i olfala gud."],[7,16,"From samting ya, i nogud yu stap traehad tumas blong kam gud moa, no blong kam waes moa, gogo i bitim mak. ?From wanem yu wantem kilim yu yu ded?","From samting ya, i nogud yu stap traehad tumas blong kam gud moa, no blong kam waes moa, gogo i bitim mak. ?From wanem yu wantem kilim yu yu ded?"],[7,17,"Mo long sem fasin tu, i nogud yu letem yu yu kam nogud we i nogud, no yu kam krangke we i krangke. ?From wanem yu wantem ded we i no kasem taem blong yu yet?","Mo long sem fasin tu, i nogud yu letem yu yu kam nogud we i nogud, no yu kam krangke we i krangke. ?From wanem yu wantem ded we i no kasem taem blong yu yet?"],[7,18,"I nogud yu go tumas long tufala rod ya, i moa gud yu stap samples long medel. Sipos yu yu man blong ona long God, bambae yu no save lus.","I nogud yu go tumas long tufala rod ya, i moa gud yu stap samples long medel. Sipos yu yu man blong ona long God, bambae yu no save lus."],[7,19,"“Waestok i save givhan moa long man, i winim we ten lida oli save givhan long wan taon.","“Waestok i save givhan moa long man, i winim we ten lida oli save givhan long wan taon."],[7,20,"“I no gat man long wol ya se i no save mekem mastik, we oltaem i stap mekem i stret nomo.","“I no gat man long wol ya se i no save mekem mastik, we oltaem i stap mekem i stret nomo."],[7,21,"“I nogud yu stap lesin long evri toktok we man i stap talem. Maet samtaem yu harem man blong wok blong yu i singaot* trabol i kam long yu.","“I nogud yu stap lesin long evri toktok we man i stap talem. Maet samtaem yu harem man blong wok blong yu i singaot* trabol i kam long yu."],[7,22,"Mo yu save, plante taem, yu tu yu singaot trabol i kam long narafala man.","Mo yu save, plante taem, yu tu yu singaot trabol i kam long narafala man."],[7,23,"“Mi mi stap yusum waes ya we mi gat, blong traem ol tok ya we mi stap talem. Oltaem mi mi wantem tumas blong kam waes man tru, be mi no naf long hem, samting ya i strong tumas long mi.","“Mi mi stap yusum waes ya we mi gat, blong traem ol tok ya we mi stap talem. Oltaem mi mi wantem tumas blong kam waes man tru, be mi no naf long hem, samting ya i strong tumas long mi."],[7,24,"?Olsem wanem bambae man i save faenemaot mining blong laef? Mining blong hem i haed we i haed, mo i had blong yumi luksave.","?Olsem wanem bambae man i save faenemaot mining blong laef? Mining blong hem i haed we i haed, mo i had blong yumi luksave."],[7,25,"Be nating, oltaem long laef blong mi, mi stap mekem tingting blong mi i strong blong mi lan, mo blong mi gat save. Mi mi wantem tumas blong kasem waes, mo blong faenem ol ansa blong ol kwestin blong mi. Mi wantem savegud from wanem man nogud i stap mekem i krangke, mo from wanem man we i no gat hed i stap mekem i krangke moa.","Be nating, oltaem long laef blong mi, mi stap mekem tingting blong mi i strong blong mi lan, mo blong mi gat save. Mi mi wantem tumas blong kasem waes, mo blong faenem ol ansa blong ol kwestin blong mi. Mi wantem savegud from wanem man nogud i stap mekem i krangke, mo from wanem man we i no gat hed i stap mekem i krangke moa."],[7,26,"“Mi mi luk wan samting we i save mekem man i harem nogud moa, i winim ded. Hemia woman ya we fasin blong hem blong laekem man i holem man olsem wan trap, no wan net, mo we han blong hem we i putum i goraon long man i holem hem olsem wan jen. Man we i stap mekem ol samting we God i glad long hem, hem nomo i save ronwe long woman olsem, be man nogud i no save aot long trap blong hem.","“Mi mi luk wan samting we i save mekem man i harem nogud moa, i winim ded. Hemia woman ya we fasin blong hem blong laekem man i holem man olsem wan trap, no wan net, mo we han blong hem we i putum i goraon long man i holem hem olsem wan jen. Man we i stap mekem ol samting we God i glad long hem, hem nomo i save ronwe long woman olsem, be man nogud i no save aot long trap blong hem."],[7,27,"Mi mi stap faenemaot ol samting ya smosmol nomo, long taem ya we mi stap lukaot ol ansa blong ol kwestin ya.","Mi mi stap faenemaot ol samting ya smosmol nomo, long taem ya we mi stap lukaot ol ansa blong ol kwestin ya."],[7,28,"Mi stap lukaot ol narafala ansa, be mi no faenem wan nating. Long saed blong man, mi mi faenem we i gat wanwan nomo we mi save ona long olgeta, be long saed blong woman, mi no faenem wan woman nating we mi save ona long hem.","Mi stap lukaot ol narafala ansa, be mi no faenem wan nating. Long saed blong man, mi mi faenem we i gat wanwan nomo we mi save ona long olgeta, be long saed blong woman, mi no faenem wan woman nating we mi save ona long hem."],[7,29,"Mi faenemaot se taem God i mekem yumi, yumi stret nomo, be yumi nomo, yumi stap mekem laef blong yumi i paspas olbaot.","Mi faenemaot se taem God i mekem yumi, yumi stret nomo, be yumi nomo, yumi stap mekem laef blong yumi i paspas olbaot."],[8,1,"“Man we i waes, hem nomo i save mining blong ol samting. Waes ya i mekem we hem i no moa save mekem fes blong hem i strong long ol narafala man, oltaem hem i glad blong luk olgeta.","“Man we i waes, hem nomo i save mining blong ol samting. Waes ya i mekem we hem i no moa save mekem fes blong hem i strong long ol narafala man, oltaem hem i glad blong luk olgeta."],[8,2,"“Yu mas mekem ol samting we king i talem, from we yu yu promes* long God blong mekem olsem.","“Yu mas mekem ol samting we king i talem, from we yu yu promes* long God blong mekem olsem."],[8,3,"Be i nogud yu stap klosap long hem oltaem, i moa gud yu gowe long hem, from we taem hem i kros, hem i save mekem wanem samting we hem i wantem.","Be i nogud yu stap klosap long hem oltaem, i moa gud yu gowe long hem, from we taem hem i kros, hem i save mekem wanem samting we hem i wantem."],[8,4,"King i gat raet blong mekem ol samting we hem i wantem mekem, mo i no gat man i save tok long hem, se from wanem hem i mekem ol samting ya.","King i gat raet blong mekem ol samting we hem i wantem mekem, mo i no gat man i save tok long hem, se from wanem hem i mekem ol samting ya."],[8,5,"Sipos yu obei long ol tok blong hem, bambae yu save stap gud. Man we i waes, hem bambae i savegud prapa rod blong mekem olsem, mo stret taem blong mekem.","Sipos yu obei long ol tok blong hem, bambae yu save stap gud. Man we i waes, hem bambae i savegud prapa rod blong mekem olsem, mo stret taem blong mekem."],[8,6,"I gat stret taem mo stret fasin blong wokem evri samting, be yumi save smol nomo.","I gat stret taem mo stret fasin blong wokem evri samting, be yumi save smol nomo."],[8,7,"I no gat wan long yumi we i save wanem samting bambae i kamtru, mo i no gat wan man we i save talemaot ol samting olsem long yumi.","I no gat wan long yumi we i save wanem samting bambae i kamtru, mo i no gat wan man we i save talemaot ol samting olsem long yumi."],[8,8,"I no gat wan man we i save holem hem i stap blong i no ded, mo i no gat man we i save seftem dei blong ded blong hem. Hemia i wan faet we yumi no save ronwe long hem. Yumi no save giaman long ded blong i no kam long yumi.","I no gat wan man we i save holem hem i stap blong i no ded, mo i no gat man we i save seftem dei blong ded blong hem. Hemia i wan faet we yumi no save ronwe long hem. Yumi no save giaman long ded blong i no kam long yumi."],[8,9,"“Long wol ya, sam man oli gat paoa, mo ol narafala man oli stap aninit long olgeta, oli stap harem nogud, mo taem mi stap tingbaot ol samting we oli stap kamtru long wol ya, mi luk ol fasin ya we mi stap tokbaot.","“Long wol ya, sam man oli gat paoa, mo ol narafala man oli stap aninit long olgeta, oli stap harem nogud, mo taem mi stap tingbaot ol samting we oli stap kamtru long wol ya, mi luk ol fasin ya we mi stap tokbaot."],[8,10,"Wan fasin we mi mi luk i olsem. Taem man nogud i ded, ol man ples blong hem oli go berem hem long beregraon, mo taem oli stap wokbaot yet long rod blong kambak, nating we ol man ples blong hem nomo we oli savegud fasin blong hem, be oli stap presem hem, se hem i wan gudfala man. Fasin ya i blong nating nomo.","Wan fasin we mi mi luk i olsem. Taem man nogud i ded, ol man ples blong hem oli go berem hem long beregraon, mo taem oli stap wokbaot yet long rod blong kambak, nating we ol man ples blong hem nomo we oli savegud fasin blong hem, be oli stap presem hem, se hem i wan gudfala man. Fasin ya i blong nating nomo."],[8,11,"“Taem ol man we oli stap brekem loa oli no kasem panis kwiktaem, tingting blong olgeta man oli stap kam fulap long ol plan blong mekem ol samting nogud.","“Taem ol man we oli stap brekem loa oli no kasem panis kwiktaem, tingting blong olgeta man oli stap kam fulap long ol plan blong mekem ol samting nogud."],[8,12,"Mi save we ol man oli stap talem se, ‘Man we i stap obei long God, olgeta samting long laef blong hem bambae oli stap ron gud, be laef blong man nogud bambae i no olsem,’ be toktok ya i blong giaman nomo. Mo mi save we oli stap talem tu se, ‘Ol man nogud, laef blong olgeta bambae i no olsem sado we i stap kam longfala moa, bambae oli ded taem oli yangfala yet, from we oli no save ona long God, mo oli no save obei long hem,’ be toktok ya tu i no tru, i blong nating nomo. Plante taem, man nogud i save mekem wan handred samting nogud, be i stap laef yet. Yu traem luk fasin ya we i stap kamtru long wol ya. Plante taem, ol stret man oli kasem panis blong ol man nogud, mo ol man nogud oli kasem pei blong ol stret man. Mi mi talem finis, se ol samting ya i blong nating nomo.","Mi save we ol man oli stap talem se, ‘Man we i stap obei long God, olgeta samting long laef blong hem bambae oli stap ron gud, be laef blong man nogud bambae i no olsem,’ be toktok ya i blong giaman nomo. Mo mi save we oli stap talem tu se, ‘Ol man nogud, laef blong olgeta bambae i no olsem sado we i stap kam longfala moa, bambae oli ded taem oli yangfala yet, from we oli no save ona long God, mo oli no save obei long hem,’ be toktok ya tu i no tru, i blong nating nomo. Plante taem, man nogud i save mekem wan handred samting nogud, be i stap laef yet. Yu traem luk fasin ya we i stap kamtru long wol ya. Plante taem, ol stret man oli kasem panis blong ol man nogud, mo ol man nogud oli kasem pei blong ol stret man. Mi mi talem finis, se ol samting ya i blong nating nomo.",14],[8,15,"“From ol samting ya, mi mi luk finis se i no gat narafala rod, man i mas stap mekem ol fasin ya we oli save mekem hem i harem gud. I gud hem i kakae, mo i dring, mo i gohed long ol fasin we oli save mekem hem i glad long laef ya. Hemia nomo hem i save mekem long laef ya we God i givim long hem long wol ya, we oltaem hem i stap hadwok tumas long hem.","“From ol samting ya, mi mi luk finis se i no gat narafala rod, man i mas stap mekem ol fasin ya we oli save mekem hem i harem gud. I gud hem i kakae, mo i dring, mo i gohed long ol fasin we oli save mekem hem i glad long laef ya. Hemia nomo hem i save mekem long laef ya we God i givim long hem long wol ya, we oltaem hem i stap hadwok tumas long hem."],[8,16,"“Taem mi traem blong kasem save, blong mi savegud ol samting we i stap gohed long wol ya, mi mi faenemaot se nating sipos man i no slip long naet, i stap lukluk gogo kasem delaet, mo i no slip bakegen long dei go kasem tudak,","“Taem mi traem blong kasem save, blong mi savegud ol samting we i stap gohed long wol ya, mi mi faenemaot se nating sipos man i no slip long naet, i stap lukluk gogo kasem delaet, mo i no slip bakegen long dei go kasem tudak,"],[8,17,"be bambae i no save luksave nating ol samting we God i stap wokem. Nating we yumi stap traehad olsem wanem, be bambae yumi no save faenemaot samtaem. Maet ol waes man oli save talem se oli save, be nogat, oli stap giaman nomo.","be bambae i no save luksave nating ol samting we God i stap wokem. Nating we yumi stap traehad olsem wanem, be bambae yumi no save faenemaot samtaem. Maet ol waes man oli save talem se oli save, be nogat, oli stap giaman nomo."],[9,1,"“Mi mi stap tingbaot ol samting ya plante taem, mo mi stap traehad tumas blong faenemaot, nao mi luk se ol waes man mo ol stret man wetem ol wok blong olgeta, mo fasin blong olgeta we oli laekem man, no oli no laekem man, olgeta samting ya oli stap long han blong God nomo. Mo i no gat man we i save ol samting we bambae hem i kasem long laef blong hem.","“Mi mi stap tingbaot ol samting ya plante taem, mo mi stap traehad tumas blong faenemaot, nao mi luk se ol waes man mo ol stret man wetem ol wok blong olgeta, mo fasin blong olgeta we oli laekem man, no oli no laekem man, olgeta samting ya oli stap long han blong God nomo. Mo i no gat man we i save ol samting we bambae hem i kasem long laef blong hem."],[9,2,"Be ol samting ya i blong nating nomo. Ol stret man wetem olgeta we oli no stret, mo ol gud man wetem olgeta we oli nogud, mo ol man we oli ona long God wetem olgeta we oli no save ona long hem, mo ol man we oli stap mekem sakrefaes wetem olgeta we oli no save mekem sakrefaes, be olgeta evriwan bambae oli ded. Ol samting we ol gudfala man oli stap kasem long laef ya, oli no winim ol samting we ol man nogud oli stap kasem. Mo ol man we oli stap talem “Tru Antap” blong soemaot we tok blong olgeta i tru, be ol samting we oli kasem oli no gudfala moa winim ol samting we oli stap kamtru long ol man we oli no save mekem fasin ya.","Be ol samting ya i blong nating nomo. Ol stret man wetem olgeta we oli no stret, mo ol gud man wetem olgeta we oli nogud, mo ol man we oli ona long God wetem olgeta we oli no save ona long hem, mo ol man we oli stap mekem sakrefaes wetem olgeta we oli no save mekem sakrefaes, be olgeta evriwan bambae oli ded. Ol samting we ol gudfala man oli stap kasem long laef ya, oli no winim ol samting we ol man nogud oli stap kasem. Mo ol man we oli stap talem “Tru Antap” blong soemaot we tok blong olgeta i tru, be ol samting we oli kasem oli no gudfala moa winim ol samting we oli stap kamtru long ol man we oli no save mekem fasin ya."],[9,3,"“Olgeta ya evriwan bambae oli ded nomo. Samting ya i no stret we i no stret, i winim olgeta narafala samting we i stap hapen long wol ya. Olgeta man we oli stap long wol ya, oltaem, tingting blong olgeta i fulap long ol samting nogud mo ol krangke fasin, mo biaen, oli go long Hom* blong ol Dedman.","“Olgeta ya evriwan bambae oli ded nomo. Samting ya i no stret we i no stret, i winim olgeta narafala samting we i stap hapen long wol ya. Olgeta man we oli stap long wol ya, oltaem, tingting blong olgeta i fulap long ol samting nogud mo ol krangke fasin, mo biaen, oli go long Hom* blong ol Dedman."],[9,4,"Man we i laef yet, hem i gat plante samting i stap we i save putum tingting blong hem i go long hem. Laeon i strong moa winim dog, be dog we i laef, hem i gud moa i winim laeon we i ded finis.","Man we i laef yet, hem i gat plante samting i stap we i save putum tingting blong hem i go long hem. Laeon i strong moa winim dog, be dog we i laef, hem i gud moa i winim laeon we i ded finis."],[9,5,"Yes, i tru, ol man we oli laef yet oli save se bambae oli ded, be ol man we oli ded finis oli no moa save wan samting. Oli no moa save kasem pei blong ol samting we oli stap mekem, mo ol man oli fogetem olgeta finis.","Yes, i tru, ol man we oli laef yet oli save se bambae oli ded, be ol man we oli ded finis oli no moa save wan samting. Oli no moa save kasem pei blong ol samting we oli stap mekem, mo ol man oli fogetem olgeta finis."],[9,6,"Ol fasin blong olgeta we oli laekem tumas ol man, no oli no laekem olgeta nating oli agens long olgeta, no oli jalus tumas long olgeta, be taem oli ded, ol samting ya oli lus wetem olgeta. Bambae oli no moa save joen bakegen long ol samting ya we oli stap kamtru long wol ya.","Ol fasin blong olgeta we oli laekem tumas ol man, no oli no laekem olgeta nating oli agens long olgeta, no oli jalus tumas long olgeta, be taem oli ded, ol samting ya oli lus wetem olgeta. Bambae oli no moa save joen bakegen long ol samting ya we oli stap kamtru long wol ya."],[9,7,"“I moa gud yumi gohed, yumi kakae blong yumi harem gud, mo yumi dring waen blong tingting blong yumi i glad. Hemia i stret nomo long fes blong God.","“I moa gud yumi gohed, yumi kakae blong yumi harem gud, mo yumi dring waen blong tingting blong yumi i glad. Hemia i stret nomo long fes blong God."],[9,8,"Oltaem yumi mas letem ol man oli luk we yumi stap harem gud, mo fes blong yumi i mas soemaot samting ya.","Oltaem yumi mas letem ol man oli luk we yumi stap harem gud, mo fes blong yumi i mas soemaot samting ya."],[9,9,"“Laef ya long wol we God i givim long yumi, hem i blong nating nomo, be taem yumi stap long hem, i gud yumi wetem ol woman blong yumi we yumi laekem olgeta tumas, yumi stap mekem ol samting we oli save mekem yumi glad. Ol dei blong laef ya long wol oli blong nating nomo. Yumi stap hadwok tumas, mo i gat ol trabol oli stap kasem yumi, be evri dei, yumi mas mekem ol samting we yumi save glad long hem, from we hemia nomo yumi save kasem long laef ya we yumi stap long hem.","“Laef ya long wol we God i givim long yumi, hem i blong nating nomo, be taem yumi stap long hem, i gud yumi wetem ol woman blong yumi we yumi laekem olgeta tumas, yumi stap mekem ol samting we oli save mekem yumi glad. Ol dei blong laef ya long wol oli blong nating nomo. Yumi stap hadwok tumas, mo i gat ol trabol oli stap kasem yumi, be evri dei, yumi mas mekem ol samting we yumi save glad long hem, from we hemia nomo yumi save kasem long laef ya we yumi stap long hem."],[9,10,"Wanem samting we yumi stap mekem, yumi mas strong long hem long fulpaoa blong yumi, from we bambae i no gat wok, mo tingting, mo save, mo waes long Hom blong ol Dedman, mo hemia nao ples we bambae yumi go long hem.","Wanem samting we yumi stap mekem, yumi mas strong long hem long fulpaoa blong yumi, from we bambae i no gat wok, mo tingting, mo save, mo waes long Hom blong ol Dedman, mo hemia nao ples we bambae yumi go long hem."],[9,11,"“Mo narafala samting tu we mi luk long wol ya i olsem. I no ol nambawan man blong resis nomo we oli stap win long resis, mo i no ol strong man blong faet nomo we oli stap win long faet. I no ol waes man nomo we oli stap kasem gudfala laef, mo i no ol man ya nomo we oli gat hed we oli stap kam rijman. Mo i no ol gudfala man blong wok nomo we oli stap kasem hae nem. Olgeta man evriwan oli stap kasem gudlak mo badlak.","“Mo narafala samting tu we mi luk long wol ya i olsem. I no ol nambawan man blong resis nomo we oli stap win long resis, mo i no ol strong man blong faet nomo we oli stap win long faet. I no ol waes man nomo we oli stap kasem gudfala laef, mo i no ol man ya nomo we oli gat hed we oli stap kam rijman. Mo i no ol gudfala man blong wok nomo we oli stap kasem hae nem. Olgeta man evriwan oli stap kasem gudlak mo badlak."],[9,12,"Yumi no save wetaem taem blong yumi bambae i kam. Olsem we pijin i fas insaed long wan trap we i sek nomo long hem, no we fis i fas insaed long wan net, yumi tu, bambae trabol i kasem yumi wantaem nomo, we yumi no tingbaot, nao yumi go lus.","Yumi no save wetaem taem blong yumi bambae i kam. Olsem we pijin i fas insaed long wan trap we i sek nomo long hem, no we fis i fas insaed long wan net, yumi tu, bambae trabol i kasem yumi wantaem nomo, we yumi no tingbaot, nao yumi go lus."],[9,13,"“I gat wan narafala samting we mi luk, we i soemaot i klia we ol man long wol ya oli no save tinghevi long waes.","“I gat wan narafala samting we mi luk, we i soemaot i klia we ol man long wol ya oli no save tinghevi long waes."],[9,14,"I gat wan smol taon i stap we i no gat plante man long hem, be wan strong king i kam blong mekem faet long hem. Hem i goraon long taon ya, i mekemrere blong brekemdaon bigfala stonwol blong hem blong go insaed long hem.","I gat wan smol taon i stap we i no gat plante man long hem, be wan strong king i kam blong mekem faet long hem. Hem i goraon long taon ya, i mekemrere blong brekemdaon bigfala stonwol blong hem blong go insaed long hem."],[9,15,"Mo long taon ya, i gat wan puaman i stap we hem i waes gud, we i save sevem taon ya, be i no gat man i save lukluk long hem.","Mo long taon ya, i gat wan puaman i stap we hem i waes gud, we i save sevem taon ya, be i no gat man i save lukluk long hem."],[9,16,"Oltaem, long tok blong mi, mi stap talem se waes i gud moa, i winim paoa, be sipos man i puaman, bambae i no gat man i save tingbaot hem se i waes, mo i no gat man i save lesin long ol tok blong hem.","Oltaem, long tok blong mi, mi stap talem se waes i gud moa, i winim paoa, be sipos man i puaman, bambae i no gat man i save tingbaot hem se i waes, mo i no gat man i save lesin long ol tok blong hem."],[9,17,"Nating we waes man i stap tok kwaet nomo, be i moa gud yumi stap lesin long hem, i winim we yumi stap lesin long wan lida blong ol man we oli no gat hed, we oltaem i stap faerap strong.","Nating we waes man i stap tok kwaet nomo, be i moa gud yumi stap lesin long hem, i winim we yumi stap lesin long wan lida blong ol man we oli no gat hed, we oltaem i stap faerap strong."],[9,18,"Waestok i save givhan moa long yumi, i winim ol tul blong faet we yumi stap holem, be wan man nogud nomo i save spolem plante gudgudfala samting.","Waestok i save givhan moa long yumi, i winim ol tul blong faet we yumi stap holem, be wan man nogud nomo i save spolem plante gudgudfala samting."],[10,1,"“Ol flae we oli ded insaed long wan botel senta oli save mekem senta ya i sting, mo long sem fasin, smol samting nomo we man we i no gat hed i mekem i save spolem bigfala wok we man we i waes i mekem.","“Ol flae we oli ded insaed long wan botel senta oli save mekem senta ya i sting, mo long sem fasin, smol samting nomo we man we i no gat hed i mekem i save spolem bigfala wok we man we i waes i mekem."],[10,2,"“Man we i waes, oltaem hem i stap mekem ol samting we i stret, be man we i no gat hed, oltaem hem i stap mekem ol samting we i nogud.","“Man we i waes, oltaem hem i stap mekem ol samting we i stret, be man we i no gat hed, oltaem hem i stap mekem ol samting we i nogud."],[10,3,"I isi nomo blong ol man oli luksave man we i no gat hed. Ol strenja nomo, be taem oli luk hem long rod, oli save wantaem nomo se man ya i no gat hed. Oltaem nomo, man olsem i stap soemaot fasin blong hem.","I isi nomo blong ol man oli luksave man we i no gat hed. Ol strenja nomo, be taem oli luk hem long rod, oli save wantaem nomo se man ya i no gat hed. Oltaem nomo, man olsem i stap soemaot fasin blong hem."],[10,4,"“Sipos yu stap wok blong king, nao hem i kam kros long yu, i nogud yu go talem long hem, se bambae yu finis long hem. Nating we yu mekem i nogud tumas long hem, be sipos yu stap kwaet, plante taem bambae hem i save fogivim yu.","“Sipos yu stap wok blong king, nao hem i kam kros long yu, i nogud yu go talem long hem, se bambae yu finis long hem. Nating we yu mekem i nogud tumas long hem, be sipos yu stap kwaet, plante taem bambae hem i save fogivim yu."],[10,5,"“I gat wan narafala fasin we i no stret nating, we mi luk long wol ya, we i stap kamaot long wok blong ol king.","“I gat wan narafala fasin we i no stret nating, we mi luk long wol ya, we i stap kamaot long wok blong ol king."],[10,6,"Oltaem oli stap putumap ol man we oli no gat hed blong oli holem ol nambawan wok, be oli stap tingting nating long ol rijman.","Oltaem oli stap putumap ol man we oli no gat hed blong oli holem ol nambawan wok, be oli stap tingting nating long ol rijman."],[10,7,"Plante taem, mi luk we ol slef* oli stap wokbaot long hos, be ol haeman oli wokbaot long leg nomo, olsem we oli slef.","Plante taem, mi luk we ol slef* oli stap wokbaot long hos, be ol haeman oli wokbaot long leg nomo, olsem we oli slef."],[10,8,"“Man we i wantem digim hol blong mekem trap, bambae i save foldaon long hol ya bakegen. Mo man we i wantem brekem wol blong haos blong gotru, snek we i stap long wol ya bambae i save kakae hem.","“Man we i wantem digim hol blong mekem trap, bambae i save foldaon long hol ya bakegen. Mo man we i wantem brekem wol blong haos blong gotru, snek we i stap long wol ya bambae i save kakae hem."],[10,9,"Man we i stap katem ston blong wokem haos bambae i save karekil long ston ya. Mo man we i stap splitim wud bambae i save karekil long wud ya.","Man we i stap katem ston blong wokem haos bambae i save karekil long ston ya. Mo man we i stap splitim wud bambae i save karekil long wud ya."],[10,10,"Sipos akis blong yumi i no sap, mo yumi no sapenem, bambae yumi mas taetem bun nomo blong yusum. Be i moa gud yumi mekem plan fastaem, nao biaen bambae yumi wok.","Sipos akis blong yumi i no sap, mo yumi no sapenem, bambae yumi mas taetem bun nomo blong yusum. Be i moa gud yumi mekem plan fastaem, nao biaen bambae yumi wok."],[10,11,"Sipos yumi save fasin blong kwaetem snek blong i no kakae yumi, be yumi no mekem, nao hem i kakae yumi fastaem, hemia yumi no win nating.","Sipos yumi save fasin blong kwaetem snek blong i no kakae yumi, be yumi no mekem, nao hem i kakae yumi fastaem, hemia yumi no win nating."],[10,12,"Tok blong man we i waes i stap mekem ol man oli ona long hem, be tok blong man we i no gat hed i stap spolem hem nomo.","Tok blong man we i waes i stap mekem ol man oli ona long hem, be tok blong man we i no gat hed i stap spolem hem nomo."],[10,13,"Taem man olsem i stat blong talem wan samting, tok blong hem i olbaot nomo, mo taem hem i finis, tok blong hem i go krangke olgeta.","Taem man olsem i stat blong talem wan samting, tok blong hem i olbaot nomo, mo taem hem i finis, tok blong hem i go krangke olgeta."],[10,14,"Fasin blong man olsem, hem i tok we i tok, i stap gohed nomo we i no save weples bambae i finis. “I no gat man we i save ol samting we bambae oli kamtru. I no gat wan man nating we i save talemaot long yumi ol samting we bambae oli hapen long ples blong hem biaen long taem we hem i ded.","Fasin blong man olsem, hem i tok we i tok, i stap gohed nomo we i no save weples bambae i finis. “I no gat man we i save ol samting we bambae oli kamtru. I no gat wan man nating we i save talemaot long yumi ol samting we bambae oli hapen long ples blong hem biaen long taem we hem i ded."],[10,15,"“Man we i stap hadwok tumas gogo i taed we i taed, hem i no gat hed, i olsem man we i no save faenem rod blong gobak long haos blong hem.","“Man we i stap hadwok tumas gogo i taed we i taed, hem i no gat hed, i olsem man we i no save faenem rod blong gobak long haos blong hem."],[10,16,"“Kantri we king blong hem i yangfala nomo mo ol lida blong hem oli stap mekem lafet gogo kasem delaet, ol man blong hem bambae oli kasem trabol.","“Kantri we king blong hem i yangfala nomo mo ol lida blong hem oli stap mekem lafet gogo kasem delaet, ol man blong hem bambae oli kasem trabol."],[10,17,"Be kantri we king blong hem, hem nomo i stap makem rod blong hem, mo ol lida blong hem oli stap kakae long stret taem nomo blong oli strong blong wok, mo oli no save drong, ol man blong hem bambae oli save harem gud.","Be kantri we king blong hem, hem nomo i stap makem rod blong hem, mo ol lida blong hem oli stap kakae long stret taem nomo blong oli strong blong wok, mo oli no save drong, ol man blong hem bambae oli save harem gud."],[10,18,"“Sipos wan man i les tumas blong wokemgud haos blong hem, bambae haos ya i lik, mo i no longtaem, bambae ruf blong hem i brobrok.","“Sipos wan man i les tumas blong wokemgud haos blong hem, bambae haos ya i lik, mo i no longtaem, bambae ruf blong hem i brobrok."],[10,19,"“Gudfala kakae i save mekem yumi harem gud, mo waen i save mekem yumi glad, be mane, hem i save givim ansa long evri problem.","“Gudfala kakae i save mekem yumi harem gud, mo waen i save mekem yumi glad, be mane, hem i save givim ansa long evri problem."],[10,20,"“Nating we yumi stap tok smosmol nomo, be i nogud yumi stap tokbaot king. Nating we yumi stap long bedrum blong yumi, be i nogud yumi stap tokbaot ol rijman. Bambae wan pijin i girap i go talemaot tok blong yumi long olgeta.","“Nating we yumi stap tok smosmol nomo, be i nogud yumi stap tokbaot king. Nating we yumi stap long bedrum blong yumi, be i nogud yumi stap tokbaot ol rijman. Bambae wan pijin i girap i go talemaot tok blong yumi long olgeta."],[11,1,"“I gud yu stap mekem bisnes wetem ol narafala kantri. Sipos yu mekem olsem, bambae yu save win gud long bisnes blong yu.","“I gud yu stap mekem bisnes wetem ol narafala kantri. Sipos yu mekem olsem, bambae yu save win gud long bisnes blong yu."],[11,2,"Mo i nogud yu putum mane blong yu long ol bisnes long tri fo ples nomo, i moa gud yu putum long plante ples, from we yu no save wanem trabol bambae i kamtru long wol ya.","Mo i nogud yu putum mane blong yu long ol bisnes long tri fo ples nomo, i moa gud yu putum long plante ples, from we yu no save wanem trabol bambae i kamtru long wol ya."],[11,3,"“Nating we bigfala tri i foldaon i go long not no i go long saot, be ples we hem i foldaon i go long hem, ples ya nao bambae i mas stap long hem. Taem wota i fulap long klaod, bambae ren i mas kam.","“Nating we bigfala tri i foldaon i go long not no i go long saot, be ples we hem i foldaon i go long hem, ples ya nao bambae i mas stap long hem. Taem wota i fulap long klaod, bambae ren i mas kam."],[11,4,"Sipos yu stap luk long win blong makem stret taem blong planem garen blong yu, neva bambae yu save planem, mo sipos yu stap luk long klaod blong makem stret taem blong tekemaot kakae blong hem, neva bambae yu save tekem kakae i kam.","Sipos yu stap luk long win blong makem stret taem blong planem garen blong yu, neva bambae yu save planem, mo sipos yu stap luk long klaod blong makem stret taem blong tekemaot kakae blong hem, neva bambae yu save tekem kakae i kam."],[11,5,"God i stap wokem olgeta samting, be i had blong yumi makem fasin blong hem. Yumi no save makem se laef blong pikinini we i stap gru long bel blong mama blong hem i stat olsem wanem, mo long sem fasin, yumi no save makem ol fasin we God i stap mekem.","God i stap wokem olgeta samting, be i had blong yumi makem fasin blong hem. Yumi no save makem se laef blong pikinini we i stap gru long bel blong mama blong hem i stat olsem wanem, mo long sem fasin, yumi no save makem ol fasin we God i stap mekem."],[11,6,"Yu mas planem ol kakae long garen blong yu long moning, mo long sapa tu, from we yu no save weswan bambae oli gru gud. Maet olgeta evriwan oli karem gudfala kakae, no narawan nomo i karem, narawan i no gat.","Yu mas planem ol kakae long garen blong yu long moning, mo long sapa tu, from we yu no save weswan bambae oli gru gud. Maet olgeta evriwan oli karem gudfala kakae, no narawan nomo i karem, narawan i no gat."],[11,7,"“Delaet i wan gudfala samting, mo oltaem yumi glad tumas blong harem gud long hem.","“Delaet i wan gudfala samting, mo oltaem yumi glad tumas blong harem gud long hem."],[11,8,"Mo evri yia, i stret blong yumi stap harem gud long laef ya we yumi stap long hem, from we nating we laef ya blong yumi i longfala olsem wanem, be sipos yumi ded, taem ya we bambae yumi stap long tudak bambae i longfala moa. Olgeta samting we oli stap kam long yumi oli blong nating nomo.","Mo evri yia, i stret blong yumi stap harem gud long laef ya we yumi stap long hem, from we nating we laef ya blong yumi i longfala olsem wanem, be sipos yumi ded, taem ya we bambae yumi stap long tudak bambae i longfala moa. Olgeta samting we oli stap kam long yumi oli blong nating nomo."],[11,9,"“Ol yangfala, naoia we yufala i yangfala yet, i gud yufala i stap mekem ol fasin we yufala i save harem gud long hem. I gud yufala i folem wanem we tingting blong yufala i wantem, mo yufala i wokem wanem samting we yufala i wantem wokem. Be yufala i mas tingbaot tu we bambae God i jajem yufala from ol samting ya we yufala i mekem.","“Ol yangfala, naoia we yufala i yangfala yet, i gud yufala i stap mekem ol fasin we yufala i save harem gud long hem. I gud yufala i folem wanem we tingting blong yufala i wantem, mo yufala i wokem wanem samting we yufala i wantem wokem. Be yufala i mas tingbaot tu we bambae God i jajem yufala from ol samting ya we yufala i mekem."],[11,10,"“I nogud yufala i letem wan samting i mekem yufala i tingting tumas, no i mekem yufala i harem nogud long bodi blong yufala. Bambae yufala i no save stap yangfala olsem oltaem.","“I nogud yufala i letem wan samting i mekem yufala i tingting tumas, no i mekem yufala i harem nogud long bodi blong yufala. Bambae yufala i no save stap yangfala olsem oltaem."],[12,1,"“God i mekem yumi, mo naoia we yufala i yangfala yet, oltaem yufala i mas tingbaot hem. I nogud yufala i stap wet go kasem taem ya we evri dei, ol trabol bambae oli stap kam kasem yufala, mo evri yia, bambae yufala i stap talem se, ‘Mi mi no glad nating long laef ya.’","“God i mekem yumi, mo naoia we yufala i yangfala yet, oltaem yufala i mas tingbaot hem. I nogud yufala i stap wet go kasem taem ya we evri dei, ol trabol bambae oli stap kam kasem yufala, mo evri yia, bambae yufala i stap talem se, ‘Mi mi no glad nating long laef ya.’"],[12,2,"Long taem ya, bambae yufala i luk se san mo mun mo ol sta oli no moa save saen gud, mo ol klaod blong ren oli no moa save gowe long laef blong yufala.","Long taem ya, bambae yufala i luk se san mo mun mo ol sta oli no moa save saen gud, mo ol klaod blong ren oli no moa save gowe long laef blong yufala."],[12,3,"Ol han blong yufala bambae oli seksek, oli no moa strong blong blokem yufala, mo ol leg blong yufala bambae oli kam slak, oli no moa strong blong wokbaot. Ol tut blong yufala bambae oli stap folfoldaon, i no moa gat plante i stap blong yufala i kakae long hem, mo ae blong yufala bambae i kam nogud, yufala i no moa save luklukgud.","Ol han blong yufala bambae oli seksek, oli no moa strong blong blokem yufala, mo ol leg blong yufala bambae oli kam slak, oli no moa strong blong wokbaot. Ol tut blong yufala bambae oli stap folfoldaon, i no moa gat plante i stap blong yufala i kakae long hem, mo ae blong yufala bambae i kam nogud, yufala i no moa save luklukgud."],[12,4,"Sora blong yufala bambae i fas, yufala i no moa save harem noes long bigrod, mo i had blong yufala i harem ol man oli granem wit* i kam flaoa. Bambae yufala i stap girap long taem we pijin i singaot, be bambae i strong blong yufala i harem stringban we i faerap.","Sora blong yufala bambae i fas, yufala i no moa save harem noes long bigrod, mo i had blong yufala i harem ol man oli granem wit* i kam flaoa. Bambae yufala i stap girap long taem we pijin i singaot, be bambae i strong blong yufala i harem stringban we i faerap."],[12,5,"Bambae yufala i stap fraet blong klaem i go antap, long ol ples we i hae, mo bambae i gat plante samting long rod blong mekem yufala i fraet. Hea blong yufala bambae i kam waet, mo bambae i strong blong yufala i stap dragem yufala i go olbaot. Mo tingting blong yufala long saed blong woman bambae i no moa gat. “Bambae yumi evriwan i mas go slip long las ples blong yumi, we bambae yumi stap olwe long hem. Mo olbaot long ol bigrod, bambae ol man oli stap harem nogud, oli stap krae.","Bambae yufala i stap fraet blong klaem i go antap, long ol ples we i hae, mo bambae i gat plante samting long rod blong mekem yufala i fraet. Hea blong yufala bambae i kam waet, mo bambae i strong blong yufala i stap dragem yufala i go olbaot. Mo tingting blong yufala long saed blong woman bambae i no moa gat. “Bambae yumi evriwan i mas go slip long las ples blong yumi, we bambae yumi stap olwe long hem. Mo olbaot long ol bigrod, bambae ol man oli stap harem nogud, oli stap krae."],[12,6,"Jen ya we oli wokem long silva bambae i brok, mo laet ya we oli wokem long gol bambae i foldaon, i smas. Rop ya we i stap long wel bambae i brok, mo bigfala botel ya blong wota bambae i brobrok long ol smosmol pis.","Jen ya we oli wokem long silva bambae i brok, mo laet ya we oli wokem long gol bambae i foldaon, i smas. Rop ya we i stap long wel bambae i brok, mo bigfala botel ya blong wota bambae i brobrok long ol smosmol pis."],[12,7,"Bodi blong yumi bambae i gobak long graon, mo laef ya we God i givim long yumi, bambae i gobak long hem bakegen.”","Bodi blong yumi bambae i gobak long graon, mo laef ya we God i givim long yumi, bambae i gobak long hem bakegen.”"],[12,8,"Man ya we i waes gud long ol fasin blong wol ya, hem i talem se, “!Laef blong yumi long wol ya, hem i blong nating nomo! !Olgeta samting blong hem i blong nating nomo!”","Man ya we i waes gud long ol fasin blong wol ya, hem i talem se, “!Laef blong yumi long wol ya, hem i blong nating nomo! !Olgeta samting blong hem i blong nating nomo!”"],[12,9,"Nao from we man ya we i waes gud long ol fasin blong wol ya, mo i save plante samting, hem i gohed, i stap tijim ol man long ol samting ya we hem i save. Hem i stap stadi gud long ol waestok, mo i stap luklukgud blong faenemaot se oli tru no oli no tru.","Nao from we man ya we i waes gud long ol fasin blong wol ya, mo i save plante samting, hem i gohed, i stap tijim ol man long ol samting ya we hem i save. Hem i stap stadi gud long ol waestok, mo i stap luklukgud blong faenemaot se oli tru no oli no tru."],[12,10,"Hem i stap traehad blong faenem ol toktok blong givhan, mo ol tok we hem i raetem long buk ya oli stret gud nomo.","Hem i stap traehad blong faenem ol toktok blong givhan, mo ol tok we hem i raetem long buk ya oli stret gud nomo."],[12,11,"Ol tok blong ol waes man oli olsem sap stik we man blong lukaot long sipsip i stap karem blong stikim ol sipsip blong hem, mo oli save stap longtaem, olsem nil we man i hamarem i go insaed long wud, we i fas gud long hem. God i stap lukaot long yumi evriwan olsem we man blong lukaot long sipsip i stap lukaot long ol sipsip blong hem, mo hem nao i givim ol waestok ya long man ya.","Ol tok blong ol waes man oli olsem sap stik we man blong lukaot long sipsip i stap karem blong stikim ol sipsip blong hem, mo oli save stap longtaem, olsem nil we man i hamarem i go insaed long wud, we i fas gud long hem. God i stap lukaot long yumi evriwan olsem we man blong lukaot long sipsip i stap lukaot long ol sipsip blong hem, mo hem nao i givim ol waestok ya long man ya."],[12,12,"Mo las tok blong hem, hem i talem se, “Pikinini blong mi, i gat wan samting i stap we yu mas lukaot gud long hem. Bambae ol man oli stap raetem ol buk gogo i no save finis, mo sipos yu stap stadi tumas long olgeta oltaem, samting ya bambae i mekem yu yu taed gud nomo.","Mo las tok blong hem, hem i talem se, “Pikinini blong mi, i gat wan samting i stap we yu mas lukaot gud long hem. Bambae ol man oli stap raetem ol buk gogo i no save finis, mo sipos yu stap stadi tumas long olgeta oltaem, samting ya bambae i mekem yu yu taed gud nomo."],[12,13,"“Antap long ol samting ya, wan samting nomo mi wantem talem long yu, se yu mas tinghevi long God, yu mas ona long hem, mo yu mas obei long ol tok blong hem, from we hemia nao samting we hem i mekem yumi from.","“Antap long ol samting ya, wan samting nomo mi wantem talem long yu, se yu mas tinghevi long God, yu mas ona long hem, mo yu mas obei long ol tok blong hem, from we hemia nao samting we hem i mekem yumi from."],[12,14,"Olgeta samting we yumi mekem, nating we i gud no i nogud, go kasem ol samting we yumi haed nomo blong mekem, be hem bambae i mekem kot long yumi from olgeta evriwan.”","Olgeta samting we yumi mekem, nating we i gud no i nogud, go kasem ol samting we yumi haed nomo blong mekem, be hem bambae i mekem kot long yumi from olgeta evriwan.”"]]}};